    // Запомненные между запусками мелочи (язык, последняя папка): строки «ключ=значение» в профиле пользователя.
    static class Settings
    {
        static string FilePath
        {
            get { return Path.Combine(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "BedrockPackStudio"), "settings.txt"); }
        }

        static Dictionary<string, string> Load()
        {
            Dictionary<string, string> r = new Dictionary<string, string>();
            try
            {
                if (File.Exists(FilePath))
                    foreach (string line in File.ReadAllLines(FilePath))
                    {
                        int eq = line.IndexOf('=');
                        if (eq > 0) r[line.Substring(0, eq).Trim()] = line.Substring(eq + 1).Trim();
                    }
            }
            catch (Exception) { return null; } // файл есть, но не прочитался (занят другим окном): не «пусто», а «неизвестно»
            return r;
        }

        public static string Get(string key)
        {
            string v;
            Dictionary<string, string> all = Load();
            return all != null && all.TryGetValue(key, out v) ? v : null;
        }

        public static void Set(string key, string value)
        {
            try
            {
                Dictionary<string, string> all = Load();
                if (all == null) return; // иначе поверх непрочитанных настроек записалась бы одна эта строка
                all[key] = value;
                List<string> lines = new List<string>();
                foreach (KeyValuePair<string, string> kv in all) lines.Add(kv.Key + "=" + kv.Value);
                Directory.CreateDirectory(Path.GetDirectoryName(FilePath));
                File.WriteAllLines(FilePath, lines.ToArray());
            }
            catch (Exception) { }
        }
    }

    // Русский или английский. Строки в коде русские; английские берутся из словаря по русскому тексту.
    // Длинные сообщения собираются из кусков, поэтому в словаре есть и обрывки фраз с пробелами по краям.
    static class L
    {
        public static bool Ru;
        static List<KeyValuePair<Action<string>, string>> bound = new List<KeyValuePair<Action<string>, string>>();

        // Язык при запуске: сохранённый выбор пользователя, а если его нет — по языку интерфейса Windows
        // (русский и украинский → русский, любой другой → английский).
        public static void Init()
        {
            string forced = Environment.GetEnvironmentVariable("BPS_LANG"); // для проверочных снимков
            if (forced != null) { Ru = forced == "ru"; return; }
            string saved = Settings.Get("lang");
            if (saved == "ru" || saved == "en") { Ru = saved == "ru"; return; }
            string ui = System.Globalization.CultureInfo.CurrentUICulture.TwoLetterISOLanguageName;
            Ru = ui == "ru" || ui == "uk";
        }

        // Ручное переключение запоминается и при следующих запусках важнее языка Windows.
        public static void Toggle()
        {
            Ru = !Ru;
            if (Environment.GetEnvironmentVariable("BPS_LANG") == null) Settings.Set("lang", Ru ? "ru" : "en");
            foreach (KeyValuePair<Action<string>, string> b in bound) b.Key(T(b.Value));
        }

        // Русский и английский варианты строки вместе, в нижнем регистре — для поиска на любом языке.
        public static string Both(string ru)
        {
            string en;
            return (ru + "\n" + (En.TryGetValue(ru, out en) ? en : "")).ToLowerInvariant();
        }

        // Ширина надписи, одинаковая для обоих языков: берётся более длинный из двух вариантов.
        // По ней задаётся ширина кнопок, чтобы при смене языка они не прыгали.
        public static int Wide(string ru, Font font)
        {
            string en;
            int w = TextRenderer.MeasureText(ru, font).Width;
            if (En.TryGetValue(ru, out en)) w = Math.Max(w, TextRenderer.MeasureText(en, font).Width);
            return w;
        }

        public static string T(string ru)
        {
            string en;
            return !Ru && En.TryGetValue(ru, out en) ? en : ru;
        }

        // Надпись элемента окна: ставится сейчас и переставляется при смене языка.
        public static void Bind(Action<string> set, string ru)
        {
            bound.Add(new KeyValuePair<Action<string>, string>(set, ru));
            set(T(ru));
        }

