            { "Верхний пакет текстур имеет приоритет над нижним,\nесли они влияют на один и тот же объект.\n\nПакеты можно перемещать по списку: зажмите левую кнопку мыши\nи перетащите пакет выше или ниже.\n\nЕсли у пакета текстур есть несколько встроенных вариантов,\nнужный выбирается в окошке справа от его названия.\n\nЧтобы использовать разные текстуры из разных вариантов одного пакета,\nдобавьте его копию, переключите её на нужный вариант\nи выбирайте текстуры в большом окне справа.",
              "The upper texture pack takes priority over the lower one\nwhen both affect the same object.\n\nYou can move packs in the list: hold the left mouse button\nand drag a pack up or down.\n\nIf a texture pack has several built-in variants,\npick the one you need in the box to the right of its name.\n\nTo use different textures from different variants of one pack,\nadd a copy of it, switch the copy to the variant you need\nand pick textures in the large window on the right." }
        };
    }

    // ------------------------------------------------------------------ JSON
    // Свой разборщик: JSON в паках Bedrock часто содержит комментарии и висячие запятые.

    class JObj
    {
        public List<string> Keys = new List<string>();
        public Dictionary<string, object> Map = new Dictionary<string, object>();

        public object Get(string k)
        {
            object v;
            return Map.TryGetValue(k, out v) ? v : null;
        }

        public void Remove(string k)
        {
            Keys.Remove(k);
            Map.Remove(k);
        }

        public void Set(string k, object v)
        {
            if (!Map.ContainsKey(k)) Keys.Add(k);
            Map[k] = v;
        }
    }

    // Число, true, false или null — хранится как исходный текст, чтобы не терять формат.
    class JLit
    {
        public string Raw;
        public JLit(string raw) { Raw = raw; }
    }

    class Json
    {
        string s;
        int p;
        int depth; // защита от переполнения стека на нарочно глубоком файле

        public static object Parse(string text)
        {
            Json q = new Json();
            q.s = text;
            q.p = 0;
            return q.Val();
        }

        void Ws()
        {
            while (p < s.Length)
            {
                char c = s[p];
                if (char.IsWhiteSpace(c) || c == '\uFEFF') p++;
                else if (c == '/' && p + 1 < s.Length && s[p + 1] == '/')
                {
                    while (p < s.Length && s[p] != '\n') p++;
                }
                else if (c == '/' && p + 1 < s.Length && s[p + 1] == '*')
                {
                    int e = s.IndexOf("*/", p + 2, StringComparison.Ordinal);
                    p = e < 0 ? s.Length : e + 2;
                }
                else break;
            }
        }

        object Val()
        {
            Ws();
            if (p >= s.Length) throw new FormatException(L.T("неожиданный конец JSON"));
            char c = s[p];
            if ((c == '{' || c == '[') && depth >= 200) throw new FormatException(L.T("ошибка JSON в позиции ") + p);
            if (c == '{')
            {
                p++;
                depth++;
                JObj o = new JObj();
                while (true)
                {
                    Ws();
                    if (p >= s.Length) throw new FormatException(L.T("не закрыта скобка {"));
                    if (s[p] == '}') { p++; break; }
                    if (s[p] == ',') { p++; continue; }
                    string k = Str();
                    Ws();
                    if (p >= s.Length || s[p] != ':') throw new FormatException(L.T("ожидалось ':' в позиции ") + p);
                    p++;
                    o.Set(k, Val());
                }
                depth--;
                return o;
            }
            if (c == '[')
            {
                p++;
                depth++;
                List<object> a = new List<object>();
                while (true)
                {
                    Ws();
                    if (p >= s.Length) throw new FormatException(L.T("не закрыта скобка ["));
                    if (s[p] == ']') { p++; break; }
                    if (s[p] == ',') { p++; continue; }
                    a.Add(Val());
                }
                depth--;
                return a;
            }
            if (c == '"') return Str();
            int st = p;
            while (p < s.Length && ",]}:/".IndexOf(s[p]) < 0 && !char.IsWhiteSpace(s[p])) p++;
            if (p == st) throw new FormatException(L.T("ошибка JSON в позиции ") + p);
            string raw = s.Substring(st, p - st);
            double num;
            if (raw != "true" && raw != "false" && raw != "null"
                && !double.TryParse(raw, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out num))
                throw new FormatException(L.T("ошибка JSON в позиции ") + st);
            return new JLit(raw);
        }

        string Str()
        {
            if (p >= s.Length || s[p] != '"') throw new FormatException(L.T("ожидалась строка в позиции ") + p);
            p++;
            StringBuilder sb = new StringBuilder();
            while (true)
            {
                if (p >= s.Length) throw new FormatException(L.T("не закрыта строка"));
                char c = s[p++];
                if (c == '"') break;
                if (c != '\\') { sb.Append(c); continue; }
                if (p >= s.Length) throw new FormatException(L.T("не закрыта строка"));
                char e = s[p++];
                switch (e)
                {
                    case 'n': sb.Append('\n'); break;
                    case 't': sb.Append('\t'); break;
                    case 'r': sb.Append('\r'); break;
                    case 'b': sb.Append('\b'); break;
                    case 'f': sb.Append('\f'); break;
                    case 'u':
                        if (p + 4 > s.Length) throw new FormatException(L.T("плохой \\u"));
                        sb.Append((char)Convert.ToInt32(s.Substring(p, 4), 16));
                        p += 4;
                        break;
                    default: sb.Append(e); break;
                }
            }
            return sb.ToString();
        }

        public static string Write(object v)
        {
            StringBuilder sb = new StringBuilder();
            Write(sb, v, 0);
            return sb.ToString();
        }

        static void Quote(StringBuilder sb, string t)
        {
            sb.Append('"');
            foreach (char c in t)
            {
                if (c == '"') sb.Append("\\\"");
                else if (c == '\\') sb.Append("\\\\");
                else if (c == '\n') sb.Append("\\n");
                else if (c == '\r') sb.Append("\\r");
                else if (c == '\t') sb.Append("\\t");
                else if (c < ' ') sb.Append("\\u").Append(((int)c).ToString("x4"));
                else sb.Append(c);
            }
            sb.Append('"');
        }

        static void Write(StringBuilder sb, object v, int ind)
        {
            JObj o = v as JObj;
            List<object> a = v as List<object>;
            if (o != null)
            {
                if (o.Keys.Count == 0) { sb.Append("{}"); return; }
                sb.Append("{\n");
                for (int i = 0; i < o.Keys.Count; i++)
                {
                    sb.Append(' ', (ind + 1) * 2);
                    Quote(sb, o.Keys[i]);
                    sb.Append(": ");
                    Write(sb, o.Map[o.Keys[i]], ind + 1);
                    if (i < o.Keys.Count - 1) sb.Append(',');
                    sb.Append('\n');
                }
                sb.Append(' ', ind * 2).Append('}');
            }
            else if (a != null)
            {
                bool flat = true;
                foreach (object x in a) if (x is JObj || x is List<object>) flat = false;
                if (flat)
                {
                    sb.Append('[');
                    for (int i = 0; i < a.Count; i++)
                    {
                        if (i > 0) sb.Append(", ");
                        Write(sb, a[i], ind);
                    }
                    sb.Append(']');
                    return;
                }
                sb.Append("[\n");
                for (int i = 0; i < a.Count; i++)
                {
                    sb.Append(' ', (ind + 1) * 2);
                    Write(sb, a[i], ind + 1);
                    if (i < a.Count - 1) sb.Append(',');
                    sb.Append('\n');
                }
                sb.Append(' ', ind * 2).Append(']');
            }
            else if (v is string) Quote(sb, (string)v);
            else if (v is JLit) sb.Append(((JLit)v).Raw);
            else sb.Append("null");
        }
    }

    // ------------------------------------------------------------------ Картинки

    static class Img
    {
        public static bool IsImage(string path)
        {
            string e = Path.GetExtension(path).ToLowerInvariant();
            return e == ".png" || e == ".tga" || e == ".jpg" || e == ".jpeg";
        }

        // Пределы для картинок из пакетов: подложенный файл не должен занять всю память.
        const int MaxSide = 8192;
        const long MaxFile = 256L * 1024 * 1024;

        // Грузит без блокировки файла и всегда отдаёт 32bppArgb.
        public static Bitmap Load(string path)
        {
            if (new FileInfo(path).Length > MaxFile) throw new InvalidDataException(L.T("Файл картинки слишком большой."));
            byte[] data = File.ReadAllBytes(path);
            CheckSides(data, Path.GetExtension(path).ToLowerInvariant());
            if (Path.GetExtension(path).ToLowerInvariant() == ".tga") return LoadTga(data);
            using (MemoryStream ms = new MemoryStream(data))
            using (Bitmap src = new Bitmap(ms))
                return Copy(src);
        }

        // Ширина и высота из заголовка файла (PNG, JPG, TGA) — до того, как картинку начнут раскладывать в память.
        static void CheckSides(byte[] d, string ext)
        {
            int w = 0, h = 0;
            if (d.Length >= 24 && d[0] == 0x89 && d[1] == 0x50 && d[2] == 0x4E && d[3] == 0x47)
            {
                w = (d[16] << 24) | (d[17] << 16) | (d[18] << 8) | d[19];
                h = (d[20] << 24) | (d[21] << 16) | (d[22] << 8) | d[23];
            }
            else if (d.Length >= 4 && d[0] == 0xFF && d[1] == 0xD8)
            {
                int i = 2;
                while (i + 9 < d.Length)
                {
                    if (d[i] != 0xFF) { i++; continue; }
                    int m = d[i + 1];
                    if (m == 0xD8 || m == 0x01 || (m >= 0xD0 && m <= 0xD7) || m == 0xFF) { i++; continue; }
                    int len = (d[i + 2] << 8) | d[i + 3];
                    if (m >= 0xC0 && m <= 0xCF && m != 0xC4 && m != 0xC8 && m != 0xCC)
                    {
                        h = (d[i + 5] << 8) | d[i + 6];
                        w = (d[i + 7] << 8) | d[i + 8];
                        break;
                    }
                    if (len < 2) break;
                    i += 2 + len;
                }
            }
            else if (ext == ".tga" && d.Length >= 18)
            {
                w = d[12] | (d[13] << 8);
                h = d[14] | (d[15] << 8);
            }
            if (w < 0 || h < 0 || w > MaxSide || h > MaxSide)
                throw new InvalidDataException(L.T("Картинка слишком большая: ") + w + "×" + h + L.T(" (предел ") + MaxSide + "×" + MaxSide + ").");
        }

        public static void Save(Bitmap bmp, string path)
        {
            string e = Path.GetExtension(path).ToLowerInvariant();
            string target = path;
            path = target + ".brpc-tmp";
            try
            {
                SaveTo(bmp, path, e);
                // «только чтение» (файлы из архива или с диска) мешало бы заменить
                if (File.Exists(target) && (File.GetAttributes(target) & FileAttributes.ReadOnly) != 0)
                    File.SetAttributes(target, File.GetAttributes(target) & ~FileAttributes.ReadOnly);
                File.Copy(path, target, true);
            }
            finally
            {
                try { File.Delete(path); } catch (Exception) { }
            }
        }

        static void SaveTo(Bitmap bmp, string path, string e)
        {
            if (e == ".jpg" || e == ".jpeg")
            {
                ImageCodecInfo jpeg = null;
                foreach (ImageCodecInfo c in ImageCodecInfo.GetImageEncoders()) if (c.FormatID == ImageFormat.Jpeg.Guid) jpeg = c;
                using (EncoderParameters q = new EncoderParameters(1))
                {
                    q.Param[0] = new EncoderParameter(System.Drawing.Imaging.Encoder.Quality, 97L);
                    if (jpeg != null) bmp.Save(path, jpeg, q); else bmp.Save(path, ImageFormat.Jpeg);
                }
            }
            else if (e != ".tga") bmp.Save(path, ImageFormat.Png);
            else
            {
                // TGA без сжатия, 32 бита, строки сверху вниз
                int[] px = GetPixels(bmp);
                byte[] o = new byte[18 + px.Length * 4];
                o[2] = 2;
                o[12] = (byte)(bmp.Width & 255); o[13] = (byte)(bmp.Width >> 8);
                o[14] = (byte)(bmp.Height & 255); o[15] = (byte)(bmp.Height >> 8);
                o[16] = 32;
                o[17] = 0x28;
                Buffer.BlockCopy(px, 0, o, 18, px.Length * 4);
                File.WriteAllBytes(path, o);
            }
        }

        public static int[] GetPixels(Bitmap b)
        {
            Rectangle r = new Rectangle(0, 0, b.Width, b.Height);
            BitmapData d = b.LockBits(r, ImageLockMode.ReadOnly, PixelFormat.Format32bppArgb);
            int[] buf = new int[b.Width * b.Height];
            Marshal.Copy(d.Scan0, buf, 0, buf.Length);
            b.UnlockBits(d);
            return buf;
        }

        public static void SetPixels(Bitmap b, int[] buf)
        {
            Rectangle r = new Rectangle(0, 0, b.Width, b.Height);
            BitmapData d = b.LockBits(r, ImageLockMode.WriteOnly, PixelFormat.Format32bppArgb);
            Marshal.Copy(buf, 0, d.Scan0, buf.Length);
            b.UnlockBits(d);
        }

        public static Bitmap FromPixels(int w, int h, int[] buf)
        {
            Bitmap b = new Bitmap(w, h, PixelFormat.Format32bppArgb);
            SetPixels(b, buf);
            return b;
        }

        public static Bitmap Copy(Bitmap src)
        {
            return FromPixels(src.Width, src.Height, GetPixels(src));
        }

        static Bitmap LoadTga(byte[] d)
        {
            if (d.Length < 18) throw new FormatException(L.T("файл TGA повреждён"));
            int idLen = d[0], cmapType = d[1], type = d[2];
            int cmapLen = d[5] | (d[6] << 8), cmapBits = d[7];
            int w = d[12] | (d[13] << 8), h = d[14] | (d[15] << 8), bpp = d[16], desc = d[17];
            bool rle = type == 10 || type == 11;
            bool gray = type == 3 || type == 11;
            if (!(type == 2 || type == 10 || gray) || !(bpp == 8 || bpp == 24 || bpp == 32) || w == 0 || h == 0)
                throw new FormatException(L.T("этот вид TGA не поддерживается (тип ") + type + ", " + bpp + L.T(" бит)"));
            int pos = 18 + idLen + (cmapType != 0 ? cmapLen * ((cmapBits + 7) / 8) : 0);
            int bytes = bpp / 8;
            long total = (long)w * h;
            if (total > 8192L * 8192L || pos > d.Length || (!rle && pos + total * bytes > d.Length))
                throw new FormatException(L.T("файл TGA повреждён"));
            int[] px = new int[w * h];
            int i = 0, n = w * h;
            byte[] one = new byte[4];
            while (i < n)
            {
                int count = 1;
                bool run = false;
                if (rle)
                {
                    if (pos >= d.Length) throw new FormatException(L.T("файл TGA повреждён"));
                    int hd = d[pos++];
                    count = (hd & 0x7F) + 1;
                    run = (hd & 0x80) != 0;
                }
                for (int k = 0; k < count && i < n; k++)
                {
                    if (!run || k == 0)
                    {
                        if (pos + bytes > d.Length) throw new FormatException(L.T("файл TGA повреждён"));
                        Buffer.BlockCopy(d, pos, one, 0, bytes);
                        pos += bytes;
                    }
                    int argb;
                    if (bytes == 1) argb = (255 << 24) | (one[0] << 16) | (one[0] << 8) | one[0];
                    else argb = ((bytes == 4 ? one[3] : 255) << 24) | (one[2] << 16) | (one[1] << 8) | one[0];
                    px[i++] = argb;
                }
            }
            if ((desc & 0x20) == 0)
            {
                // строки идут снизу вверх — переворачиваем
                int[] row = new int[w];
                for (int y = 0; y < h / 2; y++)
                {
                    Array.Copy(px, y * w, row, 0, w);
                    Array.Copy(px, (h - 1 - y) * w, px, y * w, w);
                    Array.Copy(row, 0, px, (h - 1 - y) * w, w);
                }
            }
            return FromPixels(w, h, px);
        }
    }

    // ------------------------------------------------------------------ Паки

    class Pack
    {
        public string Name;
        public string Root;
        public string TempDir; // не null, если пак распакован из архива
        public int[] MinEngine;
        public List<object> Capabilities, Subpacks;
        public string Origin; // папка или архив, откуда пакет добавлен; по этому пути проект находит его снова
        public int OriginIndex; // номер пакета внутри этого источника (в архиве их может быть несколько)
        public bool Java;     // пакет Java-издания, переведённый в вид Bedrock при добавлении
        public Bitmap Icon;   // уменьшенный pack_icon.png для списка паков
        public bool IconTried;
        // ключ — относительный путь в нижнем регистре через '/', значение — как он записан в паке
        public Dictionary<string, string> Files = new Dictionary<string, string>();
        // Корзина: файлы, убранные из списка в программе. На диске они остаются, но пакет ведёт себя так, будто их нет.
        public Dictionary<string, string> Trash = new Dictionary<string, string>();

        public string FullPath(string key)
        {
            return Path.Combine(Root, Files[key].Replace('/', Path.DirectorySeparatorChar));
        }

        // Выбранный вариант пака (subpack): отдельный слой, который накладывается прямо поверх самого пака.
        public Pack Sub;
        public string SubFolder;
        // значение-метка «выключено» в словарях выбора
        public static readonly Pack Off = new Pack();

        public override string ToString()
        {
            return Name + "   (" + (Files.Count + (Sub != null ? Sub.Files.Count : 0)) + L.T(" файлов")
                + (TempDir != null ? L.T(", из архива") : "") + ")";
        }

        public void Scan()
        {
            string root = Root.TrimEnd('\\', '/');
            if (!Directory.Exists(root)) throw new DirectoryNotFoundException(L.T("Не найдено: ") + root);
            Files.Clear(); // после проверки: если папка пропала, прежний список файлов остаётся
            foreach (string f in Directory.GetFiles(root, "*", SearchOption.AllDirectories))
            {
                string rel = f.Substring(root.Length + 1).Replace('\\', '/');
                string key = rel.ToLowerInvariant();
                // варианты в сборку целиком не идут: выбранный подмешивается как слой, остальные не нужны
                if (key.StartsWith("subpacks/")) continue;
                // служебные списки избранного — не файлы пакета
                if (key == "favorites.txt" || key == "favorites.txt.tmp" || key == "folders.txt") continue;
                Files[key] = rel;
            }
            foreach (string gone in Trash.Keys) Files.Remove(gone); // убранное в корзину после перечитывания не возвращается
            if (Sub != null) Sub.Scan();
        }

        public void SetSub(string folder)
        {
            Sub = null;
            SubFolder = null;
            if (folder == null) return;
            // имя варианта приходит из manifest.json или файла проекта: только одна папка внутри subpacks, никаких «..» и полных путей
            if (folder.Trim().Length == 0 || folder.Trim('.', ' ').Length == 0 || folder.IndexOfAny(Path.GetInvalidFileNameChars()) >= 0) return;
            string dir = Path.Combine(Path.Combine(Root, "subpacks"), folder);
            if (!Directory.Exists(dir)) return;
            Pack s = new Pack();
            s.Root = dir;
            s.Name = Name + L.T(" [вариант ") + folder + "]";
            s.Scan();
            Sub = s;
            SubFolder = folder;
        }

        public static string SubFolderOf(object subpack)
        {
            JObj o = subpack as JObj;
            return o == null ? null : o.Get("folder_name") as string;
        }
    }

    // Пакет текстур Java-издания. Игра Bedrock такие не читает: папки и многие имена файлов у неё другие
    // (block/oak_log.png — это blocks/log_oak.png). При добавлении в программу пакет переводится: каждой картинке
    // подбирается имя Bedrock. Имена берутся из самой установленной игры — из её списка блоков (blocks.json),
    // списка текстур блоков (terrain_texture.json) и перечня файлов (contents.json), — и из небольшой таблицы для предметов.
    // Переносятся только картинки; модели, звуки и надписи Java в Bedrock устроены иначе.
    static class JavaPack
    {
        static HashSet<string> files;              // текстуры самой игры, без расширения
        static Dictionary<string, object> blocks;  // блок -> его текстуры
        static JObj terrain;                       // короткое имя текстуры блока -> путь
        static Dictionary<string, string> shortOf; // путь -> короткое имя
        static string flipbooks = "";              // список анимаций самой игры

        // Папка с пакетом Java внутри root или null, если это обычный пакет Bedrock или не пакет вовсе.
        public static string Find(string root)
        {
            try
            {
                if (!Directory.Exists(root)) return null;
                if (Directory.GetFiles(root, "manifest.json", SearchOption.AllDirectories).Length > 0) return null;
                List<string> spots = new List<string>();
                spots.Add(root);
                spots.AddRange(Directory.GetDirectories(root));
                foreach (string d in spots)
                    if (Directory.Exists(Path.Combine(Path.Combine(Path.Combine(d, "assets"), "minecraft"), "textures"))) return d;
            }
            catch (Exception) { }
            return null;
        }

        static object FirstPath(object t)
        {
            string s = t as string;
            if (s != null) return s;
            List<object> list = t as List<object>;
            if (list != null) return list.Count > 0 ? FirstPath(list[0]) : null;
            JObj o = t as JObj;
            if (o == null) return null;
            return o.Get("path") as string ?? FirstPath(o.Get("variations"));
        }

        static void EnsureData()
        {
            if (files != null) return;
            files = new HashSet<string>();
            blocks = new Dictionary<string, object>();
            shortOf = new Dictionary<string, string>();
            terrain = Builder.VanillaTerrain();
            foreach (string k in terrain.Keys)
            {
                JObj e = terrain.Map[k] as JObj;
                string p = e == null ? null : FirstPath(e.Get("textures")) as string;
                if (p != null && !shortOf.ContainsKey(p.ToLowerInvariant())) shortOf[p.ToLowerInvariant()] = k;
            }
            foreach (string d in Geo.GameDirs())
            {
                try
                {
                    string list = Path.Combine(d, "contents.json");
                    if (File.Exists(list))
                        foreach (System.Text.RegularExpressions.Match m in System.Text.RegularExpressions.Regex.Matches(File.ReadAllText(list), "\"path\"\\s*:\\s*\"(textures/[^\"]+)\""))
                        {
                            string p = m.Groups[1].Value.ToLowerInvariant();
                            if (Img.IsImage(p)) files.Add(p.Substring(0, p.Length - Path.GetExtension(p).Length));
                        }
                }
                catch (Exception) { }
                try
                {
                    string bf = Path.Combine(d, "blocks.json");
                    JObj root = File.Exists(bf) ? Json.Parse(File.ReadAllText(bf)) as JObj : null;
                    if (root != null)
                        foreach (string k in root.Keys)
                        {
                            JObj b = root.Map[k] as JObj;
                            if (b != null && b.Map.ContainsKey("textures")) blocks[k] = b.Map["textures"];
                        }
                }
                catch (Exception) { }
                try
                {
                    string ff = Path.Combine(Path.Combine(d, "textures"), "flipbook_textures.json");
                    if (File.Exists(ff)) flipbooks += File.ReadAllText(ff).ToLowerInvariant();
                }
                catch (Exception) { }
            }
        }

        static bool Known(string path) { return files.Count == 0 || files.Contains(path); }

        static string TerrainPath(string name)
        {
            JObj e = name == null ? null : terrain.Get(name) as JObj;
            string p = e == null ? null : FirstPath(e.Get("textures")) as string;
            return p == null ? null : p.ToLowerInvariant();
        }

        // Короткое имя текстуры нужной стороны блока.
        static string Face(object textures, string face)
        {
            string one = textures as string;
            if (one != null) return one;
            JObj f = textures as JObj;
            if (f == null) return null;
            string[] order;
            if (face == "up") order = new string[] { "up" };
            else if (face == "down") order = new string[] { "down", "up" };
            else if (face == "front") order = new string[] { "south", "north", "side" };
            else if (face == "back") order = new string[] { "north", "side" };
            else order = new string[] { "side", "east", "west", "north", "south" };
            foreach (string k in order)
            {
                string v = f.Get(k) as string;
                if (v != null) return v;
            }
            return null;
        }

        // Названия блоков, которые в двух изданиях разные.
        static readonly string[] BlockIds = {
            "grass_block", "grass", "oak_door", "wooden_door", "oak_trapdoor", "trapdoor", "cobweb", "web", "bricks", "brick_block",
            "nether_bricks", "nether_brick", "red_nether_bricks", "red_nether_brick", "end_stone_bricks", "end_bricks", "snow_block", "snow",
            "terracotta", "hardened_clay", "magma_block", "magma", "slime_block", "slime", "melon", "melon_block", "sugar_cane", "reeds",
            "dead_bush", "deadbush", "lily_pad", "waterlily", "spawner", "mob_spawner", "nether_quartz_ore", "quartz_ore",
            "jack_o_lantern", "lit_pumpkin", "note_block", "noteblock", "powered_rail", "golden_rail", "bookshelf", "bookshelf",
            "oak_sign", "standing_sign", "crafting_table", "crafting_table", "piston", "piston", "sticky_piston", "sticky_piston" };

        static string BlockTarget(string j)
        {
            if (j.IndexOf((char)47) >= 0) return null;
            string same = "textures/blocks/" + j;
            if (files.Count == 0 || files.Contains(same)) return same;
            // стадии роста: wheat_stage7 в Java — wheat_stage_7 в Bedrock
            System.Text.RegularExpressions.Match stage = System.Text.RegularExpressions.Regex.Match(j, "^(.*_stage)(\\d+)$");
            if (stage.Success && files.Contains("textures/blocks/" + stage.Groups[1].Value + "_" + stage.Groups[2].Value))
                return "textures/blocks/" + stage.Groups[1].Value + "_" + stage.Groups[2].Value;
            string[] tails = { "_top", "up", "_bottom", "down", "_side", "side", "_front", "front", "_back", "back", "_end", "up", "", "" };
            for (int i = 0; i < tails.Length; i += 2)
            {
                if (tails[i].Length > 0 && !j.EndsWith(tails[i])) continue;
                string id = j.Substring(0, j.Length - tails[i].Length);
                List<string> ids = new List<string>();
                ids.Add(id);
                for (int k = 0; k < BlockIds.Length; k += 2) if (BlockIds[k] == id) ids.Add(BlockIds[k + 1]);
                foreach (string bid in ids)
                {
                    object t;
                    if (!blocks.TryGetValue(bid, out t)) continue;
                    string face = tails[i + 1];
                    // у двери в Bedrock верхняя половина записана как «бок», нижняя — как «низ»
                    if (id.EndsWith("_door") && tails[i] == "_top") face = "side";
                    string path = TerrainPath(Face(t, face));
                    if (path != null) return path;
                }
            }
            // блока с таким названием нет, но есть текстура с таким коротким именем
            return TerrainPath(j);
        }

