        static string ItemTarget(string j)
        {
            if (j.IndexOf((char)47) >= 0) return null;
            string same = "textures/items/" + j;
            if (files.Count == 0 || files.Contains(same)) return same;
            for (int k = 0; k < Items.Length; k += 2)
                if (Items[k] == j && files.Contains("textures/items/" + Items[k + 1])) return "textures/items/" + Items[k + 1];
            return null;
        }

        static string Armor(string material, string layer)
        {
            string m = material == "golden" ? "gold" : (material == "chainmail" ? "chain" : (material == "leather" ? "cloth" : (material == "turtle_scute" ? "turtle" : material)));
            string path = "textures/models/armor/" + m + "_" + layer;
            return Known(path) ? path : null;
        }

        // Сущности, у которых путь в двух изданиях разный: Java, Bedrock.
        static readonly string[] Entities = {
            "enderdragon/dragon", "dragon/dragon", "shulker/shulker", "shulker/shulker_undyed", "player/wide/steve", "steve", "player/slim/alex", "alex",
            "boat/oak", "boat/boat_oak", "boat/spruce", "boat/boat_spruce", "boat/birch", "boat/boat_birch", "boat/jungle", "boat/boat_jungle",
            "boat/acacia", "boat/boat_acacia", "boat/dark_oak", "boat/boat_darkoak", "illager/evoker", "illager/evoker", "illager/vindicator", "vindicator",
            "illager/pillager", "pillager", "illager/ravager", "illager/ravager", "end_crystal/end_crystal", "endercrystal/endercrystal",
            "zombie_villager/zombie_villager", "zombie_villager/zombie_villager", "fish/cod", "fish/cod", "fish/salmon", "fish/salmon",
            "turtle/big_sea_turtle", "sea_turtle", "trident", "trident", "elytra", "../models/armor/elytra" };

        static string EntityTarget(string j)
        {
            if (j.StartsWith("equipment/humanoid/")) return Armor(j.Substring(19), "1");
            if (j.StartsWith("equipment/humanoid_leggings/")) return Armor(j.Substring(28), "2");
            string same = "textures/entity/" + j;
            if (files.Count == 0 || files.Contains(same)) return same;
            for (int k = 0; k < Entities.Length; k += 2)
            {
                if (Entities[k] != j) continue;
                string path = Entities[k + 1].StartsWith("../") ? "textures/" + Entities[k + 1].Substring(3) : "textures/entity/" + Entities[k + 1];
                if (files.Contains(path)) return path;
            }
            return null;
        }

        // Путь картинки Java (относительно папки textures, без расширения) -> путь в пакете Bedrock или null.
        static string Target(string rel)
        {
            int slash = rel.IndexOf((char)47);
            if (slash < 0) return null;
            string top = rel.Substring(0, slash), rest = rel.Substring(slash + 1);
            if (top == "block" || top == "blocks") return BlockTarget(rest);
            if (top == "item" || top == "items") return ItemTarget(rest);
            if (top == "entity") return EntityTarget(rest);
            if (top == "models" && rest.StartsWith("armor/"))
            {
                string a = rest.Substring(6);
                int cut = a.IndexOf("_layer_");
                return cut > 0 ? Armor(a.Substring(0, cut), a.Substring(cut + 7)) : null;
            }
            string same = "textures/" + rel;
            return Known(same) ? same : null;
        }

        static List<object> Ver(int a, int b, int c)
        {
            List<object> v = new List<object>();
            v.Add(new JLit(a.ToString()));
            v.Add(new JLit(b.ToString()));
            v.Add(new JLit(c.ToString()));
            return v;
        }

        public static void Convert(string javaRoot, string name, string outDir, List<string> notes)
        {
            EnsureData();
            UTF8Encoding utf = new UTF8Encoding(false);
            Directory.CreateDirectory(outDir);
            string tex = Path.Combine(Path.Combine(Path.Combine(javaRoot, "assets"), "minecraft"), "textures");
            HashSet<string> taken = new HashSet<string>();
            List<object> flips = new List<object>();
            int done = 0, lost = 0;
            List<string> all = new List<string>(Directory.GetFiles(tex, "*.*", SearchOption.AllDirectories));
            all.Sort(StringComparer.OrdinalIgnoreCase);
            foreach (string file in all)
            {
                if (!Img.IsImage(file)) continue;
                string rel = file.Substring(tex.Length + 1).Replace((char)92, (char)47).ToLowerInvariant();
                rel = rel.Substring(0, rel.Length - Path.GetExtension(rel).Length);
                string target = Target(rel);
                if (target == null) { lost++; continue; }
                if (!taken.Add(target)) continue; // на это место уже легла другая картинка (у Bedrock одна текстура на верх и низ)
                string dest = Path.Combine(outDir, target.Replace((char)47, (char)92) + Path.GetExtension(file).ToLowerInvariant());
                Directory.CreateDirectory(Path.GetDirectoryName(dest));
                File.Copy(file, dest, true);
                done++;
                // своя анимация (файл .mcmeta рядом с картинкой) переносится в список анимаций Bedrock,
                // если у игры для этой текстуры анимации ещё нет
                string tile;
                if (!File.Exists(file + ".mcmeta") || !shortOf.TryGetValue(target, out tile) || flipbooks.Contains("\"" + target + "\"")) continue;
                try
                {
                    JObj meta = Json.Parse(File.ReadAllText(file + ".mcmeta")) as JObj;
                    JObj anim = meta == null ? null : meta.Get("animation") as JObj;
                    if (anim == null) continue;
                    JLit time = anim.Get("frametime") as JLit;
                    JObj flip = new JObj();
                    flip.Set("flipbook_texture", target);
                    flip.Set("atlas_tile", tile);
                    flip.Set("ticks_per_frame", new JLit(time == null ? "1" : time.Raw));
                    JLit blend = anim.Get("interpolate") as JLit;
                    if (blend != null && blend.Raw == "true") flip.Set("blend_frames", new JLit("true"));
                    flips.Add(flip);
                }
                catch (Exception) { }
            }
            if (flips.Count > 0)
            {
                Directory.CreateDirectory(Path.Combine(outDir, "textures"));
                File.WriteAllText(Path.Combine(Path.Combine(outDir, "textures"), "flipbook_textures.json"), Json.Write(flips) + "\n", utf);
            }
            // название — по имени файла пакета, описание — из pack.mcmeta
            string about = "";
            try
            {
                JObj meta = Json.Parse(File.ReadAllText(Path.Combine(javaRoot, "pack.mcmeta"))) as JObj;
                JObj pack = meta == null ? null : meta.Get("pack") as JObj;
                about = (pack == null ? null : pack.Get("description") as string) ?? "";
            }
            catch (Exception) { }
            JObj header = new JObj(), module = new JObj(), man = new JObj();
            header.Set("name", name);
            header.Set("description", about);
            header.Set("uuid", Guid.NewGuid().ToString());
            header.Set("version", Ver(1, 0, 0));
            header.Set("min_engine_version", Ver(1, 21, 0));
            module.Set("type", "resources");
            module.Set("uuid", Guid.NewGuid().ToString());
            module.Set("version", Ver(1, 0, 0));
            List<object> modules = new List<object>();
            modules.Add(module);
            man.Set("format_version", new JLit("2"));
            man.Set("header", header);
            man.Set("modules", modules);
            File.WriteAllText(Path.Combine(outDir, "manifest.json"), Json.Write(man) + "\n", utf);
            try
            {
                string icon = Path.Combine(javaRoot, "pack.png");
                if (File.Exists(icon)) File.Copy(icon, Path.Combine(outDir, "pack_icon.png"), true);
            }
            catch (Exception) { }
            // авторство и лицензия Java-пакета не должны потеряться при переводе
            try
            {
                foreach (string lf in Directory.GetFiles(javaRoot))
                    if (Builder.IsCreditFile(Path.GetFileName(lf))) File.Copy(lf, Path.Combine(outDir, Path.GetFileName(lf)), true);
            }
            catch (Exception) { }
            notes.Add("«" + name + L.T("»: пакет Java-издания переведён в вид Bedrock. Текстур перенесено: ") + done + L.T("; без соответствия в Bedrock осталось: ") + lost + ".");
            if (files.Count == 0) notes.Add(L.T("Игра не найдена: текстуры Java-пакета перенесены под своими именами, без сверки с именами Bedrock."));
        }
    }

    // Сработал предел распаковки одного источника (объём, число файлов, вложенные архивы). Отдельный тип нужен, чтобы
    // отличать его от просто испорченного вложенного архива: тот пропускается, а предел останавливает загрузку.
    class SourceLimitException : IOException
    {
        public SourceLimitException(string message) : base(message) { }
    }

    static class PackLoader
    {
        // Куда распаковываются архивы пакетов: папка BRPC-temp рядом с самой программой. Если туда нельзя писать
        // (программа лежит в защищённом месте), берётся такая же папка во временной папке Windows.
        public static string TempBase = PickTemp();

        // Каждая папка, которую программа распаковала, получает рядом файл-метку «<папка>.brpc-temp». Очистка удаляет
        // только помеченные папки: чужие файлы и папки, оказавшиеся в той же папке, она не трогает никогда.
        const string MarkExt = ".brpc-temp";

        static string MarkOf(string dir)
        {
            return dir.TrimEnd((char)92, (char)47) + MarkExt;
        }

        static void MarkTemp(string dir)
        {
            Directory.CreateDirectory(dir);
            File.WriteAllText(MarkOf(dir), "BRPC: unpacked pack, safe to delete together with the folder next to this file");
        }

        // Помеченные папки распаковки в обоих местах.
        static List<string> MarkedDirs()
        {
            List<string> r = new List<string>();
            foreach (string place in new string[] { TempBase, ShortBase })
                try
                {
                    if (!Directory.Exists(place)) continue;
                    foreach (string dir in Directory.GetDirectories(place))
                        if (File.Exists(MarkOf(dir))) r.Add(dir);
                }
                catch (Exception) { }
            return r;
        }

        // Название источника: у архива — имя без расширения, у папки — её имя целиком («Faithful 1.20.4» не обрезается до «Faithful 1.20»).
        public static string BaseName(string path)
        {
            string t = path.TrimEnd((char)92, (char)47);
            string n = Directory.Exists(path) ? Path.GetFileName(t) : Path.GetFileNameWithoutExtension(t);
            return n.Length == 0 ? t : n;
        }

        // Папка для распаковки одного архива: «название файла дата время» — по ней видно, что и когда распаковано.
        public static string TempDirFor(string source, string mark)
        {
            string name = BaseName(source);
            foreach (char c in Path.GetInvalidFileNameChars()) name = name.Replace(c, (char)95);
            name = name.Trim().TrimEnd((char)46);
            if (name.Length > 40) name = name.Substring(0, 40).Trim(); // путь внутри пакета тоже длинный, а предел Windows — 260 знаков
            if (name.Length == 0) name = "pack";
            string head = Path.Combine(TempBase, name + mark + " " + DateTime.Now.ToString("yyyy-MM-dd HH-mm-ss")), dir = head;
            for (int n = 2; Directory.Exists(dir); n++) dir = head + " (" + n + ")";
            return dir;
        }

        // Запасное место распаковки с коротким путём. Windows не даёт создать файл с путём длиннее 260 знаков, и если
        // программа сама лежит глубоко, а в архиве длинные имена (или архив в архиве), часть файлов молча терялась бы.
        static readonly string ShortBase = Path.Combine(Path.GetTempPath(), "BRPC");

        static string ShortTemp()
        {
            return Path.Combine(ShortBase, Guid.NewGuid().ToString("N").Substring(0, 8));
        }

        // Самый длинный путь внутри архива (в знаках); с запасом на архив, вложенный в архив.
        static int LongestInside(string zipPath)
        {
            int most = 0;
            bool nested = false;
            try
            {
                using (ZipArchive z = ZipFile.OpenRead(zipPath))
                    foreach (ZipArchiveEntry e in z.Entries)
                    {
                        most = Math.Max(most, e.FullName.Length);
                        string ext = Path.GetExtension(e.FullName).ToLowerInvariant();
                        if (ext == ".mcpack" || ext == ".zip" || ext == ".mcaddon") nested = true;
                    }
            }
            catch (Exception) { }
            return most + (nested ? 80 : 0);
        }

        // Сколько занимают распакованные программой пакеты (байт) и есть ли они вообще.
        // Папка BRPC-temp принадлежит программе (решение автора 22.10.2026): при очистке из неё убирается всё.
        // Защита от ошибки: так чистится только папка с этим именем, никакая другая.
        static bool OwnBase()
        {
            return string.Equals(Path.GetFileName(TempBase.TrimEnd((char)92, (char)47)), "BRPC-temp", StringComparison.OrdinalIgnoreCase) && Directory.Exists(TempBase);
        }

        // Всё, что лежит в BRPC-temp, и помеченные папки в общей %TEMP%\BRPC.
        static List<string> ClearableDirs()
        {
            List<string> r = MarkedDirs();
            if (OwnBase())
                try { foreach (string dir in Directory.GetDirectories(TempBase)) if (!r.Contains(dir)) r.Add(dir); }
                catch (Exception) { }
            return r;
        }

        public static long TempSize()
        {
            long total = 0;
            if (OwnBase())
                try { foreach (string file in Directory.GetFiles(TempBase)) try { total += new FileInfo(file).Length; } catch (Exception) { } }
                catch (Exception) { }
            foreach (string dir in ClearableDirs())
                try
                {
                    foreach (string file in Directory.GetFiles(dir, "*", SearchOption.AllDirectories))
                        try { total += new FileInfo(file).Length; } catch (Exception) { }
                }
                catch (Exception) { }
            return total;
        }

        public static bool TempUsed()
        {
            if (ClearableDirs().Count > 0) return true;
            try { return OwnBase() && Directory.GetFiles(TempBase).Length > 0; }
            catch (Exception) { return false; }
        }

        // Очистка: всё содержимое BRPC-temp и помеченные папки в общей %TEMP%\BRPC.
        public static void ClearTemp()
        {
            foreach (string dir in MarkedDirs()) DropTemp(dir);
            if (!OwnBase()) return;
            try
            {
                foreach (string dir in Directory.GetDirectories(TempBase)) try { Directory.Delete(dir, true); } catch (Exception) { }
                foreach (string file in Directory.GetFiles(TempBase)) try { File.Delete(file); } catch (Exception) { }
            }
            catch (Exception) { }
        }

        static string PickTemp()
        {
            try
            {
                string near = Path.Combine(Path.GetDirectoryName(System.Reflection.Assembly.GetExecutingAssembly().Location), "BRPC-temp");
                Directory.CreateDirectory(near);
                string probe = Path.Combine(near, Guid.NewGuid().ToString("N") + ".tmp");
                File.WriteAllText(probe, "");
                File.Delete(probe);
                return near;
            }
            catch (Exception) { }
            return Path.Combine(Path.GetTempPath(), "BRPC-temp");
        }

        public static int[] ReadVersion(object o)
        {
            List<object> l = o as List<object>;
            if (l == null || l.Count < 3) return null;
            int[] r = new int[3];
            for (int i = 0; i < 3; i++)
            {
                JLit lit = l[i] as JLit;
                if (lit == null || !int.TryParse(lit.Raw, out r[i])) return null;
            }
            return r;
        }

        // Возвращает найденные ресурс-паки; в notes — замечания для пользователя.
        public static List<Pack> Load(string path, List<string> notes)
        {
            string tempDir = null;
            bool tight = false; // путь к папке temp слишком длинный для этого архива: распаковка идёт в запасное место
            // manifest.json, перетащенный в окно или переданный при запуске, означает папку, в которой он лежит
            if (File.Exists(path) && string.Equals(Path.GetFileName(path), "manifest.json", StringComparison.OrdinalIgnoreCase))
                path = Path.GetDirectoryName(Path.GetFullPath(path));
            if (File.Exists(path))
            {
                tempDir = TempDirFor(path, "");
                tight = tempDir.Length + 1 + LongestInside(path) > 240;
                if (tight) tempDir = ShortTemp();
                MarkTemp(tempDir);
            }
            else if (!Directory.Exists(path)) throw new FileNotFoundException(L.T("Не найдено: ") + path);
            List<Pack> found = null;
            try
            {
                if (tempDir != null)
                {
                    bytesLeft = SourceBytes;
                    nestedLeft = SourceNested;
                    Extract(path, tempDir);
                    Unwrap(tempDir, 0);
                }
                string javaRoot = JavaPack.Find(tempDir ?? path);
                if (javaRoot != null)
                {
                    // пакет Java-издания: в программу попадает его перевод в вид Bedrock, сделанный во временной папке
                    string made = tight || TempBase.Length > 120 ? ShortTemp() : TempDirFor(path, " (java)");
                    try
                    {
                        MarkTemp(made);
                        JavaPack.Convert(javaRoot, BaseName(path), made, notes);
                        found = LoadFrom(path, made, made, notes);
                        foreach (Pack jp in found) jp.Java = true;
                    }
                    finally
                    {
                        if (tempDir != null) DropTemp(tempDir);
                        if (found == null || found.Count == 0) DropTemp(made);
                        tempDir = null;
                    }
                    return found;
                }
                found = LoadFrom(path, tempDir ?? path, tempDir, notes);
                return found;
            }
            finally
            {
                // архив не подошёл или не прочитался — распакованное не оставляем
                if (tempDir != null && (found == null || found.Count == 0)) DropTemp(tempDir);
            }
        }

        // Архив, в котором самого пакета нет, а лежат другие архивы (пакет, завёрнутый ещё в один .mcpack, как в .mcaddon):
        // вложенные архивы распаковываются на месте, и пакеты внутри находятся как обычно.
        static int unwrapped; // счётчик вложенных архивов: из него делаются короткие имена их папок

        // Пределы на один добавляемый источник вместе со всеми вложенными архивами: защита от «архивных бомб».
        const long SourceBytes = 4L * 1024 * 1024 * 1024;
        const int SourceNested = 200;
        static long bytesLeft = SourceBytes;
        static int nestedLeft = SourceNested;

        static void Unwrap(string dir, int depth)
        {
            try
            {
                if (Directory.GetFiles(dir, "manifest.json", SearchOption.AllDirectories).Length > 0) return;
                foreach (string file in Directory.GetFiles(dir, "*.*", SearchOption.AllDirectories))
                {
                    string ext = Path.GetExtension(file).ToLowerInvariant();
                    if (ext != ".mcpack" && ext != ".zip" && ext != ".mcaddon") continue;
                    if (--nestedLeft < 0) throw new SourceLimitException(L.T("В архиве слишком много вложенных архивов (больше ") + SourceNested + ").");
                    // короткое имя папки: у вложенного архива путь и так длинный
                    string sub = Path.Combine(Path.GetDirectoryName(file), "p" + (++unwrapped));
                    try
                    {
                        Extract(file, sub);
                        File.Delete(file);
                        if (depth < 2) Unwrap(sub, depth + 1);
                    }
                    catch (SourceLimitException) { throw; } // сработал предел — загрузка источника останавливается; битый вложенный архив просто пропускается
                    catch (Exception) { }
                }
            }
            catch (SourceLimitException) { throw; }
            catch (Exception) { }
        }

        // Удалить одну папку распаковки — только если программа сама её создала и пометила.
        public static void DropTemp(string dir)
        {
            if (dir == null) return;
            string mark = MarkOf(dir);
            try
            {
                if (!File.Exists(mark)) return;
                if (Directory.Exists(dir)) Directory.Delete(dir, true);
                File.Delete(mark);
            }
            catch (Exception) { }
        }

        static List<Pack> LoadFrom(string path, string root, string tempDir, List<string> notes)
        {

            List<string> manifests = new List<string>();
            if (File.Exists(Path.Combine(root, "manifest.json"))) manifests.Add(Path.Combine(root, "manifest.json"));
            else manifests.AddRange(Directory.GetFiles(root, "manifest.json", SearchOption.AllDirectories));

            List<Pack> res = new List<Pack>();
            foreach (string m in manifests)
            {
                Pack p = new Pack();
                p.Root = Path.GetDirectoryName(m);
                p.TempDir = tempDir;
                p.Name = Path.GetFileName(p.Root);
                bool resources = true;
                try
                {
                    JObj man = Json.Parse(File.ReadAllText(m)) as JObj;
                    JObj header = man == null ? null : man.Get("header") as JObj;
                    if (header != null)
                    {
                        string n = header.Get("name") as string;
                        if (!string.IsNullOrEmpty(n)) p.Name = n;
                        p.MinEngine = ReadVersion(header.Get("min_engine_version"));
                    }
                    if (man != null)
                    {
                        p.Capabilities = man.Get("capabilities") as List<object>;
                        p.Subpacks = man.Get("subpacks") as List<object>;
                    }
                    List<object> mods = man == null ? null : man.Get("modules") as List<object>;
                    if (mods != null && mods.Count > 0)
                    {
                        resources = false;
                        foreach (object mo in mods)
                        {
                            JObj mod = mo as JObj;
                            string t = mod == null ? null : mod.Get("type") as string;
                            if (t == null || t == "resources" || t == "skin_pack") resources = true;
                        }
                    }
                }
                catch (Exception ex)
                {
                    notes.Add(L.T("manifest.json в «") + p.Name + L.T("» не читается: ") + ex.Message);
                }
                if (!resources)
                {
                    notes.Add("«" + p.Name + L.T("» — это не ресурс-пак (поведенческий), пропущен."));
                    continue;
                }
                p.Scan();
                if (p.Subpacks != null && p.Subpacks.Count > 0) p.SetSub(Pack.SubFolderOf(p.Subpacks[0]));
                if (p.Name == "pack.name") p.Name = LangName(p) ?? BaseName(path);
                res.Add(p);
            }
            if (res.Count == 0 && manifests.Count == 0)
            {
                Pack p = new Pack();
                p.Root = root;
                p.TempDir = tempDir;
                p.Name = BaseName(path);
                p.Scan();
                notes.Add(L.T("В «") + p.Name + L.T("» нет manifest.json — добавлен как обычная папка с файлами."));
                res.Add(p);
            }
            for (int i = 0; i < res.Count; i++)
            {
                res[i].Origin = path;
                res[i].OriginIndex = i;
                List<string> bad = new List<string>();
                foreach (string rel in res[i].Files.Values) if (Risk.Program(rel)) bad.Add(Path.GetFileName(rel));
                if (bad.Count > 0)
                    notes.Add("«" + res[i].Name + L.T("»: внутри есть файлы-программы, которым не место в пакете ресурсов (") + bad.Count
                        + L.T("). Не запускайте их; в сборку они не попадут: ") + string.Join(", ", bad.GetRange(0, Math.Min(6, bad.Count)).ToArray()) + (bad.Count > 6 ? "…" : ""));
            }
            return res;
        }

        static string LangName(Pack p)
        {
            List<string> keys = new List<string>();
            if (p.Files.ContainsKey("texts/en_us.lang")) keys.Add("texts/en_us.lang");
            foreach (string key in p.Files.Keys)
                if (key.StartsWith("texts/") && key.EndsWith(".lang") && key != "texts/en_us.lang") keys.Add(key);
            foreach (string key in keys)
            {
                try
                {
                    foreach (string line in File.ReadAllLines(p.FullPath(key)))
                        if (line.StartsWith("pack.name="))
                            return line.Substring(10).Split('\t')[0].Trim();
                }
                catch (Exception) { }
            }
            return null;
        }

        static void Extract(string zipPath, string dir)
        {
            string full = Path.GetFullPath(dir) + Path.DirectorySeparatorChar;
            Directory.CreateDirectory(dir);
            // общий остаток на весь источник: вложенные архивы не получают каждый свои 4 ГБ
            int count = 0;
            byte[] buf = new byte[81920];
            using (ZipArchive zip = ZipFile.OpenRead(zipPath))
            {
                foreach (ZipArchiveEntry en in zip.Entries)
                {
                    string name = en.FullName.Replace('\\', '/');
                    if (name.EndsWith("/") || name.Length == 0) continue;
                    if (++count > 200000) throw new SourceLimitException(L.T("Архив слишком большой."));
                    string dest;
                    try
                    {
                        dest = Path.GetFullPath(Path.Combine(dir, name.Replace('/', Path.DirectorySeparatorChar)));
                        if (!dest.StartsWith(full, StringComparison.OrdinalIgnoreCase)) continue; // выход за пределы папки
                        Directory.CreateDirectory(Path.GetDirectoryName(dest));
                    }
                    catch (ArgumentException) { continue; }      // имя, которого не бывает в Windows
                    catch (NotSupportedException) { continue; }
                    catch (PathTooLongException) { continue; }
                    catch (IOException) { continue; }
                    // считаем настоящие байты, а не заявленный в архиве размер
                    using (Stream src = en.Open())
                    using (FileStream dst = new FileStream(dest, FileMode.Create, FileAccess.Write))
                    {
                        int n;
                        while ((n = src.Read(buf, 0, buf.Length)) > 0)
                        {
                            bytesLeft -= n;
                            if (bytesLeft < 0) throw new SourceLimitException(L.T("Архив слишком большой: после распаковки больше 4 ГБ."));
                            dst.Write(buf, 0, n);
                        }
                    }
                }
            }
        }
    }

    // Один файл итоговой сборки.
    class Entry
    {
        public string Key;
        public string Rel;
        public List<Pack> Sources = new List<Pack>(); // по убыванию приоритета
        public Pack Winner;
        public bool AutoMerge;
        public bool Locked;   // источник задан набором PBR, вручную не выбирается
        public bool Hidden;   // служебный файл набора PBR, отдельной карточкой не показывается
        public bool Excluded; // выключено пользователем, в сборку не идёт
        public List<Pack> Pbr; // паки, в которых у этой текстуры есть набор PBR; null — наборов нет
        public Pack PbrChoice; // из какого пака взят набор; null — без набора
        public bool PbrAuto;   // набор подтянут программой из другого пакета, пользователь его не выбирал
        public bool Orphan;    // карта отражений или рельефа, которую ничто не использует: в сборку не идёт
        public bool LayersOnly; // текстура выключена, но её слои выбраны: в сборку идут только они
        public string ColorFix; // для texture_set.json: на какой файл перенаправить слой цвета
        // дополнительные слои текстуры по пакам: имя слоя (normal, heightmap…) -> путь к файлу
        public Dictionary<Pack, List<KeyValuePair<string, string>>> Attrs;
        // из какого пака взят каждый вид слоя: "mer" — отражения и свечение, "relief" — рельеф; нет записи — слой выключен
        public Dictionary<string, Pack> Slots;
        // для texture_set.json, собранного из слоёв разных паков: имя слоя -> файл
        public Dictionary<string, string> SetPatch;
    }

    // Дополнительный случайный вариант текстуры блока: картинка из пакета P и слои для неё (null — без слоя).
    class Variant
    {
        public Pack P, Mer, Relief;
    }

    // Тот же вариант, разобранный для сборки: какие файлы взять.
    class VariantOut
    {
        public Entry E;
        public string Color; // файл картинки
        public List<KeyValuePair<string, string>> Layers = new List<KeyValuePair<string, string>>(); // ключ слоя в наборе -> файл
    }

    enum MergeKind { Json, Union, Flipbook, Lang, None }

    // Разобранный JSON одного файла сборки вместе с тем, какие определения в нём есть.
    class Doc
    {
        public Entry E;
        public object Root;
        // "вид|идентификатор" -> номер самого важного пака, где это определение есть в данном файле
        public Dictionary<string, int> DefRank = new Dictionary<string, int>();
        public int Rank = int.MaxValue;
        public bool Drop, Changed;
    }

    static class Builder
    {
        public static MergeKind KindOf(string key)
        {
            switch (key)
            {
                case "texts/languages.json":
                case "textures/textures_list.json":
                case "ui/_ui_defs.json":
                    return MergeKind.Union;
                case "textures/flipbook_textures.json":
                    return MergeKind.Flipbook;
            }
            if (key.EndsWith(".lang")) return MergeKind.Lang;
            if (ShaderConfig(key)) return MergeKind.None; // настройки шейдера не объединяются, см. ShaderConfig
            if (key.EndsWith(SetSuffix)) return MergeKind.None; // наборы PBR не объединяются, см. Collect
            if (key.EndsWith(".json") || key.EndsWith(".material")) return MergeKind.Json;
            return MergeKind.None;
        }

        // Настройки освещения, атмосферы и цветокоррекции (шейдеры). Числа в них подобраны друг под друга, поэтому
        // файл берётся целиком из одного пакета, как это делает игра: смесь двух шейдеров даёт резкие скачки света.
        public static bool ShaderConfig(string key)
        {
            return key.StartsWith("lighting/") || key.StartsWith("atmospherics/") || key.StartsWith("color_grading/")
                || key.StartsWith("pbr/") || key.StartsWith("point_lights/") || key.StartsWith("local_lighting/")
                || key.StartsWith("shadows/") || key.StartsWith("water/") || key.StartsWith("cubemaps/");
        }

        // Пакет, который задаёт освещение сборки: самый важный из тех, где есть папка lighting. others — есть ли ещё такие.
        static Pack LightOwner(List<Pack> packs, out bool others)
        {
            Pack owner = null;
            others = false;
            foreach (Pack p in packs)
            {
                bool has = false;
                foreach (string k in p.Files.Keys) if (k.StartsWith("lighting/")) { has = true; break; }
                if (!has) continue;
                if (owner == null) owner = p; else others = true;
            }
            return owner;
        }

        // В описании биома освещение, атмосферу и цветокоррекцию назначает только пакет, задающий освещение сборки:
        // у остальных пакетов эти три назначения убираются, прочее (туман, цвет воды и неба) объединяется как обычно.
        static void StripLighting(object root)
        {
            JObj r = root as JObj;
            JObj biome = r == null ? null : r.Get("minecraft:client_biome") as JObj;
            JObj comps = biome == null ? null : biome.Get("components") as JObj;
            if (comps == null) return;
            foreach (string k in new string[] { "minecraft:lighting_identifier", "minecraft:atmosphere_identifier", "minecraft:color_grading_identifier" })
                if (comps.Map.ContainsKey(k)) { comps.Map.Remove(k); comps.Keys.Remove(k); }
        }

        // Папки, где игра различает объекты по идентификатору внутри файла, а не по имени файла.
        static bool DefFolder(string key)
        {
            return key.StartsWith("entity/") || key.StartsWith("attachables/") || key.StartsWith("animations/")
                || key.StartsWith("animation_controllers/") || key.StartsWith("render_controllers/")
                || key.StartsWith("models/") || key.StartsWith("particles/") || key.StartsWith("fogs/");
        }

        static bool Skipped(string key)
        {
            // manifest создаётся заново; contents/signatures относятся к исходному паку и после слияния неверны
            return key == "manifest.json" || key == "contents.json" || key == "signatures.json"
                || key.StartsWith(".git/") || key.EndsWith("/thumbs.db") || key.EndsWith(".ds_store");
        }

        static string NoExt(string key)
        {
            return key.Substring(0, key.Length - Path.GetExtension(key).Length);
        }

        // Паки вместе с выбранными вариантами, по убыванию приоритета.
        static List<Pack> Layers(List<Pack> packs)
        {
            List<Pack> r = new List<Pack>();
            foreach (Pack p in packs)
            {
                if (p.Sub != null) r.Add(p.Sub);
                r.Add(p);
            }
            return r;
        }

        public static List<Entry> Collect(List<Pack> packs, Dictionary<string, Pack> overrides, Dictionary<string, Pack> pbr,
            Dictionary<string, Pack> slots)
        {
            packs = Layers(packs);
            Dictionary<string, Entry> map = new Dictionary<string, Entry>();
            foreach (Pack p in packs)
            {
                foreach (KeyValuePair<string, string> kv in p.Files)
                {
                    if (Skipped(kv.Key)) continue;
                    Entry e;
                    if (!map.TryGetValue(kv.Key, out e))
                    {
                        e = new Entry();
                        e.Key = kv.Key;
                        e.Rel = kv.Value;
                        map[kv.Key] = e;
                    }
                    e.Sources.Add(p);
                }
            }
            List<Entry> list = new List<Entry>(map.Values);
            foreach (Entry e in list)
            {
                Pack o;
                e.Winner = e.Sources[0];
                e.AutoMerge = e.Sources.Count > 1 && KindOf(e.Key) != MergeKind.None;
                if (overrides.TryGetValue(e.Key, out o))
                {
                    if (o == Pack.Off) e.Excluded = !e.AutoMerge;
                    else if (e.Sources.Contains(o)) e.Winner = o;
                }
                e.Rel = e.Winner.Files[e.Key];
            }

            // Наборы PBR (texture_set.json): отражения, свечение и рельеф текстуры. Игра требует, чтобы все слои
            // набора лежали в одном паке, и не объединяет описания из разных паков. Поэтому набор берётся целиком
            // из одного пака; какого — выбирается у самой текстуры (Entry.PbrChoice).
            Dictionary<string, Pack> needed = new Dictionary<string, Pack>(); // слой без расширения -> из какого пака нужен
            List<Entry> layers = new List<Entry>();
            List<Entry> dropped = new List<Entry>();
            foreach (Entry ts in list)
            {
                if (!ts.Key.EndsWith(SetSuffix)) continue;
                string res = ts.Key.Substring(0, ts.Key.Length - SetSuffix.Length);
                string dir = res.Substring(0, res.LastIndexOf('/') + 1);
                Entry img = null;
                bool chosen = false;
                foreach (string ext in ImgExts)
                {
                    Entry c;
                    if (!map.TryGetValue(res + ext, out c)) continue;
                    bool co = overrides.ContainsKey(c.Key);
                    if (img == null || (co && !chosen) || (co == chosen && packs.IndexOf(c.Winner) < packs.IndexOf(img.Winner)))
                    {
                        img = c;
                        chosen = co;
                    }
                }
                if (img == null)
                {
                    // картинка цвета названа не так, как сам набор: карточкой текстуры служит она
                    foreach (KeyValuePair<string, string> l in SetLayers(ts.Sources[0].FullPath(ts.Key)))
                    {
                        if (l.Key != "color") continue;
                        foreach (string ext in ImgExts)
                        {
                            Entry c;
                            if (img == null && map.TryGetValue(LayerKey(dir, l.Value) + ext, out c)) img = c;
                        }
                    }
                }
                string imgBase = img == null ? res : NoExt(img.Key);
                ts.Locked = true;
                ts.Hidden = true;
                Pack q;
                if (img == null)
                {
                    // цвет задан числом, а не картинкой: карточки нет, но слои всё равно служебные и в списке не показываются
                    q = ts.Sources[0];
                    foreach (Pack src in ts.Sources)
                    {
                        foreach (KeyValuePair<string, string> l in SetLayers(src.FullPath(ts.Key)))
                        {
                            foreach (string ext in ImgExts)
                            {
                                Entry le;
                                if (!map.TryGetValue(LayerKey(dir, l.Value) + ext, out le) || le.Hidden) continue;
                                le.Hidden = true;
                                le.Locked = true;
                                layers.Add(le);
                            }
                        }
                    }
                }
                else
                {
                    img.Pbr = new List<Pack>(ts.Sources);
                    // по умолчанию — как в игре: набор того же пака, что и текстура, иначе без набора
                    Pack def = ts.Sources.Contains(img.Winner) ? img.Winner : (KeepPbr ? ts.Sources[0] : null);
                    bool auto = !pbr.TryGetValue(img.Key, out q);
                    if (auto) q = def;
                    else if (q == Pack.Off) q = null;
                    else if (!ts.Sources.Contains(q)) q = def;
                    if (img.Excluded) q = null;
                    img.PbrChoice = q;
                    img.PbrAuto = auto && q != null && q != img.Winner
                        && !slots.ContainsKey(img.Key + "|mer") && !slots.ContainsKey(img.Key + "|relief");
                    // слои наборов из всех паков — служебные файлы, отдельными карточками не показываются
                    img.Attrs = new Dictionary<Pack, List<KeyValuePair<string, string>>>();
                    foreach (Pack src in ts.Sources)
                    {
                        List<KeyValuePair<string, string>> attrs = new List<KeyValuePair<string, string>>();
                        img.Attrs[src] = attrs;
                        foreach (KeyValuePair<string, string> l in SetLayers(src.FullPath(ts.Key)))
                        {
                            string lk = LayerKey(dir, l.Value);
                            if (lk == imgBase) continue;
                            foreach (string ext in ImgExts)
                            {
                                if (!src.Files.ContainsKey(lk + ext)) continue;
                                attrs.Add(new KeyValuePair<string, string>(l.Key, src.FullPath(lk + ext)));
                                break;
                            }
                            foreach (string ext in ImgExts)
                            {
                                Entry le;
                                if (!map.TryGetValue(lk + ext, out le) || le.Hidden) continue;
                                le.Hidden = true;
                                le.Locked = true;
                                layers.Add(le);
                            }
                        }
                    }

                    // Слои по отдельности. Сначала — как в выбранном наборе, затем правки пользователя:
                    // любой слой можно выключить или взять из набора другого пака.
                    Dictionary<string, Pack> slotPack = new Dictionary<string, Pack>();
                    if (q != null)
                        foreach (KeyValuePair<string, string> l in SetLayers(q.FullPath(ts.Key)))
                            if (l.Key != "color") slotPack[SlotOf(l.Key)] = q;
                    bool custom = false;
                    foreach (string slot in new string[] { "mer", "relief" })
                    {
                        Pack want, cur;
                        if (!slots.TryGetValue(img.Key + "|" + slot, out want)) continue; // слои можно выбрать и у выключенной текстуры
                        slotPack.TryGetValue(slot, out cur);
                        Pack target = want == Pack.Off ? null : (ts.Sources.Contains(want) && SlotLayer(want, ts.Key, slot).Key != null ? want : cur);
                        if (target == cur) continue;
                        custom = true;
                        if (target == null) slotPack.Remove(slot); else slotPack[slot] = target;
                    }
                    img.Slots = slotPack;
                    img.LayersOnly = img.Excluded && slotPack.Count > 0;
                    if (custom)
                    {
                        if (slotPack.Count == 0)
                        {
                            img.PbrChoice = null;
                            dropped.Add(ts);
                            continue;
                        }
                        Pack basePack = q;
                        foreach (Pack sp in slotPack.Values) if (basePack == null) basePack = sp;
                        ts.Winner = basePack;
                        ts.Rel = basePack.Files[ts.Key];
                        ts.SetPatch = new Dictionary<string, string>();
                        img.PbrChoice = null;
                        foreach (KeyValuePair<string, Pack> sp in slotPack)
                        {
                            KeyValuePair<string, string> l = SlotLayer(sp.Value, ts.Key, sp.Key);
                            ts.SetPatch[l.Key] = l.Value;
                            needed[LayerKey(dir, l.Value)] = sp.Value;
                            if (img.PbrChoice == null) img.PbrChoice = sp.Value;
                        }
                        if (img.Winner != basePack) ts.ColorFix = Path.GetFileNameWithoutExtension(img.Rel);
                        else
                        {
                            foreach (KeyValuePair<string, string> l in SetLayers(basePack.FullPath(ts.Key)))
                                if (l.Key == "color" && LayerKey(dir, l.Value) != imgBase) needed[LayerKey(dir, l.Value)] = basePack;
                        }
                        continue;
                    }
                }
                if (q == null) { dropped.Add(ts); continue; }
                ts.Winner = q;
                ts.Rel = q.Files[ts.Key];
                // набор от другого пака: цвет в нём перенаправляется на выбранную текстуру
                bool foreign = img != null && img.Winner != q;
                if (foreign) ts.ColorFix = Path.GetFileNameWithoutExtension(img.Rel);
                foreach (KeyValuePair<string, string> l in SetLayers(q.FullPath(ts.Key)))
                {
                    string lk = LayerKey(dir, l.Value);
                    if ((l.Key == "color" && foreign) || (lk == imgBase && img != null)) continue;
                    needed[lk] = q;
                    if (img != null) continue;
                    foreach (string ext in ImgExts)
                    {
                        Entry le;
                        if (!map.TryGetValue(lk + ext, out le) || !le.Sources.Contains(q)) continue;
                        le.Winner = q;
                        le.Rel = q.Files[le.Key];
                        le.Locked = true;
                    }
                }
            }
            foreach (Entry le in layers)
            {
                Pack q;
                if (needed.TryGetValue(NoExt(le.Key), out q) && le.Sources.Contains(q))
                {
                    le.Excluded = false; // на слой ссылается выбранный набор: старое «выключено» для него не действует
                    le.Winner = q;
                    le.Rel = q.Files[le.Key];
                }
                else dropped.Add(le); // слой невыбранного набора в сборке не нужен
            }
            list.RemoveAll(delegate(Entry e) { return dropped.Contains(e); });

            // Карты отражений и рельефа, на которые не ссылается ни один набор, узнаются по имени:
            // stone_mer рядом со stone — это слой, а не отдельная текстура.
            // Если на такой файл ссылаются списки текстур, это обычная текстура с похожим именем — её не трогаем.
            // Иначе игра его не использует, и в итоговый пакет он не попадает.
            // Картинки интерфейса не трогаем вовсе: там button_normal — обычное имя, а слоёв не бывает.
            HashSet<string> used = Referenced(packs);
            foreach (Entry e in list)
            {
                if (e.Hidden || !Img.IsImage(e.Key)) continue;
                if (e.Key.StartsWith("textures/ui/") || e.Key.StartsWith("textures/gui/")) continue;
                string name = NoExt(e.Key);
                if (used.Contains(name)) continue;
                foreach (string suffix in LayerSuffixes)
                {
                    if (!name.EndsWith(suffix)) continue;
                    string owner = name.Substring(0, name.Length - suffix.Length);
                    foreach (string ext in ImgExts)
                        if (map.ContainsKey(owner + ext)) e.Hidden = e.Orphan = true;
                }
            }

            // Одна и та же текстура в разных форматах (stone.png и stone.tga): игра выбрала бы формат сама,
            // не глядя на приоритет, поэтому оставляем только вариант из более важного пака.
            Dictionary<string, int> best = new Dictionary<string, int>();
            foreach (Entry e in list)
            {
                if (!Img.IsImage(e.Key)) continue;
                int r = ExtRank(e, packs, overrides), cur;
                string b = NoExt(e.Key);
                if (!best.TryGetValue(b, out cur) || r < cur) best[b] = r;
            }
            list.RemoveAll(delegate(Entry e)
            {
                return Img.IsImage(e.Key) && ExtRank(e, packs, overrides) > best[NoExt(e.Key)];
            });

            list.Sort(delegate(Entry a, Entry b) { return string.CompareOrdinal(a.Key, b.Key); });
            return list;
        }

        // Если у пакета с текстурой нет своего набора слоёв, чужой набор сам не подтягивается: слои другой текстуры
        // назначаются только вручную, перетаскиванием значка слоя. (При true брался бы набор самого важного пакета, где он есть.)
        static readonly bool KeepPbr = false;
        const string SetSuffix = ".texture_set.json";
        static readonly string[] ImgExts = { ".png", ".tga", ".jpg", ".jpeg" };
        static readonly string[] LayerSuffixes = { "_mer", "_mers", "_normal", "_heightmap" };
        static Dictionary<string, List<KeyValuePair<string, string>>> setCache = new Dictionary<string, List<KeyValuePair<string, string>>>();

        // Списки, в которых пакет перечисляет свои текстуры блоков, предметов и анимаций.
        static bool IsTexIndex(string key)
        {
            return key == "textures/terrain_texture.json" || key == "textures/item_texture.json" || key == "textures/flipbook_textures.json";
        }

        static string TexKey(string path)
        {
            path = path.ToLowerInvariant().Replace('\\', '/');
            foreach (string ext in ImgExts) if (path.EndsWith(ext)) path = path.Substring(0, path.Length - ext.Length);
            return path;
        }

        static void Strings(object o, List<string> into)
        {
            JObj j = o as JObj;
            List<object> l = o as List<object>;
            if (o is string) into.Add((string)o);
            else if (j != null) foreach (string k in j.Keys) Strings(j.Map[k], into);
            else if (l != null) foreach (object x in l) Strings(x, into);
        }

        static Dictionary<string, List<string>> refCache = new Dictionary<string, List<string>>();

        // Все текстуры, на которые ссылаются списки текстур во всех пакетах.
        static HashSet<string> Referenced(List<Pack> packs)
        {
            HashSet<string> r = new HashSet<string>();
            foreach (Pack p in packs)
            {
                foreach (string key in new string[] { "textures/terrain_texture.json", "textures/item_texture.json", "textures/flipbook_textures.json" })
                {
                    if (!p.Files.ContainsKey(key)) continue;
                    string path = p.FullPath(key), ck = path + "|" + File.GetLastWriteTimeUtc(path).Ticks;
                    List<string> found;
                    if (!refCache.TryGetValue(ck, out found))
                    {
                        found = new List<string>();
                        try { Strings(Json.Parse(File.ReadAllText(path)), found); } catch (Exception) { }
                        refCache[ck] = found;
                    }
                    foreach (string v in found) r.Add(TexKey(v));
                }
            }
            return r;
        }

        // Убирает из списка текстур записи, все текстуры которых пользователь выключил. Возвращает, изменилось ли что-то.
        static bool Prune(object root, HashSet<string> off)
        {
            bool changed = false;
            List<object> flip = root as List<object>;
            if (flip != null)
            {
                changed = flip.RemoveAll(delegate(object x)
                {
                    JObj j = x as JObj;
                    string t = j == null ? null : j.Get("flipbook_texture") as string;
                    return t != null && off.Contains(TexKey(t));
                }) > 0;
                return changed;
            }
            JObj o = root as JObj;
            JObj data = o == null ? null : o.Get("texture_data") as JObj;
            if (data == null) return false;
            foreach (string k in new List<string>(data.Keys))
            {
                JObj entry = data.Map[k] as JObj;
                if (entry == null) continue;
                List<string> paths = new List<string>();
                Strings(entry.Get("textures"), paths);
                paths.RemoveAll(delegate(string v) { return !v.ToLowerInvariant().StartsWith("textures/"); });
                if (paths.Count == 0 || !paths.TrueForAll(delegate(string v) { return off.Contains(TexKey(v)); })) continue;
                data.Remove(k);
                changed = true;
            }
            return changed;
        }

        // Файл textures_list.json составляется заново: ровно те текстуры, что вошли в сборку.
        static byte[] TexList(List<Entry> entries)
        {
            List<string> names = new List<string>();
            foreach (Entry e in entries)
            {
                if (e.Excluded || e.Orphan || !Img.IsImage(e.Key) || !e.Key.StartsWith("textures/")) continue;
                string n = e.Rel.Substring(0, e.Rel.Length - Path.GetExtension(e.Rel).Length);
                if (!names.Contains(n)) names.Add(n);
            }
            names.Sort(string.CompareOrdinal);
            StringBuilder sb = new StringBuilder("[\n");
            for (int i = 0; i < names.Count; i++) sb.Append("  ").Append(Json.Write(names[i])).Append(i < names.Count - 1 ? ",\n" : "\n");
            return new UTF8Encoding(false).GetBytes(sb.Append("]\n").ToString());
        }

        // Название и описание исходного пакета в итоговом не нужны: у него свои, в manifest.json.
        static bool PackKey(string line)
        {
            string t = line.TrimStart();
            return t.StartsWith("pack.name=") || t.StartsWith("pack.description=");
        }

        // Файл перевода из одного пакета: копируется как есть, кроме строк с названием исходного пакета.
        static byte[] CleanLang(Entry e)
        {
            string[] lines = File.ReadAllLines(e.Winner.FullPath(e.Key));
            if (!Array.Exists(lines, PackKey)) return null;
            StringBuilder sb = new StringBuilder();
            foreach (string line in lines) if (!PackKey(line)) sb.Append(line.TrimEnd('\r')).Append('\n');
            return new UTF8Encoding(false).GetBytes(sb.ToString());
        }

        static int ExtRank(Entry e, List<Pack> packs, Dictionary<string, Pack> overrides)
        {
            return e.Locked || overrides.ContainsKey(e.Key) ? -1 : packs.IndexOf(e.Sources[0]);
        }

        // Ключ файла слоя (без расширения, в нижнем регистре) по ссылке из набора.
        static string LayerKey(string dir, string name)
        {
            name = name.ToLowerInvariant().Replace('\\', '/');
            foreach (string ext in ImgExts) if (name.EndsWith(ext)) name = name.Substring(0, name.Length - ext.Length);
            // ссылка либо полная от корня пака, либо относительно папки набора
            return name.StartsWith("textures/") ? name : dir + name;
        }

        // Вид слоя: карта нормалей и карта высот — два способа задать рельеф, в наборе допустим только один.
        public static string SlotOf(string layerKey)
        {
            if (layerKey == "normal" || layerKey == "heightmap") return "relief";
            return layerKey.StartsWith("metalness") ? "mer" : layerKey;
        }

        public static string LayerTitle(string layerKey)
        {
            if (layerKey == "normal") return L.T("рельеф (карта нормалей)");
            if (layerKey == "heightmap") return L.T("рельеф (карта высот)");
            if (layerKey.StartsWith("metalness")) return L.T("отражения и свечение");
            return layerKey;
        }

        // Слой нужного вида в наборе пака; пустая пара, если такого нет.
        static KeyValuePair<string, string> SlotLayer(Pack p, string setKey, string slot)
        {
            foreach (KeyValuePair<string, string> l in SetLayers(p.FullPath(setKey)))
                if (l.Key != "color" && SlotOf(l.Key) == slot) return l;
            return new KeyValuePair<string, string>();
        }

        // Слои набора: имя слоя (color, normal…) -> ссылка на файл, как она записана в наборе.
        static List<KeyValuePair<string, string>> SetLayers(string path)
        {
            List<KeyValuePair<string, string>> r;
            string ck = path + "|" + File.GetLastWriteTimeUtc(path).Ticks;
            if (setCache.TryGetValue(ck, out r)) return r;
            r = new List<KeyValuePair<string, string>>();
            try
            {
                JObj root = Json.Parse(File.ReadAllText(path)) as JObj;
                JObj ts = root == null ? null : root.Get("minecraft:texture_set") as JObj;
                if (ts != null)
                {
                    foreach (string k in ts.Keys)
                    {
                        string v = ts.Map[k] as string; // массив или "#RRGGBB" — это сплошной цвет, а не файл
                        if (v == null || v.StartsWith("#")) continue;
                        r.Add(new KeyValuePair<string, string>(k, v));
                    }
                }
            }
            catch (Exception) { }
            setCache[ck] = r;
            return r;
        }

        // ---------------------------------------------------------- правила слияния JSON

        static bool UnionKey(string key)
        {
            return key == "animate" || key == "initialize" || key == "pre_animation";
        }

        // mode: 0 — массивы заменяются, 1 — массивы объединяются, 2 — объединяются только списки скриптов сущности
        static object Deep(object lo, object hi, int mode, string key)
        {
            JObj a = lo as JObj, b = hi as JObj;
            if (a != null && b != null)
            {
                JObj r = new JObj();
                foreach (string k in a.Keys) r.Set(k, a.Map[k]);
                foreach (string k in b.Keys)
                    r.Set(k, r.Map.ContainsKey(k) ? Deep(r.Map[k], b.Map[k], mode, k) : b.Map[k]);
                return r;
            }
            List<object> la = lo as List<object>, lb = hi as List<object>;
            if (la != null && lb != null && (mode == 1 || (mode == 2 && key != null && UnionKey(key))))
            {
                List<object> r = new List<object>(la);
                HashSet<string> seen = new HashSet<string>();
                foreach (object x in la) seen.Add(Json.Write(x));
                foreach (object x in lb) if (seen.Add(Json.Write(x))) r.Add(x);
                return r;
            }
            return hi;
        }

        // Объединяет объекты только на первых depth уровнях; глубже определение берётся целиком из важного пака.
        static object Limited(object lo, object hi, int depth)
        {
            JObj a = lo as JObj, b = hi as JObj;
            if (depth == 0 || a == null || b == null) return hi;
            JObj r = new JObj();
            foreach (string k in a.Keys) r.Set(k, a.Map[k]);
            foreach (string k in b.Keys)
                r.Set(k, r.Map.ContainsKey(k) ? Limited(r.Map[k], b.Map[k], depth - 1) : b.Map[k]);
            return r;
        }

        // Элементы интерфейса: "имя@родитель" и "имя" — один и тот же элемент.
        static object UiMerge(JObj lo, JObj hi)
        {
            JObj r = new JObj();
            Dictionary<string, string> byName = new Dictionary<string, string>();
            foreach (string k in lo.Keys) { r.Set(k, lo.Map[k]); byName[k.Split('@')[0]] = k; }
            foreach (string k in hi.Keys)
            {
                string name = k.Split('@')[0], old;
                if (byName.TryGetValue(name, out old) && old != k) r.Remove(old);
                byName[name] = k;
                r.Set(k, hi.Map[k]);
            }
            return r;
        }

        static string GeoId(object o)
        {
            JObj j = o as JObj;
            JObj d = j == null ? null : j.Get("description") as JObj;
            return d == null ? null : d.Get("identifier") as string;
        }

        static bool IsGeo(JObj o)
        {
            if (o.Map.ContainsKey("minecraft:geometry")) return true;
            foreach (string k in o.Keys) if (k.StartsWith("geometry.")) return true;
            return false;
        }

        static object GeoMerge(JObj lo, JObj hi)
        {
            JObj r = new JObj();
            foreach (string k in lo.Keys) r.Set(k, lo.Map[k]);
            foreach (string k in hi.Keys)
            {
                List<object> la = r.Get(k) as List<object>, lb = hi.Map[k] as List<object>;
                if (k == "minecraft:geometry" && la != null && lb != null)
                {
                    List<object> m = new List<object>(la);
                    foreach (object g in lb)
                    {
                        string id = GeoId(g);
                        int at = id == null ? -1 : m.FindIndex(delegate(object x) { return GeoId(x) == id; });
                        if (at >= 0) m[at] = g; else m.Add(g);
                    }
                    r.Set(k, m);
                    continue;
                }
                if (k.StartsWith("geometry."))
                {
                    string name = k.Split(':')[0];
                    foreach (string old in new List<string>(r.Keys))
                        if (old != k && old.Split(':')[0] == name) r.Remove(old);
                }
                r.Set(k, hi.Map[k]);
            }
            return r;
        }

        static string FlipKey(object o)
        {
            JObj j = o as JObj;
            if (j == null) return Json.Write(o);
            return Json.Write(j.Get("flipbook_texture")) + "|" + Json.Write(j.Get("atlas_tile")) + "|"
                + Json.Write(j.Get("atlas_index")) + "|" + Json.Write(j.Get("atlas_tile_variant"));
        }

        static bool IsEntity(JObj o)
        {
            return o.Map.ContainsKey("minecraft:client_entity") || o.Map.ContainsKey("minecraft:attachable");
        }

        // lo — менее важная версия, hi — более важная.
        static object MergeJson(string key, object lo, object hi)
        {
            MergeKind kind = KindOf(key);
            List<object> la = lo as List<object>, lb = hi as List<object>;
            if (kind == MergeKind.Flipbook && la != null && lb != null)
            {
                List<object> r = new List<object>(la);
                Dictionary<string, int> idx = new Dictionary<string, int>();
                for (int i = 0; i < r.Count; i++) idx[FlipKey(r[i])] = i;
                foreach (object x in lb)
                {
                    int at;
                    string k = FlipKey(x);
                    if (idx.TryGetValue(k, out at)) r[at] = x;
                    else { idx[k] = r.Count; r.Add(x); }
                }
                return r;
            }
            if (kind == MergeKind.Union) return Deep(lo, hi, 1, null);
            JObj l = lo as JObj, h = hi as JObj;
            if (l == null || h == null) return hi;
            if (key.StartsWith("ui/") && key != "ui/_global_variables.json") return UiMerge(l, h);
            if (IsEntity(h)) return Deep(l, h, 2, null);
            if (IsGeo(h) || IsGeo(l)) return GeoMerge(l, h);
            if (h.Map.ContainsKey("particle_effect") || h.Map.ContainsKey("minecraft:fog_settings")) return hi;
            // описание одного блока, предмета или звука берётся целиком из более важного пака
            if (key == "textures/terrain_texture.json" || key == "textures/item_texture.json" || key == "blocks.json"
                || key == "sounds/sound_definitions.json") return Limited(l, h, 2);
            if (h.Map.ContainsKey("animations") || h.Map.ContainsKey("animation_controllers")
                || h.Map.ContainsKey("render_controllers") || h.Map.ContainsKey("materials"))
                return Limited(l, h, 2);
            return Deep(l, h, 0, null);
        }

        // ---------------------------------------------------------- определения по идентификаторам

        static List<string> Defs(object root)
        {
            List<string> r = new List<string>();
            JObj o = root as JObj;
            if (o == null) return r;
            foreach (string k in o.Keys)
            {
                object v = o.Map[k];
                if (k == "minecraft:client_entity" || k == "minecraft:attachable" || k == "particle_effect" || k == "minecraft:fog_settings")
                {
                    string id = GeoId(v);
                    if (id != null) r.Add(k + "|" + id);
                }
                else if (k == "animations" || k == "animation_controllers" || k == "render_controllers")
                {
                    JObj c = v as JObj;
                    if (c != null) foreach (string ck in c.Keys) r.Add(k + "|" + ck);
                }
                else if (k == "minecraft:geometry")
                {
                    List<object> l = v as List<object>;
                    if (l != null) foreach (object g in l) { string id = GeoId(g); if (id != null) r.Add("geometry|" + id); }
                }
                else if (k.StartsWith("geometry.")) r.Add("geometry|" + k.Split(':')[0]);
            }
            return r;
        }

        static void RemoveDef(object root, string def)
        {
            JObj o = root as JObj;
            if (o == null) return;
            int bar = def.IndexOf('|');
            string kind = def.Substring(0, bar), id = def.Substring(bar + 1);
            if (kind != "geometry")
            {
                JObj c = o.Get(kind) as JObj;
                if (c != null) c.Remove(id);
                return;
            }
            foreach (string k in new List<string>(o.Keys))
                if (k.StartsWith("geometry.") && k.Split(':')[0] == id) o.Remove(k);
            List<object> l = o.Get("minecraft:geometry") as List<object>;
            if (l != null) l.RemoveAll(delegate(object g) { return GeoId(g) == id; });
        }

        static Doc MakeDoc(Entry e, List<Pack> packs, List<string> log)
        {
            // от низшего приоритета к высшему; выбранный вручную источник накладывается последним
            List<Pack> order = new List<Pack>(e.Sources);
            order.Remove(e.Winner);
            order.Insert(0, e.Winner);
            order.Reverse();
            Doc d = new Doc();
            d.E = e;
            bool track = DefFolder(e.Key);
            bool otherLights;
            Pack lightOwner = e.Key.StartsWith("biomes/") ? LightOwner(packs, out otherLights) : null;
            foreach (Pack p in order)
            {
                object cur;
                try { cur = Json.Parse(File.ReadAllText(p.FullPath(e.Key))); }
                catch (Exception ex)
                {
                    if (e.Sources.Count > 1) log.Add(e.Rel + L.T(": версия из «") + p.Name + L.T("» пропущена — ") + ex.Message);
                    continue;
                }
                if (lightOwner != null && p != lightOwner && p.Sub != lightOwner) StripLighting(cur);
                int rank = packs.IndexOf(p);
                if (rank < d.Rank) d.Rank = rank;
                if (track)
                {
                    foreach (string def in Defs(cur))
                    {
                        int old;
                        if (!d.DefRank.TryGetValue(def, out old) || rank < old) d.DefRank[def] = rank;
                    }
                }
                d.Root = d.Root == null ? cur : MergeJson(e.Key, d.Root, cur);
            }
            return d.Root == null ? null : d;
        }

        // Один и тот же объект (сущность, модель, анимация…) в файлах с разными именами:
        // в общем паке игра взяла бы случайный, поэтому оставляем определение из более важного пака.
        static int Dedupe(List<Doc> docs)
        {
            docs.Sort(delegate(Doc a, Doc b) { return a.Rank.CompareTo(b.Rank); });
            Dictionary<string, Doc> best = new Dictionary<string, Doc>();
            foreach (Doc d in docs)
            {
                foreach (KeyValuePair<string, int> kv in d.DefRank)
                {
                    Doc b;
                    if (!best.TryGetValue(kv.Key, out b) || kv.Value < b.DefRank[kv.Key]) best[kv.Key] = d;
                }
            }
            int n = 0;
            foreach (Doc d in docs)
            {
                foreach (string def in new List<string>(d.DefRank.Keys))
                {
                    Doc b = best[def];
                    if (b == d || b.DefRank[def] >= d.DefRank[def] || d.Drop) continue;
                    n++;
                    if (def.StartsWith("minecraft:client_entity|") || def.StartsWith("minecraft:attachable|"))
                    {
                        // сущность собираем из обоих файлов: текстуры, модели и анимации дополняют друг друга
                        b.Root = Deep(d.Root, b.Root, 2, null);
                        b.Changed = true;
                        d.Drop = true;
                    }
                    else if (def.StartsWith("particle_effect|") || def.StartsWith("minecraft:fog_settings|")) d.Drop = true;
                    else
                    {
                        RemoveDef(d.Root, def);
                        d.Changed = true;
                        if (Defs(d.Root).Count == 0) d.Drop = true;
                    }
                }
            }
            return n;
        }

        static byte[] MergeLang(Entry e)
        {
            List<Pack> order = new List<Pack>(e.Sources);
            order.Remove(e.Winner);
            order.Insert(0, e.Winner);
            order.Reverse();
            List<string> keys = new List<string>();
            Dictionary<string, string> lines = new Dictionary<string, string>();
            foreach (Pack p in order)
            {
                foreach (string raw in File.ReadAllLines(p.FullPath(e.Key)))
                {
                    string line = raw.TrimEnd('\r');
                    int eq = line.IndexOf('=');
                    if (eq <= 0 || line.TrimStart().StartsWith("##") || PackKey(line)) continue;
                    string k = line.Substring(0, eq);
                    if (!lines.ContainsKey(k)) keys.Add(k);
                    lines[k] = line;
                }
            }
            StringBuilder sb = new StringBuilder();
            foreach (string k in keys) sb.Append(lines[k]).Append('\n');
            return new UTF8Encoding(false).GetBytes(sb.ToString());
        }

        static List<object> Ver(int a, int b, int c)
        {
            List<object> l = new List<object>();
            l.Add(new JLit(a.ToString())); l.Add(new JLit(b.ToString())); l.Add(new JLit(c.ToString()));
            return l;
        }

        static byte[] Manifest(string name, string desc, List<Pack> packs, List<string> log, bool hasSets, List<string> authors)
        {
            int[] min = new int[] { 1, 16, 0 };
            List<object> caps = new List<object>();
            HashSet<string> seenCaps = new HashSet<string>();
            foreach (Pack p in packs)
            {
                int[] v = p.MinEngine;
                for (int i = 0; v != null && i < 3; i++)
                {
                    if (v[i] > min[i]) { min = v; break; }
                    if (v[i] < min[i]) break;
                }
                if (p.Capabilities != null)
                    foreach (object c in p.Capabilities)
                    {
                        // без наборов слоёв в сборке отметка о них была бы лишней
                        if (c is string && (string)c == "pbr" && !hasSets) continue;
                        if (seenCaps.Add(Json.Write(c))) caps.Add(c);
                    }
            }
            JObj header = new JObj();
            header.Set("name", name);
            header.Set("description", desc);
            header.Set("uuid", Guid.NewGuid().ToString());
            header.Set("version", Ver(1, 0, 0));
            header.Set("min_engine_version", Ver(min[0], min[1], min[2]));
            JObj module = new JObj();
            module.Set("type", "resources");
            module.Set("uuid", Guid.NewGuid().ToString());
            module.Set("version", Ver(1, 0, 0));
            List<object> modules = new List<object>();
            modules.Add(module);
            JObj root = new JObj();
            root.Set("format_version", new JLit("2"));
            root.Set("header", header);
            root.Set("modules", modules);
            foreach (Pack p in packs)
                if (p.Sub != null) log.Add("«" + p.Name + L.T("»: в сборку вшит вариант «") + p.SubFolder + "».");
            if (caps.Count > 0) root.Set("capabilities", caps);
            if (authors != null && authors.Count > 0)
            {
                // сборка состоит из чужих работ: их авторы перечислены в описании пакета
                JObj meta = new JObj();
                meta.Set("authors", new List<object>(authors.ToArray()));
                root.Set("metadata", meta);
            }
            return new UTF8Encoding(false).GetBytes(Json.Write(root) + "\n");
        }

        // Набор PBR взят из другого пака, чем сама текстура: слой цвета в нём указывает на выбранную текстуру.
        static byte[] FixColor(Entry e)
        {
            try
            {
                JObj root = Json.Parse(File.ReadAllText(e.Winner.FullPath(e.Key))) as JObj;
                JObj ts = root.Get("minecraft:texture_set") as JObj;
                if (e.SetPatch != null)
                {
                    // убираем только ссылки на файлы; значение, заданное числом или цветом, остаётся как было
                    foreach (string k in new string[] { "normal", "heightmap", "metalness_emissive_roughness", "metalness_emissive_roughness_subsurface" })
                    {
                        string cur = ts.Get(k) as string;
                        if (cur != null && !cur.StartsWith("#")) ts.Remove(k);
                    }
                    foreach (KeyValuePair<string, string> kv in e.SetPatch)
                    {
                        // в одном наборе бывает только одна карта рельефа и одна карта отражений
                        if (kv.Key == "normal") ts.Remove("heightmap");
                        if (kv.Key == "heightmap") ts.Remove("normal");
                        if (kv.Key == "metalness_emissive_roughness") ts.Remove("metalness_emissive_roughness_subsurface");
                        if (kv.Key == "metalness_emissive_roughness_subsurface") ts.Remove("metalness_emissive_roughness");
                        ts.Set(kv.Key, kv.Value);
                    }
                }
                if (e.ColorFix != null) ts.Set("color", e.ColorFix);
                return new UTF8Encoding(false).GetBytes(Json.Write(root) + "\n");
            }
            catch (Exception) { return null; }
        }

        // outPath с расширением .mcpack/.zip — архив, иначе папка. Возвращает журнал.
        // ---- случайные варианты текстур блоков: список variations в terrain_texture.json

        // Список текстур блоков из установленной игры: по нему видно, какие блоки пользуются файлом.
        public static JObj VanillaTerrain()
        {
            JObj all = new JObj();
            try
            {
                Geo.Ensure();
                if (Geo.GameDir == null) return all;
                List<string> dirs = new List<string>(Directory.GetDirectories(Geo.GameDir, "vanilla*"));
                dirs.Sort(StringComparer.OrdinalIgnoreCase);
                dirs.Reverse(); // основной пакет «vanilla» читается последним и потому главнее добавок к нему
                foreach (string dir in dirs)
                {
                    string file = Path.Combine(Path.Combine(dir, "textures"), "terrain_texture.json");
                    if (!File.Exists(file)) continue;
                    try
                    {
                        JObj root = Json.Parse(File.ReadAllText(file)) as JObj;
                        JObj data = root == null ? null : root.Get("texture_data") as JObj;
                        if (data != null) foreach (string k in data.Keys) all.Set(k, data.Map[k]);
                    }
                    catch (Exception) { }
                }
            }
            catch (Exception) { }
            return all;
        }

        static JObj PathItem(string path)
        {
            JObj o = new JObj();
            o.Set("path", path);
            return o;
        }

        // Заменяет в описании текстур блока ссылку на файл списком вариантов. changed — нашлась ли такая ссылка.
        static object WithVariations(object tex, Dictionary<string, List<string>> extra, HashSet<string> applied, ref bool changed)
        {
            string s = tex as string;
            List<string> more;
            if (s != null)
            {
                if (!extra.TryGetValue(s, out more)) return tex;
                JObj o = new JObj();
                List<object> vars = new List<object>();
                vars.Add(PathItem(s));
                foreach (string m in more) vars.Add(PathItem(m));
                o.Set("variations", vars);
                applied.Add(s);
                changed = true;
                return o;
            }
            List<object> list = tex as List<object>;
            if (list != null)
            {
                List<object> r = new List<object>();
                foreach (object item in list) r.Add(WithVariations(item, extra, applied, ref changed));
                return r;
            }
            JObj obj = tex as JObj;
            if (obj == null) return tex;
            List<object> have = obj.Get("variations") as List<object>;
            if (have != null)
            {
                // варианты у блока уже есть: новые дописываются к тому, что ссылается на наш файл
                List<object> r = new List<object>(have);
                foreach (object item in have)
                {
                    JObj io = item as JObj;
                    string ip = io == null ? item as string : io.Get("path") as string;
                    if (ip == null || !extra.TryGetValue(ip, out more)) continue;
                    foreach (string m in more) r.Add(PathItem(m));
                    applied.Add(ip);
                    changed = true;
                }
                JObj copy = new JObj();
                foreach (string k in obj.Keys) copy.Set(k, k == "variations" ? r : obj.Map[k]);
                return copy;
            }
            string p = obj.Get("path") as string;
            if (p == null || !extra.TryGetValue(p, out more)) return tex;
            JObj n = new JObj();
            List<object> list2 = new List<object>();
            list2.Add(PathItem(p));
            foreach (string m in more) list2.Add(PathItem(m));
            n.Set("variations", list2);
            foreach (string k in obj.Keys) if (k != "path") n.Set(k, obj.Map[k]); // цвет наложения и прочее остаются
            applied.Add(p);
            changed = true;
            return n;
        }

        // Итоговый terrain_texture.json: свой (если он есть в сборке) плюс записи из игры для блоков с вариантами.
        static byte[] TerrainWithVariants(byte[] current, Dictionary<string, List<string>> extra, string packName, HashSet<string> applied)
        {
            JObj root = null;
            if (current != null) try { root = Json.Parse(new UTF8Encoding(false).GetString(current).TrimStart('﻿')) as JObj; } catch (Exception) { }
            if (root == null)
            {
                root = new JObj();
                root.Set("resource_pack_name", packName);
                root.Set("texture_name", "atlas.terrain");
                root.Set("padding", new JLit("8"));
                root.Set("num_mip_levels", new JLit("4"));
            }
            JObj data = root.Get("texture_data") as JObj;
            if (data == null)
            {
                data = new JObj();
                root.Set("texture_data", data);
            }
            foreach (string k in new List<string>(data.Keys))
            {
                JObj entry = data.Map[k] as JObj;
                if (entry == null) continue;
                bool changed = false;
                object nt = WithVariations(entry.Get("textures"), extra, applied, ref changed);
                if (changed) entry.Set("textures", nt);
            }
            JObj vanilla = VanillaTerrain();
            foreach (string k in vanilla.Keys)
            {
                if (data.Map.ContainsKey(k)) continue;
                JObj entry = vanilla.Map[k] as JObj;
                if (entry == null) continue;
                bool changed = false;
                object nt = WithVariations(entry.Get("textures"), extra, applied, ref changed);
                if (!changed) continue;
                JObj ne = new JObj();
                ne.Set("textures", nt);
                data.Set(k, ne);
            }
            return new UTF8Encoding(false).GetBytes(Json.Write(root) + "\n");
        }

        // ---- случайные варианты текстур мобов. Игра выбирает текстуру моба в его «контроллере отрисовки»:
        // вместо одной текстуры туда ставится список, а номер в списке моб получает случайно при появлении.

        static string TexNorm(string path)
        {
            string p = path.Replace((char)92, (char)47).ToLowerInvariant();
            return p.EndsWith(".png") || p.EndsWith(".tga") ? p.Substring(0, p.Length - 4) : p;
        }

        static JObj EntityDesc(object root)
        {
            JObj r = root as JObj;
            JObj ce = r == null ? null : r.Get("minecraft:client_entity") as JObj;
            return ce == null ? null : ce.Get("description") as JObj;
        }

        const string MobVar = "variable.brpc_var";

        // extra: текстура -> её добавочные варианты. Описания мобов из пакетов правятся на месте, описания из игры
        // и новые контроллеры складываются в files. applied — текстуры, которым варианты удалось подключить.
        static void MobVariants(Dictionary<string, List<string>> extra, Dictionary<string, Doc> docs, HashSet<string> applied, List<KeyValuePair<string, byte[]>> files)
        {
            Dictionary<string, List<string>> mob = new Dictionary<string, List<string>>();
            Dictionary<string, string> realName = new Dictionary<string, string>();
            foreach (KeyValuePair<string, List<string>> kv in extra)
            {
                string k = TexNorm(kv.Key);
                if (!k.StartsWith("textures/entity/")) continue;
                mob[k] = kv.Value;
                realName[k] = kv.Key;
            }
            if (mob.Count == 0) return;
            UTF8Encoding utf = new UTF8Encoding(false);

            // описания мобов: сначала из сборки, затем из игры — те, которых в сборке нет
            Dictionary<string, object> ents = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
            Dictionary<string, Doc> entDoc = new Dictionary<string, Doc>(StringComparer.OrdinalIgnoreCase);
            // контроллеры: имя -> описание и версия формата файла, где оно лежит
            Dictionary<string, KeyValuePair<JObj, string>> ctrls = new Dictionary<string, KeyValuePair<JObj, string>>(StringComparer.OrdinalIgnoreCase);
            foreach (string text in Geo.GameTexts("render_controllers"))
            {
                try
                {
                    JObj root = Json.Parse(text.TrimStart((char)0xFEFF)) as JObj;
                    JObj all = root == null ? null : root.Get("render_controllers") as JObj;
                    if (all == null) continue;
                    string fv = root.Get("format_version") as string ?? "1.8.0";
                    foreach (string id in all.Keys)
                        if (all.Map[id] is JObj) ctrls[id] = new KeyValuePair<JObj, string>((JObj)all.Map[id], fv);
                }
                catch (Exception) { }
            }
            Dictionary<string, object> gameEnts = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
            foreach (string text in Geo.GameTexts("entity"))
            {
                try
                {
                    object root = Json.Parse(text.TrimStart((char)0xFEFF));
                    JObj d = EntityDesc(root);
                    string id = d == null ? null : d.Get("identifier") as string;
                    if (id != null) gameEnts[id] = root;
                }
                catch (Exception) { }
            }
            foreach (Doc d in docs.Values)
            {
                if (d.Drop) continue;
                if (d.E.Key.StartsWith("entity/"))
                {
                    JObj desc = EntityDesc(d.Root);
                    string id = desc == null ? null : desc.Get("identifier") as string;
                    if (id == null) continue;
                    ents[id] = d.Root;
                    entDoc[id] = d;
                }
                else if (d.E.Key.StartsWith("render_controllers/"))
                {
                    JObj root = d.Root as JObj;
                    JObj all = root == null ? null : root.Get("render_controllers") as JObj;
                    if (all == null) continue;
                    string fv = root.Get("format_version") as string ?? "1.8.0";
                    foreach (string id in all.Keys)
                        if (all.Map[id] is JObj) ctrls[id] = new KeyValuePair<JObj, string>((JObj)all.Map[id], fv);
                }
            }
            foreach (KeyValuePair<string, object> kv in gameEnts)
                if (!ents.ContainsKey(kv.Key)) ents[kv.Key] = kv.Value;

            foreach (KeyValuePair<string, object> ent in ents)
            {
                JObj desc = EntityDesc(ent.Value);
                JObj texs = desc.Get("textures") as JObj;
                List<object> rcs = desc.Get("render_controllers") as List<object>;
                if (texs == null || rcs == null) continue;
                // короткие имена текстур моба, у которых есть варианты
                Dictionary<string, string> shorts = new Dictionary<string, string>();
                foreach (string sk in texs.Keys)
                {
                    string path = texs.Map[sk] as string;
                    if (path != null && mob.ContainsKey(TexNorm(path))) shorts[sk] = TexNorm(path);
                }
                if (shorts.Count == 0) continue;
                string entName = ent.Key.Substring(ent.Key.IndexOf((char)58) + 1);
                StringBuilder safe = new StringBuilder();
                foreach (char ch in entName) safe.Append(char.IsLetterOrDigit(ch) ? char.ToLowerInvariant(ch) : (char)95);
                HashSet<string> used = new HashSet<string>();
                JObj newCtrls = new JObj();
                string newVersion = null;
                for (int i = 0; i < rcs.Count; i++)
                {
                    string cid = rcs[i] as string;
                    JObj cond = rcs[i] as JObj;
                    if (cid == null && cond != null && cond.Keys.Count == 1) cid = cond.Keys[0];
                    KeyValuePair<JObj, string> src;
                    if (cid == null || !ctrls.TryGetValue(cid, out src)) continue;
                    List<object> exprs = src.Key.Get("textures") as List<object>;
                    if (exprs == null) continue;
                    List<object> newExprs = new List<object>();
                    HashSet<string> here = new HashSet<string>();
                    foreach (object ex in exprs)
                    {
                        string expr = ex as string;
                        if (expr != null)
                            foreach (string sk in shorts.Keys)
                            {
                                string pattern = "(?i)\\btexture\\." + System.Text.RegularExpressions.Regex.Escape(sk) + "(?![\\w.])";
                                string changed = System.Text.RegularExpressions.Regex.Replace(expr, pattern, "Array.brpc_" + sk + "[" + MobVar + "]");
                                if (changed != expr) { here.Add(sk); expr = changed; }
                            }
                        newExprs.Add(expr ?? ex);
                    }
                    if (here.Count == 0) continue;
                    // общий контроллер игры не трогаем (им могут пользоваться другие мобы): моб получает свою копию
                    JObj copy = new JObj(), arrays = new JObj(), texArrays = new JObj();
                    JObj oldArrays = src.Key.Get("arrays") as JObj;
                    JObj oldTex = oldArrays == null ? null : oldArrays.Get("textures") as JObj;
                    if (oldArrays != null) foreach (string k in oldArrays.Keys) if (k != "textures") arrays.Set(k, oldArrays.Map[k]);
                    if (oldTex != null) foreach (string k in oldTex.Keys) texArrays.Set(k, oldTex.Map[k]);
                    foreach (string sk in here)
                    {
                        List<object> items = new List<object>();
                        items.Add("Texture." + sk);
                        for (int n = 0; n < mob[shorts[sk]].Count; n++) items.Add("Texture." + sk + "_brpc" + (n + 2));
                        texArrays.Set("Array.brpc_" + sk, items);
                        used.Add(sk);
                    }
                    arrays.Set("textures", texArrays);
                    foreach (string k in src.Key.Keys)
                        if (k != "textures" && k != "arrays") copy.Set(k, src.Key.Map[k]);
                    copy.Set("arrays", arrays);
                    copy.Set("textures", newExprs);
                    string newId = "controller.render.brpc_" + safe + (newCtrls.Keys.Count > 0 ? "_" + (newCtrls.Keys.Count + 1) : "");
                    newCtrls.Set(newId, copy);
                    if (newVersion == null) newVersion = src.Value;
                    if (cond != null)
                    {
                        JObj nc = new JObj();
                        nc.Set(newId, cond.Map[cond.Keys[0]]);
                        rcs[i] = nc;
                    }
                    else rcs[i] = newId;
                }
                if (used.Count == 0) continue;
                foreach (string sk in used)
                {
                    List<string> more = mob[shorts[sk]];
                    for (int n = 0; n < more.Count; n++) texs.Set(sk + "_brpc" + (n + 2), more[n]);
                    applied.Add(realName[shorts[sk]]);
                }
                // номер варианта моб получает один раз, при первой отрисовке, и дальше не меняет
                JObj scripts = desc.Get("scripts") as JObj;
                if (scripts == null) { scripts = new JObj(); desc.Set("scripts", scripts); }
                List<object> pre = scripts.Get("pre_animation") as List<object>;
                if (pre == null) { pre = new List<object>(); scripts.Set("pre_animation", pre); }
                string line = MobVar + " = (" + MobVar + " ?? math.random(0, 999));";
                if (!pre.Contains(line)) pre.Add(line);

                JObj rcRoot = new JObj();
                rcRoot.Set("format_version", newVersion ?? "1.8.0");
                rcRoot.Set("render_controllers", newCtrls);
                files.Add(new KeyValuePair<string, byte[]>("render_controllers/brpc_" + safe + ".render_controllers.json", utf.GetBytes(Json.Write(rcRoot) + "\n")));
                Doc own;
                if (entDoc.TryGetValue(ent.Key, out own)) own.Changed = true;
                else files.Add(new KeyValuePair<string, byte[]>("entity/brpc_" + safe + ".entity.json", utf.GetBytes(Json.Write(ent.Value) + "\n")));
            }
        }

        // Файлы авторства и лицензии в корне пакета: credits.txt, LICENSE, readme.md и подобные.
        public static bool IsCreditFile(string fileName)
        {
            string n = fileName.ToLowerInvariant();
            if (n.IndexOf((char)47) >= 0 || n.IndexOf((char)92) >= 0) return false;
            if (Risk.Program(n) || Risk.Archive(n)) return false;
            return n.StartsWith("credit") || n.StartsWith("licen") || n.StartsWith("readme") || n.StartsWith("copying") || n.StartsWith("author");
        }

        // Пакеты, из которых в сборку взят хотя бы один файл: победитель каждого файла, все источники слитых файлов,
        // пакеты выбранных слоёв. Вариант (subpack) засчитывается своему пакету.
        static List<Pack> UsedPacks(List<Entry> entries, Dictionary<string, Doc> docs, List<Pack> own)
        {
            List<Pack> used = new List<Pack>();
            Action<Pack> add = delegate(Pack p)
            {
                if (p == null || p == Pack.Off) return;
                Pack owner = own.Find(delegate(Pack q) { return q == p || q.Sub == p; });
                if (owner != null && !used.Contains(owner)) used.Add(owner);
            };
            foreach (Entry e in entries)
            {
                if (e.Orphan || e.Excluded) continue;
                add(e.Winner);
                if (e.Sources.Count > 1 && (docs.ContainsKey(e.Key) || KindOf(e.Key) == MergeKind.Lang)) foreach (Pack sp in e.Sources) add(sp);
                add(e.PbrChoice);
                if (e.Slots != null) foreach (Pack lp in e.Slots.Values) add(lp);
            }
            used.Sort(delegate(Pack a, Pack b) { return own.IndexOf(a).CompareTo(own.IndexOf(b)); });
            return used;
        }

        static JObj ManifestOf(Pack p)
        {
            try
            {
                string rel;
                if (!p.Files.TryGetValue("manifest.json", out rel)) return null;
                FileInfo fi = new FileInfo(Path.Combine(p.Root, rel));
                if (fi.Length > 1024 * 1024) return null; // настоящий manifest маленький
                return Json.Parse(File.ReadAllText(fi.FullName)) as JObj;
            }
            catch (Exception) { return null; }
        }

        static List<string> AuthorsOf(Pack p)
        {
            List<string> r = new List<string>();
            JObj man = ManifestOf(p);
            JObj meta = man == null ? null : man.Get("metadata") as JObj;
            List<object> list = meta == null ? null : meta.Get("authors") as List<object>;
            if (list != null)
                foreach (object o in list)
                {
                    string a = o as string;
                    if (a != null && a.Trim().Length > 0 && a.Length <= 200) r.Add(a.Trim());
                }
            return r;
        }

        // Папка credits в сборке: для каждого использованного пакета — его файлы авторства и лицензии и pack.json
        // с названием, описанием и метаданными из его manifest. Без путей на диске пользователя.
        static int PutCredits(List<Pack> used, Action<string, byte[]> put)
        {
            int count = 0;
            HashSet<string> names = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (Pack p in used)
            {
                JObj man = ManifestOf(p);
                List<string> files = new List<string>();
                foreach (KeyValuePair<string, string> kv in p.Files)
                    if (IsCreditFile(kv.Key)) files.Add(kv.Value);
                if (man == null && files.Count == 0) continue;
                // коды цвета Minecraft («§l», «§6») в имени папки не нужны
                string folder = System.Text.RegularExpressions.Regex.Replace(p.Name ?? "pack", "§.?", "");
                foreach (char c in Path.GetInvalidFileNameChars()) folder = folder.Replace(c, (char)95);
                folder = folder.Trim().TrimEnd((char)46);
                if (folder.Length > 60) folder = folder.Substring(0, 60).Trim();
                if (folder.Length == 0) folder = "pack";
                string unique = folder;
                for (int n = 2; !names.Add(unique); n++) unique = folder + " (" + n + ")";
                string dir = "credits/" + unique + "/";
                JObj info = new JObj();
                info.Set("name", p.Name ?? "");
                JObj header = man == null ? null : man.Get("header") as JObj;
                if (header != null)
                {
                    if (header.Get("description") is string) info.Set("description", header.Get("description"));
                    if (header.Get("uuid") is string) info.Set("uuid", header.Get("uuid"));
                    if (header.Get("version") != null) info.Set("version", header.Get("version"));
                }
                if (man != null && man.Get("metadata") != null) info.Set("metadata", man.Get("metadata"));
                if (p.Origin != null) info.Set("source_file", Path.GetFileName(p.Origin.TrimEnd((char)92, (char)47)));
                if (p.Java) info.Set("converted_from", "Java Edition");
                put(dir + "pack.json", new UTF8Encoding(false).GetBytes(Json.Write(info) + "\n"));
                foreach (string rel in files)
                    try
                    {
                        FileInfo fi = new FileInfo(Path.Combine(p.Root, rel));
                        if (fi.Length <= 4 * 1024 * 1024) put(dir + Path.GetFileName(rel), File.ReadAllBytes(fi.FullName));
                    }
                    catch (Exception) { }
                count++;
            }
            return count;
        }

        public static List<string> Build(List<Entry> entries, List<Pack> packs, string name, string desc, string outPath, List<VariantOut> variants = null)
        {
            List<string> log = new List<string>();
            UTF8Encoding utf = new UTF8Encoding(false);
            // сборка не должна попадать внутрь исходного пакета или поверх него: иначе она испортит то, из чего собирается
            string outFull = Path.GetFullPath(outPath).TrimEnd('\\', '/');
            foreach (Pack p in packs)
            {
                string pr = Path.GetFullPath(p.Root).TrimEnd('\\', '/');
                bool clash = string.Equals(outFull, pr, StringComparison.OrdinalIgnoreCase)
                    || outFull.StartsWith(pr + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase)
                    || pr.StartsWith(outFull + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase)
                    || (p.Origin != null && string.Equals(outFull, Path.GetFullPath(p.Origin).TrimEnd('\\', '/'), StringComparison.OrdinalIgnoreCase));
                if (clash) throw new IOException(L.T("Нельзя сохранять сборку внутрь исходного пакета или поверх него: ") + p.Name);
            }
            List<Pack> ownPacks = packs;
            packs = Layers(packs);
            bool manyShaders;
            Pack shader = LightOwner(packs, out manyShaders);
            if (shader != null && manyShaders)
                log.Add(L.T("Настройки освещения (шейдер) взяты целиком из «") + shader.Name + L.T("»: настройки разных шейдеров между собой не смешиваются."));

            // выключенные пользователем текстуры: на них не должно остаться и ссылок в списках текстур
            HashSet<string> off = new HashSet<string>();
            bool hasSets = false;
            foreach (Entry e in entries)
            {
                if (e.Excluded && Img.IsImage(e.Key)) off.Add(NoExt(e.Key));
                if (!e.Excluded && e.Key.EndsWith(SetSuffix)) hasSets = true;
            }
            // случайные варианты: под какими именами они лягут в сборку
            List<KeyValuePair<VariantOut, string>> plan = new List<KeyValuePair<VariantOut, string>>();
            Dictionary<string, List<string>> extraPaths = new Dictionary<string, List<string>>(StringComparer.OrdinalIgnoreCase);
            if (variants != null)
            {
                HashSet<string> taken = new HashSet<string>();
                foreach (Entry e in entries) if (Img.IsImage(e.Key)) taken.Add(NoExt(e.Key));
                foreach (VariantOut v in variants)
                {
                    if (v.E.Excluded || v.E.Orphan) continue;
                    string baseRel = NoExt(v.E.Rel), vName;
                    int n = 2;
                    do { vName = baseRel + "_v" + n++; } while (!taken.Add(vName.ToLowerInvariant()));
                    List<string> list;
                    if (!extraPaths.TryGetValue(baseRel, out list)) extraPaths[baseRel] = list = new List<string>();
                    list.Add(vName);
                    plan.Add(new KeyValuePair<VariantOut, string>(v, vName));
                    if (v.Layers.Count > 0) hasSets = true;
                }
            }
            string terrainRel = null;
            byte[] terrainData = null;
            // 1. JSON: слияние одноимённых файлов и разбор файлов с определениями
            Dictionary<string, Doc> docs = new Dictionary<string, Doc>();
            foreach (Entry e in entries)
            {
                MergeKind k = KindOf(e.Key);
                if (e.Excluded || e.Orphan || k == MergeKind.None || k == MergeKind.Lang) continue;
                if (e.Sources.Count < 2 && !DefFolder(e.Key) && !(off.Count > 0 && IsTexIndex(e.Key))) continue;
                Doc d = MakeDoc(e, packs, log);
                if (d != null) docs[e.Key] = d;
            }
            // 2. одинаковые объекты в файлах с разными именами
            int deduped = Dedupe(new List<Doc>(docs.Values));
            if (off.Count > 0)
                foreach (Doc d in docs.Values)
                    if (IsTexIndex(d.E.Key) && Prune(d.Root, off)) d.Changed = true;
            // случайные варианты мобов: описания мобов дописываются до того, как файлы лягут в сборку
            HashSet<string> applied = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            List<KeyValuePair<string, byte[]>> mobFiles = new List<KeyValuePair<string, byte[]>>();
            bool blockPlan = false;
            foreach (KeyValuePair<VariantOut, string> pv in plan) if (!TexNorm(pv.Key.E.Key).StartsWith("textures/entity/")) blockPlan = true;
            if (plan.Count > 0) try { MobVariants(extraPaths, docs, applied, mobFiles); } catch (Exception) { }

            string ext = Path.GetExtension(outPath).ToLowerInvariant();
            bool zipOut = ext == ".mcpack" || ext == ".zip" || ext == ".mcaddon";
            int merged = 0, written = 1, excluded = 0, orphans = 0;
            List<string> unsafeFiles = new List<string>();
            string tmp = outPath + ".tmp";
            FileStream fs = null;
            ZipArchive zip = null;
            bool done = false;
            try
            {
                if (zipOut)
                {
                    fs = new FileStream(tmp, FileMode.Create);
                    zip = new ZipArchive(fs, ZipArchiveMode.Create);
                }
                else Directory.CreateDirectory(outPath);

                Action<string, byte[]> put = delegate(string rel, byte[] data)
                {
                    if (zip != null)
                    {
                        ZipArchiveEntry en = zip.CreateEntry(rel, CompressionLevel.Optimal);
                        using (Stream s = en.Open()) s.Write(data, 0, data.Length);
                    }
                    else
                    {
                        string dest = Path.Combine(outPath, rel.Replace('/', Path.DirectorySeparatorChar));
                        Directory.CreateDirectory(Path.GetDirectoryName(dest));
                        File.WriteAllBytes(dest, data);
                    }
                };

                List<Pack> usedPacks = UsedPacks(entries, docs, ownPacks);
                List<string> authors = new List<string>();
                foreach (Pack up in usedPacks)
                    foreach (string au in AuthorsOf(up))
                        if (!authors.Contains(au)) authors.Add(au);
                put("manifest.json", Manifest(name, desc, packs, log, hasSets, authors));
                int credited = PutCredits(usedPacks, put);
                if (credited > 0) log.Add(L.T("Авторы и лицензии исходных пакетов сохранены в папке credits: ") + credited + ".");
                foreach (Entry e in entries)
                {
                    if (e.Orphan) { orphans++; continue; }
                    if (e.Excluded) { excluded++; continue; }
                    if (Risk.Program(e.Key) || Risk.Archive(e.Key)) { unsafeFiles.Add(e.Rel); continue; } // программам и архивам в пакете не место
                    byte[] data = null;
                    Doc d;
                    if (docs.TryGetValue(e.Key, out d))
                    {
                        if (d.Drop) continue;
                        // нетронутый файл из одного пака копируется как есть, с исходным оформлением
                        if (d.Changed || e.Sources.Count > 1) data = utf.GetBytes(Json.Write(d.Root) + "\n");
                    }
                    else if (KindOf(e.Key) == MergeKind.Lang) data = e.Sources.Count > 1 ? MergeLang(e) : CleanLang(e);
                    if (e.Key == "textures/textures_list.json") data = TexList(entries);
                    if (data != null && e.Sources.Count > 1) merged++;
                    if (e.ColorFix != null || e.SetPatch != null) data = FixColor(e) ?? data;
                    if (data == null) data = File.ReadAllBytes(e.Winner.FullPath(e.Key));
                    if (blockPlan && e.Key == "textures/terrain_texture.json")
                    {
                        // список текстур блоков дописывается вариантами и кладётся в сборку после остальных файлов
                        terrainRel = e.Rel;
                        terrainData = data;
                        continue;
                    }
                    put(e.Rel, data);
                    written++;
                }
                if (plan.Count > 0)
                {
                    if (blockPlan)
                    {
                        put(terrainRel ?? "textures/terrain_texture.json", TerrainWithVariants(terrainData, extraPaths, name, applied));
                        written++;
                    }
                    foreach (KeyValuePair<string, byte[]> mf in mobFiles)
                    {
                        put(mf.Key, mf.Value);
                        written++;
                    }
                    int added = 0, addedMobs = 0;
                    foreach (KeyValuePair<VariantOut, string> pv in plan)
                    {
                        VariantOut v = pv.Key;
                        string baseRel = NoExt(v.E.Rel);
                        bool isMob = TexNorm(v.E.Key).StartsWith("textures/entity/");
                        if (!applied.Contains(baseRel))
                        {
                            // файл не назван ни в списке пакетов, ни в списке игры: игра варианты не увидит, лишнее не кладём
                            log.Add(v.E.Rel + L.T(isMob ? ": моб с этой текстурой не найден, или игра выбирает её из готового списка — случайные варианты не добавлены." : ": блок с этой текстурой не найден в списках текстур, случайные варианты не добавлены."));
                            continue;
                        }
                        put(pv.Value + Path.GetExtension(v.Color), File.ReadAllBytes(v.Color));
                        written++;
                        if (isMob) addedMobs++; else added++;
                        if (v.Layers.Count == 0) continue;
                        JObj doc = new JObj(), ts = new JObj();
                        bool deep = false;
                        ts.Set("color", Path.GetFileName(pv.Value));
                        foreach (KeyValuePair<string, string> l in v.Layers)
                        {
                            bool sub = l.Key.EndsWith("subsurface");
                            deep |= sub;
                            string lName = pv.Value + "_" + (l.Key == "normal" ? "normal" : (l.Key == "heightmap" ? "heightmap" : (sub ? "mers" : "mer")));
                            put(lName + Path.GetExtension(l.Value), File.ReadAllBytes(l.Value));
                            written++;
                            ts.Set(l.Key, Path.GetFileName(lName));
                        }
                        doc.Set("format_version", deep ? "1.21.30" : "1.16.100");
                        doc.Set("minecraft:texture_set", ts);
                        put(pv.Value + ".texture_set.json", utf.GetBytes(Json.Write(doc) + "\n"));
                        written++;
                    }
                    if (added > 0) log.Add(L.T("Случайных вариантов текстур блоков добавлено: ") + added + ".");
                    if (addedMobs > 0) log.Add(L.T("Случайных вариантов текстур мобов добавлено: ") + addedMobs + ".");
                }
                done = true;
            }
            finally
            {
                try { if (zip != null) zip.Dispose(); }
                finally
                {
                    if (fs != null) fs.Dispose();
                    // сборка сорвалась — недописанный файл рядом с целью не оставляем
                    if (!done && zipOut) try { File.Delete(tmp); } catch (Exception) { }
                }
            }
            if (zipOut)
            {
                try
                {
                    if (File.Exists(outPath)) File.Delete(outPath);
                    File.Move(tmp, outPath);
                }
                catch (Exception)
                {
                    try { File.Delete(tmp); } catch (Exception) { }
                    throw;
                }
            }
            if (orphans > 0) log.Add(L.T("Карт слоёв, которые ничто не использует, не вошло в сборку: ") + orphans + ".");
            if (unsafeFiles.Count > 0)
                log.Add(L.T("Не вошли в сборку как небезопасные или лишние (программы, сценарии, вложенные архивы): ") + unsafeFiles.Count + " — "
                    + string.Join(", ", unsafeFiles.GetRange(0, Math.Min(8, unsafeFiles.Count)).ToArray()) + (unsafeFiles.Count > 8 ? "…" : "") + ".");
            int replaced = 0;
            foreach (Entry e in entries) if (e.Sources.Count > 1 && !e.AutoMerge && !e.Excluded) replaced++;
            if (excluded > 0) log.Add(L.T("Выключено вручную и не вошло в сборку: ") + excluded + ".");
            log.Insert(0, L.T("Файлов в сборке: ") + written + ".\n"
                + L.T("Объединено по содержимому (JSON, .lang): ") + merged + ".\n"
                + L.T("Одинаковых объектов в файлах с разными именами улажено по приоритету: ") + deduped + ".\n"
                + L.T("Текстур и прочих файлов, взятых целиком из более важного пака: ") + replaced + ".");
            return log;
        }
    }

    // ------------------------------------------------------------------ 3D-модели

    class Quad
    {
        public float[] P = new float[12]; // четыре угла: слева сверху, справа сверху, справа снизу, слева снизу
        public float[] UV = new float[8]; // те же углы в пикселях развёртки
    }

    class Model
    {
        public List<Quad> Quads = new List<Quad>();
        public int TexW, TexH;            // размер развёртки, на который рассчитана модель; 0 — не указан
        public float Cx, Cy, Cz, Radius;  // центр и радиус охватывающей сферы
        public float[] View;              // свой исходный ракурс { поворот, наклон }; null — общий
        public bool Opaque;               // прозрачность текстуры не учитывается (магма-куб: в игре он непрозрачный)
        public bool TopFrame;             // текстура — лента кадров анимации (фонарь): на модель идёт только верхний кадр
        public Model Alt;                 // запасная модель: берётся, если проверочный участок развёртки пуст
        public float[] AltProbe;          // этот участок { u0, v0, u1, v1 } в единицах развёртки
        public bool AltSquare;            // запасная модель берётся, если текстура квадратная, а эта модель рассчитана на вытянутую
    }

    class GeoDef
    {
        public string Id, Parent;
        public JObj Obj;
        public bool Old; // формат 1.8: кости лежат прямо в объекте "geometry.имя"
    }

    // Что известно о текстуре из описания сущности: какая у неё модель и какие анимации задают позу.
    class EntInfo
    {
        public string Gid, Id; // модель и идентификатор самой сущности (minecraft:zombie)
        public List<string> Anims = new List<string>();
        public long Version; // min_engine_version описания: из нескольких описаний одной сущности берётся самое новое
    }

    // Набор описаний из одного источника (игра или паки).
    class GeoLib
    {
        public Dictionary<string, GeoDef> Defs = new Dictionary<string, GeoDef>();
        public Dictionary<string, EntInfo> Tex = new Dictionary<string, EntInfo>();
        public Dictionary<string, JObj> Anims = new Dictionary<string, JObj>();
    }

    // Модели сущностей: из загруженных паков и из установленной игры. Какая модель у текстуры,
    // определяется по описаниям сущностей (entity/*.json), где указаны и текстуры, и геометрия.
    static class Geo
    {
        static GeoLib game, pack = new GeoLib();
        static Dictionary<string, Model> models = new Dictionary<string, Model>();
        static Dictionary<string, Model> byTexture = new Dictionary<string, Model>();
        static string packSig = "";

        // ---------------------------------------------------------- загрузка описаний

        static long VersionOf(object o)
        {
            string s = o as string;
            long v = 0;
            if (s == null) return 0;
            foreach (string part in s.Split('.'))
            {
                int n;
                int.TryParse(part, out n);
                v = v * 1000 + n;
            }
            return v;
        }

        static void AddJson(string text, GeoLib lib)
        {
            JObj root;
            try { root = Json.Parse(text) as JObj; }
            catch (Exception) { return; }
            if (root == null) return;
            foreach (string k in root.Keys)
            {
                object v = root.Map[k];
                if (k.StartsWith("geometry.") && v is JObj) AddDef(k, (JObj)v, true, lib.Defs);
                else if (k == "minecraft:geometry" && v is List<object>)
                {
                    foreach (object g in (List<object>)v)
                    {
                        JObj go = g as JObj;
                        JObj d = go == null ? null : go.Get("description") as JObj;
                        string id = d == null ? null : d.Get("identifier") as string;
                        if (id != null) AddDef(id, go, false, lib.Defs);
                    }
                }
                else if (k == "animations" && v is JObj)
                {
                    JObj anims = (JObj)v;
                    foreach (string ak in anims.Keys) if (anims.Map[ak] is JObj) lib.Anims[ak] = (JObj)anims.Map[ak];
                }
                else if (k == "minecraft:client_entity" || k == "minecraft:attachable")
                {
                    JObj ce = v as JObj;
                    JObj d = ce == null ? null : ce.Get("description") as JObj;
                    JObj t = d == null ? null : d.Get("textures") as JObj, g = d == null ? null : d.Get("geometry") as JObj;
                    if (t == null || g == null || g.Keys.Count == 0) continue;
                    // анимации, которые играют всегда (setup, general): в них игра задаёт исходную позу
                    List<string> always = new List<string>();
                    JObj names = d.Get("animations") as JObj, scripts = d.Get("scripts") as JObj;
                    List<object> animate = scripts == null ? null : scripts.Get("animate") as List<object>;
                    if (names != null && animate != null)
                        foreach (object a in animate)
                        {
                            string id = a is string ? names.Get((string)a) as string : null;
                            if (id != null) always.Add(id);
                        }
                    // исходную позу игра нередко задаёт анимацией «general» или «base_pose», которую включает не описание,
                    // а контроллер (скрещённые руки жителя и ведьмы): такие анимации тоже учитываются
                    if (names != null)
                        foreach (string nk in names.Keys)
                        {
                            string aid = names.Map[nk] as string;
                            if (aid != null && (aid.EndsWith(".general") || aid.EndsWith(".base_pose") || aid.EndsWith(".setup")) && !always.Contains(aid)) always.Add(aid);
                        }
                    long ver = VersionOf(d.Get("min_engine_version"));
                    foreach (string tk in t.Keys)
                    {
                        string path = t.Map[tk] as string;
                        string near = null;
                        foreach (string gk in g.Keys)
                            if (gk != "default" && tk.StartsWith(gk) && (near == null || gk.Length > near.Length)) near = gk;
                        string gid = (g.Get(tk) ?? (near != null ? g.Get(near) : null) ?? g.Get("default") ?? g.Map[g.Keys[0]]) as string;
                        if (path == null || gid == null) continue;
                        EntInfo old;
                        if (lib.Tex.TryGetValue(path.ToLowerInvariant(), out old) && old.Version > ver) continue;
                        EntInfo info = new EntInfo();
                        info.Gid = gid;
                        info.Id = d.Get("identifier") as string;
                        info.Anims = always;
                        info.Version = ver;
                        lib.Tex[path.ToLowerInvariant()] = info;
                    }
                }
            }
        }

        static void AddDef(string key, JObj obj, bool old, Dictionary<string, GeoDef> defs)
        {
            string[] parts = key.Split(':'); // "geometry.zombie:geometry.humanoid" — модель с родителем
            GeoDef d = new GeoDef();
            d.Id = parts[0];
            d.Parent = parts.Length > 1 ? parts[1] : null;
            d.Obj = obj;
            d.Old = old;
            // В новых версиях игры из моделей убран исходный поворот деталей (bind_pose_rotation): лежачее туловище лисы,
            // оцелота, медведя в файле стоит стоймя. Прежняя версия той же модели его хранит — он переносится в новую.
            GeoDef was;
            if (defs.TryGetValue(d.Id, out was))
            {
                List<object> fresh = obj.Get("bones") as List<object>, stale = was.Obj.Get("bones") as List<object>;
                if (fresh != null && stale != null)
                    foreach (object fo in fresh)
                    {
                        JObj fb = fo as JObj;
                        string fname = fb == null ? null : fb.Get("name") as string;
                        if (fname == null || fb.Get("bind_pose_rotation") != null) continue;
                        foreach (object so in stale)
                        {
                            JObj sb = so as JObj;
                            if (sb == null || (sb.Get("name") as string) != fname || sb.Get("bind_pose_rotation") == null) continue;
                            fb.Set("bind_pose_rotation", sb.Get("bind_pose_rotation"));
                            break;
                        }
                    }
            }
            defs[d.Id] = d;
        }

        // Архив игры .brarchive: заголовок 16 байт, затем записи по 256 байт (имя, смещение, длина), затем сами файлы.
        static void AddArchive(string file, GeoLib lib)
        {
            try
            {
                byte[] b = File.ReadAllBytes(file);
                if (b.Length < 16) return;
                int n = BitConverter.ToInt32(b, 8), start = 16 + n * 256;
                if (n < 0 || 16L + (long)n * 256 > b.Length) return;
                for (int i = 0; i < n; i++)
                {
                    int o = 16 + i * 256;
                    int off = BitConverter.ToInt32(b, o + 248), len = BitConverter.ToInt32(b, o + 252);
                    if (off < 0 || len <= 0 || (long)start + off + len > b.Length) continue;
                    AddJson(Encoding.UTF8.GetString(b, start + off, len), lib);
                }
            }
            catch (Exception) { }
        }

        static void AddFolder(string dir, GeoLib lib)
        {
            if (!Directory.Exists(dir)) return;
            try
            {
                foreach (string f in Directory.GetFiles(dir, "*.json", SearchOption.AllDirectories))
                    try { AddJson(File.ReadAllText(f), lib); } catch (Exception) { }
            }
            catch (Exception) { }
        }

        static int[] DirVersion(string dirName)
        {
            int[] v = new int[4];
            string[] parts = dirName.Substring(Math.Min(dirName.Length, 8)).Split('.');
            for (int i = 0; i < parts.Length && i < 4; i++) int.TryParse(parts[i], out v[i]);
            return v;
        }

        // Стандартные модели берутся из установленной игры; без неё 3D-вид есть только у моделей из самих паков.
        static void EnsureGame()
        {
            if (game != null) return;
            game = new GeoLib();
            List<string> roots = new List<string>();
            try
            {
                foreach (DriveInfo d in DriveInfo.GetDrives())
                {
                    if (d.DriveType != DriveType.Fixed) continue;
                    roots.Add(Path.Combine(d.Name, @"XboxGames\Minecraft for Windows\Content\data\resource_packs"));
                }
            }
            catch (Exception) { }
            foreach (string root in roots)
            {
                if (!Directory.Exists(root)) continue;
                try
                {
                    List<string> dirs = new List<string>();
                    foreach (string d in Directory.GetDirectories(root))
                    {
                        string name = Path.GetFileName(d).ToLowerInvariant();
                        if (name == "vanilla" || (name.StartsWith("vanilla_") && name.Length > 8 && char.IsDigit(name[8]))) dirs.Add(d);
                    }
                    // более новые версии перекрывают старые, как и в самой игре
                    dirs.Sort(delegate(string a, string b)
                    {
                        int[] va = DirVersion(Path.GetFileName(a)), vb = DirVersion(Path.GetFileName(b));
                        for (int i = 0; i < 4; i++) if (va[i] != vb[i]) return va[i].CompareTo(vb[i]);
                        return 0;
                    });
                    foreach (string d in dirs)
                    {
                        foreach (string sub in new string[] { "models", "entity", "attachables", "animations" })
                            AddFolder(Path.Combine(d, sub), game);
                        string br = Path.Combine(d, "__brarchive");
                        if (!Directory.Exists(br)) continue;
                        foreach (string name in new string[] { "models.brarchive", "entity.brarchive", "attachables.brarchive", "animations.brarchive" })
                            if (File.Exists(Path.Combine(br, name))) AddArchive(Path.Combine(br, name), game);
                        string nested = Path.Combine(br, "models");
                        if (Directory.Exists(nested))
                            foreach (string f in Directory.GetFiles(nested, "*.brarchive", SearchOption.AllDirectories)) AddArchive(f, game);
                    }
                }
                catch (Exception) { }
                if (game.Defs.Count > 0) { GameDir = root; break; }
            }
            if (!game.Defs.ContainsKey("geometry.boat")) AddJson(BoatJson, game);
            AddJson(ChestJson, game);
            AddJson(SignJson, game);
            AddJson(BannerJson, game);
            AddJson(PistonJson, game);
            AddJson(PotJson, game);
            AddJson(BlocksJson, game);
            AddJson(MoreBlocksJson, game);
            AddJson(PropaguleJson, game);
            AddJson(DragonJson, game); // заменяет описание из игры
            AddJson(ShieldJson, game);
            AddJson(LanternJson, game);
            AddJson(EggJson, game);
            string dump = Environment.GetEnvironmentVariable("BPS_GEODUMP"); // для проверки: какие модели и описания нашлись в игре
            if (dump != null)
            {
                List<string> lines = new List<string>();
                lines.Add("dir: " + GameDir);
                foreach (string k in game.Defs.Keys) lines.Add("def " + k);
                foreach (KeyValuePair<string, EntInfo> kv in game.Tex) lines.Add("tex " + kv.Key + " -> " + kv.Value.Gid + " (" + kv.Value.Id + ")");
                File.WriteAllLines(dump, lines.ToArray());
            }
        }

