        public void ClearCache()
        {
            foreach (Bitmap[] t in cache.Values)
                foreach (Bitmap b in t) if (b != null) b.Dispose();
            cache.Clear();
            frameCount.Clear();
            cacheBytes = 0;
            if (CacheCleared != null) CacheCleared();
        }

        // ---------------------------------------------------------- раскладка

        int CellW { get { return Math.Max(tile + 12, 88); } }
        int CellH { get { return tile + 12 + 18; } }
        int Mini { get { return (CellW - 4 - 12) / 3; } } // значки идут по три в ряд на ширину варианта

        public event Action CacheCleared;

        // Переходит к текстуре и выделяет её так же, как это делают стрелки клавиатуры.
        public void GoTo(Entry e)
        {
            NavTile best = null;
            foreach (NavTile t in NavTiles())
            {
                if (t.E.Key != e.Key) continue;
                if (best == null || t.P == e.Winner) best = t;
            }
            if (best != null) NavShow(best, -1);
        }

        // Значки под вариантом: развёртка (если сверху 3D-модель) и слои этого пака (если включён их показ).
        // Случайные варианты: у текстуры блока выбрано несколько картинок сразу, у каждой свои слои.
        public Func<Entry, Pack, bool> AlsoOn;                                            // вариант выбран дополнительно к основному
        public Func<Entry, Pack, List<KeyValuePair<string, string>>> MultiMinis;          // значки слоёв этого варианта; null — как обычно
        public Func<Entry, Pack, string, string, bool?> MultiLayerOn;                             // горит ли такой значок; null — как обычно
        public event Action<Entry, Pack> VariantToggled;                                  // Ctrl+щелчок по картинке

        bool LayerLive(Entry e, Pack p, string layerKey, string file)
        {
            bool? multi = MultiLayerOn != null ? MultiLayerOn(e, p, layerKey, file) : null;
            return multi.HasValue ? multi.Value : LayerOn(e, p, layerKey);
        }

        List<KeyValuePair<string, string>> MinisOf(Entry e, Pack p)
        {
            List<KeyValuePair<string, string>> r = new List<KeyValuePair<string, string>>();
            if (!showAttrs) return r;
            // какие слои стоят под этой текстурой, решает окно: слой, назначенный другой текстуре, переезжает под неё
            List<KeyValuePair<string, string>> placed = MultiMinis != null ? MultiMinis(e, p) : null;
            List<KeyValuePair<string, string>> attrs;
            if (placed != null) r.AddRange(placed);
            else if (e.Attrs != null && e.Attrs.TryGetValue(p, out attrs)) r.AddRange(attrs);
            return r;
        }

        // Стороны и стадии одного объекта (log_oak и log_oak_top, wheat_stage_0…7) стоят вплотную одной системой.
        static readonly HashSet<string> SideWords = new HashSet<string>(new string[] {
            "top", "bottom", "side", "front", "back", "end", "inner", "outer", "upper", "lower", "left", "right",
            "north", "south", "east", "west", "up", "down", "on", "off", "lit", "unlit", "powered", "open", "closed", "stage", "age" });

        // Общее имя объекта: название файла без хвоста из обозначений стороны и номеров стадии.
        public static string GroupKey(string key)
        {
            if (!Img.IsImage(key) || !(key.StartsWith("textures/blocks/") || key.StartsWith("textures/items/"))) return key;
            string dir = key.Substring(0, key.LastIndexOf('/') + 1), name = Path.GetFileNameWithoutExtension(key);
            string[] t = name.Split('_');
            int n = t.Length, num;
            while (n > 1 && (SideWords.Contains(t[n - 1]) || int.TryParse(t[n - 1], out num))) n--;
            return dir + string.Join("_", t, 0, n);
        }

        // Цвет рамки системы повторяет кристаллы её текстур: зелёные оттенки (kind 1) — если есть текстура с несколькими
        // вариантами, синие (kind 2) — если все текстуры обычные, оранжевые (kind 0) — в остальных случаях (есть слои).
        // Оттенок и яркость каждой следующей системы сдвигаются на долю золотого сечения, поэтому соседние системы
        // различимы; с чего начать — решается случайно при запуске программы. Цвета насыщенные, без бледных.
        static readonly double tintStart = new Random().NextDouble();

        public static Color GroupTint(int n, int kind)
        {
            double t = (tintStart + n * 0.618034) % 1, u = (tintStart * 7 + n * 0.381966) % 1;
            double h = ((kind == 1 ? 138 : (kind == 2 ? 214 : 32)) + (t - 0.5) * (kind == 1 ? 40 : (kind == 2 ? 36 : 22))) / 60;
            double sat = kind == 1 ? 0.74 : (kind == 2 ? 0.80 : 0.92);
            double light = (kind == 1 ? 0.38 : (kind == 2 ? 0.50 : 0.46)) + u * 0.12;
            double c = (1 - Math.Abs(2 * light - 1)) * sat, x = c * (1 - Math.Abs(h % 2 - 1)), m = light - c / 2;
            double r = 0, g = 0, b = 0;
            if (h < 1) { r = c; g = x; }
            else if (h < 2) { r = x; g = c; }
            else if (h < 3) { g = c; b = x; }
            else if (h < 4) { g = x; b = c; }
            else if (h < 5) { r = x; b = c; }
            else { r = c; b = x; }
            return Color.FromArgb((int)((r + m) * 255), (int)((g + m) * 255), (int)((b + m) * 255));
        }

        void Relayout()
        {
            cards.Clear();
            int cw = CellW, rowH = 0, x = 8, y = 8;
            int maxW = ClientSize.Width - bar.Width - 8;
            // Сетка: карточка с одной картинкой занимает ровно одну ячейку, между ячейками зазор 8.
            // Любая карточка начинается на границе ячейки и занимает целое их число, поэтому столбцы не «плывут».
            int grid = cw + 16;
            // первый проход: размеры карточек и то, какие из соседних относятся к одному объекту
            int count = items.Count;
            int[] tilesN = new int[count], perRow = new int[count], cells = new int[count], extra = new int[count], groupEnd = new int[count];
            string[] group = new string[count];
            int fitTiles = Math.Max(1, (maxW - 8 - 8) / cw); // сколько вариантов помещается в строку витрины
            for (int i = 0; i < count; i++)
            {
                Entry e = items[i] as Entry;
                if (e == null) continue;
                List<Pack> shownTiles = Tiles(e);
                int most = 0;
                foreach (Pack p in shownTiles) most = Math.Max(most, MinisOf(e, p).Count);
                int rows = (most + 2) / 3;
                tilesN[i] = Math.Max(1, shownTiles.Count);
                perRow[i] = Math.Min(tilesN[i], fitTiles); // вариантов больше, чем влезает, — карточка растёт вниз
                cells[i] = (perRow[i] * cw + 8 + 8 + grid - 1) / grid;
                extra[i] = rows == 0 ? 0 : rows * (Mini + 3) + 3;
                group[i] = GroupKey(e.Key);
            }
            for (int i = 0; i < count; )
            {
                int j = i;
                if (group[i] != null) while (j + 1 < count && group[j + 1] == group[i]) j++;
                int tall = 0;
                for (int k = i; k <= j; k++) tall = Math.Max(tall, extra[k]);
                for (int k = i; k <= j; k++) { groupEnd[k] = j; if (j > i) extra[k] = tall; } // у системы общая высота
                i = j + 1;
            }
            bool under = false; // идёт продолжение системы, не поместившейся в одну строку
            int groupNo = 0;    // порядковый номер системы: по нему ей выдаётся цвет
            Color tint = Theme.Accent;
            for (int i = 0; i < count; i++)
            {
                Card c = new Card();
                Head head = items[i] as Head;
                if (head != null)
                {
                    if (x > 8) { x = 8; y += rowH + 8; rowH = 0; }
                    under = false;
                    c.H = head;
                    int hh = head.Big ? 32 : 26, indent = head.Big ? 0 : 18;
                    c.R = new Rectangle(8 + indent, y, Math.Max(50, maxW - 8 - indent), hh);
                    y += hh + 4;
                }
                else
                {
                    c.E = (Entry)items[i];
                    c.Extra = extra[i];
                    c.PerRow = perRow[i];
                    int tileRows = (tilesN[i] + perRow[i] - 1) / perRow[i];
                    int w = cells[i] * grid - 8, natural = perRow[i] * cw + 8;
                    int h = 24 + tileRows * (CellH + c.Extra) + 6; // шапка карточки: 24 пикселя под название и кристаллы
                    c.PadX = (w - natural) / 2; // картинки стоят по центру своих ячеек
                    bool first = i == 0 || group[i - 1] != group[i], grouped = groupEnd[i] > i || !first;
                    c.InGroup = grouped;
                    bool afterUnder = first && under; // перед этой карточкой закончилась система, перенесённая на несколько строк
                    if (first) under = false;
                    if (first && grouped)
                    {
                        // какие кристаллы есть в системе: зелёный (варианты) главнее всех, одни синие — синяя рамка
                        bool many = false, plain = true;
                        for (int k = i; k <= groupEnd[i]; k++)
                        {
                            Entry ge = (Entry)items[k];
                            if (tilesN[k] > 1) many = true;
                            if (ge.Pbr != null) plain = false;
                            else foreach (Pack ap in Tiles(ge)) if (Animated(ge, ap)) plain = false;
                        }
                        tint = GroupTint(groupNo++, many ? 1 : (plain ? 2 : 0));
                    }
                    // одиночная карточка с несколькими вариантами тоже получает свой цвет: это тоже «комплект»
                    c.Tint = grouped ? tint : (tilesN[i] > 1 ? GroupTint(groupNo++, 1) : Theme.Accent);
                    if (grouped && !first)
                    {
                        // следующая сторона того же объекта: в соседней ячейке, а зазор до неё закрыт самой карточкой
                        string baseName = Path.GetFileName(group[i]), name = Path.GetFileNameWithoutExtension(c.E.Rel);
                        c.Suffix = name.Length > baseName.Length ? name.Substring(baseName.Length).TrimStart('_') : name;
                        if (x + w > maxW)
                        {
                            // система шире строки: продолжается ниже вплотную, без зазора между строками
                            x = 8;
                            y += rowH;
                            rowH = 0;
                            under = true;
                        }
                        else c.Join = true;
                    }
                    else
                    {
                        // система целиком переносится на новую строку, если не помещается в остаток этой;
                        // справа при этом остаются пустые ячейки — разрывать систему между строками нельзя
                        int whole = 0;
                        for (int k = i; k <= groupEnd[i]; k++) whole += cells[k] * grid;
                        whole -= 8;
                        // и та, что шире целой строки, тоже начинается с новой: её продолжения лягут ровно под ней
                        // после системы, занявшей несколько строк, тоже новая строка: иначе чужая карточка прилипла бы к её продолжению
                        if (x > 8 && (afterUnder || x + w > maxW || x + whole > maxW)) { x = 8; y += rowH + 8; rowH = 0; }
                    }
                    c.Under = under && grouped;
                    if (c.Join)
                    {
                        c.R = new Rectangle(x - 8, y, w + 8, h);
                        c.PadX += 8;
                    }
                    else c.R = new Rectangle(x, y, w, h);
                    rowH = Math.Max(rowH, h);
                    x += w + 8;
                }
                cards.Add(c);
            }
            int total = cards.Count == 0 ? 0 : (x > 8 ? y + rowH + 8 : y + 8);
            int view = Math.Max(1, ClientSize.Height);
            bar.Maximum = Math.Max(total, view);
            bar.LargeChange = view;
            bar.Enabled = total > view;
            SetScroll(bar.Value);
            Invalidate();
        }

        void SetScroll(int v)
        {
            int max = Math.Max(0, bar.Maximum - bar.LargeChange + 1);
            bar.Value = Math.Max(0, Math.Min(max, v));
        }

        protected override void OnResize(EventArgs e)
        {
            base.OnResize(e);
            ClearMini();
            ClearModelPopup(false);
            Relayout();
        }

        protected override void OnMouseWheel(MouseEventArgs e)
        {
            if (Diag.On) Diag.Log("колесо дошло до самого списка: " + e.Delta + ", клавиши " + ModifierKeys);
            if (Preview.Alt && PreviewOpen)
            {
                // Alt + колесо меняет размер открытого превью, список при этом не прокручивается
                if (Preview.Wheel(e.Delta)) Invalidate();
                return;
            }
            SetScroll(bar.Value - Math.Sign(e.Delta) * 120);
        }

        Rectangle CellRect(Card c, int i)
        {
            int per = Math.Max(1, c.PerRow), col = i % per, row = i / per;
            return new Rectangle(c.R.X + 4 + c.PadX + col * CellW + 2, c.R.Y + 24 + row * (CellH + c.Extra) - bar.Value, CellW - 4, CellH + c.Extra);
        }

        // Крайний правый кристалл карточки; у текстуры со слоями это оранжевый, по нему открывается меню.
        Rectangle BadgeRect(Card c)
        {
            return new Rectangle(c.R.Right - 24, c.R.Y + 5 - bar.Value, 17, 17); // ниже цветной полосы и чуть левее края, чтобы кристалл с ними не сливался
        }

        Rectangle MiniRect(Rectangle cell, int k)
        {
            int m = Mini;
            return new Rectangle(cell.X + 4 + (k % 3) * (m + 2), cell.Y + CellH + (k / 3) * (m + 3), m, m);
        }

        // ---------------------------------------------------------- что под курсором

        Head HeadAt(Point p)
        {
            int vy = p.Y + bar.Value;
            foreach (Card c in cards)
            {
                if (c.R.Top > vy) break;
                if (c.H != null && c.R.Contains(p.X, vy)) return c.H;
            }
            return null;
        }

        bool Hit(Point p, out Entry e, out Pack pack, out bool badge)
        {
            e = null;
            pack = null;
            badge = false;
            int vy = p.Y + bar.Value;
            foreach (Card c in cards)
            {
                if (c.R.Bottom < vy) continue;
                if (c.R.Top > vy) break;
                if (c.E == null || !c.R.Contains(p.X, vy)) continue;
                if (c.E.Pbr != null && BadgeRect(c).Contains(p))
                {
                    e = c.E;
                    badge = true;
                    return true;
                }
                List<Pack> tiles = Tiles(c.E);
                for (int i = 0; i < tiles.Count; i++)
                {
                    if (!CellRect(c, i).Contains(p)) continue;
                    e = c.E;
                    pack = tiles[i];
                    return true;
                }
            }
            return false;
        }

        // Избранное в общем списке не дублирует текстуры: его вариант виден, только если выбран или других нет.
        // В показе самого избранного, наоборот, виден только его вариант.
        public Pack FavPack;
        public bool FavView;
        public Func<Entry, bool> SavedTexture;
        // Показ «Выбранный пакет»: у каждой текстуры виден только вариант этого пакета, чужие варианты скрыты.
        public Pack OnlyPack;

        List<Pack> Tiles(Entry e)
        {
            if (OnlyPack != null && !FavView)
            {
                List<Pack> own = new List<Pack>();
                foreach (Pack p in e.Sources) if (p == OnlyPack || p == OnlyPack.Sub) own.Add(p);
                if (own.Count > 0) return own;
            }
            if (FavPack == null || !e.Sources.Contains(FavPack)) return e.Sources;
            List<Pack> r = new List<Pack>();
            if (FavView) { r.Add(FavPack); return r; }
            bool chosen = e.Sources.Count == 1 || (e.Winner == FavPack && !e.Excluded);
            if (!chosen && e.Slots != null) foreach (Pack sp in e.Slots.Values) if (sp == FavPack) chosen = true;
            if (chosen) return e.Sources;
            foreach (Pack p in e.Sources) if (p != FavPack) r.Add(p);
            return r;
        }

        // Квадрат с картинкой варианта под курсором (без подписи и значков под ним).
        bool TileAt(Point p, out Entry e, out Pack pack, out Rectangle img)
        {
            e = null;
            pack = null;
            img = Rectangle.Empty;
            int vy = p.Y + bar.Value;
            foreach (Card c in cards)
            {
                if (c.R.Bottom < vy) continue;
                if (c.R.Top > vy) break;
                if (c.E == null || !c.R.Contains(p.X, vy)) continue;
                List<Pack> tiles = Tiles(c.E);
                for (int i = 0; i < tiles.Count; i++)
                {
                    Rectangle cell = CellRect(c, i);
                    Rectangle r = new Rectangle(cell.X + (cell.Width - tile) / 2, cell.Y + 6, tile, tile);
                    if (!r.Contains(p)) continue;
                    e = c.E;
                    pack = tiles[i];
                    img = r;
                    return true;
                }
            }
            return false;
        }

        // ---------------------------------------------------------- крупное окошко 3D-модели
        // Появляется, если задержать мышь на модели. На него можно перейти и вращать модель там правой кнопкой;
        // повёрнутая модель остаётся как есть, пока мышь не уйдёт с окошка, и только тогда возвращается.
        Entry mpE;
        Pack mpP;
        Rectangle mpCell, mpBox;
        bool mpShown;
        Timer mpTimer, mpClose;
        Rectangle mpPenRect; // карандаш на окошке: редактор этой текстуры
        bool mpPenHot;
        Bitmap mpStrip; // mpStrip — полная лента кадров анимированной текстуры
        string mpStripPath;
        Stopwatch mpClock;
        Timer mpAnim;

        // Зона, где окошко текстуры не закрывается: сама картинка, само окошко и коридор между ними на высоте картинки.
        // Подпись и слои под картинкой в неё не входят: уйдя на них, мышь окошко больше не держит.
        bool MpHas(Point p)
        {
            if (Rectangle.Inflate(mpCell, 2, 2).Contains(p)) return true;
            if (mpBox.IsEmpty) return false;
            if (Rectangle.Inflate(mpBox, 2, 2).Contains(p)) return true;
            int left = Math.Min(mpCell.Right, mpBox.Right), right = Math.Max(mpCell.Left, mpBox.Left);
            return p.X >= left && p.X <= right && p.Y >= mpCell.Top - 2 && p.Y <= mpCell.Bottom + 2;
        }

        void ClearModelPopup(bool comeBack)
        {
            if (mpTimer != null) mpTimer.Stop();
            if (mpClose != null) mpClose.Stop();
            if (mpAnim != null) mpAnim.Stop();
            if (mpStrip != null) { mpStrip.Dispose(); mpStrip = null; mpStripPath = null; }
            mpPenHot = false;
            bool was = mpShown;
            mpShown = false;
            mpE = null;
            mpP = null;
            mpBox = Rectangle.Empty;
            if (was) Invalidate();
        }

        void UpdateModelHover(Point loc)
        {
            Entry e;
            Pack p;
            Rectangle img;
            if (!TileAt(loc, out e, out p, out img) || !Img.IsImage(e.Key))
            {
                if (!mpShown) ClearModelPopup(false); // ушли раньше, чем окошко успело появиться
                return;
            }
            if (e == mpE && p == mpP) return;
            ClearModelPopup(true);
            mpE = e;
            mpP = p;
            mpCell = img;
            if (mpTimer == null)
            {
                mpTimer = new Timer();
                mpTimer.Interval = 220;
                mpTimer.Tick += delegate { mpTimer.Stop(); mpShown = mpE != null; Invalidate(); };
            }
            mpTimer.Interval = DockPreview ? 1 : 220; // панель превью слева внизу обновляется сразу, окошко — с задержкой
            mpTimer.Start();
        }

        void DrawModelPopup(Graphics g)
        {
            int size = Preview.Size(Math.Max(tile, 96) * 2), w = size + 16, h = size + 16 + 22;
            int maxX = ClientSize.Width - bar.Width - w - 4;
            int x = mpCell.Right + 10, y = mpCell.Top + mpCell.Height / 2 - h / 2;
            if (x > maxX) x = mpCell.Left - w - 10;
            x = Math.Max(4, Math.Min(maxX, x));
            y = Math.Max(4, Math.Min(ClientSize.Height - h - 4, y));
            Rectangle box = new Rectangle(x, y, w, h);
            previewBox = box;
            mpBox = box;
            using (SolidBrush b = new SolidBrush(Color.FromArgb(70, 0, 0, 0))) g.FillRectangle(b, box.X + 4, box.Y + 4, box.Width, box.Height);
            using (SolidBrush b = new SolidBrush(Theme.Card)) g.FillRectangle(b, box);
            using (Pen pen = new Pen(Theme.Dim)) g.DrawRectangle(pen, box.X, box.Y, box.Width - 1, box.Height - 1);
            Rectangle pic = new Rectangle(box.X + 8, box.Y + 8, size, size);
            using (HatchBrush hb = new HatchBrush(HatchStyle.LargeCheckerBoard, Color.FromArgb(214, 214, 214), Color.White)) g.FillRectangle(hb, pic);
            int budget = 1;
            bool pending = false;
            string path = mpP.FullPath(mpE.Key);
            Bitmap[] t = Master(path, false, ref budget, ref pending);
            bool played = false;
            if (Animated(mpE, mpP))
            {
                // анимированная текстура проигрывается: кадры берутся из полной ленты
                try
                {
                    if (mpStrip == null || mpStripPath != path)
                    {
                        if (mpStrip != null) mpStrip.Dispose();
                        mpStrip = Img.Load(path);
                        mpStripPath = path;
                        mpClock = Stopwatch.StartNew();
                    }
                    int fw = mpStrip.Width, total = Math.Max(1, mpStrip.Height / fw);
                    int ticks = FlipTicks != null ? FlipTicks(mpE) : 0;
                    if (ticks <= 0) ticks = 2;
                    int frame = (int)(mpClock.ElapsedMilliseconds / (ticks * 50L) % total); // такт игры — 1/20 секунды
                    g.InterpolationMode = fw <= size ? InterpolationMode.NearestNeighbor : InterpolationMode.HighQualityBilinear;
                    g.PixelOffsetMode = PixelOffsetMode.Half;
                    g.DrawImage(mpStrip, pic, new Rectangle(0, frame * fw, fw, fw), GraphicsUnit.Pixel);
                    played = true;
                    if (mpAnim == null)
                    {
                        mpAnim = new Timer();
                        mpAnim.Interval = 50;
                        mpAnim.Tick += delegate { if (mpShown) Invalidate(mpBox); else mpAnim.Stop(); };
                    }
                    mpAnim.Start();
                }
                catch (Exception) { }
            }
            if (!played && t != null && t[0] != null) DrawFit(g, t[0], pic);
            mpPenRect = new Rectangle(box.Right - 22, box.Y + 8 + size + 4, 16, 16);
            DrawPencil(g, mpPenRect, mpPenHot);
            TextRenderer.DrawText(g, Path.GetFileNameWithoutExtension(mpE.Rel) + "   —   " + mpP.Name, boldFont, new Rectangle(box.X + 24, box.Y + 8 + size + 4, w - 48, 17), Theme.Text,
                TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix);
        }

        bool MiniAt(Point p, out Entry e, out Pack pack, out int index, out Rectangle rect, out KeyValuePair<string, string> item)
        {
            e = null;
            pack = null;
            index = -1;
            rect = Rectangle.Empty;
            item = new KeyValuePair<string, string>();
            int vy = p.Y + bar.Value;
            foreach (Card c in cards)
            {
                if (c.R.Bottom < vy) continue;
                if (c.R.Top > vy) break;
                if (c.E == null || c.Extra == 0 || !c.R.Contains(p.X, vy)) continue;
                List<Pack> tiles = Tiles(c.E);
                for (int i = 0; i < tiles.Count; i++)
                {
                    Rectangle cell = CellRect(c, i);
                    List<KeyValuePair<string, string>> minis = MinisOf(c.E, tiles[i]);
                    for (int k = 0; k < minis.Count; k++)
                    {
                        if (!MiniRect(cell, k).Contains(p)) continue;
                        e = c.E;
                        pack = tiles[i];
                        index = k;
                        rect = MiniRect(cell, k);
                        item = minis[k];
                        return true;
                    }
                }
            }
            return false;
        }

        // Звезда избранного в начале строки с названием текстуры.
        Rectangle StarRect(Rectangle cell)
        {
            return new Rectangle(cell.X + 2, cell.Y + tile + 11, 16, 16);
        }

        Entry StarAt(Point p, out Pack pack)
        {
            pack = null;
            int vy = p.Y + bar.Value;
            foreach (Card c in cards)
            {
                if (c.R.Bottom < vy) continue;
                if (c.R.Top > vy) break;
                if (c.E == null || !Img.IsImage(c.E.Key) || !c.R.Contains(p.X, vy)) continue;
                List<Pack> tiles = Tiles(c.E);
                for (int i = 0; i < tiles.Count; i++)
                {
                    if (!StarRect(CellRect(c, i)).Contains(p)) continue;
                    pack = tiles[i];
                    return c.E;
                }
            }
            return null;
        }

        public event Action<Entry> NameCopied; // правый щелчок по названию на карточке

        // Строка названия карточки: между звездой слева и кристаллами справа.
        Entry TitleAt(Point p)
        {
            int vy = p.Y + bar.Value;
            foreach (Card c in cards)
            {
                if (c.R.Bottom < vy) continue;
                if (c.R.Top > vy) break;
                if (c.E == null) continue;
                Rectangle row = new Rectangle(c.R.X + 4, c.R.Y + 4 - bar.Value, c.R.Width - 4 - 43, 19);
                if (row.Contains(p)) return c.E;
            }
            return null;
        }

        public static void DrawStar(Graphics g, Rectangle r, bool on, bool hot, Color edge = default(Color))
        {
            PointF[] pts = new PointF[10];
            float cx = r.X + r.Width / 2f, cy = r.Y + r.Height / 2f + 0.5f;
            for (int i = 0; i < 10; i++)
            {
                double a = -Math.PI / 2 + i * Math.PI / 5, rad = i % 2 == 0 ? 7.2 : 3.1;
                pts[i] = new PointF(cx + (float)(Math.Cos(a) * rad), cy + (float)(Math.Sin(a) * rad));
            }
            SmoothingMode sm = g.SmoothingMode;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            if (on)
                using (SolidBrush b = new SolidBrush(Color.FromArgb(255, 196, 37))) g.FillPolygon(b, pts);
            using (Pen pen = new Pen(!edge.IsEmpty ? edge : (hot ? Theme.Accent : (on ? Color.FromArgb(196, 140, 0) : Theme.Dim)), 1.3f)) g.DrawPolygon(pen, pts);
            g.SmoothingMode = sm;
        }

        // Карандаш пиксель-артом 8×8, каждая точка рисуется квадратом 2×2: k — контур, y — корпус, p — ластик, w — дерево.
        static readonly string[] PencilArt = {
            ".....kk.",
            "....kppk",
            "...kyypk",
            "..kyyyk.",
            ".kyyyk..",
            "kwyyk...",
            "kkwk....",
            "kkk....." };

        static void DrawPencil(Graphics g, Rectangle r, bool hot)
        {
            // без подложки; под курсором обводится рамкой
            if (hot)
                using (Pen edge = new Pen(Theme.Accent)) g.DrawRectangle(edge, r.X - 1, r.Y - 1, r.Width + 1, r.Height + 1);
            for (int y = 0; y < 8; y++)
                for (int x = 0; x < 8; x++)
                {
                    char c = PencilArt[y][x];
                    if (c == '.') continue;
                    Color col = c == 'k' ? Color.FromArgb(34, 34, 40) : (c == 'y' ? Color.FromArgb(255, 196, 37)
                        : (c == 'p' ? Color.FromArgb(240, 104, 136) : Color.FromArgb(240, 214, 170)));
                    using (SolidBrush b = new SolidBrush(col)) g.FillRectangle(b, r.X + x * 2, r.Y + y * 2, 2, 2);
                }
        }

        static bool On(Entry e, Pack p)
        {
            return !e.Excluded && (e.AutoMerge || e.Winner == p);
        }

        static bool Fixed(Entry e)
        {
            return e.AutoMerge || e.Locked;
        }

        static bool LayerOn(Entry e, Pack p, string layerKey)
        {
            if (layerKey == Unwrap) return On(e, p);
            Pack sp;
            return e.Slots != null && e.Slots.TryGetValue(Builder.SlotOf(layerKey), out sp) && sp == p;
        }

        // Всплывающее окошко слоя: пока мышь на нём или на пути к нему от значка, оно не закрывается.
        public event Action<Entry, Pack, KeyValuePair<string, string>> PopupFavClicked, PopupEditClicked;
        Rectangle popupBox, popStarRect, popPenRect;
        int popHot; // 1 — мышь на звезде окошка, 2 — на карандаше

        bool InPopup(Point p)
        {
            if (!popup || miniE == null || popupBox.IsEmpty) return false;
            // Зона, где окошко не закрывается: сам значок, само окошко и узкий коридор между ними на высоте значка.
            // Всё, что выше и ниже значка (там могут стоять другие слои), в зону не входит — на них можно навестись.
            if (Rectangle.Inflate(popupBox, 2, 2).Contains(p) || Rectangle.Inflate(miniRect, 2, 2).Contains(p)) return true;
            int left = Math.Min(miniRect.Right, popupBox.Right), right = Math.Max(miniRect.Left, popupBox.Left);
            return p.X >= left && p.X <= right && p.Y >= miniRect.Top - 2 && p.Y <= miniRect.Bottom + 2;
        }

        Timer leaveTimer; // отсчёт до закрытия окошка слоя, когда мышь ушла на другую текстуру

        void ClearMini()
        {
            popupTimer.Stop();
            if (leaveTimer != null) leaveTimer.Stop();
            popup = false;
            popupBox = Rectangle.Empty;
            popHot = 0;
            miniE = null;
            miniP = null;
            miniK = -1;
        }

        // Настоящая мышь после проверочного наведения не учитывается, иначе она сразу сбила бы его.
        bool testHold;

        public void TestHover(Point p)
        {
            OnMouseMove(new MouseEventArgs(MouseButtons.None, 0, p.X, p.Y, 0));
            testHold = true;
        }

        // ---------------------------------------------------------- мышь

        protected override void OnMouseMove(MouseEventArgs ev)
        {
            base.OnMouseMove(ev);
            if (testHold) return;
            if (navKey != null)
            {
                // Пока есть выделение (от стрелок или Shift), превью показывает выделенное, а мышь, стоящая на месте,
                // его не перебивает. Сдвинули мышь — выделение пропадает, дальше всё снова идёт за мышью.
                Point now = Cursor.Position;
                int moved = Math.Abs(now.X - navMouse.X) + Math.Abs(now.Y - navMouse.Y);
                // Колесо и клавиши слегка толкают мышь: небольшой сдвиг сразу после шага выделения движением не считается,
                // иначе выделение слетало бы посреди перебора, и следующий шаг начинался бы с другого места.
                if (moved <= 16 && Environment.TickCount - navAt < 450) { navMouse = now; return; }
                if (moved <= 3) return;
                if (Diag.On) Diag.Log("выделение снято движением мыши: сдвиг " + moved + ", прошло мс " + (Environment.TickCount - navAt));
                navKey = null;
                navP = null;
                navMini = -1;
                ClearMini();
                ClearModelPopup(false);
                Invalidate();
            }
            if (layE != null)
            {
                if ((ev.Button & MouseButtons.Right) == 0) { layE = null; Invalidate(); return; }
                layAt = ev.Location;
                if (Math.Abs(layAt.X - layStart.X) + Math.Abs(layAt.Y - layStart.Y) > 3) layMoved = true;
                if (layMoved)
                {
                    if (mpShown || popup) { ClearMini(); ClearModelPopup(false); } // слой тащат — превью закрывается
                    TrackTrash();
                }
                Cursor = Cursors.Hand;
                Invalidate();
                return;
            }
            {
                // крестик под курсором краснеет
                Entry ce;
                Pack cp;
                if (!CrossAt(ev.Location, out ce, out cp)) { ce = null; cp = null; }
                if (ce != crossE || cp != crossP)
                {
                    crossE = ce;
                    crossP = cp;
                    Invalidate();
                }
            }
            if (dragE != null)
            {
                if ((ev.Button & MouseButtons.Left) == 0) { dragE = null; return; }
                Size ds = SystemInformation.DragSize;
                if (Math.Abs(ev.X - dragStart.X) < ds.Width && Math.Abs(ev.Y - dragStart.Y) < ds.Height) return;
                string key = dragE.Key;
                dragE = null;
                DoDragDrop(DragPrefix + key, DragDropEffects.Move);
                return;
            }
            if (rotE != null && (MouseButtons & MouseButtons.Right) == 0)
            {
                // кнопку отпустили, пока окно было не активно: отпускание сюда не пришло
                rotE = null;
                rotMoved = false;
                if (overTrash) { overTrash = false; if (TrashHover != null) TrashHover(false); }
                Invalidate();
            }
            if (rotE != null && (ev.Button & MouseButtons.Right) != 0)
            {
                int dx = ev.X - rotStart.X, dy = ev.Y - rotStart.Y;
                if (Math.Abs(dx) + Math.Abs(dy) > 3) rotMoved = true;
                rotAt = ev.Location;
                if (rotMoved)
                {
                    // текстуру тащат: её уменьшенный вид едет за курсором, корзина отзывается, когда над ней;
                    // открытое превью при этом закрывается, чтобы не заслонять место, куда её несут
                    if (mpShown || popup) { ClearMini(); ClearModelPopup(false); }
                    TrackTrash();
                    if (OverEditor != null && Img.IsImage(rotE.Key)) OverEditor(Cursor.Position);
                    Invalidate();
                }
                return;
            }
            Entry e;
            Pack p;
            bool badge;
            Entry me;
            Pack mp;
            int mk;
            Rectangle mr;
            KeyValuePair<string, string> mi;
            if (mpShown)
            {
                // мышь на окошке модели или на пути к нему: оно остаётся, остальное под ним не реагирует
                bool inArea = MpHas(ev.Location);
                // на чужой текстуре (не на самом окошке) оно тоже доживает только треть секунды
                Entry oe;
                Pack op;
                Rectangle oi;
                bool onOther = inArea && !mpBox.Contains(ev.Location) && !mpCell.Contains(ev.Location) && TileAt(ev.Location, out oe, out op, out oi);
                if (inArea && !onOther)
                {
                    if (mpClose != null) mpClose.Stop();
                    if (!mpCell.Contains(ev.Location))
                    {
                        bool pen = mpPenRect.Contains(ev.Location);
                        Cursor = pen ? Cursors.Hand : Cursors.Default;
                        if (pen != mpPenHot) { mpPenHot = pen; Invalidate(); }
                        special = true;
                        return;
                    }
                }
                else
                {
                    // мышь ушла с окошка: оно закрывается через треть секунды
                    if (mpClose == null)
                    {
                        mpClose = new Timer();
                        mpClose.Interval = 170;
                        mpClose.Tick += delegate
                        {
                            mpClose.Stop();
                            if (rotE != null) return; // модель ещё вращают
                            ClearModelPopup(true);
                            Point at = PointToClient(Cursor.Position);
                            if (ClientRectangle.Contains(at)) OnMouseMove(new MouseEventArgs(MouseButtons.None, 0, at.X, at.Y, 0));
                        };
                    }
                    if (!mpClose.Enabled) mpClose.Start();
                    if (onOther) { special = true; return; } // чужая текстура под окошком пока не реагирует
                }
            }
            if (InPopup(ev.Location) && !miniRect.Contains(ev.Location))
            {
                // по пути к окошку мышь оказалась на чужой текстуре: если задержится там на треть секунды, окошко слоя закрывается
                Entry te;
                Pack tp;
                Rectangle ti;
                if (!popupBox.Contains(ev.Location) && TileAt(ev.Location, out te, out tp, out ti))
                {
                    if (leaveTimer == null)
                    {
                        leaveTimer = new Timer();
                        leaveTimer.Interval = 170;
                        leaveTimer.Tick += delegate
                        {
                            leaveTimer.Stop();
                            ClearMini();
                            Invalidate();
                            Point at = PointToClient(Cursor.Position);
                            OnMouseMove(new MouseEventArgs(MouseButtons.None, 0, at.X, at.Y, 0)); // дальше — обычное наведение на эту текстуру
                        };
                    }
                    if (!leaveTimer.Enabled) leaveTimer.Start();
                }
                else if (leaveTimer != null) leaveTimer.Stop();
                // мышь перешла со значка на само окошко: оно остаётся, подсвечиваются его кнопки
                int hot = popStarRect.Contains(ev.Location) ? 1 : popPenRect.Contains(ev.Location) ? 2 : 0;
                Cursor = hot != 0 ? Cursors.Hand : Cursors.Default;
                if (hot != popHot) { popHot = hot; Invalidate(); }
                special = true;
                return;
            }
            if (leaveTimer != null) leaveTimer.Stop();
            // пока прежнее окошко доживает свою треть секунды, новое не заводится
            if (!mpShown || MpHas(ev.Location)) UpdateModelHover(ev.Location);
            if (popHot != 0) { popHot = 0; Invalidate(); }
            MiniAt(ev.Location, out me, out mp, out mk, out mr, out mi);
            if (me != miniE || mp != miniP || mk != miniK)
            {
                ClearMini();
                Invalidate();
                if (me != null)
                {
                    miniE = me;
                    miniP = mp;
                    miniK = mk;
                    miniRect = mr;
                    miniItem = mi;
                    popupTimer.Interval = DockPreview ? 1 : 220;
                    popupTimer.Start(); // крупный вид всплывает, если задержаться на значке
                    hotE = null;
                    hotP = null;
                    hotBadge = false;
                    hotHead = null;
                    starE = null;
                    special = true;
                    Cursor = mi.Key == Unwrap ? Cursors.Default : Cursors.Hand;
                    if (LayerHovered != null) LayerHovered(me, mp, mi.Key);
                }
            }
            if (me != null) return;
            Pack sp;
            Entry se = StarAt(ev.Location, out sp);
            if (se != starE || sp != starP)
            {
                starE = se;
                starP = sp;
                Invalidate();
                if (se != null && LayerHovered != null) LayerHovered(se, sp, "fav");
            }
            if (se != null)
            {
                Cursor = Cursors.Hand;
                special = true;
                hotE = null;
                hotP = null;
                hotBadge = false;
                hotHead = null;
                return;
            }
            Hit(ev.Location, out e, out p, out badge);
            Head head = HeadAt(ev.Location);
            if (!special && e == hotE && p == hotP && badge == hotBadge && head == hotHead) return;
            special = false;
            hotE = e;
            hotP = p;
            hotBadge = badge;
            hotHead = head;
            Cursor = head != null || (e != null && !badge && !TrashView && !Fixed(e)) ? Cursors.Hand : Cursors.Default;
            Invalidate();
            if (Hovered != null) Hovered(e, p, badge);
        }

        protected override void OnMouseLeave(EventArgs ev)
        {
            base.OnMouseLeave(ev);
            if (testHold) return;
            if (miniE != null) { ClearMini(); Invalidate(); }
            if (rotE == null) ClearModelPopup(true);
            if (starE != null) { starE = null; Invalidate(); }
            if (hotE == null && hotHead == null && !special) return;
            special = false;
            hotHead = null;
            hotE = null;
            hotP = null;
            hotBadge = false;
            Invalidate();
            if (Hovered != null) Hovered(null, null, false);
        }

        protected override void OnMouseDown(MouseEventArgs ev)
        {
            base.OnMouseDown(ev);
            Focus();
            Entry e;
            Pack p;
            bool badge;
            if (navKey != null) { navKey = null; Invalidate(); if (Diag.On) Diag.Log("выделение снято нажатием кнопки мыши"); }
            // любое новое нажатие отменяет отложенное меню; второе правое по той же текстуре откроет её файл
            Entry waitE = menuE;
            Pack waitP = menuP;
            CancelMenu();
            if (mpShown && mpE != null && mpBox.Contains(ev.Location))
            {
                // на окошке: карандаш открывает редактор, правая кнопка вращает модель; остальные щелчки ничего не делают
                if (ev.Button == MouseButtons.Left && mpPenRect.Contains(ev.Location))
                {
                    Entry pe = mpE;
                    Pack pp = mpP;
                    ClearModelPopup(true);
                    if (EditClicked != null) EditClicked(pe, pp);
                    return;
                }
                return;
            }
            if (InPopup(ev.Location) && popupBox.Contains(ev.Location))
            {
                // щелчок по окошку не проваливается на карточки под ним
                Entry oe = miniE;
                Pack op = miniP;
                KeyValuePair<string, string> oi = miniItem;
                bool star = popStarRect.Contains(ev.Location), pen = popPenRect.Contains(ev.Location);
                if (ev.Button != MouseButtons.Left || (!star && !pen)) return;
                ClearMini();
                Invalidate();
                if (star && PopupFavClicked != null) PopupFavClicked(oe, op, oi);
                if (pen && PopupEditClicked != null) PopupEditClicked(oe, op, oi);
                return;
            }
            Head head = HeadAt(ev.Location);
            if (head != null)
            {
                if (ev.Button == MouseButtons.Left && ev.Clicks < 2 && HeaderClicked != null) HeaderClicked(head.Key);
                return;
            }
            Entry me;
            Pack mp;
            int mk;
            Rectangle mr;
            KeyValuePair<string, string> mi;
            if (MiniAt(ev.Location, out me, out mp, out mk, out mr, out mi))
            {
                if (ev.Button == MouseButtons.Left && mi.Key != Unwrap && LayerClicked != null) LayerClicked(me, mp, mi.Key, mi.Value);
                if (ev.Button == MouseButtons.Right && mi.Key != Unwrap)
                {
                    // зажатая правая кнопка берёт слой, чтобы перенести его на другую текстуру этой же карточки
                    layE = me;
                    layP = mp;
                    layItem = mi;
                    layLive = LayerLive(me, mp, mi.Key, mi.Value);
                    layStart = layAt = ev.Location;
                    layMoved = false;
                    ClearMini();
                    Invalidate();
                }
                return;
            }
            Pack sp;
            Entry se = StarAt(ev.Location, out sp);
            if (se != null)
            {
                if (ev.Button == MouseButtons.Left && FavClicked != null) FavClicked(se, sp);
                return;
            }
            Entry xe;
            Pack xp;
            if (ev.Button == MouseButtons.Left && CrossAt(ev.Location, out xe, out xp))
            {
                // крестик в углу текстуры: она уходит в корзину
                // второе нажатие двойного щелчка пришлось бы уже на соседнюю текстуру, подъехавшую под курсор
                if (ev.Clicks < 2)
                {
                    ClearModelPopup(false);
                    if (Trashed != null) Trashed(xe, xp);
                }
                return;
            }
            if (ev.Button == MouseButtons.Right)
            {
                Entry te = TitleAt(ev.Location);
                if (te != null)
                {
                    if (NameCopied != null) NameCopied(te);
                    return;
                }
            }
            if (!Hit(ev.Location, out e, out p, out badge)) return;
            if (badge)
            {
                return;
            }
            if (ev.Button == MouseButtons.Right)
            {
                if (waitE != null && waitE.Key == e.Key && waitP == p)
                {
                    // двойной правый щелчок: файл текстуры открывается в программе по умолчанию
                    if (OpenedFile != null) OpenedFile(e, p);
                    return;
                }
                // зажатая правая кнопка вращает модель или тащит текстуру в корзину; короткий щелчок открывает меню файла
                rotDown = Environment.TickCount;
                rotAt = ev.Location;
                rotE = e;
                rotP = p;
                rotStart = ev.Location;
                rotMoved = false;
                ClearMini();
                return;
            }
            if (ev.Button != MouseButtons.Left) return;
            if ((ModifierKeys & Keys.Control) != 0)
            {
                // Ctrl+щелчок добавляет или убирает случайный вариант, не трогая основной выбор
                if (VariantToggled != null) VariantToggled(e, p);
                return;
            }
            if (CanDrag != null && CanDrag(e))
            {
                // текстуру можно утащить мышью в папку избранного, поэтому щелчок засчитывается при отпускании кнопки
                dragE = e;
                dragP = p;
                dragStart = ev.Location;
                return;
            }
            if (Fixed(e)) return;
            if (Picked != null) Picked(e, On(e, p) ? null : p);
        }

        // Правый щелчок по текстуре открывает меню файла не сразу, а через короткую паузу: если за это время приходит
        // второй правый щелчок, это двойной — он открывает сам файл, а меню не появляется.
        static int ClickPause { get { return Math.Min(SystemInformation.DoubleClickTime, 170); } }
        Timer menuTimer;
        Entry menuE;
        Pack menuP;
        int rotDown;
        Point rotAt;      // где сейчас курсор при зажатой правой кнопке
        bool overTrash;   // тащат над кнопкой корзины
        public Func<Point, bool> OverTrash;      // точка экрана — над кнопкой корзины
        public event Action<bool> TrashHover;    // то, что тащат, зашло на кнопку корзины или ушло с неё
        public event Action<Entry, Pack, string, string> LayerTrashed; // значок слоя отпустили над корзиной

        void CancelMenu()
        {
            if (menuTimer != null) menuTimer.Stop();
            menuE = null;
            menuP = null;
        }

        void TrackTrash()
        {
            bool over = OverTrash != null && OverTrash(Cursor.Position);
            if (over == overTrash) return;
            overTrash = over;
            if (TrashHover != null) TrashHover(over);
        }
        public event Action<Entry, Pack, Entry, Pack> TextureDropped; // текстуру перетащили правой кнопкой на другую текстуру
        public Func<Entry, bool> CanDrag;       // какие текстуры можно перетаскивать из витрины
        public const string DragPrefix = "brpc-texture:";
        public Func<Point, bool> OverEditor;         // курсор (в координатах экрана) над окном редактора; заодно подсвечивает в нём рамку
        public Action<Entry, Pack> EditorDropped;    // текстуру отпустили над окном редактора
        Entry dragE;
        Pack dragP;
        Point dragStart;

        protected override void OnMouseUp(MouseEventArgs ev)
        {
            base.OnMouseUp(ev);
            if (ev.Button == MouseButtons.Left && dragE != null)
            {
                Entry de = dragE;
                Pack dp = dragP;
                dragE = null;
                if (!Fixed(de) && Picked != null) Picked(de, On(de, dp) ? null : dp);
                return;
            }
            if (ev.Button == MouseButtons.Right && layE != null)
            {
                Entry le = layE, te;
                Pack lp = layP, tp;
                bool moved = layMoved, binned = moved && OverTrash != null && OverTrash(Cursor.Position);
                layE = null;
                Cursor = Cursors.Default;
                Invalidate();
                TrackTrash();
                if (binned)
                {
                    // слой отпущен над корзиной
                    if (overTrash) { overTrash = false; if (TrashHover != null) TrashHover(false); }
                    if (LayerTrashed != null) LayerTrashed(le, lp, layItem.Key, layItem.Value);
                    return;
                }
                // слой отпущен над другой текстурой той же карточки — он назначается ей
                // (годится вся её ячейка: и картинка, и подпись, и место со слоями под ней)
                if (moved && CellAt(ev.Location, out te, out tp) && te == le && tp != lp && LayerDropped != null)
                    LayerDropped(le, lp, layItem.Key, layItem.Value, tp, layLive);
                return;
            }
            if (ev.Button != MouseButtons.Right || rotE == null) return;
            Entry e = rotE;
            rotE = null;
            if (rotMoved)
            {
                // текстуру отпустили над окном редактора: она заменяет ту, что в нём редактируется
                if (OverEditor != null && Img.IsImage(e.Key) && OverEditor(Cursor.Position))
                {
                    if (overTrash) { overTrash = false; if (TrashHover != null) TrashHover(false); }
                    Invalidate();
                    if (EditorDropped != null) EditorDropped(e, rotP);
                    return;
                }
                bool binned = OverTrash != null && OverTrash(Cursor.Position);
                if (overTrash) { overTrash = false; if (TrashHover != null) TrashHover(false); }
                Invalidate();
                if (binned && CanTrash != null && CanTrash(e, rotP) && Trashed != null)
                {
                    // текстуру отпустили над корзиной
                    ClearModelPopup(false);
                    Trashed(e, rotP);
                    return;
                }
                Entry dropE;
                Pack dropP;
                if (CellAt(ev.Location, out dropE, out dropP) && dropE != e && TextureDropped != null)
                {
                    // отпустили над другой текстурой: если это карта слоя, окно назначит её слоем той текстуры
                    ClearModelPopup(false);
                    TextureDropped(e, rotP, dropE, dropP);
                    return;
                }
                return;
            }
            // меню показывается, когда истечёт пауза двойного щелчка (она отсчитывается от нажатия)
            menuE = e;
            menuP = rotP;
            if (menuTimer == null)
            {
                menuTimer = new Timer();
                menuTimer.Tick += delegate
                {
                    Entry me = menuE;
                    Pack mp = menuP;
                    CancelMenu();
                    if (me != null && Opened != null) Opened(me, mp);
                };
            }
            menuTimer.Interval = Math.Max(1, ClickPause - unchecked(Environment.TickCount - rotDown));
            menuTimer.Start();
        }

        // ---------------------------------------------------------- картинки

        static Bitmap Gray(Bitmap c)
        {
            Bitmap gray = new Bitmap(c.Width, c.Height, PixelFormat.Format32bppArgb);
            using (Graphics g = Graphics.FromImage(gray))
            using (ImageAttributes ia = new ImageAttributes())
            {
                ColorMatrix m = new ColorMatrix(new float[][] {
                    new float[] { 0.30f, 0.30f, 0.30f, 0, 0 },
                    new float[] { 0.59f, 0.59f, 0.59f, 0, 0 },
                    new float[] { 0.11f, 0.11f, 0.11f, 0, 0 },
                    new float[] { 0, 0, 0, 0.55f, 0 },
                    new float[] { 0.10f, 0.10f, 0.10f, 0, 1 } });
                ia.SetColorMatrix(m);
                g.DrawImage(c, new Rectangle(0, 0, c.Width, c.Height), 0, 0, c.Width, c.Height, GraphicsUnit.Pixel, ia);
            }
            return gray;
        }

        // Картинка из кэша; за один проход рисования загружается ограниченное число новых.
        // whole — показать файл целиком (развёртка), иначе у анимированной текстуры берётся первый кадр.
        int clearedAt = -1;
        object clearedFor;

        Bitmap[] Master(string path, bool whole, ref int budget, ref bool pending)
        {
            Bitmap[] t;
            string ck = whole ? path + "|whole" : path;
            if (cache.TryGetValue(ck, out t)) return t;
            if (budget <= 0) { pending = true; return null; }
            // Если видимое само не помещается в предел, очистка на том же месте списка повторялась бы без конца:
            // на одном положении прокрутки кэш сбрасывается только раз.
            if ((cache.Count > 4000 || cacheBytes > 300L * 1024 * 1024) && (clearedAt != bar.Value || clearedFor != items))
            {
                clearedAt = bar.Value;
                clearedFor = items;
                ClearCache();
            }
            t = new Bitmap[2];
            try
            {
                using (Bitmap src = Img.Load(path))
                {
                    int sw = src.Width, sh = src.Height;
                    if (!whole) frameCount[path] = sh > sw && sh % sw == 0 ? sh / sw : 1;
                    if (!whole && frameCount[path] > 1) pending = true; // кристалл анимации рисуется раньше картинки: нужен ещё один проход
                    if (!whole && sh > sw && sh % sw == 0) sh = sw;
                    int sx = 0, sy0 = 0;
                    string lowPath = path.Replace((char)92, (char)47).ToLowerInvariant();
                    if (lowPath.Contains("banner_pattern") || lowPath.Contains("shield_pattern") || lowPath.Contains("/banner/"))
                    {
                        // Узор флага или щита занимает малую часть холста, остальное пусто: показывается только сам рисунок,
                        // иначе в ячейке он выглядит точкой.
                        int[] spx = Img.GetPixels(src);
                        int x0 = sw, y0 = sh, x1 = -1, y1 = -1;
                        for (int yy = 0; yy < sh; yy++)
                            for (int xx = 0; xx < sw; xx++)
                                if (((spx[yy * src.Width + xx] >> 24) & 255) >= 16)
                                {
                                    if (xx < x0) x0 = xx;
                                    if (xx > x1) x1 = xx;
                                    if (yy < y0) y0 = yy;
                                    if (yy > y1) y1 = yy;
                                }
                        if (x1 >= x0 && y1 >= y0 && (x1 - x0 + 1) * (y1 - y0 + 1) * 2 < sw * sh)
                        {
                            sx = x0; sy0 = y0; sw = x1 - x0 + 1; sh = y1 - y0 + 1;
                        }
                    }
                    // очень большие текстуры хранятся уменьшенными, чтобы не занимать память
                    double k = Math.Min(1.0, 256.0 / Math.Max(sw, sh));
                    int w = Math.Max(1, (int)(sw * k)), h = Math.Max(1, (int)(sh * k));
                    Bitmap c = new Bitmap(w, h, PixelFormat.Format32bppArgb);
                    using (Graphics g = Graphics.FromImage(c))
                    {
                        g.InterpolationMode = k >= 1 ? InterpolationMode.NearestNeighbor : InterpolationMode.HighQualityBicubic;
                        g.PixelOffsetMode = PixelOffsetMode.Half;
                        g.DrawImage(src, new Rectangle(0, 0, w, h), new Rectangle(sx, sy0, sw, sh), GraphicsUnit.Pixel);
                    }
                    t[0] = c;
                    t[1] = Gray(c);
                    cacheBytes += (long)w * h * 8;
                }
            }
            catch (Exception)
            {
                // пара должна быть целой: рисование берёт оба вида
                if (t[0] != null && t[1] == null) { t[0].Dispose(); t[0] = null; }
            }
            cache[ck] = t;
            budget--;
            return t;
        }

        // Вписывает картинку в квадрат; пиксели остаются чёткими при увеличении.
        static void DrawFit(Graphics g, Bitmap b, Rectangle box)
        {
            double k = Math.Min((double)box.Width / b.Width, (double)box.Height / b.Height);
            int w = Math.Max(1, (int)(b.Width * k)), h = Math.Max(1, (int)(b.Height * k));
            g.InterpolationMode = k >= 1 ? InterpolationMode.NearestNeighbor : InterpolationMode.HighQualityBilinear;
            g.PixelOffsetMode = PixelOffsetMode.Half;
            g.DrawImage(b, new Rectangle(box.X + (box.Width - w) / 2, box.Y + (box.Height - h) / 2, w, h));
        }

        // ---------------------------------------------------------- рисование

        static void Gem(Graphics g, Rectangle r, Color color, bool filled, bool hot)
        {
            int cx = r.X + r.Width / 2, cy = r.Y + r.Height / 2, d = 6;
            Point[] pts = { new Point(cx, cy - d), new Point(cx + d, cy), new Point(cx, cy + d), new Point(cx - d, cy) };
            SmoothingMode sm = g.SmoothingMode;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            if (filled) Theme.DrawGem(g, cx, cy, d, color);
            if (!filled || hot)
                using (Pen pen = new Pen(hot ? Color.Black : ControlPaint.Dark(color, 0.15f), 1.4f)) g.DrawPolygon(pen, pts);
            g.SmoothingMode = sm;
        }

        protected override void OnPaint(PaintEventArgs pe)
        {
            Graphics g = pe.Graphics;
            g.Clear(BackColor);
            if (cards.Count == 0)
            {
                string hint = EmptyText != null ? EmptyText : L.T("Добавьте файл с окончанием .mcpack через «+» в левой части окна\nили перетащите файл в любое место этой программы.");
                // строки рисуются по одной, с увеличенным интервалом между ними: так подсказка читается быстрее
                string[] hintLines = hint.Split('\n');
                int hintW = ClientSize.Width - bar.Width, lineH = hintFont.Height + 10;
                int hintY = (ClientSize.Height - hintLines.Length * lineH) / 2;
                for (int li = 0; li < hintLines.Length; li++)
                {
                    Rectangle lr = new Rectangle(0, hintY + li * lineH, hintW, lineH);
                    int plus = hintLines[li].IndexOf("«+»", StringComparison.Ordinal);
                    if (plus < 0)
                    {
                        TextRenderer.DrawText(g, hintLines[li], hintFont, lr, Theme.Dim,
                            TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix);
                        continue;
                    }
                    // знак «+» крупнее остального текста, но того же цвета
                    string before = hintLines[li].Substring(0, plus + 1), after = hintLines[li].Substring(plus + 2);
                    TextFormatFlags part = TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPadding | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine;
                    Size big = new Size(int.MaxValue, lineH);
                    int w1 = TextRenderer.MeasureText(g, before, hintFont, big, part).Width, w2 = TextRenderer.MeasureText(g, "+", plusFont, big, part).Width,
                        w3 = TextRenderer.MeasureText(g, after, hintFont, big, part).Width;
                    int lx = (hintW - w1 - w2 - w3) / 2;
                    TextRenderer.DrawText(g, before, hintFont, new Rectangle(lx, lr.Y, w1, lineH), Theme.Dim, part);
                    TextRenderer.DrawText(g, "+", plusFont, new Rectangle(lx + w1, lr.Y - 2, w2, lineH), Theme.Dim, part);
                    TextRenderer.DrawText(g, after, hintFont, new Rectangle(lx + w1 + w2, lr.Y, w3, lineH), Theme.Dim, part);
                }
                return;
            }
            int sy = bar.Value, budget = 40;
            bool pending = false;
            TextFormatFlags tf = TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix | TextFormatFlags.VerticalCenter;
            foreach (Card c in cards)
            {
                if (c.R.Bottom < sy) continue;
                if (c.R.Top > sy + ClientSize.Height) break;
                Entry e = c.E;
                Rectangle r = c.R;
                r.Offset(0, -sy);
                if (e == null)
                {
                    Head hd = c.H;
                    int tone = Theme.HeadTone(hd.Big, hd == hotHead);
                    using (SolidBrush b = new SolidBrush(Color.FromArgb(tone, tone + 1, tone + 6))) g.FillRectangle(b, r);
                    // треугольник, как у списка слева: вправо — свёрнуто, вниз — развёрнуто
                    int ax = r.X + 13, ay = r.Y + r.Height / 2;
                    Point[] arrow = hd.Open
                        ? new Point[] { new Point(ax - 5, ay - 3), new Point(ax + 5, ay - 3), new Point(ax, ay + 4) }
                        : new Point[] { new Point(ax - 3, ay - 5), new Point(ax + 4, ay), new Point(ax - 3, ay + 5) };
                    using (SolidBrush b = new SolidBrush(Theme.Dim)) g.FillPolygon(b, arrow);
                    TextRenderer.DrawText(g, hd.Title + "   " + hd.Count, hd.Big ? bigFont : boldFont,
                        new Rectangle(r.X + 26, r.Y, r.Width - 30, r.Height),
                        Theme.Text, tf);
                    continue;
                }
                bool choice = e.Sources.Count > 1 && !Fixed(e);
                using (SolidBrush b = new SolidBrush(e.Excluded ? Theme.CardOff : Theme.Card)) g.FillRectangle(b, r);
                using (Pen pen = new Pen(Theme.Edge)) g.DrawRectangle(pen, r.X, r.Y, r.Width - 1, r.Height - 1);
                // оранжевая рамка вокруг всей карточки: сама текстура выключена, но её слои выбраны
                if (e.LayersOnly)
                    using (Pen pen = new Pen(Orange, 2)) g.DrawRectangle(pen, r.X + 1, r.Y + 1, r.Width - 2, r.Height - 2);
                if (!c.InGroup && Tiles(e).Count > 1)
                    using (SolidBrush strip = new SolidBrush(c.Tint)) g.FillRectangle(strip, r.X, r.Y, r.Width, 3); // варианты одной текстуры: полоса своего цвета
                if (c.InGroup)
                {
                    // стороны одного объекта: общая синяя полоса сверху, а между соседними — пунктир вместо зазора
                    SmoothingMode gsm = g.SmoothingMode;
                    g.SmoothingMode = SmoothingMode.AntiAlias;
                    if (c.Under)
                        using (SolidBrush dot = new SolidBrush(c.Tint))
                        {
                            // продолжение системы на следующей строке: вместо сплошной полосы — ряд точек, как между сторонами
                            for (float dx = r.X + 4; dx < r.Right - 4; dx += 13) g.FillEllipse(dot, dx, r.Y - 0.5f, 4.6f, 4.6f);
                        }
                    else
                        using (SolidBrush strip = new SolidBrush(c.Tint)) g.FillRectangle(strip, r.X, r.Y, r.Width, 3);
                    if (c.Join)
                        using (SolidBrush dot = new SolidBrush(c.Tint))
                        {
                            // между сторонами одного объекта — столбик точек
                            for (float dy = r.Y + 8; dy < r.Bottom - 5; dy += 13) g.FillEllipse(dot, r.X - 1.8f, dy, 4.6f, 4.6f);
                        }
                    g.SmoothingMode = gsm;
                }

                // Кристаллы: оранжевый — есть слои, зелёный — есть варианты из других паков, синий — ни того, ни другого.
                Rectangle gem = BadgeRect(c);
                int gems = 0;
                if (e.Pbr != null)
                {
                    Gem(g, gem, Orange, e.PbrChoice != null, false);
                    gem.Offset(-17, 0);
                    gems++;
                }
                if (choice)
                {
                    Gem(g, gem, Green, true, false);
                    gem.Offset(-17, 0);
                    gems++;
                }
                bool anim = false;
                foreach (Pack ap in Tiles(e)) if (Animated(e, ap)) anim = true;
                if (anim) { Gem(g, gem, Violet, true, false); gems++; } // сиреневый: текстура анимированная
                if (gems == 0) { Gem(g, gem, Blue, true, false); gems++; }
                string title = (c.Suffix != null ? "· " + c.Suffix : Path.GetFileNameWithoutExtension(e.Rel))
                    + (e.AutoMerge ? L.T("  — объединяются") : (e.Excluded ? L.T("  — выключено") : ""));
                TextRenderer.DrawText(g, title, Font, new Rectangle(r.X + 4, r.Y + 4, r.Width - 13 - gems * 17, 19),
                    e.Excluded ? Theme.Dim : Theme.Text, tf);

                List<Pack> tiles = Tiles(e);
                for (int i = 0; i < tiles.Count; i++)
                {
                    Pack p = tiles[i];
                    // в показе избранного вариант выглядит так, как сохранён: текстура цветная, если сохраняли её саму
                    bool saved = FavView && p == FavPack;
                    bool on = saved ? (SavedTexture == null || SavedTexture(e)) : (On(e, p) || (AlsoOn != null && AlsoOn(e, p))), hot = e == hotE && p == hotP;
                    Rectangle cell = CellRect(c, i);
                    Color back = on ? Theme.CellOn : (hot && !Fixed(e) ? Theme.CellHot : Theme.CellOff);
                    bool navHere = navKey == e.Key && navP == p; // текстура, выделенная стрелками, — синеватая
                    if (navHere) back = Theme.Dark ? Color.FromArgb(50, 78, 124) : Color.FromArgb(196, 220, 250);
                    using (SolidBrush b = new SolidBrush(back)) g.FillRectangle(b, cell);
                    Color edge = navHere ? Theme.Accent : (hot && !on && !Fixed(e) ? Theme.Dim : Theme.Edge); // выбранный вариант отличает светлый фон, а не рамка
                    using (Pen pen = new Pen(edge))
                        g.DrawRectangle(pen, cell.X, cell.Y, cell.Width - 1, cell.Height - 1);

                    Rectangle tr = new Rectangle(cell.X + (cell.Width - tile) / 2, cell.Y + 6, tile, tile);
                    string path = p.FullPath(e.Key);
                    Color ink = on ? Theme.Text : Theme.Dim;
                    if (Img.IsImage(e.Key))
                    {
                        Bitmap[] t = Master(path, false, ref budget, ref pending);
                        if (t != null && t[0] != null) DrawFit(g, on ? t[0] : t[1], tr);
                        else if (t != null)
                            TextRenderer.DrawText(g, L.T("не читается"), Font, tr, ink, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter);
                    }
                    else
                    {
                        TextRenderer.DrawText(g, Path.GetExtension(e.Key), Font, tr, ink,
                            TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix);
                    }
                    if (CanTrash != null && CanTrash(e, p))
                    {
                        // крестик в левом верхнем углу: убрать текстуру в корзину
                        Rectangle xr = CrossRect(tr);
                        bool xhot = e == crossE && p == crossP;
                        Color xfill = !xhot ? Color.FromArgb(110, 0, 0, 0) : (TrashView ? Color.FromArgb(225, 46, 160, 84) : Color.FromArgb(225, 208, 52, 52));
                        using (SolidBrush b = new SolidBrush(xfill)) g.FillRectangle(b, xr);
                        SmoothingMode xsm = g.SmoothingMode;
                        g.SmoothingMode = TrashView ? SmoothingMode.None : SmoothingMode.AntiAlias;
                        using (Pen pen = new Pen(Color.FromArgb(xhot ? 255 : 215, 255, 255, 255), 1.4f))
                        {
                            if (TrashView)
                            {
                                g.DrawLine(pen, xr.X + 3, xr.Y + 7, xr.Right - 4, xr.Y + 7);
                                g.DrawLine(pen, xr.X + 7, xr.Y + 3, xr.X + 7, xr.Bottom - 4);
                            }
                            else
                            {
                                g.DrawLine(pen, xr.X + 4, xr.Y + 4, xr.Right - 5, xr.Bottom - 5);
                                g.DrawLine(pen, xr.Right - 5, xr.Y + 4, xr.X + 4, xr.Bottom - 5);
                            }
                        }
                        g.SmoothingMode = xsm;
                    }
                    int lead = 0;
                    if (Img.IsImage(e.Key))
                    {
                        // звезда избранного — у каждого варианта, перед названием его пакета
                        DrawStar(g, StarRect(cell), IsFavTile != null && IsFavTile(e, p), e == starE && p == starP);
                        lead = 17;
                    }
                    TextRenderer.DrawText(g, p.Name, Font, new Rectangle(cell.X + 2 + lead, cell.Y + tile + 11, cell.Width - 4 - lead, 17), ink,
                        tf | TextFormatFlags.HorizontalCenter);

                    if (tiles.Count > 1 && i % Math.Max(1, c.PerRow) != 0)
                    {
                        // между вариантами одной текстуры — пунктир (а между сторонами объекта — точки)
                        using (Pen dash = new Pen(c.Tint, 2))
                        {
                            dash.DashPattern = new float[] { 6.1f, 5.1f }; // штрих около 12 пикселей, промежуток около 10
                            g.DrawLine(dash, cell.X - 2f, cell.Y + 3, cell.X - 2f, cell.Bottom - 3);
                        }
                    }
                    if (c.Extra == 0) continue;
                    List<KeyValuePair<string, string>> minis = MinisOf(e, p);
                    for (int k = 0; k < minis.Count; k++)
                    {
                        // значок цветной, только если именно этот файл войдёт в сборку
                        bool live = (saved && minis[k].Key != Unwrap) || LayerLive(e, p, minis[k].Key, minis[k].Value); // сохранённые слои в избранном горят
                        Rectangle mr = MiniRect(cell, k);
                        using (SolidBrush b = new SolidBrush(live ? Theme.CellOn : Theme.CellOff)) g.FillRectangle(b, mr);
                        Bitmap[] mt = Master(minis[k].Value, minis[k].Key == Unwrap, ref budget, ref pending);
                        if (mt != null && mt[0] != null) DrawFit(g, live ? mt[0] : mt[1], Rectangle.Inflate(mr, -1, -1));
                        bool hotMini = e == miniE && p == miniP && k == miniK;
                        Color frame = minis[k].Key == Unwrap ? Color.FromArgb(120, 122, 132) : (live ? Orange : Color.FromArgb(140, 140, 140));
                        using (Pen pen = new Pen(hotMini ? Color.Black : frame))
                            g.DrawRectangle(pen, mr.X, mr.Y, mr.Width - 1, mr.Height - 1);
                        if (navHere && k == navMini)
                            using (Pen pen = new Pen(Theme.Accent, 2)) g.DrawRectangle(pen, mr.X - 1, mr.Y - 1, mr.Width + 1, mr.Height + 1);
                    }
                }
            }
            if (DockPreview)
            {
                // окошки не рисуются: то, что в них было бы, показывает панель слева внизу
                bool layerHot = popup && miniE != null;
                Entry de = layerHot ? miniE : (mpShown ? mpE : null);
                Pack dp = layerHot ? miniP : (mpShown ? mpP : null);
                string df = layerHot ? miniItem.Value : null;
                if (de != null && dp != null && (de != dockE || dp != dockP || df != dockFile))
                {
                    dockE = de;
                    dockP = dp;
                    dockFile = df;
                    if (Docked != null) Docked(de, dp, df);
                }
            }
            else
            {
                if (popup && miniE != null) DrawPopup(g, ref budget, ref pending);
                if (mpShown && mpE != null) DrawModelPopup(g);
                if (PreviewOpen && Preview.Alt) Preview.Badge(g, previewBox, Font);
            }
            if (rotE != null && rotMoved && Img.IsImage(rotE.Key))
            {
                // текстура, которую тащат правой кнопкой (в корзину): её уменьшенный вид едет за курсором
                Rectangle dr = new Rectangle(rotAt.X - 20, rotAt.Y - 20, 40, 40);
                using (SolidBrush b = new SolidBrush(Theme.CellOn)) g.FillRectangle(b, dr);
                Bitmap[] dt = Master(rotP.FullPath(rotE.Key), false, ref budget, ref pending);
                if (dt != null && dt[0] != null) DrawFit(g, dt[0], Rectangle.Inflate(dr, -1, -1));
                using (Pen pen = new Pen(Theme.Accent, 2)) g.DrawRectangle(pen, dr.X, dr.Y, dr.Width - 1, dr.Height - 1);
            }
            if (layE != null && layMoved)
            {
                // слой, который тащат: его значок едет за курсором
                Rectangle gr = new Rectangle(layAt.X - Mini / 2, layAt.Y - Mini / 2, Mini, Mini);
                using (SolidBrush b = new SolidBrush(Theme.CellOn)) g.FillRectangle(b, gr);
                Bitmap[] gt = Master(layItem.Value, false, ref budget, ref pending);
                if (gt != null && gt[0] != null) DrawFit(g, gt[0], Rectangle.Inflate(gr, -1, -1));
                using (Pen pen = new Pen(Orange, 2)) g.DrawRectangle(pen, gr.X, gr.Y, gr.Width - 1, gr.Height - 1);
            }
            // остальные картинки догружаются следующими проходами, чтобы окно не замирало
            if (pending) BeginInvoke((MethodInvoker)delegate { Invalidate(); });
        }

        // Всплывающее окошко: слой в размере обычной текстуры или развёртка в увеличенном виде.
        void DrawPopup(Graphics g, ref int budget, ref bool pending)
        {
            bool flat = miniItem.Key == Unwrap;
            int size = Preview.Size(Math.Max(flat ? 220 : 0, Math.Max(tile, 96) * 2)), w = Math.Max(size + 16, 170), h = size + 16 + 38; // того же размера, что окошко модели
            int maxX = ClientSize.Width - bar.Width - w - 4;
            int x = miniRect.Right + 8, y = miniRect.Top - h / 2;
            if (x > maxX) x = miniRect.Left - w - 8;
            x = Math.Max(4, Math.Min(maxX, x));
            y = Math.Max(4, Math.Min(ClientSize.Height - h - 4, y));
            Rectangle box = new Rectangle(x, y, w, h);
            previewBox = box;
            popupBox = box;
            popStarRect = new Rectangle(box.X + 6, box.Y + size + 8 + 4, 16, 16);
            popPenRect = new Rectangle(box.Right - 22, box.Y + size + 8 + 4, 16, 16);
            using (SolidBrush b = new SolidBrush(Color.FromArgb(70, 0, 0, 0))) g.FillRectangle(b, box.X + 4, box.Y + 4, box.Width, box.Height);
            using (SolidBrush b = new SolidBrush(Theme.Card)) g.FillRectangle(b, box);
            using (Pen pen = new Pen(Theme.Dim)) g.DrawRectangle(pen, box.X, box.Y, box.Width - 1, box.Height - 1);
            Rectangle pic = new Rectangle(box.X + (w - size) / 2, box.Y + 8, size, size);
            using (HatchBrush hb = new HatchBrush(HatchStyle.LargeCheckerBoard, Color.FromArgb(214, 214, 214), Color.White)) g.FillRectangle(hb, pic);
            Bitmap[] t = Master(miniItem.Value, flat, ref budget, ref pending);
            if (t != null && t[0] != null) DrawFit(g, t[0], pic);
            TextFormatFlags tf = TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix;
            TextRenderer.DrawText(g, flat ? L.T("развёртка текстуры") : Builder.LayerTitle(miniItem.Key), boldFont,
                new Rectangle(box.X + 24, pic.Bottom + 4, w - 48, 17), Theme.Text, tf);
            // на окошке всегда есть звезда (в избранное) и карандаш (редактор) для показанной картинки
            DrawStar(g, popStarRect, IsFav != null && IsFav(miniE), popHot == 1);
            DrawPencil(g, popPenRect, popHot == 2);
            string note = flat ? miniP.Name : miniP.Name + (LayerLive(miniE, miniP, miniItem.Key, miniItem.Value) ? L.T("  —  включён") : L.T("  —  выключен"));
            TextRenderer.DrawText(g, note, Font, new Rectangle(box.X + 2, pic.Bottom + 21, w - 4, 17), Theme.Dim, tf);
        }
    }

    // Просмотр картинки в крупном масштабе: без сглаживания, на клетчатом фоне.
    class ImageView : Control
    {
        static readonly double[] Steps = { 0.125, 0.25, 0.5, 1, 2, 3, 4, 6, 8, 12, 16, 24, 32, 48 };
        public Bitmap Image;
        double zoom = 1;
        public event EventHandler ZoomChanged;

        public ImageView()
        {
            SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint
                | ControlStyles.OptimizedDoubleBuffer | ControlStyles.Selectable, true);
        }

        public double Zoom
        {
            get { return zoom; }
            set
            {
                zoom = value;
                if (Image != null)
                {
                    // слишком большое окно Windows не создаст — уменьшаем масштаб до допустимого
                    int i = Array.IndexOf(Steps, zoom);
                    while (i > 0 && Math.Max(Image.Width, Image.Height) * zoom > 16000) zoom = Steps[--i];
                    Size = new Size(Math.Max(1, (int)(Image.Width * zoom)), Math.Max(1, (int)(Image.Height * zoom)));
                }
                Invalidate();
                if (ZoomChanged != null) ZoomChanged(this, EventArgs.Empty);
            }
        }

        public void SetImage(Bitmap b)
        {
            if (Image != null) Image.Dispose();
            Image = b;
            if (b == null) Size = new Size(1, 1);
            Invalidate();
        }

        public void Step(int d)
        {
            int i = Array.IndexOf(Steps, zoom);
            if (i < 0) i = 3;
            Zoom = Steps[Math.Max(0, Math.Min(Steps.Length - 1, i + d))];
        }

        public void Fit(Size area)
        {
            if (Image == null) return;
            double k = Math.Min((area.Width - 4.0) / Image.Width, (area.Height - 4.0) / Image.Height);
            double best = Steps[0];
            foreach (double st in Steps) if (st <= k) best = st;
            Zoom = best;
        }

        protected override void OnMouseDown(MouseEventArgs e)
        {
            base.OnMouseDown(e);
            Focus();
        }

        protected override void OnMouseWheel(MouseEventArgs e)
        {
            if ((ModifierKeys & Keys.Control) != 0)
            {
                Step(e.Delta > 0 ? 1 : -1);
                HandledMouseEventArgs h = e as HandledMouseEventArgs;
                if (h != null) h.Handled = true;
                return;
            }
            base.OnMouseWheel(e);
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            if (Image == null) return;
            Graphics g = e.Graphics;
            Rectangle src = new Rectangle(0, 0, Image.Width, Image.Height), dest = new Rectangle(0, 0, Width, Height);
            if (zoom >= 1)
            {
                // рисуется только видимая часть: при большом увеличении вся картинка была бы слишком тяжёлой
                int z = (int)zoom;
                Rectangle c = e.ClipRectangle;
                int x0 = Math.Max(0, c.Left / z), y0 = Math.Max(0, c.Top / z);
                int x1 = Math.Min(Image.Width, c.Right / z + 1), y1 = Math.Min(Image.Height, c.Bottom / z + 1);
                if (x1 <= x0 || y1 <= y0) return;
                src = new Rectangle(x0, y0, x1 - x0, y1 - y0);
                dest = new Rectangle(x0 * z, y0 * z, (x1 - x0) * z, (y1 - y0) * z);
            }
            using (HatchBrush hb = new HatchBrush(HatchStyle.LargeCheckerBoard, Color.FromArgb(205, 205, 205), Color.White))
                g.FillRectangle(hb, dest);
            g.InterpolationMode = zoom >= 1 ? InterpolationMode.NearestNeighbor : InterpolationMode.HighQualityBilinear;
            g.PixelOffsetMode = PixelOffsetMode.Half;
            g.DrawImage(Image, dest, src, GraphicsUnit.Pixel);
        }
    }

