        public static int TypeOf(string key)
        {
            if (!Img.IsImage(key)) return Other;
            if (key.StartsWith("textures/blocks/")) return 1;
            if (key.StartsWith("textures/entity/")) return 2;
            if (key.StartsWith("textures/items/")) return 3;
            if (key.StartsWith("textures/ui/") || key.StartsWith("textures/gui/")) return 4;
            if (key.StartsWith("textures/models/")) return 5;
            if (key.StartsWith("textures/environment/")) return 6;
            if (key.StartsWith("textures/particle/")) return 7;
            if (key.StartsWith("textures/painting/")) return 8;
            return 9;
        }

        // Названия категорий внутри типа или null, если тип на категории не делится.
        public static string[] SubNames(int type)
        {
            return type == 1 ? BlockNames : (type == 2 ? MobNames : (type == 3 ? ItemNames : null));
        }

        public static int SubOf(string key, int type)
        {
            string[][] rules = type == 1 ? BlockRules : (type == 2 ? MobRules : (type == 3 ? ItemRules : null));
            if (rules == null) return 0;
            // у сущностей имя моба часто стоит в названии папки, поэтому берётся путь внутри раздела
            string name = type == 2 ? key.Substring("textures/entity/".Length) : Path.GetFileName(key);
            for (int i = 0; i < rules.Length; i++)
                foreach (string w in rules[i]) if (name.Contains(w)) return i;
            return rules.Length;
        }
    }

