    // Цвета интерфейса: светлая тема и тёмно-серая.
    static class Theme
    {
        public static bool Dark;
        public static readonly Color Accent = Color.FromArgb(46, 125, 209);
        // цвета кристаллов на карточках: есть слои, есть варианты, нет ни того, ни другого
        public static readonly Color GemOrange = Color.FromArgb(218, 128, 0), GemGreen = Color.FromArgb(46, 170, 84), GemBlue = Color.FromArgb(52, 130, 220), GemViolet = Color.FromArgb(178, 124, 255);

        static Color Pick(Color light, Color dark) { return Dark ? dark : light; }

        public static Color Back { get { return Pick(SystemColors.Control, Color.FromArgb(45, 46, 50)); } }           // окно и панели
        public static Color Canvas { get { return Pick(Color.FromArgb(226, 227, 231), Color.FromArgb(34, 35, 38)); } } // фон витрины
        public static Color Field { get { return Pick(Color.White, Color.FromArgb(30, 31, 34)); } }                   // списки и поля ввода
        public static Color Card { get { return Pick(Color.FromArgb(246, 246, 248), Color.FromArgb(58, 60, 66)); } }
        public static Color CardOff { get { return Pick(Color.FromArgb(214, 214, 217), Color.FromArgb(44, 45, 49)); } }
        public static Color Edge { get { return Pick(Color.FromArgb(200, 201, 206), Color.FromArgb(92, 94, 102)); } }
        public static Color Text { get { return Pick(Color.FromArgb(30, 30, 30), Color.FromArgb(232, 233, 236)); } }
        public static Color Dim { get { return Pick(Color.FromArgb(112, 112, 116), Color.FromArgb(150, 152, 160)); } }
        public static Color CellOn { get { return Pick(Color.White, Color.FromArgb(88, 91, 100)); } }                 // включённый вариант текстуры
        public static Color CellOff { get { return Pick(Color.FromArgb(186, 186, 186), Color.FromArgb(46, 47, 51)); } }
        public static Color CellHot { get { return Pick(Color.FromArgb(204, 204, 204), Color.FromArgb(66, 68, 75)); } }
        public static Color ToggleOff { get { return Pick(Color.FromArgb(212, 213, 218), Color.FromArgb(70, 72, 79)); } }

        [DllImport("uxtheme.dll", CharSet = CharSet.Unicode)]
        static extern int SetWindowTheme(IntPtr hWnd, string app, string idList);
        [DllImport("uxtheme.dll", EntryPoint = "#133")]
        static extern bool AllowDarkModeForWindow(IntPtr hWnd, bool allow);
        [DllImport("uxtheme.dll", EntryPoint = "#135")]
        static extern int SetPreferredAppMode(int mode);
        [DllImport("uxtheme.dll", EntryPoint = "#136")]
        static extern void FlushMenuThemes();
        [DllImport("dwmapi.dll")]
        static extern int DwmSetWindowAttribute(IntPtr hWnd, int attribute, ref int value, int size);

        // Просит Windows рисовать свои части приложения (полосы прокрутки, меню) в тёмном или светлом виде.
        // Эти вызовы есть не во всех версиях Windows, поэтому неудача просто пропускается.
        public static void App()
        {
            try { SetPreferredAppMode(Dark ? 2 : 3); FlushMenuThemes(); } catch (Exception) { }
        }

        // Тёмный или светлый заголовок окна.
        public static void TitleBar(Form form)
        {
            try
            {
                int on = Dark ? 1 : 0;
                if (DwmSetWindowAttribute(form.Handle, 20, ref on, 4) != 0) DwmSetWindowAttribute(form.Handle, 19, ref on, 4);
            }
            catch (Exception) { }
        }

        // Системные полосы прокрутки у списка, дерева или поля текста.
        static void Native(Control c)
        {
            try
            {
                AllowDarkModeForWindow(c.Handle, Dark);
                // у дерева в светлой теме тоже вид проводника: те же уголки раскрытия, что в тёмной, а не квадратики с плюсом
                SetWindowTheme(c.Handle, Dark ? "DarkMode_Explorer" : (c is TreeView ? "Explorer" : null), null);
            }
            catch (Exception) { }
        }

        // Яркость полосы-заголовка раздела в витрине.
        public static int HeadTone(bool big, bool hot)
        {
            if (Dark) return (big ? 74 : 60) + (hot ? 10 : 0);
            return (big ? 204 : 216) - (hot ? 10 : 0);
        }

        // Красит элемент окна и всё, что в нём лежит. Цветные кнопки (Tag = "keep") и свои рисованные элементы не трогает.
        // Всплывающая подсказка рисуется самой программой: цвета темы, текст по левому краю и поля со всех сторон,
        // чтобы строки не липли к рамке (у системной подсказки полей почти нет).
        public static ToolTip Tip(ToolTip tip)
        {
            const int PadX = 12, PadY = 9;
            TextFormatFlags flags = TextFormatFlags.Left | TextFormatFlags.Top | TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding;
            tip.OwnerDraw = true;
            tip.Popup += delegate(object sender, PopupEventArgs e)
            {
                string text = tip.GetToolTip(e.AssociatedControl) ?? "";
                Size size = TextRenderer.MeasureText(text, SystemFonts.MessageBoxFont, new Size(int.MaxValue, int.MaxValue), flags);
                e.ToolTipSize = new Size(size.Width + PadX * 2, size.Height + PadY * 2);
            };
            tip.Draw += delegate(object sender, DrawToolTipEventArgs e)
            {
                using (SolidBrush back = new SolidBrush(Dark ? Card : Color.White)) e.Graphics.FillRectangle(back, e.Bounds);
                using (Pen edge = new Pen(Dark ? Dim : Color.FromArgb(118, 118, 118)))
                    e.Graphics.DrawRectangle(edge, e.Bounds.X, e.Bounds.Y, e.Bounds.Width - 1, e.Bounds.Height - 1);
                TextRenderer.DrawText(e.Graphics, e.ToolTipText, SystemFonts.MessageBoxFont,
                    new Rectangle(e.Bounds.X + PadX, e.Bounds.Y + PadY, e.Bounds.Width - PadX * 2, e.Bounds.Height - PadY * 2),
                    Dark ? Text : Color.FromArgb(30, 30, 30), flags);
            };
            return tip;
        }

        static Color Mix(Color c, Color to, float k)
        {
            return Color.FromArgb(255, (int)(c.R + (to.R - c.R) * k), (int)(c.G + (to.G - c.G) * k), (int)(c.B + (to.B - c.B) * k));
        }

        // Кристалл: ромб из четырёх граней разной яркости (свет падает слева сверху) с белым бликом.
        public static void DrawGem(Graphics g, float cx, float cy, float d, Color color)
        {
            PointF top = new PointF(cx, cy - d), right = new PointF(cx + d, cy), bottom = new PointF(cx, cy + d), left = new PointF(cx - d, cy);
            PointF mid = new PointF(cx - d * 0.08f, cy - d * 0.18f); // вершина граней чуть смещена к свету
            SmoothingMode sm = g.SmoothingMode;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            using (SolidBrush b = new SolidBrush(Mix(color, Color.White, 0.42f))) g.FillPolygon(b, new PointF[] { top, left, mid });
            using (SolidBrush b = new SolidBrush(Mix(color, Color.White, 0.14f))) g.FillPolygon(b, new PointF[] { top, right, mid });
            using (SolidBrush b = new SolidBrush(Mix(color, Color.Black, 0.16f))) g.FillPolygon(b, new PointF[] { left, bottom, mid });
            using (SolidBrush b = new SolidBrush(Mix(color, Color.Black, 0.36f))) g.FillPolygon(b, new PointF[] { right, bottom, mid });
            // блики: полоска на светлой грани и искра на тёмной
            using (SolidBrush w = new SolidBrush(Color.FromArgb(235, 255, 255, 255)))
                g.FillPolygon(w, new PointF[] { new PointF(cx - d * 0.52f, cy - d * 0.20f), new PointF(cx - d * 0.16f, cy - d * 0.58f),
                    new PointF(cx - d * 0.04f, cy - d * 0.46f), new PointF(cx - d * 0.40f, cy - d * 0.08f) });
            using (SolidBrush w = new SolidBrush(Color.FromArgb(150, 255, 255, 255)))
                g.FillEllipse(w, cx + d * 0.22f, cy + d * 0.12f, d * 0.24f, d * 0.24f);
            using (Pen pen = new Pen(Mix(color, Color.Black, 0.45f), 1f)) g.DrawPolygon(pen, new PointF[] { top, right, bottom, left });
            g.SmoothingMode = sm;
        }

        public static void Style(Control c)
        {
            bool keep = c.Tag as string == "keep";
            if (keep || c is Gallery || c is ImageView || c is CheckBox || c is RadioButton) { }
            else if (c is TextBox || c is ListBox || c is TreeView || c is Glyph)
            {
                c.BackColor = Field;
                c.ForeColor = Text;
            }
            else if (c is Button)
            {
                Button b = (Button)c;
                b.BackColor = Field;
                b.ForeColor = Text;
                if (b.FlatStyle == FlatStyle.Flat) b.FlatAppearance.BorderColor = Edge;
            }
            else
            {
                c.BackColor = c is Panel && c.Tag as string == "field" ? Field : Back;
                c.ForeColor = Text;
            }
            if (c is ListBox || c is TreeView || c is TextBox || (c is Panel && ((Panel)c).AutoScroll)) Native(c);
            ToolStrip strip = c as ToolStrip;
            // у встроенных в панель кнопок и полей цвет свой, панель его не навязывает
            if (strip != null) foreach (ToolStripItem item in strip.Items) if (!(item is ToolStripControlHost)) item.ForeColor = Text;
            foreach (Control child in c.Controls) Style(child);
        }
    }

    // Ползунок масштаба, нарисованный цветами темы: системный в тёмной теме остаётся светлым.
    class ThemedSlider : Control
    {
        int min, max = 100, pos;
        bool hot, drag;
        public int SmallChange = 1, LargeChange = 10;
        public event EventHandler ValueChanged;

        public ThemedSlider()
        {
            SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer
                | ControlStyles.ResizeRedraw | ControlStyles.Selectable, true);
        }

        public int Minimum { get { return min; } set { min = value; if (max <= min) max = min + 1; Invalidate(); } }
        public int Maximum { get { return max; } set { max = Math.Max(min + 1, value); Invalidate(); } }

        public int Value
        {
            get { return pos; }
            set
            {
                int v = Math.Max(min, Math.Min(max, value));
                if (v == pos) return;
                pos = v;
                Invalidate();
                if (ValueChanged != null) ValueChanged(this, EventArgs.Empty);
            }
        }

        const int Knob = 10; // ширина бегунка

        int KnobX { get { return (int)((long)(Width - Knob) * (pos - min) / (max - min)); } }

        void SetFromMouse(int x)
        {
            Value = min + (int)Math.Round((double)(x - Knob / 2) * (max - min) / Math.Max(1, Width - Knob));
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.Clear(BackColor);
            int cy = Height / 2, x = KnobX;
            using (SolidBrush track = new SolidBrush(Theme.Edge)) g.FillRectangle(track, 0, cy - 2, Width, 4);
            using (SolidBrush done = new SolidBrush(Theme.Accent)) g.FillRectangle(done, 0, cy - 2, x + Knob / 2, 4); // пройденная часть
            Color knob = hot || drag ? Color.FromArgb(70, 146, 228) : Theme.Accent;
            using (SolidBrush b = new SolidBrush(knob)) g.FillRectangle(b, x, cy - 9, Knob, 18);
        }

        protected override void OnMouseDown(MouseEventArgs e)
        {
            base.OnMouseDown(e);
            if (e.Button != MouseButtons.Left) return;
            Focus();
            drag = true;
            SetFromMouse(e.X);
        }

        protected override void OnMouseMove(MouseEventArgs e)
        {
            base.OnMouseMove(e);
            if (drag) SetFromMouse(e.X);
        }

        protected override void OnMouseUp(MouseEventArgs e)
        {
            base.OnMouseUp(e);
            drag = false;
            Invalidate();
        }

        protected override void OnMouseWheel(MouseEventArgs e)
        {
            Value += Math.Sign(e.Delta) * LargeChange;
        }

        protected override bool IsInputKey(Keys keyData)
        {
            return keyData == Keys.Left || keyData == Keys.Right || base.IsInputKey(keyData);
        }

        protected override void OnKeyDown(KeyEventArgs e)
        {
            base.OnKeyDown(e);
            if (e.KeyCode == Keys.Left) Value -= SmallChange;
            else if (e.KeyCode == Keys.Right) Value += SmallChange;
        }

        protected override void OnMouseEnter(EventArgs e) { base.OnMouseEnter(e); hot = true; Invalidate(); }
        protected override void OnMouseLeave(EventArgs e) { base.OnMouseLeave(e); hot = false; Invalidate(); }
    }

    // Вертикальная полоса прокрутки витрины, нарисованная цветами темы.
    class ThemedScroll : Control
    {
        int max = 1, large = 1, pos, grab;
        bool hot, drag;
        public int SmallChange = 40;
        public event EventHandler ValueChanged;

        public ThemedScroll()
        {
            SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
            Width = 14;
        }

        public int Maximum { get { return max; } set { max = Math.Max(1, value); Invalidate(); } }
        public int LargeChange { get { return large; } set { large = Math.Max(1, value); Invalidate(); } }
        int Limit { get { return Math.Max(0, max - large + 1); } }

        public int Value
        {
            get { return pos; }
            set
            {
                int v = Math.Max(0, Math.Min(Limit, value));
                if (v == pos) return;
                pos = v;
                Invalidate();
                if (ValueChanged != null) ValueChanged(this, EventArgs.Empty);
            }
        }

        Rectangle Thumb()
        {
            if (!Enabled || Limit == 0) return Rectangle.Empty;
            int h = Math.Max(28, (int)((long)Height * large / (max + 1)));
            int y = (int)((long)(Height - h) * pos / Limit);
            return new Rectangle(3, y, Width - 6, h);
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            e.Graphics.Clear(Theme.Canvas); // дорожка цвета витрины: её правый край совпадает с краем кнопок над ней
            Rectangle t = Thumb();
            if (t.IsEmpty) return;
            using (SolidBrush b = new SolidBrush(hot || drag ? Theme.Dim : Theme.Edge)) e.Graphics.FillRectangle(b, t);
        }

        protected override void OnMouseDown(MouseEventArgs e)
        {
            base.OnMouseDown(e);
            Rectangle t = Thumb();
            if (t.IsEmpty || e.Button != MouseButtons.Left) return;
            if (e.Y >= t.Top && e.Y < t.Bottom) { drag = true; grab = e.Y - t.Top; }
            else Value += e.Y < t.Top ? -large : large; // щелчок мимо ползунка листает на экран
            Invalidate();
        }

        protected override void OnMouseMove(MouseEventArgs e)
        {
            base.OnMouseMove(e);
            Rectangle t = Thumb();
            if (!drag || t.IsEmpty || Height <= t.Height) return;
            Value = (int)((long)(e.Y - grab) * Limit / (Height - t.Height));
        }

        protected override void OnMouseUp(MouseEventArgs e)
        {
            base.OnMouseUp(e);
            drag = false;
            Invalidate();
        }

        protected override void OnMouseEnter(EventArgs e) { base.OnMouseEnter(e); hot = true; Invalidate(); }
        protected override void OnMouseLeave(EventArgs e) { base.OnMouseLeave(e); hot = false; Invalidate(); }
    }

    // Панель кнопок без системного градиента: фон и подсветка берутся из темы.
    class ThemeRenderer : ToolStripProfessionalRenderer
    {
        protected override void OnRenderToolStripBackground(ToolStripRenderEventArgs e)
        {
            using (SolidBrush b = new SolidBrush(Theme.Back)) e.Graphics.FillRectangle(b, e.AffectedBounds);
        }

        protected override void OnRenderToolStripBorder(ToolStripRenderEventArgs e) { }

        protected override void OnRenderButtonBackground(ToolStripItemRenderEventArgs e)
        {
            ToolStripButton b = e.Item as ToolStripButton;
            if (!e.Item.Selected && (b == null || !b.Checked)) return;
            using (SolidBrush br = new SolidBrush(Theme.CellHot)) e.Graphics.FillRectangle(br, new Rectangle(Point.Empty, e.Item.Size));
        }

        protected override void OnRenderSeparator(ToolStripSeparatorRenderEventArgs e)
        {
            using (Pen pen = new Pen(Theme.Edge)) e.Graphics.DrawLine(pen, e.Item.Width / 2, 3, e.Item.Width / 2, e.Item.Height - 4);
        }
    }

    // Список-дерево без горизонтальной прокрутки: когда у дерева есть обе полосы, система рисует между ними белый квадрат,
    // который не перекрашивается под тёмную тему. Строку, которая не поместилась, дерево само показывает подсказкой под курсором.
    class PlainTree : TreeView
    {
        protected override CreateParams CreateParams
        {
            get
            {
                CreateParams cp = base.CreateParams;
                cp.Style |= 0x8000; // TVS_NOHSCROLL
                return cp;
            }
        }
    }

    // Обычная кнопка без рамки «кнопки по умолчанию»: система обводит такой рамкой кнопку, которая сработает по Enter,
    // и на цветной кнопке («Скачать») эта рамка выглядит светлой каймой.
    // Подсказка в виде обычных подсказок программы для мест, где ToolTip не работает (всплывающий список настроек —
    // отдельное окно). Она открывается как вложенный список того же меню: так список настроек под ней не закрывается.
    class HoverNote : Control
    {
        const int PadX = 12, PadY = 9;
        const TextFormatFlags Flags = TextFormatFlags.Left | TextFormatFlags.Top | TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding;
        static ToolStripDropDown drop;
        static HoverNote body;
        string note = "";

        HoverNote()
        {
            SetStyle(ControlStyles.OptimizedDoubleBuffer | ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint, true);
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            Rectangle r = ClientRectangle;
            using (SolidBrush back = new SolidBrush(Theme.Dark ? Theme.Card : Color.White)) e.Graphics.FillRectangle(back, r);
            using (Pen edge = new Pen(Theme.Dark ? Theme.Dim : Color.FromArgb(118, 118, 118))) e.Graphics.DrawRectangle(edge, 0, 0, r.Width - 1, r.Height - 1);
            TextRenderer.DrawText(e.Graphics, note, SystemFonts.MessageBoxFont, new Rectangle(PadX, PadY, r.Width - PadX * 2, r.Height - PadY * 2),
                Theme.Dark ? Theme.Text : Color.FromArgb(30, 30, 30), Flags);
        }

        // Показать рядом с элементом at, который лежит в списке owner (пункт всплывающего меню).
        public static void ShowAt(Control at, string text, ToolStripItem owner)
        {
            if (drop == null || drop.IsDisposed)
            {
                body = new HoverNote();
                ToolStripControlHost host = new ToolStripControlHost(body);
                host.AutoSize = false;
                host.Margin = Padding.Empty;
                host.Padding = Padding.Empty;
                drop = new ToolStripDropDown();
                drop.Padding = Padding.Empty;
                drop.AutoClose = false;
                drop.DropShadowEnabled = false;
                drop.Items.Add(host);
            }
            body.note = text;
            Size t = TextRenderer.MeasureText(text, SystemFonts.MessageBoxFont, new Size(int.MaxValue, int.MaxValue), Flags);
            Size size = new Size(t.Width + PadX * 2, t.Height + PadY * 2);
            body.Size = size;
            drop.Items[0].Size = size;
            drop.Size = size;
            drop.OwnerItem = owner;
            body.Invalidate();
            drop.Show(at, new Point(at.Width + 8, 0)); // справа от элемента: саму кнопку подсказка не закрывает
        }

        public static void HideNote()
        {
            if (drop != null && !drop.IsDisposed && drop.Visible) drop.Close();
        }
    }
    class CleanButton : Button
    {
        protected override bool ShowFocusCues { get { return false; } }
        public override void NotifyDefault(bool value) { base.NotifyDefault(false); }

        // Windows рисует надпись неактивной кнопки системным серым, а на тёмном фоне его почти не видно.
        // Кнопки со своими значками (без надписи) и с картинкой не трогаются.
        protected override void OnPaint(PaintEventArgs e)
        {
            base.OnPaint(e);
            if (Enabled || Text.Length == 0 || Image != null) return;
            Rectangle r = ClientRectangle;
            int edge = FlatStyle == FlatStyle.Flat ? FlatAppearance.BorderSize : 2;
            r.Inflate(-edge, -edge);
            using (SolidBrush bg = new SolidBrush(BackColor)) e.Graphics.FillRectangle(bg, r);
            TextFormatFlags how = TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix;
            TextRenderer.DrawText(e.Graphics, Text, Font, r, Theme.Dim, how);
        }
    }

    // Витрина режима 3D: каждый объект собран в объём. Моб — по своей модели, блок — кубом из своих сторон (верх, низ, бок),
    // растение — крестовиной, предмет — пластинкой. Показано то, что попадёт в сборку: текстуры из выбранных пакетов.
    // Щелчок по объекту возвращает в обычный список к его текстуре.
    class ObjectView : Control
    {
        class Obj
        {
            public Head H;       // не null — это заголовок раздела
            public string Title, Id;
            public string Boxes; // форма из таблицы Shapes; null — форма угадывается по названию
            public string Name;  // название блока, если оно не совпадает с подписью (у стадий подпись сокращена)
            public int Band;     // номер полосы: стадии и состояния одного блока стоят вплотную под общей цветной чертой
            public bool Follow;  // не первый в своей полосе
            public bool Join;    // стоит вплотную к предыдущему объекту полосы (между ними столбик точек)
            public bool Under;   // продолжение полосы на следующей строке (сверху ряд точек вместо сплошной черты)
            public int Kind;     // цвет полосы, как у систем обычного списка: 1 — есть варианты, 0 — есть слои, 2 — обычные
            public bool Pano;    // панорама главного меню: шесть картинок — стенки куба, вид изнутри
            public List<Entry> Parts = new List<Entry>();
            public Rectangle R;  // в координатах всей ленты, без учёта прокрутки
        }

        List<Obj> objs = new List<Obj>();
        ThemedScroll bar = new ThemedScroll();
        Dictionary<string, Bitmap> views = new Dictionary<string, Bitmap>();        // готовые картинки: "объект|размер"
        Dictionary<string, object[]> texCache = new Dictionary<string, object[]>(); // пиксели текстур: { int[], ширина, высота }
        Dictionary<string, float[]> angles = new Dictionary<string, float[]>();     // поворот объекта в открытом окошке, если его вращали
        Dictionary<string, float[]> home = new Dictionary<string, float[]>();       // исходный ракурс объекта
        Timer closeTimer = new Timer();
        int tile = 100;
        Obj hot, shown, rot;
        Point rotStart;
        float[] rotFrom;
        Timer popTimer = new Timer(), drawTimer = new Timer();
        Font bold, big;
        const int IconSize = 44;
        int PopSize { get { return Preview.Size(260); } }
        bool PreviewOpen { get { return shown != null; } }
        bool altWas;
        bool frozen;
        int hotIcon = -1; // значок текстуры в окошке под курсором

        public event Action<Entry> Go;
        public event Action<string> HeaderClicked;
        // Режим закреплённого превью: окошко не всплывает, готовая картинка объекта отдаётся панели слева внизу.
        // Последний признак — закрепить (нажали Shift); картинка null при закреплении — отпустить.
        public bool DockPreview;
        public event Action<Bitmap, string, Entry, bool> Docked;
        bool shiftWas;

        // ---------------------------------------------------------- выделение клавишей Shift
        // Как в обычном списке: зажали Shift — выделяется объект под мышью (или первый видимый), Shift + колесо ведёт
        // выделение по объектам. Превью показывает выделенный объект; движение мыши выделение снимает.
        Obj nav;
        Point navMouse; // где стояла мышь при последнем шаге выделения
        int navAt;      // и когда он был
        public bool NavActive { get { return nav != null; } }

        void NavShow(Obj o) { NavShow(o, true); }

        // pin — закрепить на объекте панель превью слева внизу (если она открыта)
        void NavShow(Obj o, bool pin)
        {
            nav = o;
            navMouse = Cursor.Position;
            navAt = Environment.TickCount;
            // выделенное должно быть видно целиком
            if (o.R.Top - 30 < bar.Value) SetScroll(Math.Max(0, o.R.Top - 30));
            else if (o.R.Bottom + 8 > bar.Value + ClientSize.Height) SetScroll(o.R.Bottom + 8 - ClientSize.Height);
            popTimer.Stop();
            closeTimer.Stop();
            hot = o;
            if (DockPreview) SendDocked(o, pin); // панель слева внизу показывает его и, если надо, остаётся закреплённой на нём
            else
            {
                if (shown != o) ClosePopup();
                shown = o;
            }
            Invalidate();
        }

        // Выделить объект под мышью, а если мышь не на объекте — первый видимый.
        public void ShiftSelect()
        {
            Form top = FindForm();
            if (!Visible || nav != null || top == null || Form.ActiveForm != top) return;
            Point at = PointToClient(Cursor.Position);
            if (!ClientRectangle.Contains(at)) return;
            Obj o = At(at);
            if (o != null && o.H == null) { NavShow(o, true); return; }
            // Мышь не на объекте: как в обычном списке, выделяется первый видимый объект.
            // Закреплённое превью при этом отпускается; закрепится оно снова там, куда выделение доведут колесом.
            if (DockPreview) SendDocked(null, true);
            o = objs.Find(delegate(Obj x) { return x.H == null && x.R.Top >= bar.Value; });
            if (o != null) NavShow(o, false);
        }

        // Стрелки и Enter, как в обычном списке: влево и вправо — соседний объект, вверх и вниз — ближайший в соседней строке,
        // Enter — перейти к текстуре выделенного объекта.
        public bool NavKey(Keys key)
        {
            if (key != Keys.Left && key != Keys.Right && key != Keys.Up && key != Keys.Down && key != Keys.Enter) return false;
            if (nav == null)
            {
                if (key == Keys.Enter) return false;
                Obj first = objs.Find(delegate(Obj x) { return x.H == null && x.R.Top >= bar.Value; });
                if (first != null) NavShow(first, false);
                return first != null;
            }
            if (key == Keys.Enter) { if (Go != null) Go(nav.Parts[0]); return true; }
            if (key == Keys.Left || key == Keys.Right) { NavStep(key == Keys.Right ? 1 : -1); return true; }
            Obj best = null;
            int cx = nav.R.X + nav.R.Width / 2;
            foreach (Obj o in objs)
            {
                if (o.H != null) continue;
                int dy = key == Keys.Down ? o.R.Top - nav.R.Top : nav.R.Top - o.R.Top;
                if (dy <= 10) continue;
                if (best == null) { best = o; continue; }
                int bdy = key == Keys.Down ? best.R.Top - nav.R.Top : nav.R.Top - best.R.Top;
                if (dy < bdy - 10 || (Math.Abs(dy - bdy) <= 10 && Math.Abs(o.R.X + o.R.Width / 2 - cx) < Math.Abs(best.R.X + best.R.Width / 2 - cx))) best = o;
            }
            if (best != null) NavShow(best);
            return true;
        }

        // Shift + колесо: к следующему объекту (step = 1) или к предыдущему (step = -1).
        public void NavStep(int step)
        {
            if (nav == null) { ShiftSelect(); return; }
            int i = objs.IndexOf(nav);
            for (int k = i + step; k >= 0 && k < objs.Count; k += step)
                if (objs[k].H == null) { NavShow(objs[k]); return; }
        }

        public event Action<Bitmap, Entry> DockedFrame; // следующий кадр объекта, который сейчас показан в панели
        HashSet<string> animated = new HashSet<string>(); // объекты с анимированной текстурой
        Obj dockObj, dockAsked;                          // показанный в панели и только что предложенный ей
        bool dockMoves, dockAskedMoves;                  // у него есть что проигрывать: анимация или панорама

        void SendDocked(Obj o, bool pin)
        {
            if (Docked == null) return;
            Bitmap v = o == null ? null : View(o, PopSize);
            dockAsked = o;
            dockAskedMoves = o != null && (o.Pano || animated.Contains(o.Id));
            // у стадии или состояния подпись в списке сокращена («· lit»); в панели пишется полное название
            string full = o == null ? null : (o.Follow ? Path.GetFileNameWithoutExtension(o.Parts[0].Key) : o.Title);
            Docked(v == null ? null : new Bitmap(v), full, o == null ? null : o.Parts[0], pin);
        }

        // Объект в панели начинают вращать: запоминается, откуда.
        float[] dockTurnFrom;

        public void DockTurnStart()
        {
            dockTurnFrom = null;
            if (dockObj == null) return;
            float[] a;
            if (dockObj.Pano) a = new float[] { panoYaw, 0 };
            else if (!angles.TryGetValue(dockObj.Id, out a) && !home.TryGetValue(dockObj.Id, out a)) return;
            dockTurnFrom = a;
        }

        // …и ведут мышью: сдвиг от места нажатия. Панель получает объект в новом повороте.
        public void DockTurn(int dx, int dy)
        {
            if (dockObj == null || dockTurnFrom == null || DockedFrame == null) return;
            if (dockObj.Pano) panoYaw = dockTurnFrom[0] - dx * 0.008f;
            else angles[dockObj.Id] = new float[] { dockTurnFrom[0] - dx * 0.012f, Math.Max(-1.5f, Math.Min(1.5f, dockTurnFrom[1] - dy * 0.012f)) };
            Bitmap old;
            string key = dockObj.Id + "|" + PopSize;
            if (views.TryGetValue(key, out old))
            {
                if (old != null) old.Dispose();
                views.Remove(key);
            }
            Bitmap v = View(dockObj, PopSize);
            if (v != null) DockedFrame(new Bitmap(v), dockObj.Parts[0]);
        }

        // Окно приняло предложенный объект: теперь в панели он, его анимацию и ведём.
        public void AcceptDock()
        {
            // прежний объект, если его вращали, возвращается в исходное положение
            if (dockObj != null && dockObj != dockAsked && angles.Remove(dockObj.Id)) DropViews(dockObj);
            dockObj = dockAsked;
            dockMoves = dockAskedMoves;
            panoYaw = 0;
        }

        // Очередной кадр объекта, показанного в панели: анимированная текстура или поворот панорамы.
        bool DockStep()
        {
            if (!DockPreview || dockObj == null || !dockMoves || DockedFrame == null || !Visible) return false;
            if (dockObj.Pano) panoYaw += 0.006f;
            else
            {
                animTick++;
                if (animTick % 3 != 0) return true;
            }
            Bitmap old;
            string key = dockObj.Id + "|" + PopSize;
            if (views.TryGetValue(key, out old))
            {
                if (old != null) old.Dispose();
                views.Remove(key);
            }
            Bitmap v = View(dockObj, PopSize);
            if (v != null) DockedFrame(new Bitmap(v), dockObj.Parts[0]);
            return true;
        }

        public ObjectView()
        {
            SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer
                | ControlStyles.ResizeRedraw | ControlStyles.Selectable, true);
            bar.Dock = DockStyle.Right;
            bar.ValueChanged += delegate
            {
                popTimer.Stop();
                ClosePopup();
                Invalidate();
                // список уехал под неподвижной мышью: наведение пересчитывается, чтобы превью показало объект под ней
                if (nav != null || MouseButtons != MouseButtons.None || !IsHandleCreated) return;
                Point under = PointToClient(Cursor.Position);
                if (ClientRectangle.Contains(under)) OnMouseMove(new MouseEventArgs(MouseButtons.None, 0, under.X, under.Y, 0));
            };
            closeTimer.Interval = 170; // окошко закрывается с той же задержкой, что в обычном списке
            closeTimer.Tick += delegate { closeTimer.Stop(); if (rot == null && !frozen) { ClosePopup(); Invalidate(); } };
            Controls.Add(bar);
            popTimer.Interval = 220; // та же задержка, что у окошек обычного списка
            popTimer.Tick += delegate
            {
                popTimer.Stop();
                Obj next = hot != null && hot.H == null ? hot : null;
                if (DockPreview)
                {
                    if (next != null) SendDocked(next, false);
                    return;
                }
                if (next != shown) ClosePopup();
                shown = next;
                closeTimer.Stop();
                Invalidate();
            };
            animTimer.Interval = 50;
            animTimer.Tick += delegate { AnimStep(); };
            animTimer.Start();
            drawTimer.Interval = 15;
            drawTimer.Tick += delegate { drawTimer.Stop(); Invalidate(); };
        }

        protected override void OnFontChanged(EventArgs e)
        {
            base.OnFontChanged(e);
            if (bold != null) bold.Dispose();
            if (big != null) big.Dispose();
            bold = new Font(Font, FontStyle.Bold);
            big = new Font(Font.FontFamily, 12f, FontStyle.Bold);
        }

        public int Tile
        {
            get { return tile; }
            set
            {
                if (tile == value) return;
                tile = value;
                ClearViews();
                Relayout();
            }
        }

        // Окошко закрывается: объект, который в нём вращали, возвращается в исходное положение.
        void ClosePopup()
        {
            if (shown == null) return;
            if (angles.Remove(shown.Id)) DropViews(shown);
            if (shown.Pano) { panoYaw = 0; DropViews(shown); }
            shown = null;
            rot = null;
        }

        // Где стоит окошко объекта: сбоку от его плитки, целиком в пределах витрины.
        Rectangle PopBox(Obj o)
        {
            Rectangle tr = o.R;
            tr.Offset(0, -bar.Value);
            int per = PopSize / (IconSize + 6), rows = (o.Parts.Count + per - 1) / per;
            int w = PopSize + 16, h = 30 + PopSize + 6 + rows * (IconSize + 6) + 6;
            int x = tr.Right + 6;
            if (x + w > ClientSize.Width - bar.Width - 4) x = tr.Left - 6 - w;
            if (x < 4) x = 4;
            int y = Math.Max(4, Math.Min(ClientSize.Height - h - 4, tr.Y + tr.Height / 2 - h / 2));
            return new Rectangle(x, y, w, h);
        }

        Rectangle IconRect(Obj o, Rectangle box, int i)
        {
            int per = PopSize / (IconSize + 6);
            int rowW = Math.Min(per, o.Parts.Count) * (IconSize + 6) - 6, ix0 = box.X + (box.Width - rowW) / 2;
            return new Rectangle(ix0 + (i % per) * (IconSize + 6), box.Y + 30 + PopSize + 6 + (i / per) * (IconSize + 6), IconSize, IconSize);
        }

        // Значок текстуры в окошке под точкой или -1.
        int IconAt(Point p)
        {
            if (shown == null) return -1;
            Rectangle box = PopBox(shown);
            for (int i = 0; i < shown.Parts.Count; i++) if (IconRect(shown, box, i).Contains(p)) return i;
            return -1;
        }

        // Мышь там, где окошко остаётся открытым: на плитке объекта, на самом окошке или в проходе между ними.
        bool InPopupZone(Point p)
        {
            if (shown == null) return false;
            Rectangle tr = shown.R, box = PopBox(shown);
            tr.Offset(0, -bar.Value);
            if (tr.Contains(p) || box.Contains(p)) return true;
            Rectangle gap = Rectangle.Union(tr, box);
            return gap.Contains(p) && p.Y >= tr.Top && p.Y < tr.Bottom;
        }

        void ClearViews()
        {
            foreach (Bitmap b in views.Values) if (b != null) b.Dispose();
            views.Clear();
        }

        public void ClearCache()
        {
            ClearViews();
            texCache.Clear();
            Invalidate();
        }

        public void SetItems(List<object> items)
        {
            string keepDock = dockObj != null ? dockObj.Id : null;
            objs.Clear();
            hot = shown = rot = null;
            nav = null;
            dockObj = dockAsked = null;
            popTimer.Stop();
            closeTimer.Stop();
            angles.Clear();
            ClearViews();
            FillNames();
            objs = Assemble(items);
            // панель превью могла быть закреплена на объекте: он остаётся в ней живым (анимация, вращение), если есть и в новом списке
            if (keepDock != null) dockObj = objs.Find(delegate(Obj x) { return x.H == null && x.Id == keepDock; });
            Relayout();
        }

        void FillNames()
        {
            byName.Clear();
            foreach (Entry all in AllEntries)
                if (all.Key.StartsWith("textures/blocks/") && Img.IsImage(all.Key) && all.Winner != null)
                    byName[all.Key.Substring(16, all.Key.Length - 16 - Path.GetExtension(all.Key).Length)] = all;
        }

        // Объекты из списка текстур и заголовков. Состояние витрины не трогает: так же собирается объект для редактора текстур.
        List<Obj> Assemble(List<object> items)
        {
            List<Obj> list = new List<Obj>();
            Obj last = null;
            string lastGroup = null;
            Dictionary<int, Obj> shaped = new Dictionary<int, Obj>();
            Dictionary<string, Obj> panos = new Dictionary<string, Obj>();
            // Карта слоя (отражения, рельеф) лежит рядом со своей текстурой под тем же именем с хвостом: coal_ore и coal_ore_n.
            // Это не отдельный предмет, в объёме она не показывается.
            HashSet<string> names = new HashSet<string>();
            foreach (object it in items)
            {
                Entry ne = it as Entry;
                if (ne != null && Img.IsImage(ne.Key)) names.Add(ne.Key.Substring(0, ne.Key.Length - Path.GetExtension(ne.Key).Length));
            }
            foreach (object it in items)
            {
                Head h = it as Head;
                if (h != null)
                {
                    Obj ho = new Obj();
                    ho.H = h;
                    list.Add(ho);
                    last = null;
                    continue;
                }
                Entry e = it as Entry;
                if (e == null || !Img.IsImage(e.Key)) continue;
                string bare = e.Key.Substring(0, e.Key.Length - Path.GetExtension(e.Key).Length);
                if (bare.EndsWith(" - copy")) bare = bare.Substring(0, bare.Length - 7); // забытая в пакете копия файла
                bool layer = false;
                // длинный хвост говорит сам за себя; короткий (_n, _s, _e, _h) считается слоем, только если рядом есть сама текстура
                foreach (string tail in new string[] { "_mer", "_mers", "_normal", "_heightmap", "_n", "_s", "_e", "_h" })
                    if (bare.EndsWith(tail) && (tail.Length > 2 || names.Contains(bare.Substring(0, bare.Length - tail.Length)))) { layer = true; break; }
                if (layer) continue;
                // панорама главного меню: шесть картинок panorama_0…5 — один объект
                System.Text.RegularExpressions.Match pano = System.Text.RegularExpressions.Regex.Match(bare, "^textures/ui/(.*panorama.*)_([0-5])$");
                if (pano.Success)
                {
                    Obj po;
                    if (!panos.TryGetValue(pano.Groups[1].Value, out po))
                    {
                        po = new Obj();
                        po.Pano = true;
                        po.Title = pano.Groups[1].Value;
                        po.Id = "pano:" + po.Title;
                        list.Add(po);
                        panos[po.Title] = po;
                    }
                    po.Parts.Add(e);
                    last = null;
                    continue;
                }
                bool block = e.Key.StartsWith("textures/blocks/");
                int row = block ? ShapeOf(bare.Substring(16)) : -1;
                if (row >= 0)
                {
                    // текстура блока особой формы: все его текстуры — один объект, где бы они ни стояли в списке
                    Obj so;
                    if (!shaped.TryGetValue(row, out so))
                    {
                        string[] spec = Shapes[row].Split((char)124);
                        so = new Obj();
                        so.Title = spec[0];
                        so.Id = "shape:" + spec[0];
                        so.Boxes = spec[2];
                        list.Add(so);
                        shaped[row] = so;
                    }
                    so.Parts.Add(e);
                    last = null;
                    continue;
                }
                string group = Gallery.GroupKey(e.Key);
                // стороны и стадии одного блока — один объект
                if (last != null && block && group == lastGroup) { last.Parts.Add(e); continue; }
                Obj n = new Obj();
                n.Parts.Add(e);
                n.Id = e.Key;
                n.Title = block ? group.Substring(group.LastIndexOf((char)47) + 1) : Path.GetFileNameWithoutExtension(e.Key);
                list.Add(n);
                last = block ? n : null;
                lastGroup = group;
            }
            // Стадии роста и состояния одного блока (wheat_stage_0…7, лампа включённая и выключенная) — отдельные объекты:
            // у каждого своя основная текстура и общие стороны. Стоят вплотную одной полосой, как система в обычном списке.
            List<Obj> split = new List<Obj>();
            int band = 0;
            foreach (Obj o in list)
            {
                List<Entry> bases = new List<Entry>(), sides = new List<Entry>();
                string gk = o.H == null && o.Boxes == null && !o.Pano && o.Parts.Count > 1 ? Gallery.GroupKey(o.Parts[0].Key) : null;
                if (gk != null)
                    foreach (Entry part in o.Parts)
                    {
                        if (Role(gk, part.Key) == "base") bases.Add(part); else sides.Add(part);
                    }
                if (bases.Count < 2) { split.Add(o); continue; }
                band++;
                int kind = 2;
                foreach (Entry part in o.Parts) if (part.Pbr != null) kind = 0;
                foreach (Entry part in o.Parts) if (part.Sources.Count > 1) kind = 1;
                string gname = gk.Substring(gk.LastIndexOf((char)47) + 1);
                for (int i = 0; i < bases.Count; i++)
                {
                    Obj v = new Obj();
                    v.Parts.Add(bases[i]);
                    v.Parts.AddRange(sides);
                    v.Id = bases[i].Key;
                    v.Name = gname;
                    v.Band = band;
                    v.Kind = kind;
                    v.Follow = i > 0;
                    string full = Path.GetFileNameWithoutExtension(bases[i].Key);
                    v.Title = i == 0 || full.Length <= gname.Length ? full : "· " + full.Substring(gname.Length).TrimStart((char)95);
                    split.Add(v);
                }
            }
            return split;
        }

        // ---------------------------------------------------------- объект для редактора текстур
        // Редактор показывает объект, в который входит редактируемая текстура. Он собирается из всех файлов сборки —
        // от отбора в витрине и от того, включён ли режим 3D, не зависит. Текстуры берутся из пакета, который правят
        // (чего в нём нет — из выбранного в сборке), а у самой редактируемой — несохранённые пиксели из редактора.
        List<Entry> edFrom;   // для какого списка файлов собраны edObjs
        List<Obj> edObjs;
        Obj edObj;
        Pack edPack;
        float[] edAngle, edTurnFrom;
        float edYaw;
        int edTick;
        bool edDraw, edStrip;
        string livePath;
        int[] livePx;
        int liveW, liveH;

        // Выбрать объект текстуры e из пакета p (null — убрать). Возвращает текстуры объекта или null, если объёмного вида нет.
        public List<Entry> EditSet(Entry e, Pack p, out string title)
        {
            title = null;
            Obj found = null;
            if (e != null && Img.IsImage(e.Key))
            {
                if (edFrom != AllEntries || edObjs == null)
                {
                    List<object> every = new List<object>();
                    foreach (Entry each in AllEntries) every.Add(each);
                    edObjs = Assemble(every);
                    edFrom = AllEntries;
                    FillNames();
                }
                found = edObjs.Find(delegate(Obj x) { return x.Parts[0].Key == e.Key; });
                if (found == null) found = edObjs.Find(delegate(Obj x) { return x.Parts.Exists(delegate(Entry part) { return part.Key == e.Key; }); });
            }
            else if (e == null) { edObjs = null; edFrom = null; }
            // тот же объект после пересчёта сборки остаётся в том же повороте
            if (found == null || edObj == null || found.Id != edObj.Id) { edAngle = null; edYaw = 0; edTick = 0; edStrip = false; }
            edObj = found;
            edPack = p;
            if (found == null) return null;
            title = found.Follow ? Path.GetFileNameWithoutExtension(found.Parts[0].Key) : found.Title;
            return found.Parts;
        }

        // Несохранённые пиксели файла, который сейчас правят; path == null — убрать.
        public void EditLive(string path, int[] px, int w, int h)
        {
            livePath = path;
            livePx = path == null ? null : px;
            liveW = w;
            liveH = h;
        }

        // Картинка объекта для редактора; она не кэшируется и принадлежит вызвавшему.
        public Bitmap EditRender(int size)
        {
            if (edObj == null) return null;
            int keepTick = animTick; // кадр ленты у редактора свой: счётчик витрины идёт, только пока в ней открыто окошко
            bool strip;
            Bitmap b;
            animTick = edTick;
            edDraw = true;
            try { b = Draw(edObj, size, true, edAngle, edYaw, out strip); }
            finally
            {
                edDraw = false;
                animTick = keepTick;
            }
            edStrip = strip;
            return b;
        }

        // Вращение правой кнопкой — с той же чувствительностью, что в панели превью.
        public void EditTurnStart()
        {
            edTurnFrom = null;
            if (edObj == null) return;
            float[] a;
            if (edObj.Pano) a = new float[] { edYaw, 0 };
            else if (edAngle != null) a = edAngle;
            else if (!home.TryGetValue(edObj.Id, out a)) return;
            edTurnFrom = a;
        }

        public void EditTurn(int dx, int dy)
        {
            if (edObj == null || edTurnFrom == null) return;
            if (edObj.Pano) edYaw = edTurnFrom[0] - dx * 0.008f;
            else edAngle = new float[] { edTurnFrom[0] - dx * 0.012f, Math.Max(-1.5f, Math.Min(1.5f, edTurnFrom[1] - dy * 0.012f)) };
        }

        // Такт анимации (раз в 50 мс): true — объект пора нарисовать заново (следующий кадр ленты, поворот панорамы).
        public bool EditStep()
        {
            if (edObj == null) return false;
            if (edObj.Pano) { edYaw += 0.006f; return true; }
            if (!edStrip) return false;
            edTick++;
            return edTick % 3 == 0;
        }

        void Relayout()
        {
            // Та же раскладка, что в обычном списке: шаг сетки, размер карточки (шапка с названием, ячейка с картинкой,
            // подпись пакета под ней) и объединение. Стадии и состояния одного блока стоят вплотную под общей цветной
            // полосой; система целиком переносится на новую строку, если не помещается в остаток этой, а та, что шире
            // строки, продолжается ниже без зазора — рядом точек вместо сплошной черты.
            int cellW = Math.Max(tile + 12, 88), grid = cellW + 16, cw = grid - 8, ch = 24 + tile + 30 + 6;
            int maxW = ClientSize.Width - bar.Width - 8, x = 8, y = 8;
            bool under = false;
            for (int i = 0; i < objs.Count; i++)
            {
                Obj o = objs[i];
                if (o.H != null)
                {
                    if (x > 8) { x = 8; y += ch + 8; }
                    under = false;
                    int hh = o.H.Big ? 32 : 26, indent = o.H.Big ? 0 : 18;
                    o.R = new Rectangle(8 + indent, y, Math.Max(50, maxW - 8 - indent), hh);
                    y += hh + 4;
                    continue;
                }
                o.Join = false;
                if (o.Follow)
                {
                    if (x + cw > maxW)
                    {
                        x = 8;
                        y += ch;
                        under = true;
                    }
                    else o.Join = x > 8;
                }
                else
                {
                    bool afterUnder = under; // перед этим объектом закончилась система, занявшая несколько строк
                    under = false;
                    int n = 1;
                    while (i + n < objs.Count && objs[i + n].Follow) n++;
                    if (x > 8 && (afterUnder || x + cw > maxW || x + n * grid - 8 > maxW)) { x = 8; y += ch + 8; }
                }
                o.Under = under && o.Band > 0;
                o.R = o.Join ? new Rectangle(x - 8, y, cw + 8, ch) : new Rectangle(x, y, cw, ch);
                x += cw + 8;
            }
            if (x > 8) y += ch + 8;
            int view = Math.Max(1, ClientSize.Height);
            bar.Maximum = Math.Max(y, view);
            bar.LargeChange = view;
            bar.Enabled = y > view;
            SetScroll(bar.Value);
            Invalidate();
        }

        void SetScroll(int v)
        {
            int max = Math.Max(0, bar.Maximum - bar.LargeChange + 1);
            bar.Value = Math.Max(0, Math.Min(max, v));
        }

        protected override void OnResize(EventArgs e)
        {
            base.OnResize(e);
            Relayout();
        }

        protected override void OnMouseWheel(MouseEventArgs e)
        {
            if (Preview.Alt && PreviewOpen)
            {
                // Alt + колесо меняет размер открытого превью, список при этом не прокручивается
                if (Preview.Wheel(e.Delta))
                {
                    // виды прежнего размера (повёрнутые, со старым кадром) не должны вернуться, когда размер выберут снова
                    string keepTail = "|" + tile;
                    foreach (string vk in new List<string>(views.Keys))
                    {
                        if (vk.EndsWith(keepTail)) continue;
                        if (views[vk] != null) views[vk].Dispose();
                        views.Remove(vk);
                    }
                    Invalidate();
                }
                return;
            }
            SetScroll(bar.Value - Math.Sign(e.Delta) * 120);
        }

        // ---------------------------------------------------------- блоки особой формы
        // Блок, который в игре не куб и собран из нескольких текстур: наковальня, воронка, котёл… Строка таблицы:
        // "название|текстуры блока через запятую (звёздочка в конце — любое продолжение)|детали через точку с запятой".
        // Деталь — брусок "x0 y0 z0 x1 y1 z1 текстура" в шестнадцатых долях блока; дальше можно задать свою текстуру грани
        // (u — верх, d — низ, n — перед, s — зад, w и e — бока), участок текстуры после @ и only= — какие грани рисовать.
        // Через косую черту — запасные текстуры, если первой нет в пакетах. Развёртка грани по умолчанию — по её месту в блоке.
