            "stonecutter|stonecutter2_top,stonecutter2_side,stonecutter2_bottom,stonecutter2_saw|0 0 0 16 9 16 stonecutter2_side u=stonecutter2_top d=stonecutter2_bottom;1 9 8 15 16 8 stonecutter2_saw@1,9,15,16 only=n" };

        public List<Entry> AllEntries = new List<Entry>(); // все файлы сборки: текстуры деталей берутся и из тех, что сейчас не показаны
        Dictionary<string, Entry> byName = new Dictionary<string, Entry>();

        // Номер строки таблицы, к которой относится текстура блока с таким именем, или -1.
        static int ShapeOf(string name)
        {
            for (int i = 0; i < Shapes.Length; i++)
            {
                string[] row = Shapes[i].Split((char)124);
                foreach (string member in row[1].Split((char)44))
                    if (member.EndsWith("*") ? name.StartsWith(member.Substring(0, member.Length - 1)) : name == member) return i;
            }
            return -1;
        }

        // Грань бруска b = { x0, y0, z0, x1, y1, z1 }; uv — свой участок текстуры или null; left — где текстура лежит в общей развёртке.
        static Quad BoxFace(char f, float[] b, float left, float S, float[] uv)
        {
            float x0 = b[0] - 8, y0 = b[1], z0 = b[2] - 8, x1 = b[3] - 8, y1 = b[4], z1 = b[5] - 8;
            float lift = b[4] > 16 ? 16 * (float)Math.Floor((b[4] - 0.001f) / 16) : 0; // вторая половина высокой детали (дверь)
            float u0, u1, v0 = 16 - (b[4] - lift), v1 = 16 - Math.Max(0, b[1] - lift);
            float[] p;
            if (f == (char)110) { u0 = b[0]; u1 = b[3]; p = new float[] { x0, y1, z0, x1, y1, z0, x1, y0, z0, x0, y0, z0 }; }
            else if (f == (char)115) { u0 = 16 - b[3]; u1 = 16 - b[0]; p = new float[] { x1, y1, z1, x0, y1, z1, x0, y0, z1, x1, y0, z1 }; }
            else if (f == (char)119) { u0 = 16 - b[5]; u1 = 16 - b[2]; p = new float[] { x0, y1, z1, x0, y1, z0, x0, y0, z0, x0, y0, z1 }; }
            else if (f == (char)101) { u0 = b[2]; u1 = b[5]; p = new float[] { x1, y1, z0, x1, y1, z1, x1, y0, z1, x1, y0, z0 }; }
            else if (f == (char)117) { u0 = b[0]; u1 = b[3]; v0 = 16 - b[5]; v1 = 16 - b[2]; p = new float[] { x0, y1, z1, x1, y1, z1, x1, y1, z0, x0, y1, z0 }; }
            else { u0 = b[0]; u1 = b[3]; v0 = b[2]; v1 = b[5]; p = new float[] { x0, y0, z0, x1, y0, z0, x1, y0, z1, x0, y0, z1 }; }
            if (uv != null) { u0 = uv[0]; v0 = uv[1]; u1 = uv[2]; v1 = uv[3]; }
            return Q(p, left + u0 / 16 * S, v0 / 16 * S, left + u1 / 16 * S, v1 / 16 * S);
        }

        // Центр и размер модели по её граням.
        static void Bound(Model m)
        {
            float top = 0, wide = 0;
            foreach (Quad q in m.Quads)
                for (int i = 0; i < 4; i++)
                {
                    top = Math.Max(top, q.P[i * 3 + 1]);
                    wide = Math.Max(wide, Math.Max(Math.Abs(q.P[i * 3]), Math.Abs(q.P[i * 3 + 2])));
                }
            m.Cy = top / 2;
            m.Radius = (float)Math.Sqrt(wide * wide * 2 + top * top / 4) + 0.1f;
        }

        static string TexSpec(string spec, out float[] uv)
        {
            uv = null;
            int at = spec.IndexOf((char)64);
            if (at < 0) return spec;
            string[] n = spec.Substring(at + 1).Split((char)44);
            uv = new float[4];
            for (int i = 0; i < 4; i++) uv[i] = float.Parse(n[i], System.Globalization.CultureInfo.InvariantCulture);
            return spec.Substring(0, at);
        }

        bool ShapeModel(Obj o, out Model m, out int[] tex, out int tw, out int th)
        {
            m = null; tex = null; tw = th = 0;
            List<string> names = new List<string>();
            List<object[]> texs = new List<object[]>();
            List<object[]> faces = new List<object[]>(); // { грань, брусок, номер текстуры, участок }
            float[] uvSpare;
            foreach (string box in o.Boxes.Split((char)59))
            {
                string[] t = box.Trim().Split(new char[] { (char)32 }, StringSplitOptions.RemoveEmptyEntries);
                if (t.Length < 7) continue;
                float[] b = new float[6];
                for (int i = 0; i < 6; i++) b[i] = float.Parse(t[i], System.Globalization.CultureInfo.InvariantCulture);
                string only = "udnswe";
                Dictionary<char, string> own = new Dictionary<char, string>();
                for (int i = 7; i < t.Length; i++)
                {
                    if (t[i].StartsWith("only=")) only = t[i].Substring(5);
                    else if (t[i].Length > 2 && t[i][1] == (char)61) own[t[i][0]] = t[i].Substring(2);
                }
                foreach (char f in only)
                {
                    // грань нулевой площади (у пластины) не рисуется
                    bool flat = (f == (char)117 || f == (char)100) ? (b[0] == b[3] || b[2] == b[5]) : ((f == (char)110 || f == (char)115) ? (b[0] == b[3] || b[1] == b[4]) : (b[2] == b[5] || b[1] == b[4]));
                    if (flat) continue;
                    string spec;
                    bool special = own.TryGetValue(f, out spec);
                    if (!special) spec = t[6];
                    float[] uv;
                    spec = TexSpec(spec, out uv);
                    int found = -1;
                    // у грани своя текстура, а в пакетах её нет: берётся основная текстура бруска, иначе в блоке была бы дыра
                    string[] alts = special ? (spec + "/" + TexSpec(t[6], out uvSpare)).Split((char)47) : spec.Split((char)47);
                    foreach (string alt in alts)
                    {
                        found = names.IndexOf(alt);
                        Entry e;
                        if (found < 0 && byName.TryGetValue(alt, out e))
                        {
                            object[] loaded = Tex(e);
                            if (loaded != null) { names.Add(alt); texs.Add(loaded); found = names.Count - 1; }
                        }
                        if (found >= 0) break;
                    }
                    if (found >= 0) faces.Add(new object[] { f, b, found, uv });
                }
            }
            if (faces.Count == 0) return false;
            int size = 16;
            foreach (object[] t in texs) size = Math.Max(size, Math.Min(128, Math.Min((int)t[1], (int)t[2])));
            tw = size * texs.Count;
            th = size;
            tex = new int[tw * size];
            for (int i = 0; i < texs.Count; i++)
            {
                int[] px = Frame(texs[i], size);
                for (int y = 0; y < size; y++) Array.Copy(px, y * size, tex, y * tw + i * size, size);
            }
            m = new Model();
            foreach (object[] face in faces) m.Quads.Add(BoxFace((char)face[0], (float[])face[1], (int)face[2] * size, size, (float[])face[3]));
            m.TexW = tw;
            m.TexH = size;
            Bound(m);
            return true;
        }

        // ---------------------------------------------------------- сборка объекта

        object[] Tex(Entry e)
        {
            Pack from = edDraw && edPack != null && edPack.Files.ContainsKey(e.Key) ? edPack : e.Winner;
            string path = from.FullPath(e.Key);
            if (edDraw && livePx != null && string.Equals(path, livePath, StringComparison.OrdinalIgnoreCase)) return new object[] { livePx, liveW, liveH };
            object[] t;
            if (texCache.TryGetValue(path, out t)) return t;
            try
            {
                using (Bitmap b = Img.Load(path)) t = new object[] { Img.GetPixels(b), b.Width, b.Height };
            }
            catch (Exception) { t = null; }
            if (texCache.Count > 800) texCache.Clear();
            if (t != null) texCache[path] = t; // неудача не запоминается: файл мог быть занят или не хватило памяти
            return t;
        }

        // Квадратный кадр size×size: у ленты кадров берётся верхний, картинка приводится к общему размеру без сглаживания.
        int[] Frame(object[] t, int size)
        {
            int[] px = (int[])t[0];
            int w = (int)t[1], h = (int)t[2], s = Math.Min(w, h);
            // лента кадров: в плитке — первый кадр, в открытом окошке кадры сменяются
            int frames = h > w && h % w == 0 ? h / w : 1, skip = 0;
            if (frames > 1)
            {
                stripSeen = true;
                if (animRender) skip = (animTick / 3 % frames) * w;
            }
            int[] r = new int[size * size];
            for (int y = 0; y < size; y++)
                for (int x = 0; x < size; x++)
                    r[y * size + x] = px[(skip + y * s / size) * w + x * s / size];
            return r;
        }

        // Анимация в окошке: раз в 50 мс идёт такт, кадр держится три такта (как у большинства анимаций игры).
        int animTick;
        bool animRender, stripSeen, shownAnimated;
        Timer animTimer = new Timer();

        void AnimStep()
        {
            if (Preview.Alt != altWas) { altWas = !altWas; if (shown != null) Invalidate(); }
            bool shift = (ModifierKeys & Keys.Shift) != 0;
            if (shift != shiftWas)
            {
                shiftWas = shift;
                Form top = FindForm();
                if (shift && top != null) ShiftSelect();
            }
            if (!Visible) return;
            if (DockStep()) return;
            if (shown == null || rot != null) return;
            if (shown.Pano) panoYaw += 0.006f; // полный оборот примерно за 50 секунд
            else
            {
                if (!shownAnimated) return;
                animTick++;
                if (animTick % 3 != 0) return;
            }
            Bitmap old;
            string key = shown.Id + "|" + PopSize;
            if (views.TryGetValue(key, out old))
            {
                if (old != null) old.Dispose();
                views.Remove(key);
            }
            Invalidate();
        }

        // Какую сторону блока рисует текстура, по хвосту её имени.
        static string Role(string group, string key)
        {
            string name = Path.GetFileNameWithoutExtension(key), g = group.Substring(group.LastIndexOf((char)47) + 1);
            string rest = name.Length > g.Length ? name.Substring(g.Length) : "";
            foreach (string t in rest.Split((char)95))
            {
                if (t == "top" || t == "up" || t == "end") return "up";
                if (t == "bottom" || t == "down" || t == "lower") return "down";
                if (t == "upper") return "up";
                if (t == "side") return "side";
                if (t == "front") return "front";
                if (t == "back") return "back";
            }
            return "base";
        }

        static Quad Q(float[] p, float u0, float v0, float u1, float v1)
        {
            Quad q = new Quad();
            Array.Copy(p, q.P, 12);
            q.UV = new float[] { u0, v0, u1, v0, u1, v1, u0, v1 };
            return q;
        }

        static object[] Pick(Dictionary<string, object[]> roles, params string[] order)
        {
            object[] t;
            foreach (string r in order) if (roles.TryGetValue(r, out t)) return t;
            return null;
        }

        static bool Has(string name, params string[] words)
        {
            foreach (string w in words) if (name.Contains(w)) return true;
            return false;
        }

        // Блок: куб со своими текстурами на гранях; прозрачная текстура без сторон — растение (крестовина);
        // двери, рельсы, лестницы и подобное — одна пластина.
        bool BlockModel(Obj o, out Model m, out int[] tex, out int tw, out int th)
        {
            m = null; tex = null; tw = th = 0;
            if (o.Boxes != null) return ShapeModel(o, out m, out tex, out tw, out th);
            string group = Gallery.GroupKey(o.Parts[0].Key);
            Dictionary<string, object[]> roles = new Dictionary<string, object[]>();
            object[] first = null;
            int size = 16;
            foreach (Entry e in o.Parts)
            {
                object[] t = Tex(e);
                if (t == null) continue;
                if (first == null) first = t;
                size = Math.Max(size, Math.Min(256, Math.Min((int)t[1], (int)t[2])));
                string role = Role(group, e.Key);
                if (role == "base" || !roles.ContainsKey(role)) roles[role] = t; // из стадий роста остаётся последняя
            }
            if (first == null) return false;
            bool door = (o.Name ?? o.Title).Contains("door") && !(o.Name ?? o.Title).Contains("trapdoor");
            if (roles.ContainsKey("up") && roles.ContainsKey("down") && !roles.ContainsKey("side") && !roles.ContainsKey("base"))
            {
                // Две половины по высоте: дверь (нижняя и верхняя часть) — пластина в два блока, высокое растение
                // (double_plant_…_bottom и …_top) — две крестовины одна над другой.
                int[] lo = Frame(roles["down"], size), hi = Frame(roles["up"], size);
                int gaps = 0;
                foreach (int c in lo) if (((c >> 24) & 255) < 16) gaps++;
                if (door || gaps * 100 > lo.Length * 12)
                {
                    tw = size * 2;
                    th = size;
                    tex = new int[tw * size];
                    for (int y = 0; y < size; y++)
                    {
                        Array.Copy(lo, y * size, tex, y * tw, size);
                        Array.Copy(hi, y * size, tex, y * tw + size, size);
                    }
                    m = new Model();
                    m.Cy = 16;
                    float W = size;
                    if (door)
                    {
                        // дверь — доска толщиной в три шестнадцатых блока, а не плоский лист
                        foreach (char f in "udnswe")
                        {
                            m.Quads.Add(BoxFace(f, new float[] { 0, 0, 6.5f, 16, 16, 9.5f }, 0, W, null));
                            m.Quads.Add(BoxFace(f, new float[] { 0, 16, 6.5f, 16, 32, 9.5f }, W, W, null));
                        }
                        m.Opaque = false;
                    }
                    else for (int d = -1; d <= 1; d += 2)
                    {
                        m.Quads.Add(Q(new float[] { -7, 16, -7 * d, 7, 16, 7 * d, 7, 0, 7 * d, -7, 0, -7 * d }, 0, 0, W, W));
                        m.Quads.Add(Q(new float[] { -7, 32, -7 * d, 7, 32, 7 * d, 7, 16, 7 * d, -7, 16, -7 * d }, W, 0, 2 * W, W));
                    }
                    m.TexW = tw;
                    m.TexH = size;
                    m.Radius = 19f;
                    return true;
                }
            }
            object[] side = Pick(roles, "side", "base", "front") ?? first;
            bool sided = roles.ContainsKey("up") || roles.ContainsKey("down") || roles.ContainsKey("side") || roles.ContainsKey("front");
            string name = o.Name ?? o.Title;
            int[] sidePx = Frame(side, size);
            int holes = 0;
            foreach (int c in sidePx) if (((c >> 24) & 255) < 16) holes++;
            if (Has(name, "stairs"))
            {
                // ступени: нижняя половина целиком и верхняя половина сзади
                tex = sidePx;
                tw = size;
                th = size;
                m = new Model();
                // Текстура ступеней в пакетах бывает нарисована «профилем» — с пустой верхней четвертью. Поэтому на все грани,
                // кроме боков нижней половины, идёт её сплошная нижняя половина: пустое место чернотой на ступень не ложится.
                bool hollow = holes * 20 > sidePx.Length;
                float[] low = hollow ? new float[] { 0, 8, 16, 16 } : null, lowHalf = hollow ? new float[] { 0, 8, 8, 16 } : null;
                foreach (char f in "udnswe")
                {
                    bool flatFace = f == (char)117 || f == (char)100;
                    m.Quads.Add(BoxFace(f, new float[] { 0, 0, 0, 16, 8, 16 }, 0, size, flatFace ? low : null));
                    m.Quads.Add(BoxFace(f, new float[] { 0, 8, 8, 16, 16, 16 }, 0, size, f == (char)119 || f == (char)101 ? lowHalf : low));
                }
                m.TexW = size;
                m.TexH = size;
                m.Opaque = true;
                Bound(m);
                return true;
            }
            int slab = Has(name, "trapdoor") ? 3 : (Has(name, "carpet") ? 1 : 0);       // лежачая плита такой толщины
            bool lying = slab == 0 && Has(name, "rail", "waterlily", "lily_pad");        // плоская картинка на земле
            bool solid = slab == 0 && !lying && (sided || Has(name, "leaves", "glass", "ice", "spawner", "slime", "honey", "grate", "vault", "mangrove_roots", "scaffolding"));
            bool plane = slab == 0 && !lying && !solid && (name == "vine" || Has(name, "door", "ladder", "lichen", "sculk_vein", "pane", "bars"));
            bool cross = slab == 0 && !lying && !solid && !plane && holes * 100 > sidePx.Length * 12;
            if (slab > 0 || lying)
            {
                tex = roles.ContainsKey("base") ? Frame(roles["base"], size) : sidePx; // сверху — основная картинка, не боковая
                tw = size;
                th = size;
                float T = size, hgt = slab, edge = T * slab / 16f;
                m = new Model();
                m.Cy = hgt / 2;
                m.Quads.Add(Q(new float[] { -8, hgt, 8, 8, hgt, 8, 8, hgt, -8, -8, hgt, -8 }, 0, 0, T, T));
                if (slab > 0)
                {
                    m.Quads.Add(Q(new float[] { -8, 0, -8, 8, 0, -8, 8, 0, 8, -8, 0, 8 }, 0, 0, T, T));
                    m.Quads.Add(Q(new float[] { -8, hgt, -8, 8, hgt, -8, 8, 0, -8, -8, 0, -8 }, 0, 0, T, edge));
                    m.Quads.Add(Q(new float[] { 8, hgt, 8, -8, hgt, 8, -8, 0, 8, 8, 0, 8 }, 0, 0, T, edge));
                    m.Quads.Add(Q(new float[] { -8, hgt, 8, -8, hgt, -8, -8, 0, -8, -8, 0, 8 }, 0, 0, T, edge));
                    m.Quads.Add(Q(new float[] { 8, hgt, -8, 8, hgt, 8, 8, 0, 8, 8, 0, -8 }, 0, 0, T, edge));
                }
                m.TexW = size;
                m.TexH = size;
                m.Radius = 11.6f;
                m.View = new float[] { 0.6f, -0.75f }; // лежачее показывается сверху, иначе видно одно ребро
                return true;
            }
            m = new Model();
            m.Cy = 8;
            th = size;
            float S = size;
            if (plane || cross)
            {
                tex = sidePx;
                tw = size;
                if (plane) m.Quads.Add(Q(new float[] { -8, 16, 0, 8, 16, 0, 8, 0, 0, -8, 0, 0 }, 0, 0, S, S));
                else
                {
                    m.Quads.Add(Q(new float[] { -7, 16, -7, 7, 16, 7, 7, 0, 7, -7, 0, -7 }, 0, 0, S, S));
                    m.Quads.Add(Q(new float[] { -7, 16, 7, 7, 16, -7, 7, 0, -7, -7, 0, 7 }, 0, 0, S, S));
                }
                m.TexW = size;
                m.TexH = size;
                m.Radius = 12.5f;
                return true;
            }
            object[] up = Pick(roles, "up", "base") ?? side, down = Pick(roles, "down", "up", "base") ?? side;
            object[] front = Pick(roles, "front") ?? side, back = Pick(roles, "back") ?? side;
            // развёртка куба: шесть кадров в ряд — верх, низ, перед, зад, левый бок, правый бок
            object[][] faces = { up, down, front, back, side, side };
            tw = size * 6;
            tex = new int[tw * size];
            for (int i = 0; i < 6; i++)
            {
                int[] px = faces[i] == side ? sidePx : Frame(faces[i], size);
                for (int y = 0; y < size; y++) Array.Copy(px, y * size, tex, y * tw + i * size, size);
            }
            m.Quads.Add(Q(new float[] { -8, 16, 8, 8, 16, 8, 8, 16, -8, -8, 16, -8 }, 0, 0, S, S));
            m.Quads.Add(Q(new float[] { -8, 0, -8, 8, 0, -8, 8, 0, 8, -8, 0, 8 }, S, 0, 2 * S, S));
            m.Quads.Add(Q(new float[] { -8, 16, -8, 8, 16, -8, 8, 0, -8, -8, 0, -8 }, 2 * S, 0, 3 * S, S));
            m.Quads.Add(Q(new float[] { 8, 16, 8, -8, 16, 8, -8, 0, 8, 8, 0, 8 }, 3 * S, 0, 4 * S, S));
            m.Quads.Add(Q(new float[] { -8, 16, 8, -8, 16, -8, -8, 0, -8, -8, 0, 8 }, 4 * S, 0, 5 * S, S));
            m.Quads.Add(Q(new float[] { 8, 16, -8, 8, 16, 8, 8, 0, 8, 8, 0, -8 }, 5 * S, 0, 6 * S, S));
            m.TexW = tw;
            m.TexH = size;
            m.Radius = 13.9f;
            // У сплошного блока прозрачность текстуры игра не показывает (в ней пакеты хранят свечение): руда и лампа
            // не должны просвечивать. Прозрачными остаются только блоки с настоящими просветами.
            m.Opaque = holes * 50 <= sidePx.Length && !Has(name, "leaves", "glass", "ice", "spawner", "slime", "honey", "grate", "vault", "mangrove_roots", "scaffolding");
            return true;
        }

        // Модель и текстура объекта. m == null при удаче — у текстуры нет объёмной формы, она показывается как есть.
        bool Build(Obj o, out Model m, out int[] tex, out int tw, out int th)
        {
            m = null; tex = null; tw = th = 0;
            Entry e = o.Parts[0];
            Model known = Geo.Find(e.Key.Substring(0, e.Key.Length - Path.GetExtension(e.Key).Length));
            if (known == null && e.Key.StartsWith("textures/blocks/")) return BlockModel(o, out m, out tex, out tw, out th);
            object[] t = Tex(e);
            if (t == null) return false;
            tex = (int[])t[0];
            tw = (int)t[1];
            th = (int)t[2];
            m = known;
            if (m == null && e.Key.StartsWith("textures/items/"))
            {
                // предмет — тонкая пластинка с его картинкой
                int size = Math.Max(16, Math.Min(256, Math.Min(tw, th)));
                tex = Frame(t, size);
                tw = th = size;
                m = new Model();
                m.Cy = 8;
                m.Quads.Add(Q(new float[] { -8, 16, 0, 8, 16, 0, 8, 0, 0, -8, 0, 0 }, 0, 0, size, size));
                m.TexW = m.TexH = size;
                m.Radius = 12.5f;
            }
            return true;
        }

        static Bitmap FlatView(int[] tex, int tw, int th, int size)
        {
            Bitmap r = new Bitmap(size, size, PixelFormat.Format32bppArgb);
            using (Bitmap src = Img.FromPixels(tw, th, tex))
            using (Graphics g = Graphics.FromImage(r))
            {
                float k = Math.Min(size / (float)tw, size / (float)th);
                int w = Math.Max(1, (int)(tw * k)), h = Math.Max(1, (int)(th * k));
                g.InterpolationMode = k >= 1 ? InterpolationMode.NearestNeighbor : InterpolationMode.HighQualityBicubic;
                g.PixelOffsetMode = PixelOffsetMode.Half;
                g.DrawImage(src, new Rectangle((size - w) / 2, (size - h) / 2, w, h));
            }
            return r;
        }

        Bitmap View(Obj o, int size)
        {
            string key = o.Id + "|" + size;
            Bitmap b;
            if (views.TryGetValue(key, out b)) return b;
            // плитка всегда в исходном ракурсе; повёрнутым объект бывает только в окошке
            bool live = size == PopSize, strip;
            float[] turned = null;
            if (live) angles.TryGetValue(o.Id, out turned);
            b = Draw(o, size, live, turned, panoYaw, out strip);
            if (!o.Pano)
            {
                if (strip) animated.Add(o.Id); // у объекта есть лента кадров: запоминается, даже если картинка потом берётся готовой
                if (live && o == shown) shownAnimated = strip;
            }
            views[key] = b;
            return b;
        }

        // Рисует объект. live — как в открытом окошке: текущий кадр ленты, поворот turned (null — исходный ракурс),
        // панорама под углом yaw; иначе это плитка списка. strip — у объекта есть лента кадров.
        Bitmap Draw(Obj o, int size, bool live, float[] turned, float yaw, out bool strip)
        {
            strip = false;
            Bitmap b = null;
            if (o.Pano)
            {
                try { b = RenderPano(o, size, live ? yaw : 0); }
                catch (Exception) { b = null; }
                return b;
            }
            animRender = live;
            stripSeen = false;
            try
            {
                Model m;
                int[] tex;
                int tw, th;
                if (Build(o, out m, out tex, out tw, out th))
                {
                    if (m == null) b = FlatView(tex, tw, th, size);
                    else
                    {
                        float[] h = m.View ?? new float[] { 0.6f, -0.3f };
                        home[o.Id] = h;
                        float[] a = turned ?? h;
                        b = Geo.Render(m, tex, tw, th, size, a[0], a[1]);
                    }
                }
            }
            catch (Exception) { b = null; }
            animRender = false;
            strip = stripSeen;
            return b;
        }

        // Панорама главного меню. Шесть картинок — стенки куба: 0 — перед, 1 — право, 2 — зад, 3 — лево, 4 — верх, 5 — низ.
        // Вид изнутри куба; в окошке панорама медленно поворачивается, как в меню игры, а правой кнопкой её можно вести рукой.
        float panoYaw;

        Bitmap RenderPano(Obj o, int size, float yaw)
        {
            object[][] wall = new object[6][];
            foreach (Entry part in o.Parts)
            {
                string name = Path.GetFileNameWithoutExtension(part.Key);
                int n = name[name.Length - 1] - (char)48;
                if (n >= 0 && n < 6) wall[n] = Tex(part);
            }
            int[] res = new int[size * size];
            float cy = (float)Math.Cos(yaw), sy = (float)Math.Sin(yaw), half = size / 2f;
            for (int py = 0; py < size; py++)
            {
                for (int px = 0; px < size; px++)
                {
                    // луч из центра куба через точку экрана (угол обзора 90 градусов), повёрнутый вокруг вертикали
                    float dx = (px + 0.5f - half) / half, y = -(py + 0.5f - half) / half;
                    float x = dx * cy + sy, z = -dx * sy + cy;
                    float ax = Math.Abs(x), ay = Math.Abs(y), az = Math.Abs(z), u, v;
                    int face;
                    if (az >= ax && az >= ay) { face = z > 0 ? 0 : 2; u = x / z; v = -y / az; }
                    else if (ax >= ay) { face = x > 0 ? 1 : 3; u = -z / x; v = -y / ax; }
                    else { face = y > 0 ? 4 : 5; u = x / ay; v = y > 0 ? z / ay : -z / ay; }
                    object[] t = wall[face];
                    if (t == null) continue;
                    int w = (int)t[1], h = (int)t[2];
                    int tx = Math.Max(0, Math.Min(w - 1, (int)((u + 1) / 2 * w))), ty = Math.Max(0, Math.Min(h - 1, (int)((v + 1) / 2 * h)));
                    res[py * size + px] = ((int[])t[0])[ty * w + tx] | unchecked((int)0xFF000000);
                }
            }
            return Img.FromPixels(size, size, res);
        }

        Bitmap IconOf(Entry e)
        {
            string key = "icon|" + e.Key;
            Bitmap b;
            if (views.TryGetValue(key, out b)) return b;
            object[] t = Tex(e);
            try
            {
                // у ленты кадров (анимированный блок или предмет) значком служит верхний кадр
                bool strip = t != null && (int)t[2] > (int)t[1] && (e.Key.StartsWith("textures/blocks/") || e.Key.StartsWith("textures/items/"));
                if (strip) b = FlatView(Frame(t, (int)t[1]), (int)t[1], (int)t[1], IconSize);
                else b = t == null ? null : FlatView((int[])t[0], (int)t[1], (int)t[2], IconSize);
            }
            catch (Exception) { b = null; }
            views[key] = b;
            return b;
        }

        // ---------------------------------------------------------- отрисовка

        protected override void OnPaint(PaintEventArgs pe)
        {
            Graphics g = pe.Graphics;
            g.Clear(Theme.Canvas);
            int top = bar.Value;
            Stopwatch sw = Stopwatch.StartNew();
            bool pending = false;
            foreach (Obj o in objs)
            {
                Rectangle r = o.R;
                r.Offset(0, -top);
                if (r.Bottom < 0) continue;
                if (r.Top > ClientSize.Height) break;
                if (o.H != null)
                {
                    // заголовок раздела — такой же, как в обычном списке
                    int tone = Theme.HeadTone(o.H.Big, o == hot);
                    using (SolidBrush hb = new SolidBrush(Color.FromArgb(tone, tone + 1, tone + 6))) g.FillRectangle(hb, r);
                    int ax = r.X + 13, ay = r.Y + r.Height / 2;
                    Point[] tri = o.H.Open
                        ? new Point[] { new Point(ax - 5, ay - 3), new Point(ax + 5, ay - 3), new Point(ax, ay + 4) }
                        : new Point[] { new Point(ax - 3, ay - 5), new Point(ax + 4, ay), new Point(ax - 3, ay + 5) };
                    using (SolidBrush tb = new SolidBrush(Theme.Dim)) g.FillPolygon(tb, tri);
                    TextRenderer.DrawText(g, o.H.Title + "   " + o.H.Count, o.H.Big ? big : bold, new Rectangle(r.X + 26, r.Y, r.Width - 30, r.Height),
                        Theme.Text, TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.EndEllipsis);
                    continue;
                }
                bool isHot = o == hot;
                // карточка — как в обычном списке: сверху название, под ним ячейка с картинкой и подписью пакета
                using (SolidBrush back = new SolidBrush(Theme.Card)) g.FillRectangle(back, r);
                using (Pen edge = new Pen(Theme.Edge)) g.DrawRectangle(edge, r.X, r.Y, r.Width - 1, r.Height - 1);
                if (o.Band > 0)
                {
                    SmoothingMode gsm = g.SmoothingMode;
                    g.SmoothingMode = SmoothingMode.AntiAlias;
                    using (SolidBrush tint = new SolidBrush(Gallery.GroupTint(o.Band, o.Kind)))
                    {
                        if (o.Under) for (float dx = r.X + 4; dx < r.Right - 4; dx += 13) g.FillEllipse(tint, dx, r.Y - 0.5f, 4.6f, 4.6f);
                        else g.FillRectangle(tint, r.X, r.Y, r.Width, 3);
                        if (o.Join) for (float dy = r.Y + 8; dy < r.Bottom - 5; dy += 13) g.FillEllipse(tint, r.X - 1.8f, dy, 4.6f, 4.6f);
                    }
                    g.SmoothingMode = gsm;
                }
                int cellW = Math.Max(tile + 12, 88), lead = o.Join ? 8 : 0;
                TextRenderer.DrawText(g, o.Title, Font, new Rectangle(r.X + lead + 4, r.Y + 4, r.Width - lead - 8, 19), Theme.Text,
                    TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.EndEllipsis);
                Rectangle cell = new Rectangle(r.X + lead + 6, r.Y + 24, cellW - 4, tile + 30);
                bool navHere = o == nav; // объект, выделенный через Shift, — синеватый, как выделенная текстура в обычном списке
                Color cellBack = navHere ? (Theme.Dark ? Color.FromArgb(50, 78, 124) : Color.FromArgb(196, 220, 250)) : (isHot ? Theme.CellHot : Theme.CellOn);
                using (SolidBrush cb = new SolidBrush(cellBack)) g.FillRectangle(cb, cell);
                using (Pen ce = new Pen(isHot || navHere ? Theme.Accent : Theme.Edge)) g.DrawRectangle(ce, cell.X, cell.Y, cell.Width - 1, cell.Height - 1);
                Bitmap v = null;
                if (views.ContainsKey(o.Id + "|" + tile) || sw.ElapsedMilliseconds < 30) v = View(o, tile);
                else pending = true; // остальное дорисуется следующими проходами, окно не замирает
                if (v != null) g.DrawImageUnscaled(v, cell.X + (cell.Width - tile) / 2, cell.Y + 6);
                Pack from = o.Parts.Count > 0 ? o.Parts[0].Winner : null;
                TextRenderer.DrawText(g, from == null ? "" : from.Name, Font, new Rectangle(cell.X + 2, cell.Y + 6 + tile + 3, cell.Width - 4, 18), Theme.Text,
                    TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.EndEllipsis);
            }
            // в списке одни файлы, у которых нет объёмного вида (звуки, JSON, карты слоёв): пустое поле объясняется
            bool anyObj3 = false, closedHead3 = false;
            foreach (Obj eo in objs) { if (eo.H == null) anyObj3 = true; else if (!eo.H.Open) closedHead3 = true; }
            if (!anyObj3 && !closedHead3)
                TextRenderer.DrawText(g, L.T("Здесь нет текстур, которые можно показать в 3D"), Font, ClientRectangle, Theme.Dim,
                    TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix);
            if (pending) drawTimer.Start();
            if (shown != null) DrawPopup(g);
            if (shown != null && Preview.Alt) Preview.Badge(g, PopBox(shown), Font);
        }

        // Крупный вид объекта под курсором; внизу — уменьшенные текстуры, из которых он собран.
        void DrawPopup(Graphics g)
        {
            Rectangle box = PopBox(shown);
            int x = box.X, y = box.Y, w = box.Width;
            using (SolidBrush back = new SolidBrush(Theme.Card)) g.FillRectangle(back, box);
            using (Pen edge = new Pen(Theme.Accent)) g.DrawRectangle(edge, box.X, box.Y, box.Width - 1, box.Height - 1);
            TextRenderer.DrawText(g, shown.Title, bold, new Rectangle(x + 8, y + 4, w - 16, 22), Theme.Text,
                TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.EndEllipsis);
            Bitmap big = View(shown, PopSize);
            if (big != null) g.DrawImageUnscaled(big, x + 8, y + 28);
            for (int i = 0; i < shown.Parts.Count; i++)
            {
                Rectangle ir = IconRect(shown, box, i);
                using (SolidBrush cell = new SolidBrush(Theme.CellOff)) g.FillRectangle(cell, ir);
                Bitmap icon = IconOf(shown.Parts[i]);
                if (icon != null) g.DrawImageUnscaled(icon, ir.Location);
                using (Pen edge = new Pen(i == hotIcon ? Theme.Accent : Theme.Edge)) g.DrawRectangle(edge, ir.X, ir.Y, ir.Width - 1, ir.Height - 1);
            }
        }

        // ---------------------------------------------------------- мышь

        Obj At(Point p)
        {
            int vy = p.Y + bar.Value;
            foreach (Obj o in objs)
            {
                if (o.R.Bottom < vy) continue;
                if (o.R.Top > vy) break;
                if (o.R.Contains(p.X, vy)) return o;
            }
            return null;
        }

        void DropViews(Obj o)
        {
            foreach (int size in new int[] { tile, PopSize })
            {
                Bitmap b;
                string key = o.Id + "|" + size;
                if (!views.TryGetValue(key, out b)) continue;
                if (b != null) b.Dispose();
                views.Remove(key);
            }
        }

        protected override void OnMouseMove(MouseEventArgs e)
        {
            base.OnMouseMove(e);
            if (frozen) return;
            if (nav != null && rot == null)
            {
                // пока есть выделение, превью показывает его; небольшой сдвиг мыши сразу после шага не считается движением
                Point now = Cursor.Position;
                int moved = Math.Abs(now.X - navMouse.X) + Math.Abs(now.Y - navMouse.Y);
                if (moved <= 16 && Environment.TickCount - navAt < 450) { navMouse = now; return; }
                if (moved <= 3) return;
                nav = null;
                ClosePopup();
                Invalidate();
            }
            if (rot != null && (MouseButtons & MouseButtons.Right) == 0) rot = null; // кнопку отпустили вне окна: отпускание сюда не пришло
            if (rot != null)
            {
                // объект идёт за курсором, как модели в окошке обычного списка
                int dx = e.X - rotStart.X, dy = e.Y - rotStart.Y;
                if (rot.Pano)
                {
                    // панорама едет за курсором влево и вправо
                    panoYaw = rotFrom[0] - dx * 0.008f;
                    DropViews(rot);
                    Invalidate();
                    return;
                }
                angles[rot.Id] = new float[] { rotFrom[0] - dx * 0.012f, Math.Max(-1.5f, Math.Min(1.5f, rotFrom[1] - dy * 0.012f)) };
                DropViews(rot);
                Invalidate();
                return;
            }
            if (InPopupZone(e.Location))
            {
                // мышь на окошке или на пути к нему: оно остаётся, плитки под ним не отзываются
                closeTimer.Stop();
                popTimer.Stop();
                int icon = IconAt(e.Location);
                Cursor = Cursors.Hand;
                if (hot != shown || icon != hotIcon) { hot = shown; hotIcon = icon; Invalidate(); }
                return;
            }
            hotIcon = -1;
            if (shown != null && !closeTimer.Enabled) closeTimer.Start();
            Obj o = At(e.Location);
            Cursor = o != null ? Cursors.Hand : Cursors.Default;
            if (o == hot) return;
            hot = o;
            popTimer.Stop();
            popTimer.Interval = DockPreview ? 1 : 220; // панель превью обновляется сразу, окошко — с задержкой
            if (o != null && o.H == null) popTimer.Start();
            Invalidate();
        }

        protected override void OnMouseLeave(EventArgs e)
        {
            base.OnMouseLeave(e);
            if (rot != null || frozen) return;
            hot = null;
            hotIcon = -1;
            popTimer.Stop();
            if (shown != null) closeTimer.Start();
            Invalidate();
        }

        protected override void OnMouseDown(MouseEventArgs e)
        {
            base.OnMouseDown(e);
            Focus();
            // вращается только объект в открытом окошке
            float[] a;
            if (e.Button != MouseButtons.Right || shown == null || !PopBox(shown).Contains(e.Location)) return;
            if (shown.Pano) a = new float[] { panoYaw, 0 };
            else if (!angles.TryGetValue(shown.Id, out a) && !home.TryGetValue(shown.Id, out a)) return;
            rot = shown;
            rotStart = e.Location;
            rotFrom = a;
        }

        protected override void OnMouseUp(MouseEventArgs e)
        {
            base.OnMouseUp(e);
            if (e.Button == MouseButtons.Right) { rot = null; return; }
            if (e.Button != MouseButtons.Left) return;
            if (shown != null && PopBox(shown).Contains(e.Location))
            {
                // щелчок в окошке: по значку — к этой текстуре, в остальном месте — к первой текстуре объекта
                int icon = IconAt(e.Location);
                if (Go != null) Go(shown.Parts[Math.Max(0, icon)]);
                return;
            }
            Obj o = At(e.Location);
            if (o == null) return;
            if (o.H != null) { if (HeaderClicked != null) HeaderClicked(o.H.Key); }
            else if (Go != null) Go(o.Parts[0]);
        }

        // для проверочных снимков: выделить объект с этим номером и сделать от него шаги вперёд
        public void TestNav(int n, int steps)
        {
            foreach (Obj o in objs)
            {
                if (o.H != null || n-- > 0) continue;
                frozen = true;
                NavShow(o);
                for (int i = 0; i < steps; i++) NavStep(1);
                return;
            }
        }

        // для проверочных снимков: показать окошко у объекта с этим номером или перейти к нему
        public void TestHover(int n, bool go)
        {
            foreach (Obj o in objs)
            {
                if (o.H != null || n-- > 0) continue;
                if (go) { if (Go != null) Go(o.Parts[0]); return; }
                SetScroll(o.R.Top - 60);
                frozen = true; // настоящая мышь над окном не должна сбить проверочный снимок
                if (DockPreview) { hot = o; SendDocked(o, true); Invalidate(); return; }
                hot = shown = o;
                Invalidate();
                return;
            }
        }
    }

    // Кнопка, которая не забирает фокус ввода: после щелчка система не обводит её утолщённой тёмной рамкой.
    class PlainButton : Button
    {
        public PlainButton() { SetStyle(ControlStyles.Selectable, false); }
        protected override bool ShowFocusCues { get { return false; } }
        public override void NotifyDefault(bool value) { base.NotifyDefault(false); }
    }

    // Кнопка-переключатель верхнего ряда: не забирает фокус ввода, поэтому на нажатой не появляется пунктирная рамка.
    class FlatToggle : CheckBox
    {
        public FlatToggle() { SetStyle(ControlStyles.Selectable, false); }
        protected override bool ShowFocusCues { get { return false; } }
    }

    // Выпадающий список кнопки «Все текстуры»: крупные строки во всю ширину; строка под мышью заливается синим,
    // выбранный сейчас пункт написан жирным. Рисуется сам, поэтому размер точный — без полей и прокрутки меню.
    class DropList : Control
    {
        public const int RowH = 30;
        public string[] Rows = new string[0];
        public bool[] Active = new bool[0];
        public int Current = -1, Hot = -1;
        public event Action<int> Chosen;
        public void Pick(int row) { if (row >= 0 && row < Rows.Length && Active[row] && Chosen != null) Chosen(row); } // для проверочных снимков

        public DropList()
        {
            SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer, true);
            Cursor = Cursors.Hand;
        }

        public void Fit(int minWidth)
        {
            int w = minWidth;
            using (Font bold = new Font(Font, FontStyle.Bold))
                foreach (string row in Rows) w = Math.Max(w, TextRenderer.MeasureText(row, bold).Width + 28);
            Size = new Size(w, Rows.Length * RowH + 2);
        }

        int RowAt(Point p)
        {
            int i = (p.Y - 1) / RowH;
            return p.Y >= 1 && i >= 0 && i < Rows.Length && Active[i] ? i : -1;
        }

        protected override void OnMouseMove(MouseEventArgs e)
        {
            base.OnMouseMove(e);
            int now = RowAt(e.Location);
            if (now == Hot) return;
            Hot = now;
            Invalidate();
        }

        protected override void OnMouseLeave(EventArgs e)
        {
            base.OnMouseLeave(e);
            if (Hot < 0) return;
            Hot = -1;
            Invalidate();
        }

        protected override void OnMouseUp(MouseEventArgs e)
        {
            base.OnMouseUp(e);
            int i = RowAt(e.Location);
            if (e.Button == MouseButtons.Left && i >= 0 && Chosen != null) Chosen(i);
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.Clear(Theme.Card);
            using (Font bold = new Font(Font, FontStyle.Bold))
                for (int i = 0; i < Rows.Length; i++)
                {
                    Rectangle r = new Rectangle(1, 1 + i * RowH, Width - 2, RowH);
                    if (i == Hot) using (SolidBrush b = new SolidBrush(Theme.Accent)) g.FillRectangle(b, r);
                    Color c = !Active[i] ? Theme.Dim : (i == Hot ? Color.White : Theme.Text);
                    TextRenderer.DrawText(g, Rows[i], i == Current ? bold : Font, new Rectangle(r.X + 11, r.Y, r.Width - 14, r.Height), c,
                        TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine);
                }
            using (Pen pen = new Pen(Theme.Dim)) g.DrawRectangle(pen, 0, 0, Width - 1, Height - 1);
        }
    }

    // Строка состояния. Метки {o}, {g}, {b} в тексте рисуются кристаллами — такими же, как на карточках текстур.
    class StatusLabel : Label
    {
        // Подсказки (LoopText) идут бегущей строкой по кругу: через три секунды после появления начинают медленно
        // двигаться влево. Любой другой текст — сведения о текстуре под курсором — стоит на месте.
        public Func<string> LoopText;
        const int Pause = 3000;            // задержка перед движением, мс
        const string Between = "        "; // промежуток между подсказками в тексте; такой же ставится между концом строки и её новым началом
        Timer timer = new Timer();
        System.Diagnostics.Stopwatch since = System.Diagnostics.Stopwatch.StartNew();
        float offset;
        bool hover;
        // Кружок «i» слева: щелчок включает и выключает подсказки. На сведения о текстуре под курсором он не влияет.
        const int Icon = 16, TextLeft = 24;
        public bool HintsOn = Environment.GetEnvironmentVariable("BPS_HINTS") != "0"; // при каждом запуске подсказки включены; переменная — для проверочных снимков
        bool overIcon;

        Rectangle IconRect { get { return new Rectangle(2, (Height - Icon) / 2, Icon, Icon); } }

        protected override void OnMouseMove(MouseEventArgs e)
        {
            base.OnMouseMove(e);
            bool now = IconRect.Contains(e.Location);
            if (now == overIcon) return;
            overIcon = now;
            Cursor = now ? Cursors.Hand : Cursors.Default;
            Invalidate();
            ShowHints();
        }

        // Пока карусель выключена, те же подсказки показываются всплывающим окошком над кружком «i» — столбиком, с кристаллами.
        ToolTip tip;
        bool tipShown;
        const int TipPadX = 12, TipPadY = 9, TipGap = 5;
        static readonly TextFormatFlags TipFlags = TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix
            | TextFormatFlags.NoPadding | TextFormatFlags.SingleLine;

        static string[] HintLines(string text)
        {
            return System.Text.RegularExpressions.Regex.Split((text ?? "").Trim(), " {3,}");
        }

        // Рисует или только измеряет (g == null) одну строку подсказки; возвращает её ширину.
        static int HintLine(Graphics g, string line, int x, int y, int h, Color color)
        {
            Font font = SystemFonts.MessageBoxFont;
            int x0 = x;
            foreach (string part in System.Text.RegularExpressions.Regex.Split(line, @"(\{[ogbv]\})"))
            {
                if (part.Length == 0) continue;
                if (part.Length == 3 && part[0] == '{')
                {
                    if (g != null)
                    {
                        Color c = part[1] == 'o' ? Theme.GemOrange : (part[1] == 'g' ? Theme.GemGreen : (part[1] == 'v' ? Theme.GemViolet : Theme.GemBlue));
                        Theme.DrawGem(g, x + 7, y + h / 2, 6, c);
                    }
                    x += 15;
                    continue;
                }
                int w = TextRenderer.MeasureText(part, font, new Size(int.MaxValue, h), TipFlags).Width;
                if (g != null) TextRenderer.DrawText(g, part, font, new Rectangle(x, y, w + 4, h), color, TipFlags);
                x += w;
            }
            return x - x0;
        }

        public void TestTip() { overIcon = true; HintsOn = false; Invalidate(); ShowHints(); } // для проверочных снимков

        void ShowHints()
        {
            bool want = overIcon && !HintsOn && LoopText != null;
            if (want == tipShown) return;
            tipShown = want;
            if (!want) { if (tip != null) tip.Hide(this); return; }
            string text = LoopText();
            string[] lines = HintLines(text);
            int lineH = SystemFonts.MessageBoxFont.Height + TipGap;
            if (tip == null)
            {
                tip = new ToolTip();
                tip.OwnerDraw = true;
                tip.Popup += delegate(object sender, PopupEventArgs e)
                {
                    string[] ls = HintLines(LoopText());
                    int h = SystemFonts.MessageBoxFont.Height + TipGap, w = 0;
                    foreach (string l in ls) w = Math.Max(w, HintLine(null, l, 0, 0, h, Color.Empty));
                    e.ToolTipSize = new Size(w + TipPadX * 2, ls.Length * h + TipPadY * 2);
                };
                tip.Draw += delegate(object sender, DrawToolTipEventArgs e)
                {
                    using (SolidBrush back = new SolidBrush(Theme.Dark ? Theme.Card : Color.White)) e.Graphics.FillRectangle(back, e.Bounds);
                    using (Pen edge = new Pen(Theme.Dark ? Theme.Dim : Color.FromArgb(118, 118, 118)))
                        e.Graphics.DrawRectangle(edge, e.Bounds.X, e.Bounds.Y, e.Bounds.Width - 1, e.Bounds.Height - 1);
                    string[] ls = HintLines(e.ToolTipText);
                    int h = SystemFonts.MessageBoxFont.Height + TipGap;
                    for (int i = 0; i < ls.Length; i++)
                        HintLine(e.Graphics, ls[i], e.Bounds.X + TipPadX, e.Bounds.Y + TipPadY + i * h, h, Theme.Dark ? Theme.Text : Color.FromArgb(30, 30, 30));
                };
            }
            // окошко встаёт над строкой состояния, левым краем у кружка
            tip.Show(text, this, IconRect.X, -(lines.Length * lineH + TipPadY * 2) - 4);
        }

        protected override void OnMouseDown(MouseEventArgs e)
        {
            base.OnMouseDown(e);
            if (e.Button != MouseButtons.Left || !IconRect.Contains(e.Location)) return;
            HintsOn = !HintsOn;
            offset = 0;
            since.Restart();
            Invalidate();
            ShowHints();
        }

        public StatusLabel()
        {
            SetStyle(ControlStyles.OptimizedDoubleBuffer | ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint, true);
            timer.Interval = 30;
            timer.Tick += delegate
            {
                if (!Looping || !HintsOn || hover || since.ElapsedMilliseconds < Pause || !Visible) return;
                offset += 1.2f; // около сорока пикселей в секунду
                Invalidate();
            };
        }

        bool Looping { get { return LoopText != null && Text == LoopText(); } }

        protected override void OnHandleCreated(EventArgs e)
        {
            base.OnHandleCreated(e);
            since.Restart();
            timer.Start();
        }

        protected override void OnTextChanged(EventArgs e)
        {
            base.OnTextChanged(e);
            // строка сменилась: подсказки начнут движение заново, с начала и после паузы
            offset = 0;
            since.Restart();
            Invalidate();
        }

        // Под курсором карусель останавливается, чтобы строку можно было дочитать.
        protected override void OnMouseEnter(EventArgs e) { base.OnMouseEnter(e); hover = true; }
        protected override void OnMouseLeave(EventArgs e) { base.OnMouseLeave(e); hover = false; if (overIcon) { overIcon = false; Cursor = Cursors.Default; Invalidate(); ShowHints(); } }

        protected override void Dispose(bool disposing)
        {
            if (disposing) { timer.Dispose(); if (tip != null) tip.Dispose(); }
            base.Dispose(disposing);
        }

        // Рисует строку с кристаллами начиная с x; draw == false — только измеряет. Возвращает x после конца.
        int Line(Graphics g, string[] parts, int x, bool draw, bool clip)
        {
            // PreserveGraphicsClipping: без него текст рисуется поверх кружка «i», не замечая обрезки
            TextFormatFlags flags = TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPadding
                | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine | TextFormatFlags.PreserveGraphicsClipping;
            int cy = Height / 2;
            foreach (string part in parts)
            {
                if (part.Length == 0) continue;
                if (part.Length == 3 && part[0] == '{')
                {
                    if (draw && x > -16 && x < Width)
                    {
                        Color c = part[1] == 'o' ? Theme.GemOrange : (part[1] == 'g' ? Theme.GemGreen : (part[1] == 'v' ? Theme.GemViolet : Theme.GemBlue));
                        Theme.DrawGem(g, x + 7, cy, 6, c);
                    }
                    x += 15;
                    continue;
                }
                int w = TextRenderer.MeasureText(g, part, Font, new Size(int.MaxValue, Height), flags).Width;
                if (draw && x + w > 0 && x < Width)
                {
                    if (clip) TextRenderer.DrawText(g, part, Font, new Rectangle(x, 0, Width - x, Height), ForeColor, flags | TextFormatFlags.EndEllipsis);
                    else TextRenderer.DrawText(g, part, Font, new Rectangle(x, 0, w + 4, Height), ForeColor, flags);
                }
                x += w;
            }
            return x;
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.Clear(BackColor);
            string[] parts = System.Text.RegularExpressions.Regex.Split(Text, @"(\{[ogbv]\})");
            // кружок «i»: синий — подсказки включены, серый — выключены
            Rectangle ic = IconRect;
            SmoothingMode sm = g.SmoothingMode;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            Color fill = HintsOn ? Color.FromArgb(46, 125, 209) : Color.FromArgb(112, 118, 130);
            using (SolidBrush b = new SolidBrush(overIcon ? ControlPaint.Light(fill, 0.4f) : fill)) g.FillEllipse(b, ic);
            g.SmoothingMode = sm;
            using (Font bold = new Font(Font, FontStyle.Bold))
                TextRenderer.DrawText(g, "i", bold, new Rectangle(ic.X, ic.Y - 1, ic.Width + 1, ic.Height), Color.White,
                    TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPadding);
            // текст — правее кружка и под него не заезжает
            g.SetClip(new Rectangle(TextLeft - 2, 0, Math.Max(0, Width - TextLeft + 2), Height));
            if (!Looping) Line(g, parts, TextLeft, true, true);
            else if (HintsOn) // подсказки выключены — строка пустая, пока мышь не наведена на текстуру
            {
                TextFormatFlags plain = TextFormatFlags.NoPadding | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine;
                Size big = new Size(int.MaxValue, Height);
                int tail = TextRenderer.MeasureText(g, "." + Between + ".", Font, big, plain).Width - TextRenderer.MeasureText(g, "..", Font, big, plain).Width;
                int total = Line(g, parts, 0, false, false) + tail;
                int shift = (int)offset % total;
                Line(g, parts, TextLeft - shift, true, false);
                if (TextLeft - shift + total < Width) Line(g, parts, TextLeft - shift + total, true, false); // следом идёт начало — круг замкнут
            }
            g.ResetClip();
        }
    }

    // Зелёная плашка-указатель: прямоугольник с надписью и хвостиком, который тянется вниз —
    // к кружку «i» под витриной. Показывается пару секунд после запуска.
    class Callout : Control
    {
        const int Tail = 9; // высота хвостика под плашкой
        Font big;

        public Callout(Font baseFont, string text)
        {
            SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer, true);
            big = new Font(baseFont.FontFamily, baseFont.Size * 1.3f, FontStyle.Bold);
            Text = text;
            Size = new Size(TextRenderer.MeasureText(text, big).Width + 20, 28 + Tail);
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.Clear(Theme.Canvas);
            g.SmoothingMode = SmoothingMode.AntiAlias;
            Rectangle pill = new Rectangle(0, 0, Width - 1, Height - Tail - 1);
            using (SolidBrush green = new SolidBrush(Color.FromArgb(46, 160, 84)))
            {
                // простой прямоугольник без скруглений и короткий треугольный хвостик вниз, к кружку
                g.SmoothingMode = SmoothingMode.None;
                g.FillRectangle(green, pill.X, pill.Y, pill.Width + 1, pill.Height + 1);
                g.SmoothingMode = SmoothingMode.AntiAlias;
                g.FillPolygon(green, new Point[] { new Point(4, pill.Bottom), new Point(16, pill.Bottom), new Point(4, Height - 1) });
            }
            TextRenderer.DrawText(g, Text, big, pill, Color.White, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPadding);
        }

        protected override void Dispose(bool disposing)
        {
            if (disposing) big.Dispose();
            base.Dispose(disposing);
        }
    }

    // Маленький рисованный значок: лупа в начале строки поиска или крестик очистки, краснеющий под курсором.
    class Glyph : Control
    {
        public bool Cross;
        bool hot;

        public Glyph()
        {
            SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer, true);
        }

        protected override void OnMouseEnter(EventArgs e)
        {
            base.OnMouseEnter(e);
            hot = true;
            Invalidate();
        }

        protected override void OnMouseLeave(EventArgs e)
        {
            base.OnMouseLeave(e);
            hot = false;
            Invalidate();
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            int cx = Width / 2, cy = Height / 2;
            if (!Cross)
            {
                g.Clear(BackColor);
                using (Pen pen = new Pen(Theme.Dim, 1.6f))
                {
                    g.DrawEllipse(pen, cx - 6, cy - 6, 9, 9);
                    g.DrawLine(pen, cx + 2, cy + 2, cx + 6, cy + 6);
                }
                return;
            }
            g.Clear(hot ? (Theme.Dark ? Color.FromArgb(92, 44, 44) : Color.FromArgb(255, 226, 226)) : Theme.ToggleOff);
            using (Pen pen = new Pen(hot ? Color.FromArgb(226, 60, 60) : Theme.Dim, 1.8f))
            {
                g.DrawLine(pen, cx - 4, cy - 4, cx + 4, cy + 4);
                g.DrawLine(pen, cx + 4, cy - 4, cx - 4, cy + 4);
            }
            // рамка как у строки поиска, кроме левой стороны: значок выглядит её продолжением
            g.SmoothingMode = SmoothingMode.None;
            using (Pen pen = new Pen(Color.FromArgb(100, 100, 100)))
                g.DrawLines(pen, new Point[] { new Point(0, 0), new Point(Width - 1, 0), new Point(Width - 1, Height - 1), new Point(0, Height - 1) });
        }
    }

    // Избранное: текстуры, сохранённые в самой программе, в профиле пользователя. Папка устроена как обычный
    // пакет ресурсов, поэтому её можно показать в списке пакетов и использовать в сборке.
    static class Favorites
    {
        static Dictionary<string, List<string>> index; // текстура -> сохранённые для неё файлы (пути внутри папки)

        public static string Dir
        {
            get
            {
                string test = Environment.GetEnvironmentVariable("BPS_FAVDIR"); // при проверках избранное пишется в отдельную папку
                if (test != null) return test;
                return Path.Combine(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "BedrockPackStudio"), "favorites");
            }
        }

        static string IndexFile { get { return Path.Combine(Dir, "favorites.txt"); } }

        static void Load()
        {
            if (index != null) return;
            Dictionary<string, List<string>> read = new Dictionary<string, List<string>>();
            // список не прочитался (файл занят) — не считаем его пустым, иначе следующая запись стёрла бы всё сохранённое
            if (File.Exists(IndexFile))
            {
                string[] lines = File.ReadAllLines(IndexFile);
                // список старого вида отметок не содержит: там каждая текстура считается сохранённой нарочно
                bool marked = Array.IndexOf(lines, Version) >= 0;
                foreach (string line in lines)
                {
                    string[] parts = line.Split('|');
                    if (parts[0].Length == 0 || parts[0].StartsWith("#")) continue;
                    List<string> files = new List<string>();
                    for (int i = 1; i < parts.Length; i++) if (parts[i].StartsWith(From) || Inside(parts[i])) files.Add(parts[i]);
                    if (!marked && !files.Contains(Own)) files.Add(Own);
                    read[parts[0]] = files;
                }
            }
            index = read;
        }

        // Отметка «из какого пакета сохранено»: по ней звезда горит у того же варианта, а не у всех сразу.
        const string From = "@";

        public static string SourceOf(string key)
        {
            try { Load(); } catch (Exception) { return null; }
            List<string> files;
            if (!index.TryGetValue(key, out files)) return null;
            foreach (string x in files) if (x.StartsWith(From)) return x.Substring(1);
            return null;
        }

        const string Version = "#v2";
        // Отметка в списке файлов текстуры: её сохранили саму, а не только как основу для сохранённого слоя.
        const string Own = "!";

        public static bool TextureSaved(string key)
        {
            try { Load(); } catch (Exception) { return true; }
            List<string> files;
            return !index.TryGetValue(key, out files) || files.Contains(Own);
        }

        // Путь из списка должен оставаться внутри папки избранного.
        static bool Inside(string rel)
        {
            if (rel.Length == 0 || rel.IndexOf(":", StringComparison.Ordinal) >= 0 || rel.StartsWith("/") || rel.StartsWith("\\")) return false;
            foreach (string part in rel.Split('/', '\\')) if (part == "..") return false;
            return rel.IndexOfAny(Path.GetInvalidPathChars()) < 0;
        }

        static void Store()
        {
            Directory.CreateDirectory(Dir);
            List<string> lines = new List<string>();
            lines.Add(Version);
            foreach (KeyValuePair<string, List<string>> kv in index) lines.Add(kv.Key + "|" + string.Join("|", kv.Value.ToArray()));
            string tmp = IndexFile + ".tmp";
            File.WriteAllLines(tmp, lines.ToArray());
            File.Copy(tmp, IndexFile, true);
            try { File.Delete(tmp); } catch (Exception) { }
            string manifest = Path.Combine(Dir, "manifest.json");
            if (!File.Exists(manifest))
                File.WriteAllText(manifest, "{\"format_version\":2,\"header\":{\"name\":\"Favorites\",\"description\":\"BRPC\","
                    + "\"uuid\":\"7d2b6c7e-5a43-4b0e-9a54-3f6f2f6d1b01\",\"version\":[1,0,0],\"min_engine_version\":[1,16,0]},"
                    + "\"modules\":[{\"type\":\"resources\",\"uuid\":\"7d2b6c7e-5a43-4b0e-9a54-3f6f2f6d1b02\",\"version\":[1,0,0]}]}");
        }

        public static bool Has(string key)
        {
            try { Load(); } catch (Exception) { return false; }
            return index.ContainsKey(key);
        }

        public static int Count
        {
            get
            {
                try { Load(); } catch (Exception) { return 0; }
                return index.Count;
            }
        }

        static void Copy(string source, string rel, List<string> files)
        {
            string dest = Path.Combine(Dir, rel.Replace('/', Path.DirectorySeparatorChar));
            if (!string.Equals(Path.GetFullPath(source), Path.GetFullPath(dest), StringComparison.OrdinalIgnoreCase))
            {
                Directory.CreateDirectory(Path.GetDirectoryName(dest));
                if (File.Exists(dest)) File.SetAttributes(dest, FileAttributes.Normal); // «только чтение» мешало бы заменить
                File.Copy(source, dest, true);
                File.SetAttributes(dest, FileAttributes.Normal);
            }
            if (!files.Contains(rel)) files.Add(rel);
        }

        // Сохраняет вариант текстуры из пакета p: саму картинку (texture) и/или выбранные слои.
        public static void Add(Pack p, Entry e, bool texture, List<KeyValuePair<string, string>> layers)
        {
            var indexWas = index;
            index = null; // список могло изменить другое окно программы
            try { Load(); }
            catch (Exception) { index = indexWas; throw; }
            Directory.CreateDirectory(Dir);
            // список в памяти меняется только после того, как все файлы скопированы
            List<string> had, files;
            files = index.TryGetValue(e.Key, out had) ? new List<string>(had) : new List<string>();
            string rel = p.Files[e.Key];
            bool withLayers = layers != null && layers.Count > 0;
            // слой без своей текстуры игре не нужен и в витрине не виден, поэтому текстура сохраняется вместе с ним
            if (texture || (withLayers && !File.Exists(Path.Combine(Dir, rel.Replace('/', Path.DirectorySeparatorChar)))))
                Copy(p.FullPath(e.Key), rel, files);
            if (texture && !files.Contains(Own)) files.Add(Own);
            if (layers != null && layers.Count > 0)
            {
                // слоям нужно описание набора: создаётся или дополняется то, что уже лежит в избранном
                string root = p.Root.TrimEnd('\\', '/');
                string setRel = rel.Substring(0, rel.Length - Path.GetExtension(rel).Length) + ".texture_set.json";
                string setFile = Path.Combine(Dir, setRel.Replace('/', Path.DirectorySeparatorChar));
                JObj doc = null;
                try { if (File.Exists(setFile)) doc = Json.Parse(File.ReadAllText(setFile)) as JObj; } catch (Exception) { }
                if (doc == null)
                {
                    doc = new JObj();
                    doc.Set("format_version", "1.16.100");
                    doc.Set("minecraft:texture_set", new JObj());
                }
                JObj ts = doc.Get("minecraft:texture_set") as JObj;
                if (ts == null)
                {
                    ts = new JObj();
                    doc.Set("minecraft:texture_set", ts);
                }
                ts.Set("color", Path.GetFileNameWithoutExtension(rel));
                string setDir = setRel.Substring(0, setRel.LastIndexOf('/') + 1);
                foreach (KeyValuePair<string, string> l in layers)
                {
                    // слой может быть взят из другого пакета: тогда его место определяется по папке textures
                    string lfull = l.Value.Replace('\\', '/'), lroot = root.Replace('\\', '/') + "/";
                    string lrel;
                    if (lfull.StartsWith(lroot, StringComparison.OrdinalIgnoreCase)) lrel = lfull.Substring(lroot.Length);
                    else
                    {
                        int lcut = lfull.LastIndexOf("/textures/", StringComparison.OrdinalIgnoreCase);
                        if (lcut < 0) throw new InvalidOperationException(L.T("Слой лежит вне пакета, сохранить его нельзя."));
                        lrel = lfull.Substring(lcut + 1);
                    }
                    Copy(l.Value, lrel, files);
                    // рельеф и карта отражений в наборе могут быть только по одной
                    if (l.Key == "normal") ts.Remove("heightmap");
                    if (l.Key == "heightmap") ts.Remove("normal");
                    if (l.Key == "metalness_emissive_roughness") ts.Remove("metalness_emissive_roughness_subsurface");
                    if (l.Key == "metalness_emissive_roughness_subsurface")
                    {
                        ts.Remove("metalness_emissive_roughness");
                        doc.Set("format_version", "1.21.30");
                    }
                    // слой из другой папки записывается полным путём, иначе игра искала бы его рядом с набором
                    string lname = lrel.Substring(0, lrel.Length - Path.GetExtension(lrel).Length);
                    bool sameDir = string.Equals(lrel.Substring(0, lrel.LastIndexOf('/') + 1), setDir, StringComparison.OrdinalIgnoreCase);
                    ts.Set(l.Key, sameDir ? Path.GetFileName(lname) : lname);
                }
                Directory.CreateDirectory(Path.GetDirectoryName(setFile));
                File.WriteAllText(setFile, Json.Write(doc) + "\n", new UTF8Encoding(false));
                if (!files.Contains(setRel)) files.Add(setRel);
            }
            if (!string.Equals(Path.GetFullPath(p.Root).TrimEnd('\\', '/'), Path.GetFullPath(Dir).TrimEnd('\\', '/'), StringComparison.OrdinalIgnoreCase))
            {
                files.RemoveAll(delegate(string x) { return x.StartsWith(From); });
                files.Add(From + p.Name.Replace('|', ' ').Replace('\r', ' ').Replace('\n', ' '));
            }
            index[e.Key] = files;
            Store();
        }

        // ---- свои папки: это только раскладка для показа, сами файлы лежат как в обычном пакете
        static List<string> folders;               // названия папок по порядку создания
        static Dictionary<string, string> folderOf; // текстура -> папка

        static string FoldersFile { get { return Path.Combine(Dir, "folders.txt"); } }

        static void LoadFolders()
        {
            if (folders != null) return;
            folders = new List<string>();
            folderOf = new Dictionary<string, string>();
            try
            {
                if (!File.Exists(FoldersFile)) return;
                foreach (string line in File.ReadAllLines(FoldersFile))
                {
                    string[] p = line.Split('\t');
                    if (p.Length == 2 && p[0] == "F" && p[1].Length > 0 && !folders.Contains(p[1])) folders.Add(p[1]);
                    if (p.Length == 3 && p[0] == "K" && folders.Contains(p[2])) folderOf[p[1]] = p[2];
                }
            }
            catch (Exception) { }
        }

        static void StoreFolders()
        {
            Directory.CreateDirectory(Dir);
            List<string> lines = new List<string>();
            foreach (string f in folders) lines.Add("F\t" + f);
            foreach (KeyValuePair<string, string> kv in folderOf) lines.Add("K\t" + kv.Key + "\t" + kv.Value);
            File.WriteAllLines(FoldersFile, lines.ToArray());
        }

        public static List<string> Folders { get { LoadFolders(); return new List<string>(folders); } }

        public static string FolderOf(string key)
        {
            LoadFolders();
            string f;
            return folderOf.TryGetValue(key, out f) ? f : null;
        }

        // Название приводится к виду, который можно хранить: без табуляций и переводов строк. Пустое или занятое — null.
        public static string AddFolder(string name)
        {
            LoadFolders();
            name = (name ?? "").Replace('\t', ' ').Replace('\r', ' ').Replace('\n', ' ').Trim();
            if (name.Length == 0 || folders.Contains(name)) return null;
            folders.Add(name);
            StoreFolders();
            return name;
        }

        // Папка убирается, её текстуры остаются в избранном без папки.
        public static void RemoveFolder(string name)
        {
            LoadFolders();
            if (!folders.Remove(name)) return;
            foreach (string k in new List<string>(folderOf.Keys)) if (folderOf[k] == name) folderOf.Remove(k);
            StoreFolders();
        }

        // folder == null — вынуть текстуру из папки.
        public static void SetFolder(string key, string folder)
        {
            LoadFolders();
            if (folder == null) { if (!folderOf.Remove(key)) return; }
            else
            {
                if (!folders.Contains(folder) || FolderOf(key) == folder) return;
                folderOf[key] = folder;
            }
            StoreFolders();
        }

        public static void Remove(string key)
        {
            try { SetFolder(key, null); } catch (Exception) { }
            var indexWas = index;
            index = null; // список могло изменить другое окно программы
            try { Load(); }
            catch (Exception) { index = indexWas; throw; }
            List<string> files;
            if (!index.TryGetValue(key, out files)) return;
            index.Remove(key);
            // сначала список, потом файлы: иначе при неудачной записи текстура осталась бы в списке без файлов
            try { Store(); }
            catch (Exception) { index[key] = files; throw; }
            foreach (string rel in files)
            {
                if (rel == Own || rel.StartsWith(From)) continue; // отметки, а не файлы
                bool shared = false; // файл может быть нужен другой избранной текстуре
                foreach (List<string> other in index.Values) if (other.Contains(rel)) shared = true;
                if (shared) continue;
                try
                {
                    string file = Path.Combine(Dir, rel.Replace('/', Path.DirectorySeparatorChar));
                    if (!File.Exists(file)) continue;
                    File.SetAttributes(file, FileAttributes.Normal);
                    File.Delete(file);
                }
                catch (Exception) { }
            }
        }
    }

    // Названия блоков, предметов и мобов из самой игры (Bedrock) — чтобы текстуру можно было найти
    // по имени объекта, которому она принадлежит: «алмазная руда», «diamond ore».
    static class GameNames
    {
        static Dictionary<string, string[]> names;   // идентификатор объекта -> { английское название, русское }
        static Dictionary<string, List<string>> ids; // текстура -> идентификаторы объектов, которые её используют
        static Dictionary<string, string[]> cache = new Dictionary<string, string[]>(); // текстура -> { все названия, en, ru }
        // окончания имён текстур, обозначающие сторону или состояние одного и того же объекта
        static readonly string[] Suffixes = { "_top", "_bottom", "_side", "_front", "_back", "_on", "_off", "_lit", "_inner", "_outer",
            "_upper", "_lower", "_end", "_carried", "_snowed", "_overlay", "_base", "_head", "_stalk", "_open", "_closed", "_empty", "_full" };

        static void Note(string tex, string id)
        {
            tex = tex.ToLowerInvariant();
            List<string> l;
            if (!ids.TryGetValue(tex, out l)) ids[tex] = l = new List<string>();
            id = id.ToLowerInvariant();
            if (!l.Contains(id)) l.Add(id);
        }

        static void ReadLang(string file, int column)
        {
            if (!File.Exists(file)) return;
            foreach (string line in File.ReadAllLines(file))
            {
                int eq = line.IndexOf('=');
                if (eq < 6 || !line.Substring(0, eq).EndsWith(".name")) continue;
                string key = line.Substring(0, eq);
                if (!(key.StartsWith("tile.") || key.StartsWith("item.") || key.StartsWith("entity."))) continue;
                // tile.planks.oak.name -> planks_oak: так же обычно называется и файл текстуры
                int dot = key.IndexOf('.');
                string id = key.Substring(dot + 1, key.Length - dot - 6).Replace('.', '_').ToLowerInvariant();
                string value = line.Substring(eq + 1);
                int cut = value.IndexOf('\t');
                if (cut >= 0) value = value.Substring(0, cut);
                cut = value.IndexOf("#");
                if (cut >= 0) value = value.Substring(0, cut);
                value = value.Trim();
                if (value.Length == 0) continue;
                string[] n;
                if (!names.TryGetValue(id, out n)) names[id] = n = new string[2];
                if (n[column] == null) n[column] = value;
            }
        }

        static void Strings(object o, List<string> into)
        {
            JObj j = o as JObj;
            List<object> l = o as List<object>;
            if (o is string) into.Add((string)o);
            else if (j != null) foreach (string k in j.Keys) Strings(j.Map[k], into);
            else if (l != null) foreach (object x in l) Strings(x, into);
        }

        // Список текстур игры: короткое имя -> файлы. owners — какие объекты пользуются этим коротким именем.
        static void ReadIndex(string json, Dictionary<string, List<string>> owners)
        {
            JObj root = Json.Parse(json) as JObj;
            JObj data = root == null ? null : root.Get("texture_data") as JObj;
            if (data == null) return;
            foreach (string shortName in data.Keys)
            {
                List<string> paths = new List<string>();
                Strings(data.Map[shortName], paths);
                foreach (string p in paths)
                {
                    if (!p.ToLowerInvariant().StartsWith("textures/")) continue;
                    Note(p, shortName);
                    List<string> who;
                    if (owners != null && owners.TryGetValue(shortName, out who)) foreach (string id in who) Note(p, id);
                }
            }
        }

        static void Load()
        {
            if (names != null) return;
            names = new Dictionary<string, string[]>();
            ids = new Dictionary<string, List<string>>();
            Geo.Ensure();
            string dir = Geo.GameDir == null ? null : Path.Combine(Geo.GameDir, "vanilla");
            if (dir == null || !Directory.Exists(dir)) return; // игры нет — поиск работает только по именам файлов
            try
            {
                ReadLang(Path.Combine(dir, @"texts\en_US.lang"), 0);
                ReadLang(Path.Combine(dir, @"texts\ru_RU.lang"), 1);
            }
            catch (Exception) { }
            try
            {
                // блоки: blocks.json называет короткие имена текстур блока, terrain_texture.json — в каких они файлах
                Dictionary<string, List<string>> owners = new Dictionary<string, List<string>>();
                JObj blocks = Json.Parse(File.ReadAllText(Path.Combine(dir, "blocks.json"))) as JObj;
                if (blocks != null)
                    foreach (string block in blocks.Keys)
                    {
                        JObj b = blocks.Map[block] as JObj;
                        if (b == null) continue;
                        List<string> shorts = new List<string>();
                        Strings(b.Get("textures"), shorts);
                        Strings(b.Get("carried_textures"), shorts);
                        foreach (string sn in shorts)
                        {
                            List<string> who;
                            if (!owners.TryGetValue(sn, out who)) owners[sn] = who = new List<string>();
                            who.Add(block);
                        }
                    }
                ReadIndex(File.ReadAllText(Path.Combine(dir, @"textures\terrain_texture.json")), owners);
            }
            catch (Exception) { }
            try
            {
                string loose = Path.Combine(dir, @"textures\item_texture.json");
                string items = File.Exists(loose) ? File.ReadAllText(loose)
                    : Geo.ArchiveText(Path.Combine(dir, @"__brarchive\textures.brarchive"), "item_texture.json");
                if (items != null) ReadIndex(items, null);
            }
            catch (Exception) { }
            // мобы: какая текстура у какой сущности, известно из описаний, уже прочитанных для 3D-моделей
            foreach (KeyValuePair<string, string> kv in Geo.EntityIds()) Note(kv.Key, kv.Value);
        }

        static string Trim(string name)
        {
            int us = name.LastIndexOf('_');
            int n;
            if (us > 0 && int.TryParse(name.Substring(us + 1), out n)) return name.Substring(0, us); // fire_0, wheat_stage_3
            foreach (string suffix in Suffixes) if (name.EndsWith(suffix) && name.Length > suffix.Length) return name.Substring(0, name.Length - suffix.Length);
            return name;
        }

        static string[] Info(string texKey)
        {
            string[] r;
            if (cache.TryGetValue(texKey, out r)) return r;
            Load();
            List<string> cand = new List<string>();
            List<string> known;
            if (ids.TryGetValue(texKey, out known)) cand.AddRange(known);
            cand.Add(texKey.Substring(texKey.LastIndexOf('/') + 1));
            if (texKey.StartsWith("textures/entity/"))
            {
                string rest = texKey.Substring(16);
                if (rest.IndexOf('/') > 0) cand.Add(rest.Substring(0, rest.IndexOf('/'))); // папка моба: entity/zombie/…
            }
            for (int i = 0; i < cand.Count && cand.Count < 60; i++)
            {
                string c = cand[i], t = Trim(c);
                if (t != c && !cand.Contains(t)) cand.Add(t);
                string[] parts = c.Split('_');
                if (parts.Length == 2 && !cand.Contains(parts[1] + "_" + parts[0])) cand.Add(parts[1] + "_" + parts[0]); // apple_golden -> golden_apple
            }
            string en = null, ru = null;
            StringBuilder all = new StringBuilder();
            foreach (string c in cand)
            {
                string[] n;
                if (!names.TryGetValue(c, out n)) continue;
                foreach (string v in n) if (v != null) all.Append(v.ToLowerInvariant()).Append('\n');
                if (en == null) en = n[0];
                if (ru == null) ru = n[1];
            }
            r = new string[] { all.ToString(), en, ru };
            cache[texKey] = r;
            return r;
        }

        // Есть ли строка поиска (в нижнем регистре) в названиях объекта на любом из двух языков.
        public static bool Matches(string texKey, string find)
        {
            return Info(texKey)[0].Contains(find);
        }
    }

    // ------------------------------------------------------------------ Редактор текстуры

    enum EditTool { Pencil, Eraser, Fill, Replace, Picker, Move, Select, BrushSelect, Line, Rect, Ellipse, Wand, Shade }

    // Холст редактора: рабочее поле крупно, по пикселям, на клетчатом фоне. Поле больше самой текстуры: посередине рамка
    // размером с файл, вокруг запас, куда текстуру можно сдвинуть и откуда вернуть. В файл идёт только то, что в рамке;
    // всё остальное притемнено.
    class EditCanvas : Control
    {
        public int[] Px;
        public int W, H;
        public Rectangle Frame;
        public byte[] Sel;        // выделение: по байту на пиксель поля; null — выделения нет
        public Rectangle Rubber;  // прямоугольник, который сейчас растягивают инструментом выделения
        public Bitmap Layer;      // картинка, которую вставляют (режим размещения), и её место на поле
        public Rectangle LayerAt;
        public bool DropCue;      // над окном держат перетаскиваемую текстуру: рамка подсвечена
        public int Phase;         // «бегущие муравьи» по краю выделения
        public bool Grid = true;  // сетка пикселей (видна при масштабе от 6)
        public bool SpaceHeld;    // зажат пробел: левая кнопка не рисует, а двигает вид
        public bool MirX, MirY;   // симметрия: зеркально слева направо и сверху вниз — показываются оси
        public bool Wrap;         // «Бесшовно»: за рамкой показан её повтор
        public Rectangle Onion;   // «луковая кожура»: соседний кадр ленты, полупрозрачно поверх текущего; пусто — выключена
        Bitmap view;
        int zoom = 8;
        bool down, rightDown, panning;
        Point panFrom, panScroll;
        public event Action<Point, MouseButtons, bool> Stroke; // пиксель, кнопка мыши, начало ли это мазка
        public event Action StrokeEnd;
        public event Action<Point> Menu;                       // правый щелчок по пикселю
        public event Action<int> ZoomWheel;
        public event Action<Point, bool> Hover;                // пиксель под курсором; false — курсор ушёл с холста
        public event Action Panned;                            // вид отпустили — курсору пора стать прежним

        public EditCanvas()
        {
            SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.Selectable, true);
            Cursor = Cursors.Cross;
        }

        public int Zoom
        {
            get { return zoom; }
            set
            {
                zoom = Math.Max(1, Math.Min(64, value));
                while (zoom > 1 && Math.Max(W, H) * zoom > 12000) zoom--;
                Size = new Size(W * zoom, H * zoom);
                Invalidate();
            }
        }

        public int Version; // растёт при каждой правке: по нему редактор узнаёт, что палитру пора собрать заново
        public bool Down { get { return down; } } // идёт протяжка левой кнопкой

        // Показать изменённые пиксели.
        public void Changed()
        {
            Version++;
            if (view == null || view.Width != W || view.Height != H)
            {
                if (view != null) view.Dispose();
                view = new Bitmap(W, H, PixelFormat.Format32bppArgb);
            }
            Img.SetPixels(view, Px);
            Invalidate();
        }

        Point ToPixel(Point p)
        {
            return new Point((int)Math.Floor(p.X / (double)zoom), (int)Math.Floor(p.Y / (double)zoom));
        }

        protected override void OnMouseDown(MouseEventArgs e)
        {
            base.OnMouseDown(e);
            Focus();
            if (e.Button == MouseButtons.Middle || (e.Button == MouseButtons.Left && SpaceHeld))
            {
                // средняя кнопка или пробел с левой — вид едет за рукой, как в графических программах
                ScrollableControl sp = Parent as ScrollableControl;
                if (sp == null) return;
                panning = true;
                panFrom = Cursor.Position;
                panScroll = new Point(-sp.AutoScrollPosition.X, -sp.AutoScrollPosition.Y);
                Cursor = Cursors.Hand;
                return;
            }
            if (e.Button == MouseButtons.Right) { rightDown = true; return; } // правая кнопка — меню, оно открывается при отпускании
            down = true;
            if (Stroke != null) Stroke(ToPixel(e.Location), e.Button, true);
        }

        protected override void OnMouseMove(MouseEventArgs e)
        {
            base.OnMouseMove(e);
            if (panning)
            {
                // по экранным точкам: сам холст при прокрутке сдвигается под курсором
                ScrollableControl sp = Parent as ScrollableControl;
                if (sp != null) sp.AutoScrollPosition = new Point(panScroll.X - (Cursor.Position.X - panFrom.X), panScroll.Y - (Cursor.Position.Y - panFrom.Y));
                return;
            }
            if (Hover != null) Hover(ToPixel(e.Location), true);
            if (down && Stroke != null) Stroke(ToPixel(e.Location), e.Button, false);
        }

        protected override void OnMouseLeave(EventArgs e)
        {
            base.OnMouseLeave(e);
            if (Hover != null) Hover(Point.Empty, false);
        }

        protected override void OnMouseUp(MouseEventArgs e)
        {
            base.OnMouseUp(e);
            if (panning)
            {
                if (e.Button != MouseButtons.Middle && e.Button != MouseButtons.Left) return;
                panning = false;
                if (Panned != null) Panned();
                return;
            }
            if (e.Button == MouseButtons.Right)
            {
                if (rightDown && !down && Menu != null && ClientRectangle.Contains(e.Location)) Menu(ToPixel(e.Location));
                rightDown = false;
                return;
            }
            if (down && StrokeEnd != null) StrokeEnd();
            down = false;
        }

        protected override void OnMouseWheel(MouseEventArgs e)
        {
            if ((ModifierKeys & Keys.Control) != 0 && ZoomWheel != null)
            {
                ZoomWheel(e.Delta > 0 ? 1 : -1);
                HandledMouseEventArgs h = e as HandledMouseEventArgs;
                if (h != null) h.Handled = true;
                return;
            }
            base.OnMouseWheel(e);
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            if (view == null) return;
            Graphics g = e.Graphics;
            Rectangle c = e.ClipRectangle;
            int x0 = Math.Max(0, c.Left / zoom), y0 = Math.Max(0, c.Top / zoom);
            int x1 = Math.Min(W, c.Right / zoom + 1), y1 = Math.Min(H, c.Bottom / zoom + 1);
            if (x1 <= x0 || y1 <= y0) return;
            Rectangle dest = new Rectangle(x0 * zoom, y0 * zoom, (x1 - x0) * zoom, (y1 - y0) * zoom);
            using (HatchBrush hb = new HatchBrush(HatchStyle.LargeCheckerBoard, Color.FromArgb(205, 205, 205), Color.White))
                g.FillRectangle(hb, dest);
            g.InterpolationMode = InterpolationMode.NearestNeighbor;
            g.PixelOffsetMode = PixelOffsetMode.Half;
            g.DrawImage(view, dest, new Rectangle(x0, y0, x1 - x0, y1 - y0), GraphicsUnit.Pixel);
            Rectangle fr = new Rectangle(Frame.X * zoom, Frame.Y * zoom, Frame.Width * zoom, Frame.Height * zoom);
            if (Wrap)
            {
                // «Бесшовно»: за рамкой — повтор самой рамки, как текстура лежит в игре рядом с собой; швы видны сразу.
                // Настоящие пиксели поля за рамкой не трогаются и вернутся, когда режим выключат.
                GraphicsState tiles = g.Save();
                using (Region outside = new Region(dest))
                {
                    outside.Exclude(fr);
                    g.SetClip(outside, CombineMode.Intersect);
                }
                using (HatchBrush hb = new HatchBrush(HatchStyle.LargeCheckerBoard, Color.FromArgb(205, 205, 205), Color.White)) g.FillRectangle(hb, dest);
                for (int ty = -1; ty <= 1; ty++)
                    for (int tx = -1; tx <= 1; tx++)
                        if (tx != 0 || ty != 0)
                            g.DrawImage(view, new Rectangle(fr.X + tx * fr.Width, fr.Y + ty * fr.Height, fr.Width, fr.Height), Frame, GraphicsUnit.Pixel);
                g.Restore(tiles);
            }
            if (!Onion.IsEmpty)
            {
                // поверх текущего кадра — соседний, бледно: кадры игры почти всегда непрозрачны, и под ними его не было бы видно;
                // текущий кадр остаётся главным, в файл это не идёт
                GraphicsState skin = g.Save();
                g.SetClip(fr, CombineMode.Intersect);
                using (ImageAttributes pale = new ImageAttributes())
                {
                    ColorMatrix fade = new ColorMatrix();
                    fade.Matrix33 = 0.3f;
                    pale.SetColorMatrix(fade);
                    g.DrawImage(view, fr, Onion.X, Onion.Y, Onion.Width, Onion.Height, GraphicsUnit.Pixel, pale);
                }
                g.Restore(skin);
            }
            if (Layer != null)
            {
                // Вставляемая картинка: вне рамки полупрозрачна, в рамке видна так, как ляжет в файл (прежнее содержимое рамки она заменит).
                Rectangle lr = new Rectangle(LayerAt.X * zoom, LayerAt.Y * zoom, LayerAt.Width * zoom, LayerAt.Height * zoom);
                using (ImageAttributes half = new ImageAttributes())
                {
                    ColorMatrix fade = new ColorMatrix();
                    fade.Matrix33 = 0.45f;
                    half.SetColorMatrix(fade);
                    g.DrawImage(Layer, lr, 0, 0, Layer.Width, Layer.Height, GraphicsUnit.Pixel, half);
                }
                GraphicsState whole = g.Save();
                g.SetClip(fr, CombineMode.Intersect);
                using (HatchBrush hb = new HatchBrush(HatchStyle.LargeCheckerBoard, Color.FromArgb(205, 205, 205), Color.White)) g.FillRectangle(hb, fr);
                g.DrawImage(Layer, lr, 0, 0, Layer.Width, Layer.Height, GraphicsUnit.Pixel);
                g.Restore(whole);
            }
            g.PixelOffsetMode = PixelOffsetMode.Default;
            // то, что за рамкой, в файл не попадёт: оно притемнено
            using (Region outside = new Region(dest))
            using (SolidBrush dim = new SolidBrush(Theme.Dark ? Color.FromArgb(150, Theme.Canvas) : Color.FromArgb(120, 96, 98, 106)))
            {
                outside.Exclude(fr);
                g.FillRegion(dim, outside);
            }
            // линия сетки — тёмная и рядом светлая, обе полупрозрачные: одна из них видна на любом цвете пикселя
            if (Grid && zoom >= 6)
                using (Pen dark = new Pen(Color.FromArgb(90, 0, 0, 0)))
                using (Pen light = new Pen(Color.FromArgb(45, 255, 255, 255)))
                {
                    for (int x = x0; x <= x1; x++)
                    {
                        g.DrawLine(dark, x * zoom, dest.Top, x * zoom, dest.Bottom);
                        g.DrawLine(light, x * zoom + 1, dest.Top, x * zoom + 1, dest.Bottom);
                    }
                    for (int y = y0; y <= y1; y++)
                    {
                        g.DrawLine(dark, dest.Left, y * zoom, dest.Right, y * zoom);
                        g.DrawLine(light, dest.Left, y * zoom + 1, dest.Right, y * zoom + 1);
                    }
                }
            using (Pen edge = new Pen(Theme.Accent, 2)) g.DrawRectangle(edge, fr.X - 1, fr.Y - 1, fr.Width + 1, fr.Height + 1);
            if (MirX || MirY)
                using (Pen under = new Pen(Color.FromArgb(150, 255, 255, 255)))
                using (Pen axis = new Pen(Theme.Accent))
                {
                    // ось симметрии — середина рамки (у нечётной ширины она идёт по середине среднего пикселя)
                    axis.DashPattern = new float[] { 4, 3 };
                    float ax = (Frame.X + Frame.Width / 2f) * zoom, ay = (Frame.Y + Frame.Height / 2f) * zoom;
                    if (MirX) { g.DrawLine(under, ax, c.Top, ax, c.Bottom); g.DrawLine(axis, ax, c.Top, ax, c.Bottom); }
                    if (MirY) { g.DrawLine(under, c.Left, ay, c.Right, ay); g.DrawLine(axis, c.Left, ay, c.Right, ay); }
                }
            if (DropCue)
            {
                using (SolidBrush tint = new SolidBrush(Color.FromArgb(70, Theme.Accent))) g.FillRectangle(tint, fr);
                using (Pen edge = new Pen(Theme.Accent, 6)) g.DrawRectangle(edge, fr.X - 3, fr.Y - 3, fr.Width + 5, fr.Height + 5);
            }
            if (Sel != null) PaintAnts(g, dest);
            using (Pen black = new Pen(Color.Black))
            using (Pen white = new Pen(Color.White))
            {
                white.DashPattern = new float[] { 3, 3 };
                white.DashOffset = Phase % 6;
                if (!Rubber.IsEmpty)
                {
                    Rectangle rr = new Rectangle(Rubber.X * zoom, Rubber.Y * zoom, Rubber.Width * zoom, Rubber.Height * zoom);
                    g.DrawRectangle(black, rr);
                    g.DrawRectangle(white, rr);
                }
            }
        }

        // Край выделения двухцветный и движется («бегущие муравьи»): его видно на любой текстуре и в любой теме.
        // Рисуется точками в отдельную картинку размером с видимую часть, а не линиями: у выделения волшебной
        // палочкой на шумной текстуре краёв сотни тысяч, и линии рисовались бы секундами.
        void PaintAnts(Graphics g, Rectangle dest)
        {
            Rectangle vis = dest;
            if (Parent != null) vis.Intersect(RectangleToClient(Parent.RectangleToScreen(Parent.ClientRectangle)));
            if (vis.Width <= 0 || vis.Height <= 0) return;
            int[] ov = new int[vis.Width * vis.Height];
            int cx0 = vis.Left / zoom, cy0 = vis.Top / zoom, cx1 = Math.Min(W, (vis.Right - 1) / zoom + 1), cy1 = Math.Min(H, (vis.Bottom - 1) / zoom + 1);
            int black = unchecked((int)0xFF000000), white = -1;
            for (int y = cy0; y < cy1; y++)
                for (int x = cx0; x < cx1; x++)
                {
                    int i = y * W + x;
                    if (Sel[i] == 0) continue;
                    bool top = y == 0 || Sel[i - W] == 0, bottom = y == H - 1 || Sel[i + W] == 0;
                    bool left = x == 0 || Sel[i - 1] == 0, right = x == W - 1 || Sel[i + 1] == 0;
                    if (!top && !bottom && !left && !right) continue;
                    int sx = x * zoom, sy = y * zoom;
                    for (int k = 0; k < zoom; k++)
                    {
                        // край рисуется по клетке выделенного пикселя: соседние области не накладываются
                        if (top) Dot(ov, vis, sx + k, sy, black, white);
                        if (bottom) Dot(ov, vis, sx + k, sy + zoom - 1, black, white);
                        if (left) Dot(ov, vis, sx, sy + k, black, white);
                        if (right) Dot(ov, vis, sx + zoom - 1, sy + k, black, white);
                    }
                }
            using (Bitmap b = Img.FromPixels(vis.Width, vis.Height, ov)) g.DrawImageUnscaled(b, vis.X, vis.Y);
        }

        // для проверки скорости: нарисовать видимую часть холста в чужую картинку
        public void TestPaint(Graphics g)
        {
            Rectangle vis = ClientRectangle;
            if (Parent != null) vis.Intersect(RectangleToClient(Parent.RectangleToScreen(Parent.ClientRectangle)));
            g.TranslateTransform(-vis.X, -vis.Y);
            OnPaint(new PaintEventArgs(g, vis));
        }

        void Dot(int[] ov, Rectangle vis, int x, int y, int black, int white)
        {
            if (x < vis.Left || y < vis.Top || x >= vis.Right || y >= vis.Bottom) return;
            ov[(y - vis.Y) * vis.Width + x - vis.X] = (((x + y + Phase) / 3) & 1) == 0 ? black : white;
        }
    }

    // Пипетка за пределами программы: экран «замораживается» снимком, щелчок по любой точке берёт её цвет.
    class ScreenPicker : Form
    {
        Bitmap shot;
        Point cur;
        public Color Picked;

        public ScreenPicker()
        {
            Rectangle vs = SystemInformation.VirtualScreen;
            shot = new Bitmap(vs.Width, vs.Height, PixelFormat.Format32bppArgb);
            using (Graphics g = Graphics.FromImage(shot)) g.CopyFromScreen(vs.Location, Point.Empty, vs.Size);
            FormBorderStyle = FormBorderStyle.None;
            StartPosition = FormStartPosition.Manual;
            Bounds = vs;
            TopMost = true;
            ShowInTaskbar = false;
            Cursor = Cursors.Cross;
            DoubleBuffered = true;
            KeyPreview = true;
            cur = PointToClient(Cursor.Position);
        }

        Color At(Point p)
        {
            return shot.GetPixel(Math.Max(0, Math.Min(shot.Width - 1, p.X)), Math.Max(0, Math.Min(shot.Height - 1, p.Y)));
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.DrawImageUnscaled(shot, 0, 0);
            // лупа рядом с курсором: 11×11 пикселей крупно и цвет под перекрестием
            int cell = 9, n = 11, size = cell * n, x = cur.X + 24, y = cur.Y + 24;
            if (x + size + 4 > Width) x = cur.X - 24 - size;
            if (y + size + 44 > Height) y = cur.Y - 24 - size - 40;
            g.InterpolationMode = InterpolationMode.NearestNeighbor;
            g.PixelOffsetMode = PixelOffsetMode.Half;
            g.FillRectangle(Brushes.Black, x - 2, y - 2, size + 4, size + 44);
            g.DrawImage(shot, new Rectangle(x, y, size, size), new Rectangle(cur.X - n / 2, cur.Y - n / 2, n, n), GraphicsUnit.Pixel);
            g.PixelOffsetMode = PixelOffsetMode.Default;
            g.DrawRectangle(Pens.White, x + (n / 2) * cell, y + (n / 2) * cell, cell - 1, cell - 1);
            Color c = At(cur);
            using (SolidBrush b = new SolidBrush(c)) g.FillRectangle(b, x, y + size + 2, 36, 36);
            TextRenderer.DrawText(g, "#" + c.R.ToString("X2") + c.G.ToString("X2") + c.B.ToString("X2"), Font,
                new Point(x + 40, y + size + 4), Color.White, Color.Black);
            TextRenderer.DrawText(g, L.T("Щелчок — взять, Esc — отмена"), Font, new Point(x + 40, y + size + 21), Color.Silver, Color.Black);
        }

        protected override void OnMouseMove(MouseEventArgs e)
        {
            base.OnMouseMove(e);
            cur = e.Location;
            Invalidate();
        }

        protected override void OnMouseDown(MouseEventArgs e)
        {
            base.OnMouseDown(e);
            if (e.Button == MouseButtons.Left) { Picked = At(e.Location); DialogResult = DialogResult.OK; }
            else DialogResult = DialogResult.Cancel;
        }

        protected override void OnKeyDown(KeyEventArgs e)
        {
            base.OnKeyDown(e);
            if (e.KeyCode == Keys.Escape) DialogResult = DialogResult.Cancel;
        }

        protected override void Dispose(bool disposing)
        {
            if (disposing && shot != null) shot.Dispose();
            base.Dispose(disposing);
        }
    }

    // Картинка в рядах редактора: вариант текстуры из другого пакета, сторона объекта или слой.
    class EditItem
    {
        public string Title; // подпись под значком
        public string From;  // название пакета — для превью
        public string Key;   // текстура, к которой картинка относится (Entry.Key), и её пакет
        public Pack P;
        public string File;
        public string Layer; // ключ слоя; null — сама текстура
        public int Ticks;    // лента кадров, которую превью проигрывает: сколько тактов игры держится кадр; 0 — не проигрывать
    }

    // Что редактор показывает вокруг холста. Собирает главное окно. Записей сборки (Entry) здесь нет: после любого
    // пересчёта сборки они другие, поэтому описание строится заново по ключу текстуры и пакету.
    class EditTarget
    {
        public string Title;    // для заголовка окна
        public string ObjTitle; // название 3D-объекта; null — объёмного вида у текстуры нет
        public List<EditItem> Variants = new List<EditItem>(), Sides = new List<EditItem>(), Layers = new List<EditItem>();
    }

    // Что редактор просит у главного окна; о пакетах, сборке и витринах он сам ничего не знает.
    class EditHost
    {
        // ключ текстуры, пакет, файл -> ряды картинок; null — такой текстуры в сборке нет. Заодно выбирает объект для 3D-вида.
        public Func<string, Pack, string, EditTarget> Resolve;
        public Func<EditItem, bool> IsFav;
        public Action<EditItem> Fav;
        public Func<int, Bitmap> Render;             // 3D-вид объекта такого размера
        public Action TurnStart;
        public Action<int, int> Turn;
        public Func<bool> Step;                      // такт анимации: пора ли рисовать объект заново
        public Action<string, int[], int, int> Live; // несохранённые пиксели файла — чтобы 3D-вид показывал правку сразу
    }

    // Панель с прокруткой, которая не прыгает к началу, когда её содержимое получает фокус: холст редактора больше окна,
    // и щелчок по нему не должен уводить вид.
    class StillPanel : Panel
    {
        protected override Point ScrollToControl(Control activeControl) { return DisplayRectangle.Location; }
    }

    // Элемент окна, который рисует его хозяин: без мерцания, с перерисовкой при смене размера.
    class PaintBox : Control
    {
        public PaintBox()
        {
            SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
        }
    }

