        // Одна из трёх кнопок над левым нижним списком; нажатая повторно — отжимается, и список прячется.
        void PickLeft(RadioButton which)
        {
            bool was = which.Checked;
            catsOff = was;
            foreach (RadioButton rb in new RadioButton[] { modeCats, modePreview, modeFiles })
                if (rb != which || was) rb.Checked = false;
            if (!was) which.Checked = true;
            bool pane = modePreview.Checked;
            tree.Visible = modeCats.Checked;
            previewPane.Visible = pane;
            gallery.DockPreview = pane;
            objView.DockPreview = pane;
            if (!pane) { previewPinned = false; previewPane.Pinned = false; }
