            objView.Invalidate();
            if (rebalance != null) rebalance(this, EventArgs.Empty);
        }

        // Панель превью слева внизу: Shift + колесо ведёт выделение по текстурам, и панель показывает каждую из них;
        // на той, где остановились, превью остаётся закреплённым. Без нажатой кнопки «Превью» ничего не делает.
        void DockFollowNav()
        {
            Entry e;
            Pack p;
            if (!modePreview.Checked || mode3D || !gallery.NavTarget(out e, out p)) return;
            previewPinned = true;
            previewPane.Pinned = true;
            ShowDocked(e, p, null, true);
