        static bool Opt(string key, bool byDefault)
        {
            if (Environment.GetEnvironmentVariable("BPS_DEFAULTS") != null) return byDefault; // для проверочных снимков: настройки как у новой установки
            string v = Settings.Get(key);
            return v == null ? byDefault : v == "1";
        }

        // Кнопки темы и языка можно убрать из верхнего ряда (настройки); кнопка 2D/3D встаёт вплотную к тому, что осталось.
        void PlaceTopButtons()
        {
            Control name = nameBox.Parent;
            if (name == null) return;
            int x = name.Left - Gap;
            lang.Visible = Opt("showLang", true);
            if (lang.Visible) { lang.Left = x - lang.Width; x = lang.Left - Gap; }
            themeBtn.Visible = Opt("showTheme", true);
            if (themeBtn.Visible) { themeBtn.Left = x - themeBtn.Width; x = themeBtn.Left - Gap; }
            modeBtn.Left = x - modeBtn.Width;
            int pl = favBtn.Right + Gap * 2, pr = modeBtn.Left - Gap * 2;
            projLabel.SetBounds(pl, 0, Math.Max(0, pr - pl), Row);
        }

        // Список настроек, всплывающий у шестерёнки.
        int settingsClosed; // когда список настроек закрылся: щелчок по шестерёнке, закрывший его, не открывает его снова

        void ShowSettings(Control anchor)
        {
            // Открытый список закрывается любым щелчком мимо него, в том числе по самой шестерёнке. Без этой проверки
            // тот же щелчок тут же открыл бы его заново, и казалось бы, что шестерёнка его не закрывает.
            if (!shotMode && Environment.TickCount - settingsClosed < 300) return;
            const int W = 300;
            Panel box = new Panel();
            box.BackColor = Theme.Field;
            int y = 4;
            ToolStripDropDown drop = new ToolStripDropDown();
            List<string[]> rows = new List<string[]>();
            rows.Add(new string[] { "tempAuto", "0", "Автоматически очищать TEMP BRPC" });
            // вопрос об очистке отключили галочкой «Больше не спрашивать»: только тогда здесь есть пункт, который его возвращает
            if (!Opt("tempAsk", true)) rows.Add(new string[] { "tempAsk", "1", "Спрашивать об очистке TEMP при закрытии" });
            rows.Add(new string[] { "showTheme", "1", "Оформление" });
            rows.Add(new string[] { "showLang", "1", "Язык" });
            foreach (string[] row in rows)
            {
                string key = row[0];
                CheckRow r = new CheckRow();
                r.Font = Font;
                r.Text = L.T(row[2]);
                r.Checked = Opt(key, row[1] == "1");
                r.SetBounds(0, y, W, 30);
                r.Changed += delegate
                {
                    Settings.Set(key, r.Checked ? "1" : "0");
                    PlaceTopButtons();
                };
                box.Controls.Add(r);
                y += 30;
            }
            if (Support.PayPal.Trim().Length > 0)
            {
                // кнопка поддержки разработчика: всегда здесь, отделена от настроек промежутком с чертой
                y += 12;
                Panel line = new Panel();
                line.BackColor = Theme.Edge;
                line.Tag = "keep";
                line.SetBounds(10, y, W - 20, 1);
                box.Controls.Add(line);
                y += 13;
                Label cap = new Label();
                cap.Text = L.T("Поддержать");
                cap.TextAlign = ContentAlignment.MiddleCenter;
                cap.ForeColor = Theme.Dim;
                cap.Font = new Font(Font.FontFamily, 11.5f);
                cap.SetBounds(0, y, W, 24);
                box.Controls.Add(cap);
                y += 28;
                Button pay = new CleanButton();
                pay.FlatStyle = FlatStyle.Flat;
                pay.FlatAppearance.BorderColor = Theme.Edge;
                pay.BackColor = Theme.Field;
                pay.ForeColor = Theme.Text;
                pay.Cursor = Cursors.Hand;
                pay.Text = "PayPal";
                pay.SetBounds((W - 140) / 2, y, 140, Row + 8);
                pay.Click += delegate
                {
                    drop.Close();
                    try { Process.Start(Support.PayPal.Trim()); }
                    catch (Exception ex) { MessageBox.Show(this, ex.Message, Text, MessageBoxButtons.OK, MessageBoxIcon.Warning); }
                };
                // при наведении на кнопку — обычная подсказка программы: поддержка добровольная (среди пользователей много детей).
                // Список настроек — отдельное всплывающее окно, обычная подсказка в нём сама не появляется: показываем её вручную
                string payNote = L.T("Поддержка добровольная и по желанию — если вам нравится проект.\nЭто не покупка: программа бесплатна и ничего за это не открывает.\nЕсли вам меньше 18 лет, сначала спросите родителей.");
                pay.MouseEnter += delegate { HoverNote.ShowAt(pay, payNote, drop.Items.Count > 0 ? drop.Items[0] : null); };
                pay.MouseLeave += delegate { HoverNote.HideNote(); };
                pay.Click += delegate { HoverNote.HideNote(); };
                drop.Closed += delegate { HoverNote.HideNote(); };
                box.Controls.Add(pay);
                y += Row + 8 + 8;
            }
            box.Size = new Size(W, y + 4);
            if (shotMode)
            {
                // всплывающее окно в проверочный снимок не попадает: список кладётся прямо в окно на то же место
                box.BorderStyle = BorderStyle.FixedSingle;
                box.Location = PointToClient(anchor.PointToScreen(new Point(0, anchor.Height + 2)));
                Controls.Add(box);
                box.BringToFront();
                return;
            }
            ToolStripControlHost host = new ToolStripControlHost(box);
            host.AutoSize = false;
            host.Size = box.Size;
            host.Margin = Padding.Empty;
            host.Padding = Padding.Empty;
            drop.Padding = new Padding(1);
            drop.Margin = Padding.Empty;
            drop.BackColor = Theme.Edge;
            drop.DropShadowEnabled = false;
            drop.Items.Add(host);
            drop.Closed += delegate { settingsClosed = Environment.TickCount; BeginInvoke((MethodInvoker)delegate { drop.Dispose(); }); };
            drop.Show(anchor, new Point(0, anchor.Height + 2));
        }

        // При закрытии: очистить папку распаковки сразу (если так настроено), спросить или оставить как есть.
        // Возвращает false, если пользователь передумал закрывать программу (закрыл окно вопроса крестиком).
        bool CleanOnClose()
        {
            if (shotMode)
            {
                // проверочный запуск убирает за собой только своё
                foreach (Pack p in packs) PackLoader.DropTemp(p.TempDir);
                return true;
            }
            bool auto = Opt("tempAuto", false);
            if (!auto && userClose && Opt("tempAsk", true) && PackLoader.TempUsed())
            {
                using (Form k = new Form())
                {
                    k.Text = L.T("Очистить папку temp?");
                    k.FormBorderStyle = FormBorderStyle.FixedDialog;
                    k.MaximizeBox = k.MinimizeBox = false;
                    k.ShowInTaskbar = false;
                    k.StartPosition = FormStartPosition.CenterParent;
                    k.Font = Font;
                    const int Pad = 14, W = 420;
                    Label label = new Label();
                    label.Text = L.T("В папке BRPC-temp лежат распакованные пакеты (") + Math.Max(1, PackLoader.TempSize() / (1024 * 1024)) + L.T(" МБ). Очистить её?");
                    label.SetBounds(Pad, Pad, W, 38);
                    CheckRow always = new CheckRow(), never = new CheckRow();
                    always.Text = L.T("Автоматически очищать TEMP BRPC");
                    never.Text = L.T("Больше не спрашивать");
                    always.SetBounds(Pad - 10, label.Bottom + 4, W + 10, 28);
                    never.SetBounds(Pad - 10, always.Bottom, W + 10, 28);
                    Button yes = new CleanButton(), no = new CleanButton();
                    yes.Text = L.T("Очистить");
                    no.Text = L.T("Закрыть");
                    yes.FlatStyle = no.FlatStyle = FlatStyle.Flat;
                    // кнопки узкие и разнесены: «Очистить» слева, синяя «Закрыть» (закрыть программу, ничего не удаляя) справа
                    // симметрично относительно середины окна, каждая на 44 пикселя ближе к ней, чем край
                    yes.SetBounds(Pad + 44, never.Bottom + 12, 96, Row);
                    no.SetBounds(Pad + W - 96 - 44, yes.Top, 96, Row);
                    yes.DialogResult = DialogResult.Yes;
                    no.DialogResult = DialogResult.No;
                    k.ClientSize = new Size(W + Pad * 2, yes.Bottom + Pad);
                    k.Controls.AddRange(new Control[] { label, always, never, yes, no });
                    k.AcceptButton = yes;
                    // кнопки отмены у окна нет: крестик в заголовке и Esc отменяют само закрытие программы
                    Theme.Style(k);
                    Theme.TitleBar(k);
                    yes.BackColor = Theme.CellHot; // чуть светлее обычной кнопки
                    no.BackColor = Theme.Accent;
                    no.ForeColor = Color.White;
                    no.FlatAppearance.BorderColor = Theme.Accent;
                    no.FlatAppearance.MouseOverBackColor = ControlPaint.Light(Theme.Accent, 0.35f);
                    always.OnWindow = never.OnWindow = true;
                    string snap = Environment.GetEnvironmentVariable("BPS_CLOSEASK"); // для проверки: сохранить вид окна в файл и ничего не менять
                    if (snap != null)
                    {
                        k.StartPosition = FormStartPosition.Manual;
                        k.Location = new Point(Left + 60, Top + 60);
                        k.Show(this);
                        Application.DoEvents();
                        using (Bitmap bm = new Bitmap(k.Width, k.Height))
                        {
                            k.DrawToBitmap(bm, new Rectangle(Point.Empty, bm.Size));
                            bm.Save(snap);
                        }
                        k.Close();
                        return true;
                    }
                    k.KeyPreview = true;
                    k.KeyDown += delegate(object ks_, KeyEventArgs ke_) { if (ke_.KeyCode == Keys.Escape) k.DialogResult = DialogResult.Cancel; };
                    DialogResult answer = k.ShowDialog(this);
                    if (answer != DialogResult.Yes && answer != DialogResult.No) return false; // окно закрыли крестиком: программа не закрывается
                    bool clean = answer == DialogResult.Yes;
                    Settings.Set("tempAuto", always.Checked ? "1" : "0");
                    if (never.Checked) Settings.Set("tempAsk", "0");
                    auto = clean || always.Checked; // «очищать всегда» относится и к этому закрытию
                }
            }
            if (auto)
            {
                // папка temp общая: пока открыто ещё одно окно программы, убирается только распакованное этим окном
                bool alone = true;
                try { alone = Process.GetProcessesByName(Process.GetCurrentProcess().ProcessName).Length <= 1; } catch (Exception) { }
                if (alone) PackLoader.ClearTemp();
                else foreach (Pack p in packs) PackLoader.DropTemp(p.TempDir);
            }
            return true;
        }

        // Открыть файл пакета в программе, назначенной для него в Windows. Обычные части пакета (картинки, звук, текст)
        // открываются сразу; программы и сценарии не открываются вовсе; про незнакомый тип программа спрашивает.
        void OpenOutside(string path)
        {
            if (Risk.Program(path))
            {
                MessageBox.Show(this, L.T("Этот файл — программа или сценарий, а не часть пакета ресурсов. Запускать его из чужого пакета опасно, поэтому программа его не открывает:\n") + Path.GetFileName(path),
                    Text, MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }
            if (!Risk.Plain(path) && MessageBox.Show(this, L.T("Программа не знает такой тип файла. Открыть его в программе, назначенной для него в Windows?\n") + Path.GetFileName(path),
                Text, MessageBoxButtons.YesNo, MessageBoxIcon.Question, MessageBoxDefaultButton.Button2) != DialogResult.Yes) return;
            try { Process.Start(path); }
            catch (Exception ex) { MessageBox.Show(this, ex.Message, Text, MessageBoxButtons.OK, MessageBoxIcon.Warning); }
        }

        // Что показать в панели превью: сама текстура или её слой. Закреплённое превью наведением не сменяется.
        void ShowDocked(Entry e, Pack p, string file, bool force)
        {
            if (!modePreview.Checked || (previewPinned && !force) || e == null || p == null) return;
            string path = file ?? p.FullPath(e.Key);
            Bitmap b = null;
            try { if (Img.IsImage(path)) b = Img.Load(path); } catch (Exception) { }
            previewPane.Set(b, Path.GetFileNameWithoutExtension(path), p.Name, e, p, file);
            // лента кадров бывает у блоков и предметов, в других папках — только если названа в списке анимаций пакета
            int perFrame = gallery.FlipTicks != null ? gallery.FlipTicks(e) : 0;
            bool strip = b != null && b.Height > b.Width && b.Height % b.Width == 0
                && (e.Key.StartsWith("textures/blocks/") || e.Key.StartsWith("textures/items/") || perFrame > 0);
            if (strip) previewPane.Animate(b.Height / b.Width, perFrame > 0 ? perFrame : 2);
        }
        bool catsOff;           // «Категории» или «Файлы» отжата: нижний левый список скрыт
        PackPreview packPreview; // всплывающий крупный значок пакета
        Action<int> hoverPackIcon; // для проверочного снимка: как будто мышь задержалась на значке пакета в этой строке
        EventHandler rebalance; // заново ставит границу между списком пакетов и нижним списком
        TreeView fileTree = new PlainTree();
        Pack filesPack;
        Panel galleryBar = new Panel();
        Panel viewer = new Panel(), imgScroll = new Panel();
        ImageView imgView = new ImageView();
        TextBox editor = new TextBox();
        ToolStripLabel viewTitle = new ToolStripLabel();
        ToolStripButton viewSave, zoomOut, zoomIn, zoomFit, viewOpen;
        string viewPath, viewInfo = "";
        bool textDirty, textCrLf, loading;
        TextBox filterBox = new TextBox();
        CheckBox onlyChoice = new FlatToggle();
        CheckBox showAttrs = new FlatToggle();
        CheckBox onlySingle = new FlatToggle(), allTextures = new FlatToggle(), onlyPack = new FlatToggle();
        CheckBox onlyRandom = new FlatToggle(); // «Случайный вариант»: видна, только когда такие текстуры есть
        CheckBox onlyAnim = new FlatToggle();   // «Анимированные»: видна, только когда такие текстуры есть
        // Кнопка со стрелкой: «Все текстуры» или «Выбранный пакет». Сами allTextures и onlyPack на экране не видны —
        // они только хранят, что выбрано.
        CheckBox scopeBtn = new FlatToggle();
        bool scopePack; // что выбрано в списке кнопки: false — все текстуры, true — выбранный пакет
        Func<DropList> scopeMenu; // раскрывает список под кнопкой
        CheckBox trashBtn = new FlatToggle(); // корзина: между крестиком поиска и звездой
        string projectFile;                   // открытый или только что сохранённый файл проекта
        Label projLabel = new Label();        // его название в верхнем ряду, между звездой и кнопкой темы

        void ShowProject(string file)
        {
            projectFile = file;
            projLabel.Text = file == null ? "" : Path.GetFileNameWithoutExtension(file);
            tips.SetToolTip(projLabel, file ?? "");
        }
        bool trashDrop;                       // над корзиной сейчас держат текстуру или слой
        List<TrashItem> trashLog = new List<TrashItem>();

        // Текстура, убранная в корзину: из какого пакета и какие его файлы спрятаны (сама картинка, её набор слоёв и слои).
        class TrashItem
        {
            public Pack P;
            public string Title;
            public List<string> Keys = new List<string>();
        }

        // Показ корзины: витрина та же, но в ней — убранные текстуры. Для этого из спрятанных файлов каждого пакета
        // собирается его «тень» — пакет с тем же именем и папкой, в котором лежит только убранное.
        bool trashView;
        Dictionary<Pack, Pack> shadowOf = new Dictionary<Pack, Pack>();   // настоящий пакет -> тень
        Dictionary<Pack, Pack> shadowReal = new Dictionary<Pack, Pack>(); // тень -> настоящий пакет

        List<Pack> TrashPacks()
        {
            List<Pack> r = new List<Pack>();
            foreach (Pack p in packs)
                foreach (Pack part in new Pack[] { p, p.Sub })
                {
                    if (part == null || part.Trash.Count == 0) continue;
                    Pack sh;
                    if (!shadowOf.TryGetValue(part, out sh))
                    {
                        sh = new Pack();
                        shadowOf[part] = sh;
                        shadowReal[sh] = part;
                    }
                    sh.Name = part.Name;
                    sh.Root = part.Root;
                    sh.Files = new Dictionary<string, string>(part.Trash);
                    r.Add(sh);
                }
            return r;
        }

        void SetTrashView(bool on)
        {
            if (on && trashLog.Count == 0) on = false;
            if (trashView == on) return;
            trashView = on;
            gallery.TrashView = on;
            trashBtn.Invalidate();
            Recollect();
            if (on) status.Text = L.T("Корзина. Плюс в углу текстуры или Enter возвращают её; чтобы выйти, нажмите кнопку корзины ещё раз.");
        }

        void TrashTexture(Entry e, Pack p)
        {
            if (trashView)
            {
                // в показе корзины то же действие возвращает текстуру
                Pack real;
                if (!shadowReal.TryGetValue(p, out real)) return;
                TrashItem back = trashLog.FindLast(delegate(TrashItem t) { return t.P == real && t.Keys.Contains(e.Key); });
                if (back == null) return;
                RestoreTrash(back);
                AfterTrash();
                status.Text = back.Title + "   —   " + L.T("возвращена из корзины");
                return;
            }
            if (p == favPack || gallery.FavView || !p.Files.ContainsKey(e.Key)) return;
            TrashItem item = new TrashItem();
            item.P = p;
            item.Title = Path.GetFileNameWithoutExtension(e.Rel) + "   —   " + p.Name;
            item.Keys.Add(e.Key);
            string set = TexKey(e) + ".texture_set.json";
            if (p.Files.ContainsKey(set)) item.Keys.Add(set);
            List<KeyValuePair<string, string>> layers;
            if (e.Attrs != null && e.Attrs.TryGetValue(p, out layers))
            {
                string root = p.Root.TrimEnd((char)92, (char)47);
                foreach (KeyValuePair<string, string> l in layers)
                {
                    if (l.Value.Length <= root.Length + 1 || !l.Value.StartsWith(root, StringComparison.OrdinalIgnoreCase)) continue;
                    string key = l.Value.Substring(root.Length + 1).Replace((char)92, (char)47).ToLowerInvariant();
                    if (p.Files.ContainsKey(key) && !item.Keys.Contains(key)) item.Keys.Add(key);
                }
            }
            foreach (string key in item.Keys)
            {
                p.Trash[key] = p.Files[key];
                p.Files.Remove(key);
            }
            trashLog.Add(item);
            // выбор, который держался на этой текстуре, снимается
            Pack chose;
            if (overrides.TryGetValue(e.Key, out chose) && chose == p) overrides.Remove(e.Key);
            List<Variant> vl;
            if (variants.TryGetValue(e.Key, out vl))
            {
                vl.RemoveAll(delegate(Variant v) { return v.P == p; });
                foreach (Variant v in vl)
                {
                    if (v.Mer == p) v.Mer = null;
                    if (v.Relief == p) v.Relief = null;
                }
                if (vl.Count == 0) variants.Remove(e.Key);
            }
            foreach (string slot in new string[] { "|mer", "|relief" })
                if (slotChoice.TryGetValue(e.Key + slot, out chose) && chose == p) slotChoice.Remove(e.Key + slot);
            if (pbrChoice.TryGetValue(e.Key, out chose) && chose == p) pbrChoice.Remove(e.Key);
            lent.RemoveAll(delegate(Lent l) { return l.Key == e.Key && (l.From == p || l.To == p); });
            AfterTrash();
            status.Text = item.Title + "   —   " + L.T("в корзине; вернуть можно кнопкой корзины наверху");
        }

        // Слой отпустили над корзиной. Чужой слой из набора текстуры просто убирается из набора (у хозяина он остаётся),
        // а свой уходит в корзину как файл.
        void TrashLayer(Entry e, Pack p, string layer, string file)
        {
            if (trashView || gallery.FavView || p == favPack) return;
            string slot = Builder.SlotOf(layer);
            Pack from = LayerPack(e, slot, file);
            if (from == null) return;
            if (Chosen(e, p) && SlotSource(e, p, slot) == from) SetSlot(e, p, slot, null);
            if (from != p)
            {
                lent.RemoveAll(delegate(Lent l) { return l.Key == e.Key && l.To == p && l.From == from && l.Slot == slot; });
                Recollect();
                return;
            }
            if (LayerShared(e, p, slot))
            {
                // Этим слоем пользуется другая текстура карточки. Если убрать сам файл, он пропадёт и у неё,
                // поэтому слой только исчезает из набора своей текстуры, а файл остаётся на месте.
                if (!OwnHidden(e, p, slot))
                {
                    Lent h = new Lent();
                    h.Key = e.Key;
                    h.Slot = slot;
                    h.To = p;
                    h.From = p;
                    hiddenOwn.Add(h);
                }
                Recollect();
                status.Text = e.Rel + L.T("   —   слой убран из набора этой текстуры; файл оставлен, потому что им пользуется другая текстура");
                return;
            }
            string root = p.Root.TrimEnd((char)92, (char)47);
            if (file.Length <= root.Length + 1 || !file.StartsWith(root, StringComparison.OrdinalIgnoreCase)) return;
            string key = file.Substring(root.Length + 1).Replace((char)92, (char)47).ToLowerInvariant();
            if (!p.Files.ContainsKey(key)) return;
            TrashItem item = new TrashItem();
            item.P = p;
            item.Title = Path.GetFileNameWithoutExtension(e.Rel) + "  ·  " + Builder.LayerTitle(layer) + "   —   " + p.Name;
            item.Keys.Add(key);
            p.Trash[key] = p.Files[key];
            p.Files.Remove(key);
            trashLog.Add(item);
            lent.RemoveAll(delegate(Lent l) { return l.Key == e.Key && l.From == p && l.Slot == slot; });
            AfterTrash();
            status.Text = item.Title + "   —   " + L.T("в корзине; вернуть можно кнопкой корзины наверху");
        }

        void RestoreTrash(TrashItem item)
        {
            foreach (string key in item.Keys)
            {
                string rel;
                if (!item.P.Trash.TryGetValue(key, out rel)) continue;
                item.P.Trash.Remove(key);
                item.P.Files[key] = rel;
            }
            trashLog.Remove(item);
        }

        void AfterTrash()
        {
            if (trashView && trashLog.Count == 0)
            {
                // корзина опустела — показывать в ней нечего
                trashView = false;
                gallery.TrashView = false;
            }
            gallery.ClearCache();
            Rebuild();
            packList.Invalidate();
            trashBtn.Invalidate();
            if (trashLookRef != null) trashLookRef(); // курсор-рука только над корзиной, в которой что-то есть
            tips.SetToolTip(trashBtn, L.T("Корзина: текстуры, убранные из списка") + (trashLog.Count > 0 ? "  (" + trashLog.Count + ")" : ""));
        }
        Action trashLookRef; // вид кнопки корзины под её состояние; задаётся в конструкторе

        // В пакете не осталось ничего, что попало бы в сборку: все текстуры в корзине, а звуков, моделей, текстов и прочего нет.
        static bool PackEmpty(Pack p)
        {
            if (p.Trash.Count == 0 && (p.Sub == null || p.Sub.Trash.Count == 0)) return false; // пустым пакет становится только из-за корзины
            foreach (Pack part in new Pack[] { p, p.Sub })
            {
                if (part == null) continue;
                foreach (string key in part.Files.Keys)
                {
                    if (key == "manifest.json" || key.StartsWith("pack_icon.") || key == "contents.json" || key == "signatures.json"
                        || key == "textures_list.json" || key == "textures/textures_list.json" || key == "textures/terrain_texture.json"
                        || key == "textures/item_texture.json" || key == "textures/flipbook_textures.json"
                        || key.EndsWith(".texture_set.json")) continue;
                    return false;
                }
            }
            return true;
        }

        // ---------------------------------------------------------- отмена (Ctrl+Z)
        // После каждого изменения запоминается состояние: порядок пакетов, выбор текстур, слоёв и вариантов, корзина.
        // Хранится одиннадцать состояний — это десять шагов назад. Когда пакеты добавляют или убирают, история начинается заново.
        class Snapshot
        {
            public List<Pack> Order;
            public Dictionary<string, Pack> Over, Pbr, Slot;
            public Dictionary<string, List<Variant>> Vars;
            public List<Lent> Lent, Hidden;
            public Dictionary<Pack, Dictionary<string, string>> Trash = new Dictionary<Pack, Dictionary<string, string>>();
            public List<TrashItem> Log;
            public string Sig;
        }

        List<Snapshot> history = new List<Snapshot>();
        bool undoing;

        static Dictionary<string, List<Variant>> CopyVariants(Dictionary<string, List<Variant>> from)
        {
            Dictionary<string, List<Variant>> r = new Dictionary<string, List<Variant>>();
            foreach (KeyValuePair<string, List<Variant>> kv in from)
            {
                List<Variant> list = new List<Variant>();
                foreach (Variant v in kv.Value)
                {
                    Variant c = new Variant();
                    c.P = v.P;
                    c.Mer = v.Mer;
                    c.Relief = v.Relief;
                    list.Add(c);
                }
                r[kv.Key] = list;
            }
            return r;
        }

        static int Id(object o) { return o == null ? 0 : System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode(o); }

        Snapshot TakeSnapshot()
        {
            Snapshot s = new Snapshot();
            s.Order = new List<Pack>(packs);
            s.Over = new Dictionary<string, Pack>(overrides);
            s.Pbr = new Dictionary<string, Pack>(pbrChoice);
            s.Slot = new Dictionary<string, Pack>(slotChoice);
            s.Vars = CopyVariants(variants);
            s.Lent = new List<Lent>(lent);
            s.Hidden = new List<Lent>(hiddenOwn);
            s.Log = new List<TrashItem>(trashLog);
            // отпечаток состояния: по нему видно, изменилось ли что-то с прошлого раза
            long a = 0, b = 0, c = 0, d = 0;
            System.Text.StringBuilder order = new System.Text.StringBuilder();
            foreach (Pack p in packs)
            {
                order.Append(Id(p)).Append((char)58).Append(p.SubFolder).Append((char)44);
                foreach (Pack part in new Pack[] { p, p.Sub })
                {
                    if (part == null) continue;
                    s.Trash[part] = new Dictionary<string, string>(part.Trash);
                    foreach (string k in part.Trash.Keys) d += (long)k.GetHashCode() * 31 + Id(part);
                }
            }
            foreach (Dictionary<string, Pack> map in new Dictionary<string, Pack>[] { s.Over, s.Pbr, s.Slot })
            {
                a = a * 7 + 1;
                foreach (KeyValuePair<string, Pack> kv in map) a += (long)kv.Key.GetHashCode() * 31 + Id(kv.Value);
            }
            foreach (KeyValuePair<string, List<Variant>> kv in s.Vars)
            {
                long one = kv.Key.GetHashCode();
                foreach (Variant v in kv.Value) one = one * 31 + Id(v.P) + Id(v.Mer) * 3L + Id(v.Relief) * 5L;
                b += one;
            }
            foreach (Lent l in s.Lent) c += Id(l);
            foreach (Lent l in s.Hidden) c += Id(l) * 3L;
            s.Sig = order + "|" + a + "|" + b + "|" + c + "|" + d;
            return s;
        }

        // Отпечаток состояния сразу после загрузки пакетов, открытия или сохранения проекта. Пока он тот же,
        // сохранять нечего, и при выходе о проекте не спрашивают.
        string cleanSig;

        bool Unchanged()
        {
            return packs.Count == 0 || TakeSnapshot().Sig == cleanSig;
        }

        void Remember()
        {
            Snapshot now = TakeSnapshot();
            if (history.Count > 0)
            {
                Snapshot last = history[history.Count - 1];
                if (last.Sig == now.Sig) return;
                // состав пакетов сменился — прежние состояния к нему уже не подходят
                bool same = last.Order.Count == now.Order.Count;
                if (same) foreach (Pack p in now.Order) if (!last.Order.Contains(p)) { same = false; break; }
                if (!same) history.Clear();
            }
            history.Add(now);
            if (history.Count > 11) history.RemoveAt(0);
        }

        void Undo()
        {
            if (history.Count < 2)
            {
                status.Text = L.T("Отменять нечего.");
                return;
            }
            history.RemoveAt(history.Count - 1);
            Snapshot s = history[history.Count - 1];
            undoing = true;
            try
            {
                packs.Clear();
                packs.AddRange(s.Order);
                overrides.Clear();
                foreach (KeyValuePair<string, Pack> kv in s.Over) overrides[kv.Key] = kv.Value;
                pbrChoice.Clear();
                foreach (KeyValuePair<string, Pack> kv in s.Pbr) pbrChoice[kv.Key] = kv.Value;
                slotChoice.Clear();
                foreach (KeyValuePair<string, Pack> kv in s.Slot) slotChoice[kv.Key] = kv.Value;
                variants.Clear();
                foreach (KeyValuePair<string, List<Variant>> kv in CopyVariants(s.Vars)) variants[kv.Key] = kv.Value;
                lent.Clear();
                lent.AddRange(s.Lent);
                hiddenOwn.Clear();
                hiddenOwn.AddRange(s.Hidden);
                foreach (KeyValuePair<Pack, Dictionary<string, string>> kv in s.Trash)
                {
                    // корзина пакета возвращается к тому, что в ней лежало тогда
                    Pack p = kv.Key;
                    foreach (KeyValuePair<string, string> gone in p.Trash) p.Files[gone.Key] = gone.Value;
                    p.Trash.Clear();
                    foreach (KeyValuePair<string, string> gone in kv.Value)
                    {
                        p.Trash[gone.Key] = gone.Value;
                        p.Files.Remove(gone.Key);
                    }
                }
                trashLog.Clear();
                trashLog.AddRange(s.Log);
                AfterTrash();
            }
            finally { undoing = false; }
            status.Text = L.T("Отменено. Шагов назад осталось: ") + (history.Count - 1);
        }

        // Колесо мыши система отдаёт тому, у кого фокус ввода (например, строке поиска). Этот перехватчик смотрит его раньше:
        // Ctrl + колесо меняет масштаб витрины, Shift + колесо ведёт выделение по текстурам — где бы ни стоял фокус.
        class WheelFilter : IMessageFilter
        {
            public Func<int, bool> Wheel;
            public bool PreFilterMessage(ref Message m)
            {
                if (m.Msg != 0x20A || Wheel == null) return false;
                return Wheel((short)((m.WParam.ToInt64() >> 16) & 0xFFFF));
            }
        }

        Control Under(Point screen)
        {
            Control c = this;
            while (true)
            {
                Control next = c.GetChildAtPoint(c.PointToClient(screen), GetChildAtPointSkip.Invisible);
                if (next == null) return c;
                c = next;
            }
        }

        bool OnWheel(int delta)
        {
            if (Form.ActiveForm != this || delta == 0) return false;
            bool ctrl = (ModifierKeys & Keys.Control) != 0, shift = (ModifierKeys & Keys.Shift) != 0;
            if (Diag.On) Diag.Log("КОЛЕСО " + delta + ", клавиши " + ModifierKeys + ", под мышью " + Under(Cursor.Position).GetType().Name + ", фокус у " + (ActiveControl == null ? "никого" : ActiveControl.GetType().Name));
            if (!ctrl && !shift) return false;
            Control at = Under(Cursor.Position);
            if (ctrl)
            {
                // в просмотре файла Ctrl + колесо — масштаб самой картинки
                if (at is ImageView || at is TextBox || !gallery.Visible) return false;
                sizeBar.Value += Math.Sign(delta) * sizeBar.LargeChange;
                return true;
            }
            if (mode3D)
            {
                // в режиме 3D то же самое: выделение идёт по объектам
                if (at != objView) return false;
                objView.Focus();
                objView.NavStep(delta > 0 ? 1 : -1);
                return true;
            }
            if (at != gallery) return false;
            // вверх — к следующей текстуре (вправо), вниз — к предыдущей (влево)
            gallery.Focus();
            // выделения нет (сняли движением мыши): первый щелчок колеса ставит его на текстуру под мышью, а не в начало экрана
            if (!gallery.NavActive) gallery.ShiftSelect();
            else gallery.NavKey(delta > 0 ? Keys.Right : Keys.Left);
            DockFollowNav();
            return true;
        }

        protected override void WndProc(ref Message m)
        {
            // Нажатый и отпущенный Alt система считает вызовом меню окна и забирает ввод. Здесь Alt — клавиша размера превью.
            if (m.Msg == 0x112 && (m.WParam.ToInt64() & 0xFFF0) == 0xF100 && m.LParam == IntPtr.Zero) return;
            // окно закрывает сам пользователь (крестик, Alt+F4, меню окна), а не другая программа
            if (m.Msg == 0x112 && (m.WParam.ToInt64() & 0xFFF0) == 0xF060) userClose = true;
            base.WndProc(ref m);
        }

        protected override bool ProcessCmdKey(ref Message msg, Keys keyData)
        {
            if (keyData == (Keys.Control | Keys.Z))
            {
                // в поле ввода Ctrl+Z отменяет набранный текст, в остальной программе — последнее действие
                Control fc = this;
                while (fc is ContainerControl && ((ContainerControl)fc).ActiveControl != null) fc = ((ContainerControl)fc).ActiveControl;
                // витрина скрыта (режим «Файлы») — отменять в ней вслепую нельзя
                if (!(fc is TextBoxBase) && gallery.Visible) { Undo(); return true; }
            }
            bool arrow = keyData == Keys.Left || keyData == Keys.Right || keyData == Keys.Up || keyData == Keys.Down;
            if ((arrow || keyData == Keys.Enter || keyData == Keys.Delete) && gallery.Visible && !gallery.FavView)
            {
                // стрелки управляют витриной, если фокус не в поле ввода и не в списке; Enter и Delete — только когда в ней что-то выделено
                Control at = this;
                while (at is ContainerControl && ((ContainerControl)at).ActiveControl != null) at = ((ContainerControl)at).ActiveControl;
                bool busy = at is TextBoxBase || at is ListBox || at is TreeView || at == sizeBar || (!arrow && (!(mode3D ? objView.NavActive : gallery.NavActive) || (at is ButtonBase && at.Focused)));
                if (Diag.On) Diag.Log("КЛАВИША " + keyData);
                if (!busy && !mode3D && gallery.NavKey(keyData)) return true;
                if (!busy && mode3D && objView.NavKey(keyData)) return true;
            }
            return base.ProcessCmdKey(ref msg, keyData);
        }
