        static EditItem EditItemOf(string title, Entry e, Pack p, string file, string layer)
        {
            EditItem it = new EditItem();
            it.Title = title;
            it.From = p.Name ?? "";
            it.Key = e.Key;
            it.P = p;
            it.File = file;
            it.Layer = layer;
            return it;
        }

        // Что редактор показывает вокруг холста для текстуры key из пакета p, когда открыт файл file (она сама или её слой).
        // null — такой текстуры в сборке сейчас нет. Заодно витрина 3D выбирает объект, в который текстура входит.
        EditTarget EditTargetOf(string key, Pack p, string file)
        {
            Entry e = key == null || p == null ? null : entries.Find(delegate(Entry x) { return x.Key == key && x.Sources.Contains(p); });
            if (e == null) return null;
            EditTarget t = new EditTarget();
            t.Title = p.Files[key] + "  —  " + p.Name;
            string own = p.FullPath(key);
            // сверху — та же текстура во всех пакетах, где она есть (варианты пакетов стоят отдельно, как в списке)
            if (e.Sources.Count > 1)
                foreach (Pack src in e.Sources) t.Variants.Add(EditItemOf(src.Name, e, src, src.FullPath(key), null));
            // снизу — остальные текстуры того же объекта: из этого же пакета, а каких в нём нет — из выбранного в сборке, как в 3D
            List<Entry> parts = objView.EditSet(e, p, out t.ObjTitle);
            if (parts != null && parts.Count > 1)
                foreach (Entry part in parts)
                {
                    Pack from = p.Files.ContainsKey(part.Key) ? p : part.Winner;
                    if (from == null || !from.Files.ContainsKey(part.Key)) continue;
                    // подпись — чем сторона отличается: copper_door_top у объекта copper_door подписана «top»
                    string side = Path.GetFileNameWithoutExtension(part.Key);
                    if (side.Length > t.ObjTitle.Length + 1 && side.StartsWith(t.ObjTitle + "_")) side = side.Substring(t.ObjTitle.Length + 1);
                    t.Sides.Add(EditItemOf(side, part, from, from.FullPath(part.Key), null));
                }
            // и слои текстуры в этом пакете
            List<KeyValuePair<string, string>> layers;
            if (e.Attrs != null && e.Attrs.TryGetValue(p, out layers))
                foreach (KeyValuePair<string, string> l in layers) t.Layers.Add(EditItemOf(Builder.LayerTitle(l.Key), e, p, l.Value, l.Key));
            bool known = string.Equals(file, own, StringComparison.OrdinalIgnoreCase)
                || t.Layers.Exists(delegate(EditItem it) { return string.Equals(it.File, file, StringComparison.OrdinalIgnoreCase); });
            // слой, взятый из другого пакета, среди слоёв этого пакета не значится — добавляется сам
            if (!known && File.Exists(file))
            {
                EditItem lent = EditItemOf(Path.GetFileNameWithoutExtension(file), e, p, file, null);
                lent.From = "";
                t.Layers.Add(lent);
            }
            if (t.Layers.Count > 0) t.Layers.Insert(0, EditItemOf(L.T("текстура"), e, p, own, null));
            // лента кадров проигрывается в превью у самих текстур — у блоков и предметов, в других папках только названная в списке анимаций
            foreach (List<EditItem> group in new List<EditItem>[] { t.Variants, t.Sides, t.Layers })
                foreach (EditItem it in group)
                {
                    if (it.Layer != null || it.From.Length == 0) continue;
                    int ticks;
                    string name = it.Key.Substring(0, it.Key.Length - Path.GetExtension(it.Key).Length);
                    if (!flipTicks.TryGetValue(name, out ticks)) ticks = 0;
                    if (ticks > 0 || it.Key.StartsWith("textures/blocks/") || it.Key.StartsWith("textures/items/")) it.Ticks = ticks > 0 ? ticks : 2;
                }
            return t;
        }

        // Сборку пересчитали: записи (Entry) теперь другие, пакеты могли убрать, текстуру — отправить в корзину.
        // Открытый редактор получает ряды заново по ключу текстуры и пакету. Если его текстуры больше нет ни в одном
        // загруженном пакете, он отвязывается от сборки и закрывается — со своим обычным вопросом о несохранённом.
        void SyncEditor()
        {
            TextureEditor ed = texEditor;
            if (ed == null || ed.IsDisposed || ed.Key == null) return;
            EditTarget t = EditTargetOf(ed.Key, ed.P, ed.File);
            if (t != null) { ed.SetTarget(t); return; }
            // текстура на месте, просто сейчас показана другая сборка (корзина): ряды остаются как были
            if (packs.Exists(delegate(Pack q) { return q == ed.P || q.Sub == ed.P; }) && ed.P.Files.ContainsKey(ed.Key)) return;
            ed.Detach();
            string none;
            objView.EditSet(null, null, out none);
            // закрытие — после того, как главное окно закончит начатое: вопрос редактора не должен влезать в середину пересчёта
            ed.BeginInvoke((MethodInvoker)delegate { if (!ed.IsDisposed) ed.Close(); });
        }

