        // Название пакета из поля наверху; расширение, если его набрали, отбрасывается.
        string PackName()
        {
            string t = nameBox.Text.Trim();
            foreach (string ext in new string[] { ".mcpack", ".zip" })
                if (t.ToLowerInvariant().EndsWith(ext)) t = t.Substring(0, t.Length - ext.Length).Trim();
            return t.Length > 0 ? t : DefaultName;
        }
