                help.Location = new Point(Math.Max(titleX, packsHead.ClientSize.Width - help.Width - Gap), 5); // с отступом, чтобы не липнуть к строке поиска
                // в узкой колонке надписи нет места: она скрывается, остаётся один знак вопроса
                int titleLeft = help.Left - 4 - packsTitle.PreferredWidth;
                packsTitle.Visible = titleLeft >= openProj.Right + 4;
                packsTitle.Location = new Point(Math.Max(openProj.Right + 4, titleLeft), 5);
            };
            packsHead.Resize += delegate { placeTitle(); };
            L.Bind(delegate(string v_)
            {
                packsTitle.Text = v_;
                placeTitle();
            }, "Пакеты ресурсов");
            L.Bind(delegate(string v_) { helpTips.SetToolTip(help, v_ + "\n\n" + L.T("Случайные варианты: щёлкните текстуру блока или моба с зажатым Ctrl, чтобы добавить её\nк уже выбранной. В игре такие варианты встречаются случайно.\nЩелчок по значку слоя под вариантом выбирает, из какого пакета взять слой.")); },
                "Верхний пакет текстур имеет приоритет над нижним,\nесли они влияют на один и тот же объект.\n\nПакеты можно перемещать по списку: зажмите левую кнопку мыши\nи перетащите пакет выше или ниже.\n\nЕсли у пакета текстур есть несколько встроенных вариантов,\nнужный выбирается в окошке справа от его названия.\n\nЧтобы использовать разные текстуры из разных вариантов одного пакета,\nдобавьте его копию, переключите её на нужный вариант\nи выбирайте текстуры в большом окне справа.");
            packsBox.Dock = DockStyle.Fill;
            packList.Dock = DockStyle.Fill;
            packList.IntegralHeight = false;
            packList.DrawMode = DrawMode.OwnerDrawFixed;
            packList.BorderStyle = BorderStyle.FixedSingle;
            packList.ItemHeight = 28;
            packList.DrawItem += DrawPack;
            // перетаскивание мышью меняет порядок паков
            packList.MouseDown += delegate(object s, MouseEventArgs e)
            {
                int i = packList.IndexFromPoint(e.Location);
                dragged = false;
                if (e.Button == MouseButtons.Left && i >= 0 && i < packs.Count && Variants(packs[i]).Count > 0
                    && VariantRect(packList.GetItemRectangle(i)).Contains(e.Location))
                {
                    // щелчок по номеру варианта: меню открывается после того, как список закончит обработку нажатия
                    Pack hit = packs[i];
                    dragIndex = -1;
                    BeginInvoke((MethodInvoker)delegate { VariantMenu(hit); });
                    return;
                }
                dragIndex = e.Button == MouseButtons.Left && i >= 0 && i < packs.Count ? i : -1;
            };
            packList.MouseMove += delegate(object s, MouseEventArgs e)
            {
                if (dragIndex < 0 || e.Button != MouseButtons.Left) return;
                int over = packList.IndexFromPoint(e.Location);
                if (over < 0 || over >= packs.Count || over == dragIndex) return;
                Pack p = packs[dragIndex];
                packs.RemoveAt(dragIndex);
                packs.Insert(over, p);
                suppress = true;
                packList.Items.RemoveAt(dragIndex);
                packList.Items.Insert(over, p);
                packList.SelectedIndex = over;
                suppress = false;
                dragIndex = over;
                dragged = true;
                packList.Cursor = Cursors.SizeNS;
            };
            packList.MouseUp += delegate
            {
                packList.Cursor = Cursors.Default;
                bool moved = dragged;
                dragIndex = -1;
                dragged = false;
                if (moved) Rebuild(); // состав сборки пересчитывается один раз, когда пак отпущен
            };
            FlowLayoutPanel packBtns = new FlowLayoutPanel();
            packBtns.Dock = DockStyle.Bottom;
            packBtns.FlowDirection = FlowDirection.LeftToRight;
            packBtns.WrapContents = false;
            packBtns.Height = Row + Gap;
            packBtns.Padding = new Padding(0, Gap, 0, 0);
            slowTips.InitialDelay = 500; // описание кнопки-значка всплывает через полсекунды
            slowTips.AutoPopDelay = 15000;
            helpTips.InitialDelay = 1;
            helpTips.ReshowDelay = 1;
            helpTips.AutoPopDelay = 30000;
            Color neutral = Color.FromArgb(112, 118, 130);
            packBtns.Controls.Add(IconBtn("+", Color.FromArgb(46, 160, 84),
                "Добавить пакеты текстур: откроется проводник, выбрать можно сразу несколько", delegate { AddPacks(); }));
            packBtns.Controls.Add(IconBtn("up", neutral, "Поднять пакет выше", delegate { MovePack(-1); }));
            packBtns.Controls.Add(IconBtn("down", neutral, "Опустить пакет ниже", delegate { MovePack(1); }));
            Button removeBtn = IconBtn("x", Color.FromArgb(208, 52, 52), "Убрать выбранный пакет из списка", delegate { RemovePack(); });
            packBtns.Controls.Add(removeBtn);
            // у правого края ряда — страница проекта на GitHub; без ссылки кнопка неактивна
            Button gitBtn = IconBtn("github", neutral, "Страница проекта на GitHub: отзывы и новые версии", delegate
            {
                try { Process.Start(Support.GitHub.Trim()); }
                catch (Exception ex) { MessageBox.Show(this, ex.Message, Text, MessageBoxButtons.OK, MessageBoxIcon.Warning); }
            });
            gitBtn.Enabled = Support.GitHub.Trim().Length > 0;
            if (!gitBtn.Enabled) gitBtn.Cursor = Cursors.Default;
            // слева от GitHub — сервер в Discord, кнопка его фирменного цвета; без ссылки тоже неактивна
            Button discordBtn = IconBtn("discord", Color.FromArgb(88, 101, 242), "Сервер проекта в Discord", delegate
            {
                try { Process.Start(Support.Discord.Trim()); }
                catch (Exception ex) { MessageBox.Show(this, ex.Message, Text, MessageBoxButtons.OK, MessageBoxIcon.Warning); }
            });
            discordBtn.Enabled = Support.Discord.Trim().Length > 0;
            if (!discordBtn.Enabled) discordBtn.Cursor = Cursors.Default;
            packBtns.Controls.Add(discordBtn);
            packBtns.Controls.Add(gitBtn);
            EventHandler toRight = delegate
            {
                // Все шесть кнопок одного размера, высота — 97% ширины. Четыре левые вместе занимают ровно ширину кнопки
                // «Категории» под ними: правый край четвёртой совпадает с её правым краем. Лишние пиксели, которые не делятся
                // на четыре, уходят по одному в промежутки.
                int catW = (packBtns.ClientSize.Width - Gap) / 2;
                int bw = Math.Max(24, (catW - 3 * Gap) / 4), bh = (int)Math.Round(bw * 0.97);
                int spare = Math.Max(0, catW - 3 * Gap - 4 * bw);
                for (int k = 0; k < 4; k++)
                {
                    Control pb = packBtns.Controls[k];
                    if (pb.Size != new Size(bw, bh)) pb.Size = new Size(bw, bh);
                    Padding pm = new Padding(0, 0, Gap + (k < 3 && k < spare ? 1 : 0), 0);
                    if (pb.Margin != pm) pb.Margin = pm;
                }
                if (gitBtn.Size != new Size(bw, bh)) gitBtn.Size = new Size(bw, bh);
                if (discordBtn.Size != new Size(bw, bh)) discordBtn.Size = new Size(bw, bh);
                if (packBtns.Height != bh + Gap) packBtns.Height = bh + Gap;
                if (gitBtn.Margin != Padding.Empty) gitBtn.Margin = Padding.Empty;
                // пара Discord и GitHub прижата к правому краю: свободное место уходит в отступ перед первой из них
                int free = packBtns.ClientSize.Width - removeBtn.Right - removeBtn.Margin.Right - discordBtn.Width - Gap - gitBtn.Width;
                Padding want = new Padding(Math.Max(0, free), 0, Gap, 0);
                if (discordBtn.Margin != want) discordBtn.Margin = want;
            };
            packBtns.Resize += toRight;
            packBtns.Layout += delegate { toRight(null, EventArgs.Empty); };
            emptyHint.Dock = DockStyle.Fill;
            emptyHint.TextAlign = ContentAlignment.MiddleCenter;
            emptyHint.ForeColor = Color.FromArgb(110, 112, 120);
            emptyHint.BackColor = Color.White;
            emptyHint.BorderStyle = BorderStyle.FixedSingle;
            emptyHint.UseMnemonic = false;
            L.Bind(delegate(string v_) { emptyHint.Text = v_; }, "Пакетов пока нет.\nДобавьте их кнопкой «+» или перетащите сюда.");
            Panel listHost = new Panel(); // список и подсказка занимают одно место: видно что-то одно
            listHost.Dock = DockStyle.Fill;
            listHost.Controls.Add(packList);
            listHost.Controls.Add(emptyHint);
            packsBox.Controls.Add(listHost);
            packsBox.Controls.Add(packBtns);
            packsBox.Controls.Add(packsHead);

            // --- категории
            Panel catBox = new Panel();
            catBox.Dock = DockStyle.Fill;
            TableLayoutPanel modes = new TableLayoutPanel();
            modes.Dock = DockStyle.Top;
            modes.Height = Row + Gap;
            modes.RowCount = 1;
            modes.RowStyles.Add(new RowStyle(SizeType.Percent, 100));
            modes.ColumnCount = 3;
            modes.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 34));
            modes.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 33));
            modes.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 33));
            L.Bind(delegate(string v_) { modePreview.Text = v_; }, "Превью");
            L.Bind(delegate(string v_) { modeCats.Text = v_; }, "Категории");
            L.Bind(delegate(string v_) { modeFiles.Text = v_; }, "Файлы");
            foreach (RadioButton rb in new RadioButton[] { modeCats, modePreview, modeFiles })
            {
                StyleToggle(rb);
                rb.AutoCheck = false; // переключение своё: «Категории» можно отжать совсем
                rb.Dock = DockStyle.Fill;
                rb.Margin = rb == modeCats ? new Padding(0, 0, Gap / 2, Gap) : (rb == modeFiles ? new Padding(Gap / 2, 0, 0, Gap) : new Padding(Gap / 2, 0, Gap / 2, Gap));
            }
            modes.Controls.Add(modeCats, 0, 0);
            modes.Controls.Add(modePreview, 1, 0);
            modes.Controls.Add(modeFiles, 2, 0);
            modePreview.Click += delegate { PickLeft(modePreview); };
            modeCats.Checked = true;
            modeFiles.CheckedChanged += delegate { SetMode(); };
            // «Категории»: повторное нажатие отжимает кнопку, нижний список прячется, а список пакетов занимает его место
            modeCats.Click += delegate { PickLeft(modeCats); };
            modeFiles.Click += delegate { PickLeft(modeFiles); }; // отжимается так же: нижний список прячется, справа снова витрина
            // значок пакета в списке: если задержать на нём мышь, всплывает крупный вид с названием пакета
            Timer iconTimer = new Timer();
            iconTimer.Interval = 1; // без задержки: окошко появляется сразу
            int iconRow = -1;
            Action hideIcon = delegate
            {
                iconTimer.Stop();
                iconRow = -1;
                if (packPreview != null) packPreview.Hide();
            };
            iconTimer.Tick += delegate
            {
                iconTimer.Stop();
                if (iconRow < 0 || iconRow >= packs.Count || dragIndex >= 0) return;
                Pack p = packs[iconRow];
                Bitmap big = null;
                try { if (p.Files.ContainsKey("pack_icon.png")) big = Img.Load(p.FullPath("pack_icon.png")); }
                catch (Exception) { }
                if (big == null) return; // у пакета нет значка — показывать нечего
                if (packPreview == null) packPreview = new PackPreview();
                Rectangle row = packList.GetItemRectangle(iconRow);
                Point at = packList.PointToScreen(new Point(row.X + 32, row.Y - 4));
                packPreview.ShowFor(this, big, p.Name, at);
            };
            packList.MouseWheel += delegate(object s, MouseEventArgs e)
            {
                // Alt + колесо над списком пакетов меняет размер открытого значка пакета
                if (!Preview.Alt || packPreview == null || !packPreview.Visible) return;
                if (Preview.Wheel(e.Delta)) packPreview.Rescale();
                HandledMouseEventArgs handled = e as HandledMouseEventArgs;
                if (handled != null) handled.Handled = true;
            };
            packList.MouseMove += delegate(object s, MouseEventArgs e)
            {
                int row = packList.IndexFromPoint(e.Location);
                Rectangle rr = row >= 0 ? packList.GetItemRectangle(row) : Rectangle.Empty;
                bool onIcon = row >= 0 && new Rectangle(rr.X + 3, rr.Y + 2, 24, 24).Contains(e.Location);
                if (!onIcon) { if (iconRow >= 0) hideIcon(); return; }
                if (row == iconRow) return;
                hideIcon();
                iconRow = row;
                iconTimer.Start();
            };
            packList.MouseLeave += delegate { hideIcon(); };
            packList.MouseDown += delegate { hideIcon(); };
            hoverPackIcon = delegate(int row) { iconRow = row; iconTimer.Start(); };
            fileTree.Dock = DockStyle.Fill;
            fileTree.HideSelection = false;
            fileTree.ItemHeight = 20;
            fileTree.Visible = false;
            fileTree.BeforeExpand += delegate(object s, TreeViewCancelEventArgs e) { FillDir(e.Node); };
            fileTree.AfterSelect += delegate(object s, TreeViewEventArgs e)
            {
                string tag = e.Node.Tag as string;
                if (tag != null && tag.StartsWith("F|")) OpenFile(tag.Substring(2));
            };
            packList.SelectedIndexChanged += delegate
            {
                if (suppress) return;
                if (modeFiles.Checked) FillFiles();
                if (tree.Nodes.Count > 0) tree.Nodes[0].Text = CounterText(); // счётчик относится к выбранному пакету
                if (onlyPack.Checked) ApplyFilter(); // витрина показывает текстуры именно этого пакета
            };
            tree.Dock = DockStyle.Fill;
            tree.HideSelection = false;
            tree.ShowLines = false;
            tree.FullRowSelect = true;
            tree.ItemHeight = 21;
            tree.AfterSelect += delegate(object treeFrom, TreeViewEventArgs treeArgs)
            {
                if (suppress || tree.SelectedNode == null) return;
                string tag = (string)tree.SelectedNode.Tag;
                if (tag == "f+")
                {
                    if (treeArgs.Action == TreeViewAction.ByKeyboard) return; // стрелками мимо строки проходят, не открывая вопрос
                    // строка «Новая папка»: спрашивает название и открывает созданную папку
                    string made = Favorites.AddFolder(AskText(L.T("Новая папка"), L.T("Название папки:")));
                    selNode = made != null ? "f:" + made : "f";
                    BeginInvoke((MethodInvoker)delegate { FillTree(); ApplyFilter(); });
                    return;
                }
                selNode = tag;
                ApplyFilter();
                if (tag.StartsWith("f")) status.Text = L.T("Перетащите текстуру из витрины на папку слева, чтобы положить её туда. Правый щелчок по папке — удалить её.");
            };
            // папки избранного: текстуры кладутся в них перетаскиванием из витрины
            gallery.CanDrag = delegate(Entry e) { return favPack != null && Favorites.Has(e.Key); };
            tree.AllowDrop = true;
            DragEventHandler folderOver = delegate(object s, DragEventArgs e)
            {
                e.Effect = DragDropEffects.None;
                if (e.Data.GetDataPresent(DataFormats.FileDrop)) { if (CanFocus) e.Effect = DragDropEffects.Copy; return; } // пакеты можно бросать и сюда
                string data = e.Data.GetData(DataFormats.StringFormat) as string;
                if (data == null || !data.StartsWith(Gallery.DragPrefix)) return;
                TreeNode n = tree.GetNodeAt(tree.PointToClient(new Point(e.X, e.Y)));
                string tag = n == null ? null : (string)n.Tag;
                if (tag != null && tag != "f+" && tag.StartsWith("f")) e.Effect = DragDropEffects.Move;
            };
            tree.DragEnter += folderOver;
            tree.DragOver += folderOver;
            tree.DragDrop += delegate(object s, DragEventArgs e)
            {
                string[] dropped = e.Data.GetData(DataFormats.FileDrop) as string[];
                if (dropped != null) { BeginInvoke((MethodInvoker)delegate { AddPaths(dropped); }); return; }
                string data = e.Data.GetData(DataFormats.StringFormat) as string;
                TreeNode n = tree.GetNodeAt(tree.PointToClient(new Point(e.X, e.Y)));
                string tag = n == null ? null : (string)n.Tag;
                if (data == null || !data.StartsWith(Gallery.DragPrefix) || tag == null || tag == "f+" || !tag.StartsWith("f")) return;
                string key = data.Substring(Gallery.DragPrefix.Length);
                try { Favorites.SetFolder(key, tag == "f" ? null : tag.Substring(2)); }
                catch (Exception ex) { MessageBox.Show(this, ex.Message, Text, MessageBoxButtons.OK, MessageBoxIcon.Warning); }
                BeginInvoke((MethodInvoker)delegate { FillTree(); ApplyFilter(); });
            };
            tree.NodeMouseClick += delegate(object s, TreeNodeMouseClickEventArgs e)
            {
                string tag = (string)e.Node.Tag;
                if (e.Button != MouseButtons.Right || tag == null || !tag.StartsWith("f:")) return;
                string name = tag.Substring(2);
                ContextMenuStrip m = NewMenu();
                ToolStripMenuItem del = new ToolStripMenuItem(L.T("Удалить папку «") + name + L.T("» (текстуры останутся в избранном)"));
                del.Click += delegate
                {
                    try { Favorites.RemoveFolder(name); }
                    catch (Exception ex) { MessageBox.Show(this, ex.Message, Text, MessageBoxButtons.OK, MessageBoxIcon.Warning); }
                    if (selNode == tag) selNode = "f";
                    FillTree();
                    ApplyFilter();
                };
                m.Items.Add(del);
                m.Show(tree, e.Location);
            };
            ThemeTree(tree);
            ThemeTree(fileTree);
            // строка счётчика рисуется на всю ширину с прижатой вправо частью: при изменении ширины её надо перерисовать целиком,
            // иначе Windows дорисовывает только открывшуюся полоску и цифры «размазываются»
            tree.Resize += delegate { tree.Invalidate(); };
            previewPane.Dock = DockStyle.Fill;
            previewPane.Visible = false;
            // пока пакетов нет, в левом нижнем окне — оговорка о неофициальности программы
            officialHint.Dock = DockStyle.Fill;
            officialHint.TextAlign = ContentAlignment.MiddleCenter;
            officialHint.UseMnemonic = false;
            officialHint.Padding = new Padding(Gap);
            L.Bind(delegate(string v_) { officialHint.Text = v_; }, "НЕОФИЦИАЛЬНЫЙ ПРОДУКТ MINECRAFT. НЕ ОДОБРЕН MOJANG ИЛИ MICROSOFT И НЕ СВЯЗАН С НИМИ.");
            catBox.Controls.Add(officialHint);
            catBox.Controls.Add(previewPane);
            catBox.Controls.Add(tree);
            catBox.Controls.Add(fileTree);
            catBox.Controls.Add(modes);

            SplitContainer left = new SplitContainer();
            left.Dock = DockStyle.Fill;
            left.Orientation = Orientation.Horizontal;
            left.SplitterWidth = Gap;
            left.Panel1.Controls.Add(packsBox);
            left.Panel2.Controls.Add(catBox);

            // --- витрина
            Panel bar = galleryBar;
            bar.Dock = DockStyle.Top;
            bar.Size = new Size(800, Row + Gap);
            Panel searchBox = new Panel();
            searchBox.SetBounds(0, 0, 230, Row);
            searchBox.BackColor = Color.White;
            searchBox.Tag = "field";
            searchBox.BorderStyle = BorderStyle.FixedSingle;
            Glyph lens = new Glyph();
            lens.Dock = DockStyle.Left;
            lens.Width = 24;
            lens.BackColor = Color.White;
            filterBox.BorderStyle = BorderStyle.None;
            filterBox.SetBounds(24, 4, 200, 16);
            filterBox.Anchor = AnchorStyles.Left | AnchorStyles.Top | AnchorStyles.Right;
            searchBox.Controls.Add(filterBox);
            searchBox.Controls.Add(lens);
            Glyph clear = new Glyph();
            clear.Cross = true;
            clear.SetBounds(searchBox.Right, 0, Row, Row); // вплотную к строке, без промежутка
            clear.Cursor = Cursors.Hand;
            clear.Click += delegate
            {
                filterBox.Clear();
                filterBox.Focus();
            };
            L.Bind(delegate(string v_) { tips.SetToolTip(clear, v_); }, "Очистить поиск");
            Label sizeLabel = new Label();
            sizeLabel.TextAlign = ContentAlignment.MiddleRight;
            sizeLabel.SetBounds(800 - 150 - Gap - 70, 0, 70, Row);
            sizeLabel.Anchor = AnchorStyles.Top | AnchorStyles.Right;
            L.Bind(delegate(string v_) { sizeLabel.Text = v_; }, "Масштаб:");
            sizeBar.SetBounds(800 - 150, 0, 150, Row);
            sizeBar.Anchor = AnchorStyles.Top | AnchorStyles.Right;
            sizeBar.Minimum = 40;
            sizeBar.Maximum = 220;
            sizeBar.SmallChange = 4;
            sizeBar.LargeChange = 16;
            sizeBar.Value = 100;
            sizeBar.ValueChanged += delegate { gallery.Tile = sizeBar.Value; objView.Tile = sizeBar.Value; };
            gallery.Tile = sizeBar.Value;
            objView.Tile = sizeBar.Value;
            bar.Controls.AddRange(new Control[] { sizeLabel, sizeBar });
            topBar.Controls.Add(searchBox); // строка поиска — в верхнем ряду, слева от кнопок темы и языка
            topBar.Controls.Add(clear);
            // «Избранное» — сразу справа от поиска
            StyleToggle(favBtn);
            // «Избранное» — квадратная кнопка размером с крестик поиска, на ней та же звезда, что у текстур:
            // серая, пока кнопка не нажата; под курсором загорается жёлтым, как крестик красным; нажатая — залита жёлтым.
            bool favHot = false;
            Action favLook = delegate
            {
                Color tint = Theme.Dark ? Color.FromArgb(92, 74, 30) : Color.FromArgb(255, 244, 204);
                favBtn.FlatAppearance.MouseOverBackColor = tint;
                favBtn.FlatAppearance.CheckedBackColor = tint;
                if (favBtn.Checked) favBtn.BackColor = tint;
                favBtn.Invalidate();
            };
            favBtn.Text = "";
            // звезда рисуется поверх кнопки сама: картинку кнопка ставит со своим сдвигом, не по центру
            favBtn.Paint += delegate(object ps, PaintEventArgs pe)
            {
                Gallery.DrawStar(pe.Graphics, favBtn.ClientRectangle, favBtn.Checked, false,
                    favBtn.Checked ? Color.Empty : (favHot ? Color.FromArgb(255, 196, 37) : Theme.Dim));
            };
            // корзина — между крестиком поиска и звездой; того же размера, что звезда
            StyleToggle(trashBtn);
            trashBtn.AutoCheck = false;
            trashBtn.Text = "";
            trashBtn.SetBounds(clear.Right + Gap, 0, (int)Math.Round(Row / 0.97), Row);
            bool trashHot = false;
            Action trashLook = delegate
            {
                trashBtn.FlatAppearance.MouseOverBackColor = Theme.Dark ? Color.FromArgb(92, 44, 44) : Color.FromArgb(255, 226, 226);
                trashBtn.Cursor = trashLog.Count > 0 || trashView ? Cursors.Hand : Cursors.Default;
                if (trashView) trashBtn.FlatAppearance.MouseOverBackColor = Theme.CellHot;
                trashBtn.Invalidate();
            };
            trashBtn.Paint += delegate(object ps, PaintEventArgs pe)
            {
                // ведёрко: пустая корзина серая, с текстурами — светлая, под курсором красная
                Color ink = trashDrop || (trashHot && trashLog.Count > 0) ? Color.FromArgb(226, 60, 60) : (trashLog.Count > 0 ? Theme.Text : Theme.Dim);
                Graphics tg = pe.Graphics;
                if (trashDrop)
                    using (SolidBrush drop = new SolidBrush(Theme.Dark ? Color.FromArgb(92, 44, 44) : Color.FromArgb(255, 226, 226)))
                        tg.FillRectangle(drop, 1, 1, trashBtn.Width - 2, trashBtn.Height - 2);
                float cx = trashBtn.Width / 2f, cy = trashBtn.Height / 2f;
                tg.SmoothingMode = SmoothingMode.AntiAlias;
                if (trashView)
                {
                    // пока открыта корзина, на кнопке сероватый кубик: щелчок по нему возвращает к обычному списку
                    PointF top = new PointF(cx, cy - 7.5f), rt = new PointF(cx + 6.5f, cy - 3.7f), rb = new PointF(cx + 6.5f, cy + 3.7f);
                    PointF bottom = new PointF(cx, cy + 7.5f), lb = new PointF(cx - 6.5f, cy + 3.7f), lt = new PointF(cx - 6.5f, cy - 3.7f), mid = new PointF(cx, cy);
                    int lift = trashHot ? 22 : 0;
                    using (SolidBrush b = new SolidBrush(Color.FromArgb(196 + lift, 198 + lift, 204 + lift))) tg.FillPolygon(b, new PointF[] { top, rt, mid, lt });
                    using (SolidBrush b = new SolidBrush(Color.FromArgb(150 + lift, 152 + lift, 160 + lift))) tg.FillPolygon(b, new PointF[] { lt, mid, bottom, lb });
                    using (SolidBrush b = new SolidBrush(Color.FromArgb(108 + lift, 110 + lift, 118 + lift))) tg.FillPolygon(b, new PointF[] { mid, rt, rb, bottom });
                    return;
                }
                using (Pen pen = new Pen(ink, 1.5f))
                {
                    tg.DrawLine(pen, cx - 6.5f, cy - 4.5f, cx + 6.5f, cy - 4.5f);                 // крышка
                    tg.DrawLine(pen, cx - 2f, cy - 6.5f, cx + 2f, cy - 6.5f);                     // ручка
                    tg.DrawLines(pen, new PointF[] { new PointF(cx - 4.8f, cy - 4f), new PointF(cx - 4f, cy + 6.5f), new PointF(cx + 4f, cy + 6.5f), new PointF(cx + 4.8f, cy - 4f) });
                    tg.DrawLine(pen, cx - 1.6f, cy - 1.5f, cx - 1.6f, cy + 4f);
                    tg.DrawLine(pen, cx + 1.6f, cy - 1.5f, cx + 1.6f, cy + 4f);
                }
            };
            trashBtn.MouseEnter += delegate { trashHot = true; trashBtn.Invalidate(); };
            trashBtn.MouseLeave += delegate { trashHot = false; trashBtn.Invalidate(); };
            restyle.Add(trashLook);
            trashLook();
            trashLookRef = trashLook;
            // щелчок открывает корзину в самой витрине, повторный — возвращает обычный список
            trashBtn.Click += delegate
            {
                bool nothingIn = !trashView && trashLog.Count == 0;
                SetTrashView(!trashView);
                trashLook();
                if (nothingIn) status.Text = L.T("Корзина пуста.");
            };
            topBar.Controls.Add(trashBtn);
            L.Bind(delegate(string v_) { tips.SetToolTip(trashBtn, v_ + (trashLog.Count > 0 ? "  (" + trashLog.Count + ")" : "")); trashBtn.AccessibleName = v_; }, "Корзина: текстуры, убранные из списка");
            favBtn.SetBounds(trashBtn.Right + Gap, 0, (int)Math.Round(Row / 0.97), Row); // высота — 97% ширины
            // название открытого проекта — в свободном месте между звездой и кнопкой темы
            projLabel.AutoSize = false;
            projLabel.AutoEllipsis = true;
            projLabel.UseMnemonic = false;
            projLabel.TextAlign = ContentAlignment.MiddleCenter;
            projLabel.Font = new Font(Font, FontStyle.Bold);
            EventHandler placeProj = delegate
            {
                int pl = favBtn.Right + Gap * 2, pr = modeBtn.Left - Gap * 2;
                projLabel.SetBounds(pl, 0, Math.Max(0, pr - pl), Row);
            };
            topBar.Controls.Add(projLabel);
            topBar.Resize += placeProj;
            Shown += placeProj;
            Shown += delegate { PlaceTopButtons(); };
            favBtn.MouseEnter += delegate { favHot = true; favLook(); };
            favBtn.MouseLeave += delegate { favHot = false; favLook(); };
            favBtn.CheckedChanged += delegate { favLook(); };
            restyle.Add(favLook);
            favLook();
            L.Bind(delegate(string v_) { tips.SetToolTip(favBtn, v_); favBtn.AccessibleName = v_; }, "Показать текстуры, сохранённые в программе: они добавляются в список как пакет «Избранное»");
            favBtn.CheckedChanged += delegate { ToggleFavorites(); };
            topBar.Controls.Add(favBtn);

            // кнопки-переключатели под строкой поиска: серые выключены, цветные включены
            L.Bind(delegate(string v_) { gemLabel[onlyChoice] = v_; onlyChoice.Invalidate(); }, "Дубликаты");
            L.Bind(delegate(string v_) { gemLabel[onlySingle] = v_; onlySingle.Invalidate(); }, "Один вариант");
            L.Bind(delegate(string v_) { gemLabel[showAttrs] = v_; showAttrs.Invalidate(); }, "Слои");
            L.Bind(delegate(string v_) { gemLabel[onlyAnim] = v_; onlyAnim.Invalidate(); }, "Анимированные");
            L.Bind(delegate(string v_) { onlyRandom.Text = v_; }, "Случайный вариант");
            L.Bind(delegate(string v_) { tips.SetToolTip(onlyRandom, v_); }, "Показать только текстуры блоков и мобов, у которых выбрано несколько вариантов: в игре они встречаются случайно");
            onlyRandom.Visible = false;
            onlyAnim.Visible = false;
            // кнопки отбора работают как переключатель: нажата всегда ровно одна, изначально — «Все текстуры»
            CheckBox[] filters = { allTextures, onlyChoice, onlySingle, onlyPack, onlyRandom, onlyAnim };
            foreach (CheckBox toggle in filters)
            {
                CheckBox mine = toggle;
                StyleToggle(mine, default(Color), true);
                mine.AutoCheck = false;
                mine.SetBounds(0, 0, 106, Row);
                mine.Click += delegate
                {
                    foreach (CheckBox other in filters) other.Checked = other == mine;
                    ApplyFilter();
                };
                bar.Controls.Add(mine);
            }
            allTextures.Visible = false;
            onlyPack.Visible = false;
            // первая кнопка ряда — со стрелкой: по щелчку выпадает список «Все текстуры / Выбранный пакет»
            StyleToggle(scopeBtn); // всегда серая: это не переключатель, а кнопка со списком
            scopeBtn.AutoCheck = false;
            scopeBtn.TextImageRelation = TextImageRelation.TextBeforeImage;
            // стрелка рисуется картинкой, цветом текста: значок «▾» из шрифта слишком мелкий
            bool scopeOpen = false;       // список раскрыт: стрелка на кнопке смотрит вверх
            int scopeClosed = 0;          // когда список закрылся: щелчок по кнопке, закрывший его, не открывает его снова
            Action scopeArrow = delegate
            {
                Bitmap tri = new Bitmap(16, 8, PixelFormat.Format32bppArgb);
                // Картинка пустая: она только держит место под стрелку, чтобы надпись не заходила в правую часть кнопки.
                // Сама стрелка рисуется в Paint ровно по центру этой части — системная раскладка ставила её со сдвигом.
                Image old = scopeBtn.Image;
                scopeBtn.Image = tri;
                if (old != null) old.Dispose();
            };
            restyle.Add(scopeArrow);
            scopeArrow();
            // Пока текстур нет, выбирать нечего: кнопка не нажимается, а надпись и стрелка приглушены (но светлее самой кнопки).
            // Enabled здесь не годится: система рисует отключённый текст слишком тёмным.
            scopeLook = delegate
            {
                // кнопка горит синим, как остальные, пока показан её список — все текстуры или выбранный пакет
                bool lit = !scopeOff && (allTextures.Checked || onlyPack.Checked);
                if (scopeBtn.Checked != lit) scopeBtn.Checked = lit;
                scopeBtn.ForeColor = scopeOff ? Shade(Theme.Text, 0.55) : (lit ? Color.White : Theme.Text);
                scopeBtn.Cursor = scopeOff ? Cursors.Default : Cursors.Hand;
                if (scopeOff) scopeBtn.FlatAppearance.MouseOverBackColor = scopeBtn.FlatAppearance.MouseDownBackColor = scopeBtn.BackColor;
                else
                {
                    scopeBtn.FlatAppearance.MouseOverBackColor = lit ? ControlPaint.Light(Theme.Accent, 0.35f) : Theme.CellHot;
                    scopeBtn.FlatAppearance.MouseDownBackColor = Color.Empty;
                }
                scopeArrow();
            };
            restyle.Add(scopeLook);
            scopeLook();
            EventHandler scopeText = delegate
            {
                // надпись помнит последний выбор из списка, даже когда включён отбор по кристаллу
                if (allTextures.Checked) scopePack = false;
                if (onlyPack.Checked) scopePack = true;
                scopeBtn.Text = L.T(scopePack ? "Выбранный пакет" : "Все текстуры");
                scopeLook();
                if (layoutFilters != null) layoutFilters();
            };
            allTextures.CheckedChanged += scopeText;
            onlyPack.CheckedChanged += scopeText;
            scopeMenu = delegate
            {
                if (scopeOff || unchecked(Environment.TickCount - scopeClosed) < 250) return null;
                DropList list = new DropList();
                list.Font = Font;
                list.Rows = new string[] { L.T("Все текстуры"), L.T("Выбранный пакет") };
                list.Active = new bool[] { true, packShown }; // пакет один — выбирать не из чего
                list.Current = scopePack ? 1 : 0;
                list.Fit(scopeBtn.Width);
                ToolStripControlHost host = new ToolStripControlHost(list);
                host.AutoSize = false;
                host.Size = list.Size;
                host.Margin = Padding.Empty;
                host.Padding = Padding.Empty;
                ToolStripDropDown drop = new ToolStripDropDown();
                drop.Padding = Padding.Empty;
                drop.Margin = Padding.Empty;
                drop.DropShadowEnabled = false;
                drop.Items.Add(host);
                list.Chosen += delegate(int row)
                {
                    drop.Close();
                    SetFilter(row == 1 ? onlyPack : allTextures);
                };
                drop.Closed += delegate
                {
                    scopeOpen = false;
                    scopeClosed = Environment.TickCount;
                    scopeArrow();
                    BeginInvoke((MethodInvoker)delegate { drop.Dispose(); });
                };
                scopeOpen = true;
                scopeArrow();
                drop.Show(scopeBtn, new Point(0, scopeBtn.Height));
                return list;
            };
            // Правая часть кнопки со стрелкой раскрывает список. Щелчок по надписи список не трогает: он возвращает показ
            // «всех текстур» (или выбранного пакета), если сейчас включён отбор по кристаллу или «Случайный вариант».
            const int ArrowZone = 30;
            scopeBtn.MouseClick += delegate(object ms, MouseEventArgs me)
            {
                if (me.Button != MouseButtons.Left || scopeOff) return;
                if (me.X >= scopeBtn.Width - ArrowZone) { scopeMenu(); return; }
                if (!allTextures.Checked && !onlyPack.Checked) SetFilter(scopePack && packShown ? onlyPack : allTextures);
            };
            scopeBtn.Paint += delegate(object ps, PaintEventArgs pe)
            {
                // тонкая черта отделяет часть со стрелкой
                using (Pen pen = new Pen(scopeBtn.Checked ? Color.FromArgb(110, 255, 255, 255) : Theme.Edge))
                    pe.Graphics.DrawLine(pen, scopeBtn.Width - ArrowZone, 5, scopeBtn.Width - ArrowZone, scopeBtn.Height - 6);
                // стрелка — по центру части справа от черты; при раскрытом списке смотрит вверх
                float acx = scopeBtn.Width - ArrowZone / 2f, acy = scopeBtn.Height / 2f;
                SmoothingMode was = pe.Graphics.SmoothingMode;
                pe.Graphics.SmoothingMode = SmoothingMode.AntiAlias;
                using (SolidBrush ab = new SolidBrush(scopeBtn.ForeColor))
                    pe.Graphics.FillPolygon(ab, scopeOpen
                        ? new PointF[] { new PointF(acx - 5.5f, acy + 3.25f), new PointF(acx + 5.5f, acy + 3.25f), new PointF(acx, acy - 3.25f) }
                        : new PointF[] { new PointF(acx - 5.5f, acy - 3.25f), new PointF(acx + 5.5f, acy - 3.25f), new PointF(acx, acy + 3.25f) });
                pe.Graphics.SmoothingMode = was;
            };
            bar.Controls.Add(scopeBtn);
            allTextures.Checked = true;
            // «Слои» — отдельный выключатель, выглядит как остальные кнопки ряда
            StyleToggle(showAttrs, default(Color), true);
            showAttrs.SetBounds(0, 0, 106, Row);
            // перед надписью кнопки — кристалл, которым такие текстуры помечены на карточках
            CheckBox[] gemBtns = { showAttrs, onlyChoice, onlyAnim, onlySingle };
            Color[] gemColors = { Theme.GemOrange, Theme.GemGreen, Theme.GemViolet, Theme.GemBlue };
            const int GemW = 13, GemGap = 6; // ширина кристалла и промежуток до надписи
            for (int gi = 0; gi < gemBtns.Length; gi++)
            {
                CheckBox gb = gemBtns[gi];
                Color gem = gemColors[gi];
                bool gemHot = false;
                // Кристалл и надпись кнопка рисует сама: вместе они стоят ровно по центру, кристалл — на уровне середины
                // заглавной буквы. Выключенная кнопка под курсором загорается, как крестик поиска, только цветом своего
                // кристалла: фон — тёмный оттенок, надпись — светлый.
                Action gemLook = delegate
                {
                    Color under = Theme.Dark ? Theme.ToggleOff : Color.White;
                    double k = Theme.Dark ? 0.34 : 0.22;
                    Color tint = Color.FromArgb((int)(under.R + (gem.R - under.R) * k), (int)(under.G + (gem.G - under.G) * k), (int)(under.B + (gem.B - under.B) * k));
                    if (!gb.Checked) gb.FlatAppearance.MouseOverBackColor = tint;
                    gb.Invalidate();
                };
                gb.Text = "";
                gb.Paint += delegate(object ps, PaintEventArgs pe)
                {
                    string label;
                    if (!gemLabel.TryGetValue(gb, out label)) return;
                    TextFormatFlags tf = TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPadding | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine;
                    int tw = TextRenderer.MeasureText(pe.Graphics, label, gb.Font, new Size(int.MaxValue, gb.Height), tf).Width;
                    int x = (gb.Width - (GemW + GemGap + tw)) / 2;
                    Color ink = gb.ForeColor;
                    if (!gb.Checked && gemHot)
                        ink = Theme.Dark ? ControlPaint.Light(gem, 0.55f) : ControlPaint.Dark(gem, 0.12f);
                    // середина заглавной буквы: строка стоит по центру кнопки, а буква в строке чуть ниже середины
                    Theme.DrawGem(pe.Graphics, x + GemW / 2f, gb.Height / 2f - 0.25f, 6, gem);
                    TextRenderer.DrawText(pe.Graphics, label, gb.Font, new Rectangle(x + GemW + GemGap, 0, tw + 4, gb.Height), ink, tf);
                };
                gb.MouseEnter += delegate { gemHot = true; gb.Invalidate(); };
                gb.MouseLeave += delegate { gemHot = false; gb.Invalidate(); };
                gb.CheckedChanged += delegate { gemLook(); };
                restyle.Add(gemLook);
                gemLook();
            }
            // ширина каждой кнопки ряда — по её надписи; при смене языка ряд раскладывается заново
            layoutFilters = delegate
            {
                int x = 0;
                // «Случайный вариант» — сразу после списка, дальше кнопки с кристаллами в порядке самих кристаллов:
                // слои, варианты, анимация, обычная
                foreach (CheckBox b in new CheckBox[] { scopeBtn, onlyRandom, showAttrs, onlyChoice, onlyAnim, onlySingle })
                {
                    if (b == showAttrs && !layersShown) continue;
                    if (b == onlyRandom && !randomShown) continue;
                    if (b == onlyChoice && !dupShown) continue;
                    if (b == onlySingle && !singleShown) continue;
                    if (b == onlyAnim && !animShown) continue;
                    // ширина — по самой длинной надписи кнопки в обоих языках (у кнопки со списком — ещё и по обоим пунктам):
                    // при смене языка и выбора ряд не сдвигается
                    bool withGem = gemLabel.ContainsKey(b);
                    string[] names = b == scopeBtn ? new string[] { "Все текстуры", "Выбранный пакет" }
                        : new string[] { b == onlyRandom ? "Случайный вариант" : (b == showAttrs ? "Слои" : (b == onlyChoice ? "Дубликаты" : (b == onlyAnim ? "Анимированные" : "Один вариант"))) };
                    int tw = 0;
                    foreach (string name in names) tw = Math.Max(tw, L.Wide(name, Font));
                    int w = Math.Max(80, tw + 22 + (withGem ? GemW + GemGap : (b.Image != null ? 18 : 0)));
                    b.SetBounds(x, 0, w, Row);
                    x += w + Gap;
                }
            };
            L.Bind(delegate(string v_) { scopeText(this, EventArgs.Empty); }, "");
            bar.Controls.Add(showAttrs);
            tips.InitialDelay = 330; // подсказка всплывает через треть секунды
            tips.ReshowDelay = 100;
            tips.AutoPopDelay = 30000; // длинные подсказки не должны исчезать, пока их читают
            L.Bind(delegate(string v_) { tips.SetToolTip(scopeBtn, v_); }, "Что показывать: все текстуры или только текстуры пакета, выделенного в списке слева");
            L.Bind(delegate(string v_) { tips.SetToolTip(onlyChoice, v_); }, "Показать только текстуры, которые есть сразу в нескольких паках");
            L.Bind(delegate(string v_) { tips.SetToolTip(onlySingle, v_); }, "Показать только текстуры, которые есть лишь в одном паке");
            L.Bind(delegate(string v_) { tips.SetToolTip(onlyAnim, v_); }, "Показать только анимированные текстуры");
            L.Bind(delegate(string v_) { tips.SetToolTip(showAttrs, v_); }, "Отражения, свечение и рельеф текстур");
            filterBox.TextChanged += delegate { if (modeFiles.Checked) FillFiles(); else ApplyFilter(); }; // один поиск на оба режима
            showAttrs.CheckedChanged += delegate { gallery.ShowAttrs = showAttrs.Checked; };

            gallery.Dock = DockStyle.Fill;
            gallery.Font = Font;
            // Первые две секунды после запуска над кружком «i» висит зелёная плашка «Скрыть»: она показывает, что кружок прячет подсказки.
            Callout hideTip = new Callout(Font, L.T("Скрыть"));
            hideTip.Tag = "keep";
            EventHandler placeTip = delegate { hideTip.Location = new Point(12, gallery.ClientSize.Height - hideTip.Height - 2); };
            gallery.Controls.Add(hideTip);
            gallery.Resize += placeTip;
            placeTip(this, EventArgs.Empty);
            Shown += delegate
            {
                Timer away = new Timer();
                away.Interval = 2667; // две секунды и ещё две трети
                away.Tick += delegate
                {
                    away.Stop();
                    away.Dispose();
                    gallery.Resize -= placeTip;
                    hideTip.Dispose();
                };
                away.Start();
            };
            gallery.Picked += delegate(Entry e, Pack p)
            {
                if (trashView) return; // в корзине текстуры только смотрят и возвращают
                // обычный щелчок меняет основной вариант: он перестаёт быть дополнительным, а выключение текстуры снимает все
                List<Variant> extras;
                if (variants.TryGetValue(e.Key, out extras))
                {
                    if (p == null) variants.Remove(e.Key);
                    else
                    {
                        extras.RemoveAll(delegate(Variant v) { return v.P == p; });
                        if (extras.Count == 0) variants.Remove(e.Key);
                    }
                }
                overrides[e.Key] = p ?? Pack.Off;
                if (p != null && !e.Excluded && p != e.Winner)
                {
                    // основным стал другой вариант: слои, назначенные прежнему, на него не переходят — он начинает со своих
                    slotChoice.Remove(e.Key + "|mer");
                    slotChoice.Remove(e.Key + "|relief");
                    pbrChoice.Remove(e.Key);
                }
                if (p == null)
                {
                    // выключая текстуру, выключаем и все её слои; их можно включить обратно отдельно
                    pbrChoice.Remove(e.Key);
                    slotChoice[e.Key + "|mer"] = Pack.Off;
                    slotChoice[e.Key + "|relief"] = Pack.Off;
                }
                else if (e.Excluded)
                {
                    // текстуру включили обратно: запрет на слои, поставленный при выключении, снимается
                    foreach (string slot in new string[] { "|mer", "|relief" })
                    {
                        Pack was;
                        if (slotChoice.TryGetValue(e.Key + slot, out was) && was == Pack.Off) slotChoice.Remove(e.Key + slot);
                    }
                }
                Recollect();
            };
            gallery.IsFav = delegate(Entry e) { return Favorites.Has(e.Key); };
            gallery.FlipTicks = delegate(Entry e)
            {
                int ticks;
                string name = e.Key.Substring(0, e.Key.Length - Path.GetExtension(e.Key).Length);
                return flipTicks.TryGetValue(name, out ticks) ? ticks : 0;
            };
            gallery.SavedTexture = delegate(Entry e) { return Favorites.TextureSaved(e.Key); };
            gallery.FavClicked += delegate(Entry e, Pack p) { if (!trashView) FavMenu(e, p); };
            gallery.IsFavTile = delegate(Entry e, Pack p)
            {
                if (!Favorites.Has(e.Key)) return false;
                string from = Favorites.SourceOf(e.Key);
                return p == favPack || from == null || from == p.Name; // null — сохранено до того, как источник стал записываться
            };
            // first — какой файл открыть сразу (слой из всплывающего окошка); null — саму текстуру
            // Редактор — отдельное окно, одно на программу: главное окно при нём работает как обычно. Если он уже
            // открыт, «редактировать» у другой текстуры меняет выбор в нём (несохранённое он сначала спросит).
            // Всё, что редактору нужно от программы, он получает через editHost.
            editHost.Resolve = EditTargetOf;
            editHost.IsFav = delegate(EditItem edIt) { return Favorites.Has(edIt.Key); };
            editHost.Render = objView.EditRender;
            editHost.TurnStart = objView.EditTurnStart;
            editHost.Turn = objView.EditTurn;
            editHost.Step = objView.EditStep;
            editHost.Live = objView.EditLive;
            // Текстуру из списка можно перетащить правой кнопкой в окно редактора: она заменит ту, что там редактируется.
            gallery.OverEditor = delegate(Point dragAt) { return texEditor != null && !texEditor.IsDisposed && texEditor.DragOverAt(dragAt); };
            gallery.EditorDropped = delegate(Entry dragE2, Pack dragP2)
            {
                if (texEditor == null || texEditor.IsDisposed) return;
                Pack fromP = dragP2 != null && dragP2.Files.ContainsKey(dragE2.Key) ? dragP2 : dragE2.Winner;
                if (fromP == null || !fromP.Files.ContainsKey(dragE2.Key)) return;
                texEditor.DropFromMain(fromP.FullPath(dragE2.Key));
            };
            openEditor = delegate(Entry edE, Pack edP, string first)
            {
                string edKey = edE == null ? null : edE.Key, edFile = first ?? edP.FullPath(edE.Key);
                if (texEditor != null && !texEditor.IsDisposed)
                {
                    texEditor.Retarget(edKey, edP, edFile);
                    texEditor.Activate();
                    return;
                }
                TextureEditor ed;
                try { ed = new TextureEditor(editHost, edKey, edP, edFile); }
                catch (Exception ex)
                {
                    MessageBox.Show(this, ex.Message, Text, MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }
                ed.Saved += delegate
                {
                    string savedKey = ed.Key;
                    Pack savedPack = ed.P;
                    gallery.ClearCache(); // картинка изменилась — миниатюры и 3D-виды рисуются заново
                    Recollect();          // заодно редактор получает свои ряды заново (SyncEditor)
                    Entry fresh = savedKey == null ? null : entries.Find(delegate(Entry x) { return x.Key == savedKey && x.Sources.Contains(savedPack); });
                    if (fresh == null) return;
                    // закреплённое превью само не обновится: в нём осталась бы картинка до правки
                    if (modePreview.Checked && !mode3D && previewPane.E != null && previewPane.P == savedPack && previewPane.E.Key == savedKey)
                        ShowDocked(fresh, savedPack, previewPane.File, true);
                    if (savedPack.TempDir != null)
                        status.Text = savedPack.Files[savedKey] + L.T("   |   пакет из архива: правка действует до закрытия программы (в сборку попадёт)");
                };
                ed.FormClosed += delegate
                {
                    if (texEditor == ed) texEditor = null;
                    string none;
                    objView.EditSet(null, null, out none);
                    objView.EditLive(null, null, 0, 0);
                };
                texEditor = ed;
                Rectangle area = Screen.FromControl(this).WorkingArea;
                ed.Location = new Point(Math.Max(area.Left, Math.Min(area.Right - ed.Width, Left + (Width - ed.Width) / 2)),
                    Math.Max(area.Top, Math.Min(area.Bottom - ed.Height, Top + (Height - ed.Height) / 2)));
                ed.Show(this); // окно принадлежит главному: держится поверх него и закрывается вместе с ним
            };
            gallery.EditClicked += delegate(Entry e, Pack p) { openEditor(e, p, null); };
            // закреплённое превью: что показывать, решают витрины; карандаш открывает тот же редактор
            // пакет может быть и вариантом (Sub); текстуру за это время могли убрать в корзину
            previewPane.Edit += delegate
            {
                if (previewPane.E == null || previewPane.P == null || !previewPane.P.Files.ContainsKey(previewPane.E.Key)) return;
                if (!packs.Exists(delegate(Pack penPack) { return penPack == previewPane.P || penPack.Sub == previewPane.P; })) return;
                openEditor(previewPane.E, previewPane.P, previewPane.File);
            };
            gallery.Docked += delegate(Entry e, Pack p, string file) { ShowDocked(e, p, file, false); };
            gallery.ShiftAt += delegate(Entry e, Pack p)
            {
                if (!modePreview.Checked) return;
                previewPinned = e != null;
                previewPane.Pinned = previewPinned;
                if (e != null) ShowDocked(e, p, null, true);
                previewPane.Invalidate();
            };
            objView.Docked += delegate(Bitmap view, string name, Entry first, bool pin)
            {
                if (!modePreview.Checked || (previewPinned && !pin)) { if (view != null) view.Dispose(); return; }
                if (pin)
                {
                    previewPinned = first != null;
                    previewPane.Pinned = previewPinned;
                    if (first == null) { previewPane.Invalidate(); return; }
                }
                previewPane.Set(view, name, first.Winner == null ? "" : first.Winner.Name, first, first.Winner, null);
                objView.AcceptDock();
            };
            previewPane.TurnStart += delegate { if (mode3D) objView.DockTurnStart(); };
            previewPane.Turn += delegate(int dx, int dy) { if (mode3D) objView.DockTurn(dx, dy); };
            objView.DockedFrame += delegate(Bitmap view, Entry first)
            {
                if (modePreview.Checked && mode3D && previewPane.E != null && first != null && previewPane.E.Key == first.Key) previewPane.SetImage(view);
                else view.Dispose();
            };
            gallery.NameCopied += delegate(Entry e)
            {
                string name = Path.GetFileNameWithoutExtension(e.Rel);
                try
                {
                    Clipboard.SetText(name);
                    status.Text = L.T("Название скопировано: ") + name;
                }
                catch (Exception ex) { status.Text = ex.Message; }
            };
            // кнопки на всплывающем окошке слоя: карандаш открывает в редакторе именно этот слой, звезда сохраняет его в избранное
            gallery.PopupEditClicked += delegate(Entry e, Pack p, KeyValuePair<string, string> item) { openEditor(e, p, item.Value); };
            Action<Entry, Pack, KeyValuePair<string, string>> popupFav = delegate(Entry e, Pack p, KeyValuePair<string, string> item)
            {
                if (trashView) return;
                if (item.Key == Gallery.Unwrap) { FavDo(delegate { Favorites.Add(p, e, true, null); }); return; }
                List<KeyValuePair<string, string>> one = new List<KeyValuePair<string, string>>();
                one.Add(item);
                FavDo(delegate { Favorites.Add(p, e, false, one); });
            };
            gallery.PopupFavClicked += popupFav;
            // звезда на превью слоя в редакторе делает то же самое
            editHost.Fav = delegate(EditItem edIt)
            {
                Entry favE = entries.Find(delegate(Entry x) { return x.Key == edIt.Key && x.Sources.Contains(edIt.P); });
                if (favE != null && edIt.Layer != null) popupFav(favE, edIt.P, new KeyValuePair<string, string>(edIt.Layer, edIt.File));
            };
            gallery.AlsoOn = delegate(Entry e, Pack p) { return !e.Excluded && VariantOf(e, p) != null; };
            gallery.MultiMinis = delegate(Entry e, Pack p)
            {
                // В показе избранного слои стоят как сохранены. В остальных случаях под текстурой лежит её набор слоёв:
                // свои, те, что перетащили к ней с других текстур (у хозяина они при этом остаются), и тот, что включён сейчас.
                if (e.Attrs == null || gallery.FavView) return null;
                List<KeyValuePair<string, string>> list = new List<KeyValuePair<string, string>>();
                List<KeyValuePair<string, string>> own;
                if (e.Attrs.TryGetValue(p, out own))
                    foreach (KeyValuePair<string, string> mine in own)
                    {
                        // свой слой, убранный из набора (им пользуется другая текстура), под хозяином не показывается
                        string ms = Builder.SlotOf(mine.Key);
                        if (OwnHidden(e, p, ms) && !(Chosen(e, p) && SlotSource(e, p, ms) == p)) continue;
                        list.Add(mine);
                    }
                Action<Pack, string> add = delegate(Pack from, string slot)
                {
                    KeyValuePair<string, string> item = SlotItem(e, from, slot);
                    if (item.Key != null && !list.Exists(delegate(KeyValuePair<string, string> x) { return x.Value == item.Value; })) list.Add(item);
                };
                foreach (Lent l in lent)
                    if (l.Key == e.Key && l.To == p && e.Sources.Contains(l.From)) add(l.From, l.Slot);
                if (Chosen(e, p))
                    foreach (string slot in new string[] { "mer", "relief" })
                    {
                        Pack src = SlotSource(e, p, slot);
                        if (src != null && src != p) add(src, slot);
                    }
                KeepBorrowed(e, p);
                return list;
            };
            gallery.MultiLayerOn = delegate(Entry e, Pack p, string layer, string file)
            {
                if (e.Attrs == null || gallery.FavView || layer == Gallery.Unwrap) return (bool?)null;
                // у текстуры включён не больше чем один слой каждого вида: тот, с которым она пойдёт в сборку
                if (!Chosen(e, p)) return false;
                string slot = Builder.SlotOf(layer);
                Pack src = SlotSource(e, p, slot);
                return src != null && SlotItem(e, src, slot).Value == file;
            };
            gallery.VariantToggled += delegate(Entry e, Pack p) { ToggleVariant(e, p); };
            gallery.CanTrash = delegate(Entry e, Pack p) { return p != favPack && !gallery.FavView; };
            gallery.Trashed += delegate(Entry e, Pack p) { TrashTexture(e, p); };
            // текстуру или слой можно перетащить правой кнопкой прямо на кнопку корзины
            gallery.OverTrash = delegate(Point screen)
            {
                return trashBtn.Visible && !trashView && trashBtn.RectangleToScreen(trashBtn.ClientRectangle).Contains(screen);
            };
            gallery.TrashHover += delegate(bool over) { trashDrop = over; trashBtn.Invalidate(); };
            gallery.LayerTrashed += delegate(Entry e, Pack p, string layer, string file) { TrashLayer(e, p, layer, file); };
            gallery.LayerClicked += delegate(Entry e, Pack p, string layer, string file)
            {
                // щелчок по слою из набора выбранной текстуры включает его вместо прежнего слоя того же вида,
                // а по включённому — выключает; у невыбранной текстуры щелчок ничего не делает
                if (gallery.FavView || trashView || !Chosen(e, p)) return;
                string slot = Builder.SlotOf(layer);
                Pack from = LayerPack(e, slot, file);
                if (from == null) return;
                KeepBorrowed(e, p);
                SetSlot(e, p, slot, SlotSource(e, p, slot) == from ? null : from);
                Recollect();
            };
            gallery.LayerRemoved += delegate(Entry e, Pack p, string layer, string file)
            {
                // Delete на слое: чужой слой убирается из набора текстуры, свой — только выключается
                if (gallery.FavView || trashView) return;
                string slot = Builder.SlotOf(layer);
                Pack from = LayerPack(e, slot, file);
                if (from == null) return;
                if (Chosen(e, p) && SlotSource(e, p, slot) == from) SetSlot(e, p, slot, null);
                lent.RemoveAll(delegate(Lent l) { return l.Key == e.Key && l.To == p && l.From == from && l.Slot == slot; });
                Recollect();
            };
            gallery.LayerDropped += delegate(Entry e, Pack from, string layer, string file, Pack to, bool live) { DropLayer(e, layer, file, to, live); };
            gallery.TextureDropped += delegate(Entry from, Pack fromP, Entry to, Pack toP) { AttachLayer(from, fromP, to, toP); };
            gallery.LayerHovered += delegate(Entry e, Pack p, string layer)
            {
                if (layer == "fav")
                {
                    status.Text = e.Rel + "   —   " + (Favorites.Has(e.Key) ? L.T("в избранном; щелчок по звезде — убрать") : L.T("щелчок по звезде — сохранить в избранное"));
                    return;
                }
                if (layer == "edit")
                {
                    status.Text = p.Files[e.Key] + "   —   " + p.Name + "   —   " + L.T("открыть редактор текстуры");
                    return;
                }
                if (layer == "unwrap")
                {
                    status.Text = e.Rel + L.T("   —   развёртка текстуры из пака «") + p.Name + L.T("»; задержите на ней курсор, чтобы увидеть крупно");
                    return;
                }
                Pack cur = null;
                if (e.Slots != null) e.Slots.TryGetValue(Builder.SlotOf(layer), out cur);
                status.Text = e.Rel + L.T("   —   слой «") + Builder.LayerTitle(layer) + L.T("» из пака «") + p.Name + "»   —   "
                    + (cur == p ? L.T("включён; щелчок выключит") : L.T("выключен; щелчок включит его"));
            };
            // витрина 3D лежит поверх обычной, того же размера
            objView.Visible = false;
            objView.Font = gallery.Font;
            gallery.Controls.Add(objView);
            gallery.Resize += delegate { objView.Bounds = gallery.ClientRectangle; };
            objView.Bounds = gallery.ClientRectangle;
            gallery.CacheCleared += delegate { objView.ClearCache(); };
            objView.HeaderClicked += delegate(string key)
            {
                if (!expanded.Remove(key)) expanded.Add(key);
                ApplyFilter();
            };
            objView.Go += delegate(Entry target)
            {
                // щелчок по объекту: обратно в обычный список, к его текстуре
                SetMode(false);
                gallery.Focus();
                gallery.GoTo(target);
            };
            gallery.HeaderClicked += delegate(string key)
            {
                if (!expanded.Remove(key)) expanded.Add(key);
                ApplyFilter();
            };
            gallery.Hovered += delegate(Entry e, Pack p, bool badge)
            {
                if (e == null) { status.Text = Legend; return; }
                string pbr = e.Pbr == null ? "" : (e.PbrChoice == null ? L.T("без отражений") : L.T("отражения и рельеф из «") + e.PbrChoice.Name + "»");
                if (badge) { status.Text = e.Rel + "   —   " + pbr; return; }
                status.Text = p.Files[e.Key] + "   —   " + p.Name;
            };
            gallery.OpenedFile += delegate(Entry e, Pack p)
            {
                // двойной правый щелчок по текстуре: файл открывается в программе, назначенной для него в системе
                OpenOutside(p.FullPath(e.Key));
            };
            gallery.Opened += delegate(Entry e, Pack p)
            {
                // правый щелчок по текстуре: обычное меню проводника для её файла (открыть, копировать, свойства…)
                string path = p.FullPath(e.Key);
                bool chose;
                // у программы или сценария меню проводника не показывается: в нём первым пунктом стоит «Открыть», то есть запуск
                if (Risk.Program(path)) { OpenOutside(path); return; }
                if (!ShellMenu.Show(this, path, Cursor.Position, out chose))
                {
                    // меню оболочки получить не удалось — просто открываем файл, как раньше
                    OpenOutside(path);
                    return;
                }
                if (!chose || File.Exists(path)) return;
                // файл удалили или переименовали через меню: пакеты перечитываются
                try
                {
                    foreach (Pack q in packs) q.Scan();
                }
                catch (Exception) { }
                gallery.ClearCache();
                Rebuild();
            };
            status.Dock = DockStyle.Bottom;
            status.Height = 22;
            status.TextAlign = ContentAlignment.MiddleLeft;
            status.AutoEllipsis = true;
            status.LoopText = delegate { return Legend; }; // подсказки идут каруселью
            status.Text = Legend;

            // --- просмотр и правка файла пака
            ToolStrip viewStrip = new ToolStrip();
            viewStrip.GripStyle = ToolStripGripStyle.Hidden;
            viewStrip.Renderer = new ThemeRenderer();
            viewTitle.Text = L.T("Выберите файл в списке слева");
            viewTitle.Font = new Font(Font, FontStyle.Bold);
            viewSave = Btn("Сохранить (Ctrl+S)", delegate { SaveText(); });
            zoomOut = Btn("Мельче", delegate { imgView.Step(-1); });
            zoomIn = Btn("Крупнее", delegate { imgView.Step(1); });
            zoomFit = Btn("Вписать", delegate { imgView.Fit(imgScroll.ClientSize); });
            viewOpen = Btn("Открыть в другой программе", delegate
            {
                if (viewPath == null) return;
                OpenOutside(viewPath);
            });
            viewStrip.Items.AddRange(new ToolStripItem[] { viewTitle, new ToolStripSeparator(), viewSave, zoomOut, zoomIn, zoomFit,
                new ToolStripSeparator(), viewOpen });
            editor.Dock = DockStyle.Fill;
            editor.BorderStyle = BorderStyle.FixedSingle;
            editor.Multiline = true;
            editor.ScrollBars = ScrollBars.Both;
            editor.WordWrap = false;
            editor.AcceptsTab = true;
            editor.MaxLength = 0;
            editor.Font = new Font("Consolas", 10f);
            editor.TextChanged += delegate { if (!loading) { textDirty = true; UpdateViewer(); } };
            editor.KeyDown += delegate(object s, KeyEventArgs e)
            {
