            };
            imgScroll.Dock = DockStyle.Fill;
            imgScroll.AutoScroll = true;
            imgScroll.BackColor = Color.FromArgb(96, 96, 96);
            imgScroll.Tag = "keep";
            imgScroll.Visible = false;
            imgView.Location = new Point(0, 0);
            imgView.ZoomChanged += delegate { UpdateViewer(); };
            imgScroll.Controls.Add(imgView);
            viewer.Dock = DockStyle.Fill;
            viewer.Visible = false;
            // текст и картинка делят одну область; панель кнопок остаётся над ней
            Panel viewBody = new Panel();
            viewBody.Dock = DockStyle.Fill;
            viewBody.Controls.Add(editor);
            viewBody.Controls.Add(imgScroll);
            viewer.Controls.Add(viewBody);
            viewer.Controls.Add(viewStrip);
            KeyPreview = true;

            SplitContainer main = new SplitContainer();
            main.Dock = DockStyle.Fill;
            main.Panel1.Controls.Add(left);
            main.Panel2.Controls.Add(gallery);
            main.Panel2.Controls.Add(viewer);
            main.Panel2.Controls.Add(bar);
            main.Panel2.Controls.Add(topBar);
            main.Panel2.Controls.Add(status);
            main.SplitterWidth = 8;
            Controls.Add(main);
            // уже некуда: шесть кнопок управления пакетами стоят вплотную с обычными промежутками
            main.Panel1MinSize = 254;
            main.SplitterDistance = 316;
