            string split = Environment.GetEnvironmentVariable("BPS_SPLIT");
            if (split != null) Shown += delegate { main.SplitterDistance = Program.Int(split, main.SplitterDistance); };
            left.SplitterDistance = 240;
            main.FixedPanel = FixedPanel.Panel1;
            // правая часть не сжимается до наезда кнопок друг на друга; задаётся после показа: до него окно ещё узкое
            Shown += delegate { try { if (main.Panel2.Width >= 800) main.Panel2MinSize = 800; } catch (Exception) { } };
            main.SizeChanged += delegate
            {
                try
                {
                    int splitMost = main.Width - main.Panel2MinSize - main.SplitterWidth;
                    if (splitMost >= main.Panel1MinSize && main.SplitterDistance > splitMost) main.SplitterDistance = splitMost;
                }
                catch (Exception) { }
            };
            // граница между списком пакетов и списком категорий держится на середине высоты витрины
            EventHandler balance = delegate
            {
                int top = topBar.Height + galleryBar.Height, bottom = main.Panel2.Height - status.Height;
                int at = (top + bottom) / 2 - left.SplitterWidth / 2;
                // «Категории» отжата: внизу остаётся только ряд кнопок режима, всё остальное — списку пакетов
                if (catsOff) at = left.Height - left.SplitterWidth - (Row + Gap);
                left.IsSplitterFixed = catsOff;
                if (at > left.Panel1MinSize && at < left.Height - left.Panel2MinSize - left.SplitterWidth && left.SplitterDistance != at) left.SplitterDistance = at;
            };
            rebalance = balance;
            main.Panel2.Resize += balance;
            Shown += balance;

            AllowDrop = true;
            DragEnter += delegate(object s, DragEventArgs e)
            {
                // пока открыто окно поверх (редактор, вопрос), пакеты под ним менять нельзя
                if (CanFocus && e.Data.GetDataPresent(DataFormats.FileDrop)) e.Effect = DragDropEffects.Copy;
            };
            DragDrop += delegate(object s, DragEventArgs e)
            {
                string[] files = (string[])e.Data.GetData(DataFormats.FileDrop);
                // диалоги нельзя показывать прямо из обработчика перетаскивания — проводник зависнет
                BeginInvoke((MethodInvoker)delegate { AddPaths(files); });
            };

            Rebuild();
            ApplyTheme();
        }

        static Bitmap IconOf(Pack p)
        {
            if (p.IconTried) return p.Icon;
            p.IconTried = true;
            try
            {
                if (!p.Files.ContainsKey("pack_icon.png")) return null;
                using (Bitmap src = Img.Load(p.FullPath("pack_icon.png")))
                {
                    Bitmap b = new Bitmap(24, 24, PixelFormat.Format32bppArgb);
                    using (Graphics g = Graphics.FromImage(b))
                    {
                        g.InterpolationMode = src.Width <= 32 ? InterpolationMode.NearestNeighbor : InterpolationMode.HighQualityBicubic;
                        g.PixelOffsetMode = PixelOffsetMode.Half;
                        g.DrawImage(src, new Rectangle(0, 0, 24, 24));
                    }
                    p.Icon = b;
                }
            }
            catch (Exception) { }
            return p.Icon;
        }

        void DrawPack(object sender, DrawItemEventArgs e)
        {
            if (e.Index < 0 || e.Index >= packList.Items.Count) return;
            e.DrawBackground();
            Pack p = (Pack)packList.Items[e.Index];
            Rectangle r = e.Bounds;
            bool hollow = PackEmpty(p); // всё убрано в корзину, и больше в пакете ничего нет: строка горит красным
            if (hollow)
                using (SolidBrush red = new SolidBrush(Theme.Dark ? Color.FromArgb(150, 44, 44) : Color.FromArgb(255, 196, 196))) e.Graphics.FillRectangle(red, r);
            // строка пакета, переведённого с Java, слегка подкрашена жёлтым (выбранная остаётся синей)
            else if (p.Java && (e.State & DrawItemState.Selected) == 0)
                using (SolidBrush yellow = new SolidBrush(Theme.Dark ? Color.FromArgb(88, 76, 34) : Color.FromArgb(255, 243, 188))) e.Graphics.FillRectangle(yellow, r);
            int lead = 0;
            if (p.Java)
            {
                // пакет Java-издания, переведённый при добавлении: метка перед его иконкой
                Rectangle jr = new Rectangle(r.X + 3, r.Y + 7, 32, 14);
                using (SolidBrush jb = new SolidBrush(Color.FromArgb(214, 96, 40))) e.Graphics.FillRectangle(jb, jr);
                using (Font jf = new Font(e.Font.FontFamily, 6.5f, FontStyle.Bold))
                    TextRenderer.DrawText(e.Graphics, "JAVA", jf, jr, Color.White, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding);
                lead = 36;
                r = new Rectangle(r.X + lead, r.Y, r.Width - lead, r.Height);
            }
            Bitmap icon = IconOf(p);
            if (icon != null) e.Graphics.DrawImageUnscaled(icon, r.X + 3, r.Y + 2);
            else
                using (SolidBrush b = new SolidBrush(Theme.Edge)) e.Graphics.FillRectangle(b, r.X + 3, r.Y + 2, 24, 24);
            bool sel = (e.State & DrawItemState.Selected) != 0;
            List<KeyValuePair<string, string>> vs = Variants(p);
            int right = 2;
            if (vs.Count > 0)
            {
                // номер выбранного варианта; прочерк — взята только основа пака
                Rectangle vr = VariantRect(r);
                int at = vs.FindIndex(delegate(KeyValuePair<string, string> v) { return v.Key == p.SubFolder; });
                using (SolidBrush b = new SolidBrush(Theme.Card)) e.Graphics.FillRectangle(b, vr);
                using (Pen pen = new Pen(Theme.Dim)) e.Graphics.DrawRectangle(pen, vr.X, vr.Y, vr.Width - 1, vr.Height - 1);
                TextRenderer.DrawText(e.Graphics, at >= 0 ? (at + 1).ToString() : "–", e.Font, vr, Theme.Text,
                    TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix);
                right = 34;
            }
            TextRenderer.DrawText(e.Graphics, p.ToString(), e.Font, new Rectangle(r.X + 32, r.Y, r.Width - 32 - right, r.Height),
                hollow ? (Theme.Dark ? Color.White : Color.FromArgb(120, 20, 20)) : (sel ? SystemColors.HighlightText : Theme.Text),
                TextFormatFlags.VerticalCenter | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix);
            e.DrawFocusRectangle();
        }

        // Счётчик в первой строке списка слева: включено / всего у пакета, выбранного в списке сверху,
        // а в скобках — то же по всем пакетам вместе.
        string CounterText()
        {
            int i = packList.SelectedIndex;
            Pack sel = i >= 0 && i < packs.Count ? packs[i] : null;
            int on = 0, all = 0, onAll = 0, total = 0;
            foreach (Entry e in entries)
            {
                if (e.Hidden || !Img.IsImage(e.Key)) continue;
                total += e.Sources.Count;
                if (!e.Excluded) onAll++;
                if (sel == null) continue;
                foreach (Pack src in e.Sources)
                {
                    if (src != sel && src != sel.Sub) continue;
                    all++;
                    if (!e.Excluded && e.Winner == src) on++;
                }
            }
            return L.T("Выбрано текстур  ") + on + " / " + all + "\t" + L.T("Общее  ") + onAll + " / " + total;
        }

        // После смены языка: всё, что собрано из строк заранее, пересобирается на новом языке.
