        void Relocalize()
        {
            if (favPack != null) favPack.Name = L.T("Избранное");
            foreach (Pack p in packs)
                if (p.Sub != null) p.Sub.Name = p.Name + L.T(" [вариант ") + p.SubFolder + "]";
            if (viewPath == null) viewTitle.Text = L.T("Выберите файл в списке слева");
            if (texEditor != null && !texEditor.IsDisposed) texEditor.Relocalize(); // надписи кнопок; ряды значков придут заново при пересчёте ниже
            Rebuild();
            packList.Invalidate();
            if (viewer.Visible) UpdateViewer(); else status.Text = Legend;
        }

        List<Action> restyle = new List<Action>(); // перекраска кнопок-переключателей при смене темы

        static Color Shade(Color c, double k)
        {
            return Color.FromArgb(c.A, (int)(c.R * k), (int)(c.G * k), (int)(c.B * k));
        }

        // Кнопка-переключатель без галочки: выключенная серая, включённая синяя. Кнопке можно дать свой цвет:
        // тогда включённая залита им, а у выключенной он остаётся на рамке.
        void StyleToggle(ButtonBase c, Color own = default(Color), bool dim = false)
        {
            Color accent = own.IsEmpty ? Theme.Accent : own;
            CheckBox cb = c as CheckBox;
            RadioButton rb = c as RadioButton;
            if (cb != null) cb.Appearance = Appearance.Button; else rb.Appearance = Appearance.Button;
            c.FlatStyle = FlatStyle.Flat;
            c.TextAlign = ContentAlignment.MiddleCenter;
            c.AutoSize = false;
            c.Cursor = Cursors.Hand;
            c.FlatAppearance.CheckedBackColor = accent;
            Action paint = delegate
            {
                bool on = cb != null ? cb.Checked : rb.Checked;
                c.BackColor = on ? accent : Theme.ToggleOff;
                c.ForeColor = on ? Color.White : Theme.Text;
                if (!own.IsEmpty)
                {
                    // кнопка со своим цветом (оранжевая «Слои»): выключенная чуть темнее остальных, у включённой текст не чисто белый
                    c.BackColor = on ? accent : Shade(Theme.ToggleOff, 0.86);
                    c.ForeColor = on ? Color.FromArgb(232, 232, 232) : Shade(Theme.Text, 0.82);
                }
                else if (dim && !on)
                {
                    // кнопки отбора в выключенном виде — того же приглушённого цвета, что и «Слои», только с обычной рамкой
                    c.BackColor = Shade(Theme.ToggleOff, 0.86);
                    c.ForeColor = Shade(Theme.Text, 0.82);
                }
                c.FlatAppearance.BorderColor = own.IsEmpty ? Theme.Edge : own;
                c.FlatAppearance.MouseOverBackColor = on ? ControlPaint.Light(accent, 0.35f) : Theme.CellHot;
            };
            if (cb != null) cb.CheckedChanged += delegate { paint(); }; else rb.CheckedChanged += delegate { paint(); };
            restyle.Add(paint);
            paint();
        }

        // Значок на кнопке темы: солнце — сейчас светлая, месяц — тёмная. Рисуется крупно и уменьшается, чтобы края были гладкими.
        static Bitmap ThemeIcon(bool dark)
        {
            Bitmap big = new Bitmap(64, 64, PixelFormat.Format32bppArgb);
            using (Graphics g = Graphics.FromImage(big))
            {
                g.SmoothingMode = SmoothingMode.AntiAlias;
                if (dark)
                {
                    using (GraphicsPath disc = new GraphicsPath())
                    using (GraphicsPath bite = new GraphicsPath())
                    {
                        disc.AddEllipse(8, 8, 48, 48);
                        bite.AddEllipse(24, 2, 44, 44);
                        using (Region moon = new Region(disc))
                        using (SolidBrush b = new SolidBrush(Color.FromArgb(214, 220, 240)))
                        {
                            moon.Exclude(bite);
                            g.FillRegion(b, moon);
                        }
                    }
                }
                else
                {
                    using (SolidBrush b = new SolidBrush(Color.FromArgb(240, 160, 0)))
                    using (Pen ray = new Pen(Color.FromArgb(240, 160, 0), 6f))
                    {
                        ray.StartCap = ray.EndCap = LineCap.Round;
                        g.FillEllipse(b, 20, 20, 24, 24);
                        for (int i = 0; i < 8; i++)
                        {
                            double a = i * Math.PI / 4;
                            g.DrawLine(ray, 32 + (float)Math.Cos(a) * 19, 32 + (float)Math.Sin(a) * 19, 32 + (float)Math.Cos(a) * 27, 32 + (float)Math.Sin(a) * 27);
                        }
                    }
                }
            }
            Bitmap small = new Bitmap(16, 16, PixelFormat.Format32bppArgb);
            using (Graphics g = Graphics.FromImage(small))
            {
                g.InterpolationMode = InterpolationMode.HighQualityBicubic;
                g.DrawImage(big, new Rectangle(0, 0, 16, 16));
            }
            big.Dispose();
            return small;
        }

        // Список слева: без светлой системной подсветки выбранной строки, рамка тонкая.
        void ThemeTree(TreeView t)
        {
            t.BorderStyle = BorderStyle.FixedSingle;
            t.FullRowSelect = false;
            t.DrawMode = TreeViewDrawMode.OwnerDrawText;
            t.DrawNode += delegate(object sender, DrawTreeNodeEventArgs e)
            {
                if (e.Bounds.Height == 0) return;
                bool sel = (e.State & TreeNodeStates.Selected) != 0;
                Rectangle row = new Rectangle(e.Bounds.X, e.Bounds.Y, Math.Max(e.Bounds.Width, t.ClientSize.Width - e.Bounds.X), e.Bounds.Height);
                // первая строка списка категорий — счётчик без значка раскрытия: она идёт от левого края блока, без отступа
                bool counter = t == tree && e.Node.Parent == null && e.Node.Index == 0 && e.Node.Nodes.Count == 0;
                if (counter) row = new Rectangle(0, e.Bounds.Y, t.ClientSize.Width, e.Bounds.Height);
                using (SolidBrush b = new SolidBrush(sel ? Theme.CellHot : Theme.Field)) e.Graphics.FillRectangle(b, row);
                string text = e.Node.Text;
                int paren = counter ? text.IndexOf('\t') : -1; // после табуляции — общий счётчик
                if (paren > 0)
                {
                    // второй счётчик, общий, стоит у правого края строки; в узкой колонке, где он наехал бы на первый, не рисуется
                    string total = text.Substring(paren + 1);
                    text = text.Substring(0, paren).TrimEnd();
                    Font nf = e.Node.NodeFont ?? t.Font;
                    int need = TextRenderer.MeasureText(e.Graphics, text, nf).Width + TextRenderer.MeasureText(e.Graphics, total, nf).Width + 8;
                    if (need <= row.Width)
                        TextRenderer.DrawText(e.Graphics, total, nf, new Rectangle(row.X, row.Y, row.Width - 2, row.Height), Theme.Text,
                            TextFormatFlags.Right | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix);
                }
                TextRenderer.DrawText(e.Graphics, text, e.Node.NodeFont ?? t.Font, row, Theme.Text,
                    TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix);
            };
        }

        // Перекрашивает всё окно под выбранную тему.
        void ApplyTheme()
        {
            Theme.App();
            Theme.Style(this);
            Theme.TitleBar(this);
            if (Visible && WindowState == FormWindowState.Normal) { Width++; Width--; } // заголовок окна перерисовывается только при изменении размера
            themeBtn.Image = ThemeIcon(Theme.Dark);
            lang.Text = L.Ru ? "RU" : "EN";
            buildBtn.ForeColor = Color.White; // надпись на зелёной кнопке белая в любой теме
            PaintModeBtn();
            gallery.BackColor = Theme.Canvas;
            emptyHint.BackColor = Theme.Field;
            emptyHint.ForeColor = Theme.Dim;
            officialHint.BackColor = Theme.Field;
            officialHint.ForeColor = Theme.Dim;
            foreach (Action paint in restyle) paint();
            Invalidate(true);
            if (texEditor != null && !texEditor.IsDisposed) texEditor.Restyle();
        }

