        static string GameFolder()
        {
            string local = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
            string p = Path.Combine(local, @"Packages\Microsoft.MinecraftUWP_8wekyb3d8bbwe\LocalState\games\com.mojang\resource_packs");
            if (Directory.Exists(p)) return p;
            p = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "Minecraft Bedrock");
            return Directory.Exists(p) ? p : null;
        }

        // ---------------------------------------------------------- паки

        // Кнопка «+»: проводник открывается там же, где в прошлый раз; выбрать можно сразу несколько пакетов.
        // Распакованный пакет (папка) выбирается по своему файлу manifest.json.
        void AddPacks()
        {
            using (OpenFileDialog d = new OpenFileDialog())
            {
                d.Title = L.T("Выберите пакеты текстур (у распакованного пакета — его manifest.json)");
                d.Filter = L.T("Пакеты текстур (*.mcpack;*.zip;*.mcaddon;manifest.json)|*.mcpack;*.zip;*.mcaddon;manifest.json|Все файлы|*.*");
                d.Multiselect = true;
                string last = Settings.Get("dir");
                if (last == null || !Directory.Exists(last)) last = GameFolder();
                if (last != null) d.InitialDirectory = last;
                if (d.ShowDialog(this) != DialogResult.OK) return;
                List<string> paths = new List<string>();
                string dir = null;
                foreach (string file in d.FileNames)
                {
                    bool manifest = Path.GetFileName(file).ToLowerInvariant() == "manifest.json";
                    string path = manifest ? Path.GetDirectoryName(file) : file;
                    paths.Add(path);
                    if (dir == null) dir = Path.GetDirectoryName(path);
                }
                if (dir != null) Settings.Set("dir", dir);
                AddPaths(paths.ToArray());
            }
        }

        // Цветная кнопка-значок без текста; описание всплывает через полсекунды.
        Button IconBtn(string symbol, Color color, string tip, EventHandler click)
        {
            Button b = new CleanButton();
            // значки рисуются линиями одного размера, а не буквами: у шрифта плюс и крестик выходят разной величины
            b.Paint += delegate(object sender, PaintEventArgs pe)
            {
                Graphics g = pe.Graphics;
                g.SmoothingMode = SmoothingMode.AntiAlias;
                int cx = b.Width / 2, cy = b.Height / 2;
                using (Pen pen = new Pen(Color.White, 2.4f))
                {
                    if (symbol == "+") { g.DrawLine(pen, cx - 6, cy, cx + 6, cy); g.DrawLine(pen, cx, cy - 6, cx, cy + 6); }
                    else if (symbol == "x") { g.DrawLine(pen, cx - 5, cy - 5, cx + 5, cy + 5); g.DrawLine(pen, cx + 5, cy - 5, cx - 5, cy + 5); }
                    else if (symbol == "github")
                    {
                        // знак GitHub: светлый круг, в нём силуэт кота цветом кнопки
                        Color ink = b.Enabled ? Color.White : Color.FromArgb(150, 255, 255, 255);
                        RectangleF disc = new RectangleF(cx - 10, cy - 10, 20, 20);
                        using (SolidBrush light = new SolidBrush(ink)) g.FillEllipse(light, disc);
                        using (GraphicsPath clip = new GraphicsPath())
                        using (SolidBrush dark = new SolidBrush(b.BackColor))
                        using (Pen tail = new Pen(b.BackColor, 1.6f))
                        {
                            clip.AddEllipse(disc);
                            Region old = g.Clip;
                            g.SetClip(clip);
                            g.FillEllipse(dark, cx - 6.5f, cy - 5.5f, 13, 10.5f);
                            g.FillPolygon(dark, new PointF[] { new PointF(cx - 6.5f, cy - 7.5f), new PointF(cx - 6.5f, cy - 1), new PointF(cx - 1.5f, cy - 4.5f) });
                            g.FillPolygon(dark, new PointF[] { new PointF(cx + 6.5f, cy - 7.5f), new PointF(cx + 6.5f, cy - 1), new PointF(cx + 1.5f, cy - 4.5f) });
                            g.FillRectangle(dark, cx - 2.6f, cy + 3.5f, 5.2f, 8);
                            g.DrawBezier(tail, cx - 2.6f, cy + 7.2f, cx - 4.5f, cy + 8f, cx - 5.5f, cy + 5.5f, cx - 7.5f, cy + 5.2f);
                            g.Clip = old;
                        }
                    }
                    else if (symbol == "discord")
                    {
                        // знак Discord: светлая «маска» с двумя глазами цвета кнопки; по размеру — как знак GitHub рядом
                        Color ink = b.Enabled ? Color.White : Color.FromArgb(150, 255, 255, 255);
                        PointF[] body = {
                            new PointF(cx - 7.5f, cy - 6f), new PointF(cx - 4f, cy - 7f), new PointF(cx - 2.6f, cy - 5.4f), new PointF(cx + 2.6f, cy - 5.4f),
                            new PointF(cx + 4f, cy - 7f), new PointF(cx + 7.5f, cy - 6f), new PointF(cx + 10f, cy + 3.6f), new PointF(cx + 6.6f, cy + 6.8f),
                            new PointF(cx + 4.6f, cy + 4.4f), new PointF(cx - 4.6f, cy + 4.4f), new PointF(cx - 6.6f, cy + 6.8f), new PointF(cx - 10f, cy + 3.6f) };
                        using (SolidBrush light = new SolidBrush(ink)) g.FillClosedCurve(light, body, FillMode.Winding, 0.35f);
                        using (SolidBrush dark = new SolidBrush(b.BackColor))
                        {
                            g.FillEllipse(dark, cx - 5.4f, cy - 2.1f, 3.9f, 4.8f);
                            g.FillEllipse(dark, cx + 1.5f, cy - 2.1f, 3.9f, 4.8f);
                        }
                    }
                    else if (symbol == "up") g.FillPolygon(Brushes.White, new Point[] { new Point(cx, cy - 5), new Point(cx + 6, cy + 4), new Point(cx - 6, cy + 4) });
                    else g.FillPolygon(Brushes.White, new Point[] { new Point(cx - 6, cy - 4), new Point(cx + 6, cy - 4), new Point(cx, cy + 5) });
                }
            };
            b.FlatStyle = FlatStyle.Flat;
            b.FlatAppearance.BorderSize = 0;
            b.FlatAppearance.MouseOverBackColor = ControlPaint.Light(color, 0.35f);
            b.BackColor = color;
            b.ForeColor = Color.White;
            b.Font = new Font(Font.FontFamily, 12f, FontStyle.Bold);
            b.Size = new Size(36, 26);
            b.Margin = new Padding(0, 0, 6, 0);
            b.Cursor = Cursors.Hand;
            b.Tag = "keep";
            b.Click += click;
            L.Bind(delegate(string v_) { slowTips.SetToolTip(b, v_); b.AccessibleName = v_; }, tip);
            return b;
        }

        // Перед скачиванием: слои, которые программа сама подтянула из другого пакета, показываются списком,
        // и пользователь либо соглашается, либо возвращается выбрать их вручную.
        bool ConfirmBorrowed(List<string> lines)
        {
            using (Form d = new Form())
            {
                d.Text = L.T("Слои из других пакетов");
                d.StartPosition = FormStartPosition.CenterParent;
                d.ClientSize = new Size(680, 440);
                d.MinimumSize = new Size(480, 300);
                d.MinimizeBox = false;
                d.MaximizeBox = false;
                d.ShowInTaskbar = false;
                d.Font = Font;
                Label msg = new Label();
                msg.Dock = DockStyle.Top;
                msg.Height = 96;
                msg.Padding = new Padding(10, 8, 10, 4);
                msg.Text = L.T("У этих текстур слои не были выбраны, поэтому отражения, свечение и рельеф подтянуты из другого пакета.\n"
                    + "Если такие слои есть в нескольких пакетах, взяты данные того, что стоит выше в списке слева.\n\n"
                    + "Нажимая «Согласен», вы соглашаетесь использовать эти данные. Чтобы выбрать самому, нажмите «Отмена», "
                    + "найдите текстуру и укажите слои на её карточке.");
                ListBox list = new ListBox();
                list.Dock = DockStyle.Fill;
                list.IntegralHeight = false;
                list.HorizontalScrollbar = true;
                foreach (string line in lines) list.Items.Add(line);
                FlowLayoutPanel buttons = new FlowLayoutPanel();
                buttons.Dock = DockStyle.Bottom;
                buttons.FlowDirection = FlowDirection.RightToLeft;
                buttons.Height = 44;
                buttons.Padding = new Padding(8, 6, 8, 6);
                Button cancel = new CleanButton();
                cancel.Text = L.T("Отмена");
                cancel.Size = new Size(110, 28);
                cancel.DialogResult = DialogResult.Cancel;
                Button ok = new CleanButton();
                ok.Text = L.T("Согласен");
                ok.Size = new Size(130, 28);
                ok.DialogResult = DialogResult.OK;
                buttons.Controls.Add(cancel);
                buttons.Controls.Add(ok);
                d.Controls.Add(list);
                d.Controls.Add(msg);
                d.Controls.Add(buttons);
                d.AcceptButton = ok;
                d.CancelButton = cancel;
                Theme.Style(d);
                Theme.TitleBar(d);
                return d.ShowDialog(this) == DialogResult.OK;
            }
        }

        List<string> pendingNotes = new List<string>(); // замечания, появившиеся до показа окна

        void Notify(List<string> notes)
        {
            if (notes.Count == 0) return;
            if (!Visible) { pendingNotes.AddRange(notes); return; }
            MessageBox.Show(this, string.Join("\n", notes.ToArray()), Text, MessageBoxButtons.OK, MessageBoxIcon.Information);
        }

        protected override void OnShown(EventArgs e)
        {
            base.OnShown(e);
            if (pendingNotes.Count == 0) return;
            List<string> notes = new List<string>(pendingNotes);
            pendingNotes.Clear();
            Notify(notes);
        }

        // Короткий вопрос с полем ввода; null — отменено или пусто.
        string AskText(string title, string hint)
        {
            using (Form k = new Form())
            {
                const int Pad = 12, W = 320;
                k.Text = title;
                k.FormBorderStyle = FormBorderStyle.FixedDialog;
                k.MinimizeBox = false;
                k.MaximizeBox = false;
                k.ShowInTaskbar = false;
                k.Font = Font;
                k.StartPosition = FormStartPosition.CenterParent;
                Label label = new Label();
                label.Text = hint;
                label.SetBounds(Pad, Pad, W, 20);
                TextBox box = new TextBox();
                box.MaxLength = 60;
                box.SetBounds(Pad, label.Bottom + Gap, W, Row);
                int bw = (W - Gap) / 2;
                Button ok = new CleanButton();
                ok.Text = "OK";
                ok.FlatStyle = FlatStyle.Flat;
                ok.SetBounds(Pad, box.Bottom + Gap * 2, bw, Row);
                ok.DialogResult = DialogResult.OK;
                Button cancel = new CleanButton();
                cancel.Text = L.T("Отмена");
                cancel.FlatStyle = FlatStyle.Flat;
                cancel.SetBounds(ok.Right + Gap, ok.Top, W - bw - Gap, Row);
                cancel.DialogResult = DialogResult.Cancel;
                k.ClientSize = new Size(W + Pad * 2, ok.Bottom + Pad);
                k.Controls.AddRange(new Control[] { label, box, ok, cancel });
                k.AcceptButton = ok;
                k.CancelButton = cancel;
                Theme.Style(k);
                Theme.TitleBar(k);
                if (k.ShowDialog(this) != DialogResult.OK) return null;
                string text = box.Text.Trim();
                return text.Length == 0 ? null : text;
            }
        }

