        // ---------------------------------------------------------- случайные варианты текстур блоков

        // Текстура -> варианты, выбранные дополнительно к основному. В игре они встречаются случайно.
        Dictionary<string, List<Variant>> variants = new Dictionary<string, List<Variant>>();

        Variant VariantOf(Entry e, Pack p)
        {
            List<Variant> list;
            if (variants.TryGetValue(e.Key, out list)) foreach (Variant v in list) if (v.P == p) return v;
            return null;
        }

        bool Multi(Entry e)
        {
            List<Variant> list;
            return !e.Excluded && variants.TryGetValue(e.Key, out list) && list.Count > 0;
        }

        // Пакеты, в которых для этой текстуры есть слой такого вида (отражения или рельеф).
        static List<Pack> SlotSources(Entry e, string slot)
        {
            List<Pack> r = new List<Pack>();
            if (e.Attrs == null) return r;
            foreach (Pack q in e.Attrs.Keys)
            {
                List<KeyValuePair<string, string>> layers;
                if (!e.Attrs.TryGetValue(q, out layers)) continue;
                foreach (KeyValuePair<string, string> l in layers)
                    if (Builder.SlotOf(l.Key) == slot) { r.Add(q); break; }
            }
            return r;
        }

        static KeyValuePair<string, string> SlotItem(Entry e, Pack q, string slot)
        {
            List<KeyValuePair<string, string>> layers;
            if (e.Attrs != null && q != null && e.Attrs.TryGetValue(q, out layers))
                foreach (KeyValuePair<string, string> l in layers)
                    if (Builder.SlotOf(l.Key) == slot) return l;
            return new KeyValuePair<string, string>();
        }

        // Из какого пакета выбранный вариант p берёт слой; null — без слоя.
        Pack SlotSource(Entry e, Pack p, string slot)
        {
            if (p == e.Winner)
            {
                Pack sp;
                return e.Slots != null && e.Slots.TryGetValue(slot, out sp) ? sp : null;
            }
            Variant v = VariantOf(e, p);
            return v == null ? null : (slot == "mer" ? v.Mer : v.Relief);
        }

        void ToggleVariant(Entry e, Pack p)
        {
            if (trashView) return;
            if (!Img.IsImage(e.Key) || !(e.Key.StartsWith("textures/blocks/") || e.Key.StartsWith("textures/entity/")))
            {
                status.Text = L.T("Случайные варианты игра умеет показывать только у текстур блоков и мобов.");
                return;
            }
            if (e.Excluded || p == e.Winner)
            {
                if (e.Excluded) { overrides[e.Key] = p; Recollect(); }
                else status.Text = L.T("Это основной вариант: он меняется обычным щелчком. Ctrl+щелчок добавляет к нему другие.");
                return;
            }
            // У объекта с несколькими сторонами (верх, бок, стадии) вариант добавляется или снимается сразу у всех сторон,
            // где он есть, и в том же порядке: иначе на одном блоке сошлись бы верх из одного пакета и бок из другого.
            bool add = VariantOf(e, p) == null;
            string system = Gallery.GroupKey(e.Key);
            int sides = 0;
            foreach (Entry side in entries)
            {
                if (side.Hidden || side.Excluded || !side.Sources.Contains(p) || Gallery.GroupKey(side.Key) != system) continue;
                Variant had = VariantOf(side, p);
                List<Variant> list;
                if (!add)
                {
                    if (had == null || !variants.TryGetValue(side.Key, out list)) continue;
                    list.Remove(had);
                    if (list.Count == 0) variants.Remove(side.Key);
                    sides++;
                    continue;
                }
                if (had != null || p == side.Winner) continue;
                if (!variants.TryGetValue(side.Key, out list)) variants[side.Key] = list = new List<Variant>();
                // слои по умолчанию — только свои; чужие назначаются вручную, перетаскиванием значка слоя
                Variant v = new Variant();
                v.P = p;
                foreach (string slot in new string[] { "mer", "relief" })
                {
                    Pack src = SlotSources(side, slot).Contains(p) ? p : null;
                    if (slot == "mer") v.Mer = src; else v.Relief = src;
                }
                list.Add(v);
                sides++;
            }
            Recollect();
            status.Text = e.Rel + "   —   " + L.T("вариантов, которые будут встречаться случайно: ") + (1 + (variants.ContainsKey(e.Key) ? variants[e.Key].Count : 0))
                + (sides > 1 ? L.T("   |   сторон этого объекта затронуто: ") + sides : "");
        }

        // У выбранного варианта p: из какого пакета взять слой (null — обойтись без него).
        void SetSlot(Entry e, Pack p, string slot, Pack from)
        {
            if (p == e.Winner) slotChoice[e.Key + "|" + slot] = from ?? Pack.Off;
            else
            {
                Variant v = VariantOf(e, p);
                if (v == null) return;
                if (slot == "mer") v.Mer = from; else v.Relief = from;
            }
        }

        // Текстура пакета p выбрана: это основной вариант или один из случайных.
        bool Chosen(Entry e, Pack p)
        {
            return !e.Excluded && (p == e.Winner || VariantOf(e, p) != null);
        }

        // Слои, перетащенные к текстуре с других текстур той же карточки: они лежат в её наборе рядом со своими.
        class Lent
        {
            public string Key, Slot; // ключ текстуры и вид слоя
            public Pack To, From;    // кому положили и из какого пакета слой
        }

        List<Lent> lent = new List<Lent>();
        // Свои слои, убранные из набора своей же текстуры, пока ими пользуется другая: файл остаётся, значок под хозяином скрыт.
        List<Lent> hiddenOwn = new List<Lent>();

        bool OwnHidden(Entry e, Pack p, string slot)
        {
            return hiddenOwn.Exists(delegate(Lent l) { return l.Key == e.Key && l.To == p && l.Slot == slot; });
        }

        // Слоем пакета p пользуется другая текстура карточки: он у неё включён или лежит в её наборе.
        bool LayerShared(Entry e, Pack p, string slot)
        {
            if (lent.Exists(delegate(Lent l) { return l.Key == e.Key && l.From == p && l.To != p && l.Slot == slot && e.Sources.Contains(l.To); })) return true;
            foreach (Pack q in e.Sources)
                if (q != p && Chosen(e, q) && SlotSource(e, q, slot) == p) return true;
            return false;
        }

        // Чужой слой, который текстура получила сама (подобран программой или пришёл из проекта), закрепляется в её наборе:
        // когда включат другой слой того же вида, этот не пропадёт, а только выключится.
        void KeepBorrowed(Entry e, Pack p)
        {
            if (!Chosen(e, p)) return;
            foreach (string slot in new string[] { "mer", "relief" })
            {
                Pack src = SlotSource(e, p, slot);
                string sl = slot;
                if (src == null || src == p || lent.Exists(delegate(Lent l) { return l.Key == e.Key && l.To == p && l.From == src && l.Slot == sl; })) continue;
                Lent keep = new Lent();
                keep.Key = e.Key;
                keep.Slot = slot;
                keep.To = p;
                keep.From = src;
                lent.Add(keep);
            }
        }

        // Из какого пакета этот файл слоя.
        static Pack LayerPack(Entry e, string slot, string file)
        {
            // набор слоёв бывает и в пакете, где самой текстуры нет (служебный пакет «Ручные слои»)
            if (e.Attrs != null)
                foreach (Pack q in e.Attrs.Keys)
                    if (SlotItem(e, q, slot).Value == file) return q;
            return null;
        }

        // ---- слои без своей текстуры. В пакете бывает карта слоя (stone_mer), а самой текстуры или набора к ней нет:
        // такая карта показана обычной текстурой. Её можно перетащить на любую текстуру — и она станет её слоем.
        // Для этого заводится служебный пакет «Ручные слои»: в него кладётся копия карты под нужным именем и набор
        // (texture_set) для текстуры-хозяина. Дальше слой живёт как любой другой: включается, выключается, идёт в сборку.

        const string ManualMark = "BRPC manual layers"; // по этой строке в описании служебный пакет узнаётся при открытии проекта

        static bool IsManual(string root)
        {
            try { return File.ReadAllText(Path.Combine(root, "manifest.json")).Contains(ManualMark); }
            catch (Exception) { return false; }
        }

        // Вид слоя по хвосту имени файла или null.
        static string LooseKind(string key)
        {
            string name = key.Substring(0, key.Length - Path.GetExtension(key).Length);
            if (name.EndsWith(" - copy")) name = name.Substring(0, name.Length - 7);
            if (name.EndsWith("_mers")) return "metalness_emissive_roughness_subsurface";
            if (name.EndsWith("_mer")) return "metalness_emissive_roughness";
            if (name.EndsWith("_normal") || name.EndsWith("_n")) return "normal";
            if (name.EndsWith("_heightmap") || name.EndsWith("_h")) return "heightmap";
            return null;
        }

        Pack ManualPack()
        {
            foreach (Pack p in packs)
                if (p.TempDir == null && IsManual(p.Root)) return p;
            string home = Environment.GetEnvironmentVariable("BPS_MANUALDIR") // при проверках служебный пакет пишется в отдельную папку
                ?? Path.Combine(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "BedrockPackStudio"), "manual_layers");
            string dir = Path.Combine(home, Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(dir);
            File.WriteAllText(Path.Combine(dir, "manifest.json"), "{\"format_version\":2,\"header\":{\"name\":\"" + L.T("Ручные слои") + "\",\"description\":\"" + ManualMark + "\",\"uuid\":\"" + Guid.NewGuid()
                + "\",\"version\":[1,0,0],\"min_engine_version\":[1,16,100]},\"modules\":[{\"type\":\"resources\",\"uuid\":\"" + Guid.NewGuid() + "\",\"version\":[1,0,0]}],\"capabilities\":[\"pbr\"]}", new UTF8Encoding(false));
            List<Pack> loaded = PackLoader.Load(dir, new List<string>());
            packs.Add(loaded[0]); // в конец списка: своих текстур в нём нет, приоритет ему не нужен
            return loaded[0];
        }

        // Текстуру layerE из пакета layerP перетащили на текстуру target (её вариант из пакета targetP).
        void AttachLayer(Entry layerE, Pack layerP, Entry target, Pack targetP)
        {
            if (trashView || gallery.FavView) return;
            string kind = Img.IsImage(layerE.Key) ? LooseKind(layerE.Key) : null;
            if (kind == null)
            {
                status.Text = L.T("Перетащить на другую текстуру можно только карту слоя — файл с хвостом _mer, _mers, _normal, _n, _heightmap или _h.");
                return;
            }
            if (!Img.IsImage(target.Key) || targetP == favPack || !layerP.Files.ContainsKey(layerE.Key) || !targetP.Files.ContainsKey(target.Key))
            {
                status.Text = L.T("Слой можно назначить только текстуре-картинке из настоящего пакета.");
                return;
            }
            string targetKey = target.Key, layerKey = layerE.Key, layerTitle = Path.GetFileNameWithoutExtension(layerE.Rel), targetTitle = Path.GetFileNameWithoutExtension(target.Rel);
            string file;
            Pack mp;
            try
            {
                mp = ManualPack();
                string rel = target.Rel.Replace((char)47, (char)92);
                string dir = Path.Combine(mp.Root, Path.GetDirectoryName(rel)), name = Path.GetFileNameWithoutExtension(rel);
                Directory.CreateDirectory(dir);
                bool deep = kind.EndsWith("subsurface");
                string tag = kind == "normal" ? "normal" : (kind == "heightmap" ? "heightmap" : (deep ? "mers" : "mer"));
                file = Path.Combine(dir, name + "_" + tag + Path.GetExtension(layerE.Rel).ToLowerInvariant());
                File.Copy(layerP.FullPath(layerKey), file, true);
                // набор текстуры-хозяина в служебном пакете: дописывается, если уже есть (второй слой той же текстуры)
                string setFile = Path.Combine(dir, name + ".texture_set.json");
                JObj doc = null;
                if (File.Exists(setFile)) try { doc = Json.Parse(File.ReadAllText(setFile)) as JObj; } catch (Exception) { }
                JObj ts = doc == null ? null : doc.Get("minecraft:texture_set") as JObj;
                JObj fresh = new JObj();
                fresh.Set("color", name);
                if (ts != null)
                    foreach (string k in ts.Keys)
                    {
                        // в наборе одна карта рельефа и одна карта отражений: новая заменяет прежнюю того же рода
                        bool relief = k == "normal" || k == "heightmap", mer = k.StartsWith("metalness");
                        if (k == "color" || k == kind || (relief && (kind == "normal" || kind == "heightmap")) || (mer && kind.StartsWith("metalness"))) continue;
                        fresh.Set(k, ts.Map[k]);
                        if (k.EndsWith("subsurface")) deep = true;
                    }
                fresh.Set(kind, name + "_" + tag);
                JObj root = new JObj();
                root.Set("format_version", deep ? "1.21.30" : "1.16.100");
                root.Set("minecraft:texture_set", fresh);
                File.WriteAllText(setFile, Json.Write(root) + "\n", new UTF8Encoding(false));
                mp.Scan();
            }
            catch (Exception ex)
            {
                status.Text = L.T("Не удалось назначить слой: ") + ex.Message;
                return;
            }
            gallery.ClearCache();
            Rebuild();
            Entry now = entries.Find(delegate(Entry x) { return x.Key == targetKey; });
            List<KeyValuePair<string, string>> made;
            if (now != null && now.Attrs != null && now.Attrs.TryGetValue(mp, out made))
                foreach (KeyValuePair<string, string> l in made) if (l.Key == kind) file = l.Value; // путь в том виде, в каком его знает витрина
            if (now != null && packs.Contains(targetP)) DropLayer(now, kind, file, targetP, true);
            // сама карта больше не нужна отдельной текстурой: она уходит в корзину (оттуда её можно вернуть)
            Entry loose = entries.Find(delegate(Entry x) { return x.Key == layerKey; });
            if (loose != null && packs.Contains(layerP)) TrashTexture(loose, layerP);
            if (!showAttrs.Checked) showAttrs.Checked = true;
            status.Text = layerTitle + L.T("   —   теперь слой «") + Builder.LayerTitle(kind) + L.T("» текстуры ") + targetTitle;
        }

        // Значок слоя перетащили на текстуру пакета to той же карточки: слой добавляется в её набор (у хозяина остаётся).
        // Включённый слой у выбранной текстуры сразу включается вместо прежнего слоя того же вида; выключенный
        // добавляется выключенным и ничего у неё не гасит.
        void DropLayer(Entry e, string layer, string file, Pack to, bool live)
        {
            string slot = Builder.SlotOf(layer);
            Pack from = LayerPack(e, slot, file);
            if (from == null || gallery.FavView || trashView) return;
            if (from == to) hiddenOwn.RemoveAll(delegate(Lent l) { return l.Key == e.Key && l.To == to && l.Slot == slot; }); // свой слой вернули хозяину
            KeepBorrowed(e, to);
            if (from != to && !lent.Exists(delegate(Lent l) { return l.Key == e.Key && l.To == to && l.From == from && l.Slot == slot; }))
            {
                Lent l = new Lent();
                l.Key = e.Key;
                l.Slot = slot;
                l.To = to;
                l.From = from;
                lent.Add(l);
            }
            if (live && Chosen(e, to)) SetSlot(e, to, slot, from);
            Recollect();
            status.Text = e.Rel + L.T("   —   слой «") + Builder.LayerTitle(layer) + L.T("» из пака «") + from.Name + "»  →  " + to.Name;
        }
        // Варианты в том виде, в каком их берёт сборка.
        List<VariantOut> VariantsForBuild()
        {
            List<VariantOut> r = new List<VariantOut>();
            foreach (KeyValuePair<string, List<Variant>> kv in variants)
            {
                Entry e = entries.Find(delegate(Entry x) { return x.Key == kv.Key; });
                if (e == null || e.Excluded) continue;
                foreach (Variant v in kv.Value)
                {
                    if (v.P == e.Winner || !e.Sources.Contains(v.P)) continue;
                    VariantOut o = new VariantOut();
                    o.E = e;
                    o.Color = v.P.FullPath(e.Key);
                    foreach (string slot in new string[] { "mer", "relief" })
                    {
                        KeyValuePair<string, string> item = SlotItem(e, slot == "mer" ? v.Mer : v.Relief, slot);
                        if (item.Key != null) o.Layers.Add(item);
                    }
                    r.Add(o);
                }
            }
            return r;
        }

        // Выбор, сделанный для пакета, которого больше нет в списке, не должен перейти на другие пакеты.
        void PruneChoices()
        {
            HashSet<Pack> live = new HashSet<Pack>();
            foreach (Pack p in packs)
            {
                live.Add(p);
                if (p.Sub != null) live.Add(p.Sub);
            }
            lent.RemoveAll(delegate(Lent l) { return !live.Contains(l.From) || !live.Contains(l.To); });
            hiddenOwn.RemoveAll(delegate(Lent l) { return !live.Contains(l.To); });
            if (trashLog.RemoveAll(delegate(TrashItem t) { return !live.Contains(t.P); }) > 0)
            {
                // корзина опустела вместе с пакетом — показывать в ней нечего (список обновит вызвавший)
                if (trashView && trashLog.Count == 0) { trashView = false; gallery.TrashView = false; }
                trashBtn.Invalidate();
                if (trashLookRef != null) trashLookRef();
            }
            foreach (string vk in new List<string>(variants.Keys))
            {
                List<Variant> vl = variants[vk];
                vl.RemoveAll(delegate(Variant v) { return !live.Contains(v.P); });
                foreach (Variant v in vl)
                {
                    if (v.Mer != null && !live.Contains(v.Mer)) v.Mer = null;
                    if (v.Relief != null && !live.Contains(v.Relief)) v.Relief = null;
                }
                if (vl.Count == 0) variants.Remove(vk);
            }
            foreach (Dictionary<string, Pack> map in new Dictionary<string, Pack>[] { overrides, pbrChoice, slotChoice })
            {
                foreach (string k in new List<string>(map.Keys))
                {
                    Pack v = map[k];
                    bool keep;
                    if (v != Pack.Off) keep = live.Contains(v);
                    else
                    {
                        // «выключено» остаётся, пока файл есть хотя бы в одном пакете
                        int bar = k.IndexOf('|');
                        string file = bar < 0 ? k : k.Substring(0, bar);
                        keep = false;
                        foreach (Pack p in live) if (p.Files.ContainsKey(file)) { keep = true; break; }
                    }
                    if (!keep) map.Remove(k);
                }
            }
        }

        // Источник пакета в виде, пригодном для сравнения: полный путь; manifest.json означает свою папку.
        static string SourceId(string path)
        {
            try
            {
                string full = Path.GetFullPath(path);
                if (string.Equals(Path.GetFileName(full), "manifest.json", StringComparison.OrdinalIgnoreCase) && File.Exists(full)) full = Path.GetDirectoryName(full);
                return full.TrimEnd('\\', '/').ToLowerInvariant();
            }
            catch (Exception) { return null; }
        }

        public void AddPaths(string[] paths)
        {
            foreach (string path in paths)
                if (path.ToLowerInvariant().EndsWith(".brpc"))
                {
                    if (paths.Length > 1)
                    {
                        List<string> aloneNote = new List<string>();
                        aloneNote.Add(L.T("Проект открывается отдельно: остальные файлы пропущены."));
                        Notify(aloneNote);
                    }
                    OpenProject(path);
                    return;
                }
            bool keptClean = projectFile == null && Unchanged(); // несохранённый выбор, сделанный до добавления, остаётся несохранённым
            List<string> notes = new List<string>();
            List<Pack> added = new List<Pack>();
            Cursor = Cursors.WaitCursor;
            foreach (string path in paths)
            {
                // тот же архив или папка второй раз: текстуры задвоились бы, и каждая стала бы «с выбором»
                string sameAs = SourceId(path);
                string sameNote = Path.GetFileName(path.TrimEnd('\\', '/')) + L.T(": уже добавлен");
                if (sameAs != null && added.Exists(delegate(Pack q) { return q.Origin != null && SourceId(q.Origin) == sameAs; }))
                {
                    notes.Add(sameNote);
                    continue;
                }
                try
                {
                    List<Pack> got = PackLoader.Load(path, notes);
                    // в источнике может быть несколько пакетов: заново добавляются только те, которых в списке уже нет
                    if (sameAs != null && got.Count > 0 && packs.Exists(delegate(Pack q) { return q.Origin != null && SourceId(q.Origin) == sameAs; }))
                    {
                        string gotTemp = got[0].TempDir;
                        got.RemoveAll(delegate(Pack g) { return packs.Exists(delegate(Pack q) { return q.Origin != null && q.OriginIndex == g.OriginIndex && SourceId(q.Origin) == sameAs; }); });
                        if (got.Count == 0)
                        {
                            notes.Add(sameNote);
                            PackLoader.DropTemp(gotTemp);
                        }
                    }
                    added.AddRange(got);
                }
                catch (Exception ex) { notes.Add(Path.GetFileName(path) + ": " + ex.Message); }
            }
            Cursor = Cursors.Default;
            if (added.Count > 0 && trashView)
            {
                // при открытой корзине новые пакеты были бы не видны
                trashView = false;
                gallery.TrashView = false;
                trashBtn.Invalidate();
                if (trashLookRef != null) trashLookRef();
            }
            // новый пак встаёт наверх списка, то есть получает высший приоритет
            packs.InsertRange(0, added);
            if (added.Count > 0 && packList.Items.Count > 0) packList.SelectedIndex = 0;
            Rebuild();
            if (keptClean) cleanSig = TakeSnapshot().Sig;
            Notify(notes);
        }

        // Варианты пака (subpacks): папка -> название для меню.
        static List<KeyValuePair<string, string>> Variants(Pack p)
        {
            List<KeyValuePair<string, string>> r = new List<KeyValuePair<string, string>>();
            if (p.Subpacks == null) return r;
            foreach (object s in p.Subpacks)
            {
                string folder = Pack.SubFolderOf(s);
                if (folder == null) continue;
                string name = ((JObj)s).Get("name") as string;
                r.Add(new KeyValuePair<string, string>(folder, string.IsNullOrEmpty(name) || name == folder ? folder : name + "  (" + folder + ")"));
            }
            return r;
        }

        // Кнопка с номером варианта у правого края строки пака.
        static Rectangle VariantRect(Rectangle row)
        {
            return new Rectangle(row.Right - 30, row.Y + 4, 26, row.Height - 8);
        }

        void VariantMenu(Pack p)
        {
            List<KeyValuePair<string, string>> vs = Variants(p);
            ContextMenuStrip m = NewMenu();
            ToolStripMenuItem head = new ToolStripMenuItem(L.T("Вариант пака «") + p.Name + "»");
            head.Enabled = false;
            m.Items.Add(head);
            m.Items.Add(new ToolStripSeparator());
            for (int k = 0; k < vs.Count; k++)
            {
                string folder = vs[k].Key;
                ToolStripMenuItem it = new ToolStripMenuItem((k + 1) + ".   " + vs[k].Value);
                it.Checked = p.SubFolder == folder;
                // тот же вариант не пересоздаём: на нём держится выбор текстур; история отмены к новому варианту не подходит
                it.Click += delegate { if (p.SubFolder == folder) return; p.SetSub(folder); history.Clear(); PruneChoices(); Rebuild(); };
                m.Items.Add(it);
            }
            ToolStripMenuItem none = new ToolStripMenuItem(L.T("–    Без варианта (только основа пака)"));
            none.Checked = p.SubFolder == null;
            none.Click += delegate { if (p.SubFolder == null) return; p.SetSub(null); history.Clear(); PruneChoices(); Rebuild(); };
            m.Items.Add(none);
            m.Show(Cursor.Position);
        }

        void MovePack(int d)
        {
            int i = packList.SelectedIndex, j = i + d;
            if (i < 0 || j < 0 || j >= packs.Count) return;
            Pack p = packs[i];
            packs[i] = packs[j];
            packs[j] = p;
            packList.SelectedIndex = j;
            Rebuild();
        }

        void RemovePack()
        {
            int i = packList.SelectedIndex;
            if (i < 0) return;
            AskSave(); // пока файлы пакета ещё на месте
            bool keptClean = projectFile == null && Unchanged();
            Pack p = packs[i];
            packs.RemoveAt(i);
            gallery.ClearCache();
            PruneChoices();
            if (previewPane.P != null && (previewPane.P == p || previewPane.P == p.Sub))
            {
                // закреплённое превью показывало текстуру убранного пакета
                previewPinned = false;
                previewPane.Pinned = false;
                previewPane.Set(null, "", "", null, null, null);
            }
            bool wasFav = p == favPack;
            if (wasFav)
            {
                // «Избранное» убрали из списка — кнопка отжимается, сами сохранённые текстуры остаются
                favPack = null;
                favBusy = true;
                favBtn.Checked = false;
                favBusy = false;
            }
            if (p.TempDir != null && !packs.Exists(delegate(Pack q) { return q.TempDir == p.TempDir; })) PackLoader.DropTemp(p.TempDir);
            if (p.Icon != null) { p.Icon.Dispose(); p.Icon = null; }
            if (wasFav) SetFilter(allTextures); // вместе с избранным включался показ «Выбранный пакет»
            Rebuild();
            if (keptClean) cleanSig = TakeSnapshot().Sig;
        }

        void Rebuild()
        {
            suppress = true;
            int sel = packList.SelectedIndex;
            packList.Items.Clear();
            foreach (Pack p in packs) packList.Items.Add(p);
            emptyHint.Visible = packs.Count == 0;
            ShowOfficialHint();
            packList.Visible = packs.Count > 0;
            if (packs.Count == 0 && projectFile != null) ShowProject(null); // все пакеты убраны — проект больше не открыт
            if (packs.Count > 0) packList.SelectedIndex = Math.Max(0, Math.Min(sel, packs.Count - 1));
            suppress = false;
            if (Geo.SetPacks(packs)) gallery.ClearCache(); // сменились модели — 3D-виды рисуются заново
            Recollect();
            if (modeFiles.Checked) FillFiles();
        }

        // Пересчитывает состав сборки после любого изменения выбора.
        void Recollect()
        {
            Dictionary<string, Pack> none = new Dictionary<string, Pack>();
            entries = trashView ? Builder.Collect(TrashPacks(), none, none, none) : Builder.Collect(packs, overrides, pbrChoice, slotChoice);
            ReadFlipbooks();
            UpdateToggles();
            FillTree();
            ApplyFilter();
            if (!undoing) Remember();
            SyncEditor();
        }

        // Длительность кадра анимированных текстур: из textures/flipbook_textures.json пакетов, верхний пакет важнее.
        Dictionary<string, int> flipTicks = new Dictionary<string, int>();

        void ReadFlipbooks()
        {
            flipTicks.Clear();
            foreach (Pack p in packs)
            {
                foreach (Pack layer in new Pack[] { p.Sub, p })
                {
                    if (layer == null || !layer.Files.ContainsKey("textures/flipbook_textures.json")) continue;
                    try
                    {
                        List<object> list = Json.Parse(File.ReadAllText(layer.FullPath("textures/flipbook_textures.json"))) as List<object>;
                        if (list == null) continue;
                        foreach (object o in list)
                        {
                            JObj item = o as JObj;
                            string tex = item == null ? null : item.Get("flipbook_texture") as string;
                            if (tex == null) continue;
                            tex = tex.ToLowerInvariant();
                            if (flipTicks.ContainsKey(tex)) continue;
                            JLit lit = item.Get("ticks_per_frame") as JLit;
                            int ticks;
                            flipTicks[tex] = lit != null && int.TryParse(lit.Raw, out ticks) && ticks > 0 ? ticks : 1;
                        }
                    }
                    catch (Exception) { }
                }
            }
        }

        bool layersShown = true, randomShown; // есть ли в загруженном слои и случайные варианты: от этого зависят кнопки ряда
        bool animShown; // есть ли анимированные текстуры
        bool dupShown = true, singleShown = true, packShown = true; // есть ли что отбирать кнопками «Дубликаты», «Один вариант», «Выбранный пакет»

        // «Слои» показана, только если в пакетах есть слои; «Случайный вариант» — только если такие текстуры выбраны.
        // Анимированная текстура — вертикальная лента кадров у блока или предмета (или названная в списке анимаций).
        // Размер читается из заголовка файла, без загрузки картинки, и запоминается.
        bool AnimatedEntry(Entry e)
        {
            if (!Img.IsImage(e.Key)) return false;
            if (!e.Key.StartsWith("textures/blocks/") && !e.Key.StartsWith("textures/items/") && gallery.FlipTicks(e) <= 0) return false;
            foreach (Pack p in e.Sources)
            {
                if (!p.Files.ContainsKey(e.Key)) continue;
                string path = p.FullPath(e.Key);
                bool strip;
                if (!animKnown.TryGetValue(path, out strip))
                {
                    strip = false;
                    try
                    {
                        byte[] head = new byte[24];
                        int got;
                        using (FileStream fs = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.ReadWrite)) got = fs.Read(head, 0, 24);
                        int w = 0, h = 0;
                        if (got == 24 && head[0] == 0x89 && head[1] == 'P' && head[2] == 'N' && head[3] == 'G')
                        {
                            w = (head[16] << 24) | (head[17] << 16) | (head[18] << 8) | head[19];
                            h = (head[20] << 24) | (head[21] << 16) | (head[22] << 8) | head[23];
                        }
                        else if (got >= 18 && path.EndsWith(".tga", StringComparison.OrdinalIgnoreCase))
                        {
                            w = head[12] | (head[13] << 8);
                            h = head[14] | (head[15] << 8);
                        }
                        strip = w > 0 && h > w && h % w == 0;
                    }
                    catch (Exception) { }
                    animKnown[path] = strip;
                }
                if (strip) return true;
            }
            return false;
        }

        void UpdateToggles()
        {
            if (scopeOff != (entries.Count == 0))
            {
                scopeOff = entries.Count == 0;
                if (scopeLook != null) scopeLook();
            }
            bool layers = false, random = false, dup = false, single = false, anim = false;
            foreach (Entry e in entries)
            {
                if (!anim && !e.Hidden && AnimatedEntry(e)) anim = true;
                if (e.Attrs != null && e.Attrs.Count > 0) layers = true;
                if (Multi(e)) random = true;
                if (e.Hidden) continue;
                if (e.Sources.Count > 1) dup = true; else single = true;
            }
            // кнопка отбора нужна, только когда ей есть что отбирать: «Дубликаты» — если есть текстуры сразу в нескольких пакетах,
            // «Один вариант» — если есть и такие, и единственные, «Выбранный пакет» — если пакетов больше одного
            bool wantDup = dup, wantSingle = dup && single, wantPack = packs.Count > 1;
            if (!wantPack && scopePack && !onlyPack.Checked)
            {
                scopePack = false;
                scopeBtn.Text = L.T("Все текстуры");
            }
            if ((onlyChoice.Checked && !wantDup) || (onlySingle.Checked && !wantSingle) || (onlyPack.Checked && !wantPack))
            {
                // нажатая кнопка исчезает — отбор возвращается на «Все текстуры»
                onlyChoice.Checked = onlySingle.Checked = onlyPack.Checked = false;
                allTextures.Checked = true;
            }
            if (!anim && onlyAnim.Checked)
            {
                onlyAnim.Checked = false;
                allTextures.Checked = true;
            }
            bool rowChanged = wantDup != dupShown || wantSingle != singleShown || wantPack != packShown || anim != animShown
                || onlyChoice.Visible != wantDup || onlySingle.Visible != wantSingle || onlyAnim.Visible != anim;
            animShown = anim;
            onlyAnim.Visible = anim;
            dupShown = wantDup;
            singleShown = wantSingle;
            packShown = wantPack;
            onlyChoice.Visible = wantDup;
            onlySingle.Visible = wantSingle;
            if (!random && onlyRandom.Checked)
            {
                // последний случайный вариант сняли — показываем снова все текстуры
                onlyRandom.Checked = false;
                allTextures.Checked = true;
            }
            if (!rowChanged && layers == layersShown && random == randomShown && showAttrs.Visible == layers && onlyRandom.Visible == random) return;
            layersShown = layers;
            randomShown = random;
            showAttrs.Visible = layers;
            onlyRandom.Visible = random;
            if (layoutFilters != null) layoutFilters();
        }

        // Сравнение имён с учётом чисел: stage_2 идёт раньше stage_10.
        static int Natural(string a, string b)
        {
            int i = 0, j = 0;
            while (i < a.Length && j < b.Length)
            {
                if (char.IsDigit(a[i]) && char.IsDigit(b[j]))
                {
                    int si = i, sj = j;
                    while (i < a.Length && char.IsDigit(a[i])) i++;
                    while (j < b.Length && char.IsDigit(b[j])) j++;
                    string na = a.Substring(si, i - si).TrimStart('0'), nb = b.Substring(sj, j - sj).TrimStart('0');
                    if (na.Length != nb.Length) return na.Length.CompareTo(nb.Length);
                    int byDigits = string.CompareOrdinal(na, nb);
                    if (byDigits != 0) return byDigits;
                    continue;
                }
                if (a[i] != b[j]) return a[i].CompareTo(b[j]);
                i++;
                j++;
            }
            return (a.Length - i).CompareTo(b.Length - j);
        }

        static bool NeedsChoice(Entry e)
        {
            return e.Sources.Count > 1 && !e.AutoMerge && !e.Locked;
        }

        static string NodeText(string name, int count, int choice)
        {
            return L.T(name) + "   " + count + (choice > 0 ? L.T("   ·   с выбором: ") + choice : "");
        }

        // Дерево типов и категорий со счётчиками: всего файлов и сколько из них есть в нескольких паках.
        void FillTree()
        {
            int n = Sorter.Types.Length;
            int[] count = new int[n], choice = new int[n];
            int[][] subCount = new int[n][], subChoice = new int[n][];
            for (int t = 0; t < n; t++)
            {
                string[] names = Sorter.SubNames(t);
                subCount[t] = new int[names == null ? 1 : names.Length];
                subChoice[t] = new int[subCount[t].Length];
            }
            foreach (Entry e in entries)
            {
                if (e.Hidden) continue;
                int t = Sorter.TypeOf(e.Key), s = Sorter.SubOf(e.Key, t), ch = NeedsChoice(e) ? 1 : 0;
                count[t]++;
                choice[t] += ch;
                subCount[t][s]++;
                subChoice[t][s] += ch;
                if (t != Sorter.Other) { count[Sorter.All]++; choice[Sorter.All] += ch; }
            }
            suppress = true;
            tree.BeginUpdate();
            tree.Nodes.Clear();
            TreeNode pick = null;
            for (int t = 0; t < n; t++)
            {
                if (t != Sorter.All && count[t] == 0) continue;
                TreeNode node = tree.Nodes.Add(t == Sorter.All ? CounterText() : NodeText(Sorter.Types[t], count[t], choice[t]));
                node.Tag = t.ToString();
                if ((string)node.Tag == selNode) pick = node;
                string[] names = Sorter.SubNames(t);
                for (int s = 0; names != null && s < names.Length; s++)
                {
                    if (subCount[t][s] == 0) continue;
                    TreeNode sub = node.Nodes.Add(NodeText(names[s], subCount[t][s], subChoice[t][s]));
                    sub.Tag = t + ":" + s;
                    if ((string)sub.Tag == selNode) pick = sub;
                }
            }
            if (favPack != null)
            {
                // пока избранное показано, под счётчиком стоят его папки: свои, созданные пользователем
                Dictionary<string, int> inFolder = new Dictionary<string, int>();
                int favTotal = 0;
                foreach (Entry e in entries)
                {
                    if (e.Hidden || !Favorites.Has(e.Key)) continue;
                    favTotal++;
                    string f = Favorites.FolderOf(e.Key);
                    if (f == null) continue;
                    int c;
                    inFolder.TryGetValue(f, out c);
                    inFolder[f] = c + 1;
                }
                TreeNode root = tree.Nodes.Insert(1, L.T("Папки избранного") + "   " + favTotal);
                root.Tag = "f";
                if (selNode == "f") pick = root;
                foreach (string f in Favorites.Folders)
                {
                    int c;
                    inFolder.TryGetValue(f, out c);
                    TreeNode fn = root.Nodes.Add(f + "   " + c);
                    fn.Tag = "f:" + f;
                    if ((string)fn.Tag == selNode) pick = fn;
                }
                root.Nodes.Add(L.T("+  Новая папка…")).Tag = "f+";
            }
            tree.ExpandAll();
            if (pick == null) { pick = tree.Nodes[0]; selNode = "0"; }
            tree.SelectedNode = pick;
            tree.EndUpdate();
            suppress = false;
        }

        void ApplyFilter()
        {
            // «f» — всё избранное, «f:название» — одна его папка; иначе номер типа и, через двоеточие, категории
            bool favNode = selNode.StartsWith("f");
            string favFolder = favNode && selNode.Length > 2 ? selNode.Substring(2) : null;
            string[] sel = favNode ? new string[] { Sorter.All.ToString() } : selNode.Split(':');
            int selType = int.Parse(sel[0]), selSub = sel.Length > 1 ? int.Parse(sel[1]) : -1;
            string f = filterBox.Text.Trim().ToLowerInvariant();
            // пакет, выделенный в списке слева, — для кнопки «Выбранный пакет»
            Pack chosen = packList.SelectedIndex >= 0 && packList.SelectedIndex < packs.Count ? packs[packList.SelectedIndex] : null;
            if (trashView && chosen != null && !shadowOf.TryGetValue(chosen, out chosen)) chosen = null; // в корзине — её «тень»
            List<KeyValuePair<int, Entry>> shown = new List<KeyValuePair<int, Entry>>();
            foreach (Entry e in entries)
            {
                if (e.Hidden) continue;
                int t = Sorter.TypeOf(e.Key), s = Sorter.SubOf(e.Key, t);
                if (favNode)
                {
                    if (!Favorites.Has(e.Key) || (favFolder != null && Favorites.FolderOf(e.Key) != favFolder)) continue;
                }
                else if (selType == Sorter.All ? t == Sorter.Other : t != selType) continue;
                if (selSub >= 0 && s != selSub) continue;
                if (onlyChoice.Checked && e.Sources.Count < 2) continue;
                if (onlySingle.Checked && e.Sources.Count != 1) continue;
                if (onlyRandom.Checked && !Multi(e)) continue;
                if (onlyAnim.Checked && !AnimatedEntry(e)) continue;
                if (onlyPack.Checked && (chosen == null || !(e.Sources.Contains(chosen) || (chosen.Sub != null && e.Sources.Contains(chosen.Sub))))) continue;
                if (f.Length > 0 && !Found(e, f, t, s)) continue;
                shown.Add(new KeyValuePair<int, Entry>(t * 100 + s, e));
            }
            shown.Sort(delegate(KeyValuePair<int, Entry> a, KeyValuePair<int, Entry> b)
            {
                if (a.Key != b.Key) return a.Key.CompareTo(b.Key);
                // стороны и стадии одного объекта идут подряд
                int byObject = string.CompareOrdinal(Gallery.GroupKey(a.Value.Key), Gallery.GroupKey(b.Value.Key));
                return byObject != 0 ? byObject : Natural(a.Value.Key, b.Value.Key);
            });
            Dictionary<int, int> typeCount = new Dictionary<int, int>(), subCount = new Dictionary<int, int>();
            foreach (KeyValuePair<int, Entry> kv in shown)
            {
                int c;
                typeCount.TryGetValue(kv.Key / 100, out c);
                typeCount[kv.Key / 100] = c + 1;
                subCount.TryGetValue(kv.Key, out c);
                subCount[kv.Key] = c + 1;
            }
            gallery.OnlyPack = onlyPack.Checked ? chosen : null;
            gallery.FavPack = favPack;
            gallery.FavView = favPack != null && (favNode || (onlyPack.Checked && chosen == favPack));
            // Разделы свёрнуты, пока их не развернут щелчком; при поиске всё найденное показывается сразу.
            bool all = f.Length > 0;
            List<object> items = new List<object>();
            int last = -1;
            bool typeOpen = true, subOpen = true;
            foreach (KeyValuePair<int, Entry> kv in shown)
            {
                int t = kv.Key / 100, s = kv.Key % 100;
                string[] names = Sorter.SubNames(t);
                if (last < 0 || last / 100 != t)
                {
                    typeOpen = true;
                    if (selType == Sorter.All)
                    {
                        typeOpen = all || expanded.Contains(t.ToString());
                        items.Add(MakeHead(t.ToString(), Sorter.Types[t], true, typeOpen, typeCount[t]));
                    }
                }
                if (kv.Key != last)
                {
                    subOpen = true;
                    if (typeOpen && names != null && selSub < 0)
                    {
                        subOpen = all || expanded.Contains(t + ":" + s);
                        items.Add(MakeHead(t + ":" + s, names[s], false, subOpen, subCount[kv.Key]));
                    }
                }
                last = kv.Key;
                if (typeOpen && subOpen) items.Add(kv.Value);
            }
            gallery.EmptyText = packs.Count > 0 ? L.T("Ничего не найдено.\nИзмените поиск или отбор.") : null;
            gallery.SetItems(items);
            shownItems = items;
            objView.AllEntries = entries;
            if (mode3D) objView.SetItems(items);
            objView.Visible = mode3D && items.Count > 0;
            if (objView.Visible) objView.BringToFront();
        }

        static Head MakeHead(string key, string title, bool big, bool open, int count)
        {
            Head h = new Head();
            h.Key = key;
            h.Title = L.T(title);
            h.Big = big;
            h.Open = open;
            h.Count = count;
            return h;
        }

        static string TexKey(Entry e)
        {
            return e.Key.Substring(0, e.Key.Length - Path.GetExtension(e.Key).Length);
        }

        // Подходит ли текстура под строку поиска: имя файла, название объекта в игре (на русском или английском),
        // название пакета или раздела.
        static bool Found(Entry e, string find, int type, int sub)
        {
            if (e.Key.IndexOf(find, StringComparison.Ordinal) >= 0) return true;
            if (Img.IsImage(e.Key) && GameNames.Matches(TexKey(e), find)) return true;
            foreach (Pack p in e.Sources) if (p.Name.ToLowerInvariant().Contains(find)) return true;
            if (L.Both(Sorter.Types[type]).Contains(find)) return true;
            string[] subs = Sorter.SubNames(type);
            return subs != null && L.Both(subs[sub]).Contains(find);
        }

        // ---------------------------------------------------------- избранное

        // Кнопка «Избранное»: сохранённые текстуры появляются в списке как пакет и показываются в витрине.
        void ToggleFavorites()
        {
            if (favBusy) return;
            bool favClean = Unchanged();
            if (trashView) SetTrashView(false); // вместе с показом корзины из витрины уходят и её «тени»
            favBusy = true;
            try
            {
                if (favBtn.Checked)
                {
                    if (Favorites.Count == 0)
                    {
                        MessageBox.Show(this, L.T("В избранном пока ничего нет.\nНажмите звезду перед названием текстуры, чтобы сохранить её."),
                            Text, MessageBoxButtons.OK, MessageBoxIcon.Information);
                        favBtn.Checked = false;
                        return;
                    }
                    List<Pack> found = PackLoader.Load(Favorites.Dir, new List<string>());
                    favPack = found[0];
                    favPack.Name = L.T("Избранное");
                    // в конец списка: избранное не перебивает текстуры загруженных пакетов, пока его вариант не выбран нарочно
                    packs.Add(favPack);
                    Rebuild();
                    FavCarriers();
                    packList.SelectedIndex = packs.Count - 1;
                    SetFilter(onlyPack);
                }
                else if (favPack != null)
                {
                    // выделение остаётся на том же пакете, а не съезжает на соседний
                    int si = packList.SelectedIndex;
                    Pack sel = si >= 0 && si < packs.Count ? packs[si] : null;
                    packs.Remove(favPack);
                    favPack = null;
                    PruneChoices();
                    SetFilter(allTextures);
                    Rebuild();
                    int ni = sel == null ? -1 : packs.IndexOf(sel);
                    if (ni >= 0 && ni != packList.SelectedIndex) packList.SelectedIndex = ni;
                }
            }
            catch (Exception ex)
            {
                if (favPack == null) favBtn.Checked = false;
                MessageBox.Show(this, ex.Message, Text, MessageBoxButtons.OK, MessageBoxIcon.Warning);
            }
            finally
            {
                favBusy = false;
                if (favClean) cleanSig = TakeSnapshot().Sig; // показ избранного сам по себе не повод спрашивать о сохранении проекта
            }
        }

        void SetFilter(CheckBox on)
        {
            foreach (CheckBox b in new CheckBox[] { allTextures, onlyChoice, onlySingle, onlyPack, onlyRandom, onlyAnim }) b.Checked = b == on;
            ApplyFilter();
        }

        // После изменения избранного: если оно показано пакетом, его содержимое перечитывается.
        void FavChanged()
        {
            if (favPack != null)
            {
                favPack.Scan();
                gallery.ClearCache();
                Rebuild();
                FavCarriers();
            }
            else gallery.Invalidate();
        }

        // В избранное сохранён только слой, а сама текстура лежит там лишь как его основа: в пакете «Избранное»
        // такая текстура выключена (берётся из другого пакета, если он есть), а сохранённые слои включены.
        // Сделанный руками выбор не трогается.
        void FavCarriers()
        {
            if (favPack == null) return;
            bool changed = false;
            foreach (Entry e in entries)
            {
                // если текстура есть и в другом загруженном пакете, избранное ничего не меняет в выборе
                if (e.Sources.Count != 1 || !e.Sources.Contains(favPack) || !Favorites.Has(e.Key) || Favorites.TextureSaved(e.Key)) continue;
                List<KeyValuePair<string, string>> layers;
                if (e.Attrs == null || !e.Attrs.TryGetValue(favPack, out layers) || layers.Count == 0) continue;
                if (!overrides.ContainsKey(e.Key))
                {
                    Pack other = e.Sources.Find(delegate(Pack q) { return q != favPack; });
                    overrides[e.Key] = other ?? Pack.Off;
                    changed = true;
                }
                foreach (KeyValuePair<string, string> l in layers)
                {
                    string slot = e.Key + "|" + Builder.SlotOf(l.Key);
                    if (slotChoice.ContainsKey(slot)) continue;
                    slotChoice[slot] = favPack;
                    changed = true;
                }
            }
            if (changed) Recollect();
        }

        // Запись в избранное: занятый файл или пропавший пакет — сообщение, а не падение.
        void FavDo(MethodInvoker act)
        {
            try { act(); }
            catch (Exception ex) { MessageBox.Show(this, ex.Message, Text, MessageBoxButtons.OK, MessageBoxIcon.Warning); }
            try { FavChanged(); }
            catch (Exception ex) { MessageBox.Show(this, ex.Message, Text, MessageBoxButtons.OK, MessageBoxIcon.Warning); }
        }

        // Звезда на карточке. У текстуры со слоями меню спрашивает, что именно сохранить.
        void FavMenu(Entry e, Pack p)
        {
            List<KeyValuePair<string, string>> layers;
            if (e.Attrs == null || !e.Attrs.TryGetValue(p, out layers)) layers = new List<KeyValuePair<string, string>>();
            bool has = Favorites.Has(e.Key);
            if (!has && layers.Count == 0)
            {
                FavDo(delegate { Favorites.Add(p, e, true, null); });
                return;
            }
            ContextMenuStrip m = NewMenu();
            if (has)
            {
                ToolStripMenuItem del = new ToolStripMenuItem(L.T("Убрать из избранного"));
                del.Click += delegate { FavDo(delegate { Favorites.Remove(e.Key); }); };
                m.Items.Add(del);
                if (layers.Count > 0) m.Items.Add(new ToolStripSeparator());
            }
            if (layers.Count > 0)
            {
                ToolStripMenuItem tex = new ToolStripMenuItem(L.T("Сохранить в избранное: текстуру"));
                tex.Click += delegate { FavDo(delegate { Favorites.Add(p, e, true, null); }); };
                m.Items.Add(tex);
                foreach (KeyValuePair<string, string> l in layers)
                {
                    List<KeyValuePair<string, string>> one = new List<KeyValuePair<string, string>>();
                    one.Add(l);
                    ToolStripMenuItem it = new ToolStripMenuItem(L.T("Сохранить в избранное: слой «") + Builder.LayerTitle(l.Key) + "»");
                    it.Click += delegate { FavDo(delegate { Favorites.Add(p, e, false, one); }); };
                    m.Items.Add(it);
                }
                ToolStripMenuItem all = new ToolStripMenuItem(L.T("Сохранить в избранное: всё вместе"));
                all.Click += delegate { FavDo(delegate { Favorites.Add(p, e, true, layers); }); };
                m.Items.Add(all);
            }
            m.Show(Cursor.Position);
        }

        // ---------------------------------------------------------- проект

        static Bitmap FolderIcon()
        {
            Bitmap b = new Bitmap(16, 16, PixelFormat.Format32bppArgb);
            using (Graphics g = Graphics.FromImage(b))
            using (SolidBrush back = new SolidBrush(Color.FromArgb(196, 150, 60)))
            using (SolidBrush front = new SolidBrush(Color.FromArgb(232, 186, 88)))
            {
                g.FillRectangle(back, 1, 3, 6, 3);   // язычок папки
                g.FillRectangle(back, 1, 5, 14, 9);
                g.FillRectangle(front, 1, 7, 14, 7);
            }
            return b;
        }

        // Пакет в файле проекта записан номером в списке: "2" — сам пакет, "2s" — его выбранный вариант, "off" — выключено.
        static string PackRef(List<Pack> list, Pack p)
        {
            if (p == Pack.Off) return "off";
            for (int i = 0; i < list.Count; i++)
            {
                if (list[i] == p) return i.ToString();
                if (list[i] != null && list[i].Sub == p) return i + "s";
            }
            return null;
        }

        static Pack PackOf(List<Pack> list, string r)
        {
            if (r == null) return null;
            if (r == "off") return Pack.Off;
            bool sub = r.EndsWith("s");
            int i;
            if (!int.TryParse(sub ? r.Substring(0, r.Length - 1) : r, out i) || i < 0 || i >= list.Count || list[i] == null) return null;
            return sub ? list[i].Sub : list[i];
        }

        static JObj MapOut(Dictionary<string, Pack> map, List<Pack> list)
        {
            JObj o = new JObj();
            foreach (KeyValuePair<string, Pack> kv in map)
            {
                string r = PackRef(list, kv.Value);
                if (r != null) o.Set(kv.Key, r);
            }
            return o;
        }

        static void MapIn(object saved, Dictionary<string, Pack> map, List<Pack> list)
        {
            map.Clear();
            JObj o = saved as JObj;
            if (o == null) return;
            foreach (string k in o.Keys)
            {
                Pack p = PackOf(list, o.Map[k] as string);
                if (p != null) map[k] = p;
            }
        }

        // Возвращает false, если проект не сохранён: пользователь закрыл окно выбора файла или запись не удалась.
        bool SaveProject()
        {
            using (SaveFileDialog d = new SaveFileDialog())
            {
                d.Filter = L.T("Проект Resource Pack Constructor (*.brpc)|*.brpc");
                string safe = PackName();
                foreach (char c in Path.GetInvalidFileNameChars()) safe = safe.Replace(c, '_');
                d.FileName = safe + ".brpc";
                if (projectFile != null)
                {
                    // открытый проект предлагается сохранить в тот же файл, а не в новый рядом
                    d.FileName = Path.GetFileName(projectFile);
                    try { d.InitialDirectory = Path.GetDirectoryName(projectFile); } catch (Exception) { }
                }
                if (d.ShowDialog(this) != DialogResult.OK) return false;
                try
                {
                    SaveProjectTo(d.FileName);
                    ShowProject(d.FileName);
                    cleanSig = TakeSnapshot().Sig;
                    status.Text = L.T("Проект сохранён: ") + d.FileName;
                    return true;
                }
                catch (Exception ex)
                {
                    MessageBox.Show(this, L.T("Не удалось сохранить проект:\n") + ex.Message, Text, MessageBoxButtons.OK, MessageBoxIcon.Error);
                    return false;
                }
            }
        }

        // В проекте хранятся не сами пакеты, а пути к ним и всё, что выбрано: порядок, варианты, текстуры, слои.
        void SaveProjectTo(string file)
        {
            JObj root = new JObj();
            root.Set("format", new JLit("1"));
            root.Set("name", nameBox.Text.Trim());
            List<object> list = new List<object>();
            foreach (Pack p in packs)
            {
                JObj o = new JObj();
                o.Set("path", p.Origin ?? p.Root);
                o.Set("index", new JLit(p.OriginIndex.ToString()));
                o.Set("name", p.Name);
                o.Set("variant", p.SubFolder ?? "");
                if (p == favPack) o.Set("fav", "1"); // при открытии снова станет «Избранным», а не обычным пакетом
                list.Add(o);
            }
            root.Set("packs", list);
            root.Set("textures", MapOut(overrides, packs));
            root.Set("layerSets", MapOut(pbrChoice, packs));
            root.Set("layers", MapOut(slotChoice, packs));
            JObj vars = new JObj();
            foreach (KeyValuePair<string, List<Variant>> kv in variants)
            {
                List<object> arr = new List<object>();
                foreach (Variant v in kv.Value)
                {
                    string pr = PackRef(packs, v.P);
                    if (pr == null) continue;
                    JObj jo = new JObj();
                    jo.Set("pack", pr);
                    jo.Set("mer", (v.Mer == null ? null : PackRef(packs, v.Mer)) ?? "");
                    jo.Set("relief", (v.Relief == null ? null : PackRef(packs, v.Relief)) ?? "");
                    arr.Add(jo);
                }
                if (arr.Count > 0) vars.Set(kv.Key, arr);
            }
            root.Set("variants", vars);
            // корзина: иначе убранные текстуры после открытия проекта молча вернулись бы в список и в сборку
            List<object> trashOut = new List<object>();
            foreach (TrashItem ti in trashLog)
            {
                string tref = PackRef(packs, ti.P);
                if (tref == null) continue;
                JObj tj = new JObj();
                tj.Set("pack", tref);
                tj.Set("title", ti.Title ?? "");
                List<object> tkeys = new List<object>();
                foreach (string tk in ti.Keys) tkeys.Add(tk);
                tj.Set("keys", tkeys);
                trashOut.Add(tj);
            }
            root.Set("trash", trashOut);
            List<object> open = new List<object>();
            foreach (string k in expanded) open.Add(k);
            root.Set("expanded", open);
            File.WriteAllText(file, Json.Write(root) + "\n", new UTF8Encoding(false));
        }

        void OpenProjectDialog()
        {
            using (OpenFileDialog d = new OpenFileDialog())
            {
                d.Filter = L.T("Проект Resource Pack Constructor (*.brpc)|*.brpc");
                if (d.ShowDialog(this) == DialogResult.OK) OpenProject(d.FileName);
            }
        }

        // Путь на дисках этого компьютера: «C:\…». Сетевые («\\компьютер\…»), адреса и неполные пути — нет.
        static bool LocalPath(string path)
        {
            if (path.Length < 3 || path.IndexOf("://", StringComparison.Ordinal) >= 0) return false;
            char d = char.ToUpperInvariant(path[0]);
            return d >= (char)65 && d <= (char)90 && path[1] == (char)58 && (path[2] == (char)92 || path[2] == (char)47);
        }

        public void OpenProject(string file)
        {
            if (packs.Count > 0 && MessageBox.Show(this, L.T("Открыть проект? Загруженные сейчас пакеты и выбор будут заменены."), Text,
                MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes) return;
            AskSave(); // пока файлы прежних пакетов ещё на месте
            try
            {
                Cursor = Cursors.WaitCursor;
                Pack fav = null;
                JObj root = Json.Parse(File.ReadAllText(file)) as JObj;
                List<object> saved = root == null ? null : root.Get("packs") as List<object>;
                if (saved == null) throw new FormatException(Path.GetFileName(file));
                List<string> notes = new List<string>();
                List<Pack> byNumber = new List<Pack>(); // по номерам из файла; null — пакет не нашёлся
                // источник, из которого в проекте несколько пакетов (папка с пакетами, .mcaddon), читается один раз
                Dictionary<string, List<Pack>> loadedOnce = new Dictionary<string, List<Pack>>(StringComparer.OrdinalIgnoreCase);
                foreach (object so in saved)
                {
                    JObj o = so as JObj;
                    string path = o == null ? null : o.Get("path") as string;
                    bool isFav = o != null && o.Get("fav") != null;
                    if (isFav) path = Favorites.Dir;
                    // файл проекта могли прислать: путь к чужому компьютеру в сети («\\компьютер\папка») или неполный путь
                    // не открывается — программа не должна сама обращаться к сетевым папкам
                    if (!isFav && path != null && !LocalPath(path))
                    {
                        notes.Add(L.T("Пропущен путь не с этого компьютера или неполный: ") + path);
                        byNumber.Add(null);
                        continue;
                    }
                    Pack p = null;
                    try
                    {
                        List<Pack> found;
                        if (path == null || !loadedOnce.TryGetValue(path, out found))
                        {
                            found = PackLoader.Load(path, notes);
                            if (path != null) loadedOnce[path] = found;
                        }
                        int index;
                        int.TryParse(o.Get("index") is JLit ? ((JLit)o.Get("index")).Raw : "0", out index);
                        if (index < 0) index = 0;
                        p = found.Count > index ? found[index] : (found.Count > 0 ? found[0] : null);
                        if (p != null && byNumber.Contains(p))
                        {
                            // один и тот же пакет записан в проекте дважды: второй строке нужен свой экземпляр
                            found = PackLoader.Load(path, notes);
                            p = found.Count > index ? found[index] : (found.Count > 0 ? found[0] : null);
                        }
                    }
                    catch (Exception) { }
                    if (p == null) notes.Add(L.T("Не найден пакет: ") + (o == null || string.IsNullOrEmpty(o.Get("name") as string) ? "" : (o.Get("name") as string) + "  —  ") + path);
                    else
                    {
                        string variant = o.Get("variant") as string;
                        p.SetSub(string.IsNullOrEmpty(variant) ? null : variant);
                        if (isFav && fav == null)
                        {
                            fav = p;
                            p.Name = L.T("Избранное");
                        }
                    }
                    byNumber.Add(p);
                }
                // ни один пакет проекта не нашёлся: открывать нечего, загруженное сейчас остаётся как было
                if (saved.Count > 0 && !byNumber.Exists(delegate(Pack q) { return q != null; }))
                    throw new FileNotFoundException(L.T("Ни один пакет проекта не найден.") + "\n" + string.Join("\n", notes.ToArray()));
                foreach (Pack old in packs)
                {
                    PackLoader.DropTemp(old.TempDir);
                    if (old.Icon != null) { old.Icon.Dispose(); old.Icon = null; }
                }
                packs.Clear();
                // корзина, одолженные и спрятанные слои относились к прежним пакетам
                trashLog.Clear();
                lent.Clear();
                hiddenOwn.Clear();
                shadowOf.Clear();
                shadowReal.Clear();
                trashView = false;
                gallery.TrashView = false;
                favPack = fav;
                favBusy = true;
                favBtn.Checked = fav != null;
                favBusy = false;
                foreach (Pack p in byNumber) if (p != null) packs.Add(p);
                ShowProject(file);
                MapIn(root.Get("textures"), overrides, byNumber);
                MapIn(root.Get("layerSets"), pbrChoice, byNumber);
                MapIn(root.Get("layers"), slotChoice, byNumber);
                variants.Clear();
                JObj vars = root.Get("variants") as JObj;
                if (vars != null)
                    foreach (string vk in vars.Keys)
                    {
                        List<object> arr = vars.Map[vk] as List<object>;
                        if (arr == null) continue;
                        List<Variant> vl = new List<Variant>();
                        foreach (object ao in arr)
                        {
                            JObj jo = ao as JObj;
                            Pack vp = jo == null ? null : PackOf(byNumber, jo.Get("pack") as string);
                            if (vp == null || vp == Pack.Off) continue;
                            Variant v = new Variant();
                            v.P = vp;
                            v.Mer = PackOf(byNumber, jo.Get("mer") as string);
                            v.Relief = PackOf(byNumber, jo.Get("relief") as string);
                            if (v.Mer == Pack.Off) v.Mer = null;
                            if (v.Relief == Pack.Off) v.Relief = null;
                            vl.Add(v);
                        }
                        if (vl.Count > 0) variants[vk] = vl;
                    }
                // корзина (в старых проектах её нет): файлы уходят из пакета так же, как при обычном удалении в корзину
                List<object> trashIn = root.Get("trash") as List<object>;
                if (trashIn != null)
                    foreach (object tio in trashIn)
                    {
                        JObj tj = tio as JObj;
                        Pack tp = tj == null ? null : PackOf(byNumber, tj.Get("pack") as string);
                        List<object> tkeys = tj == null ? null : tj.Get("keys") as List<object>;
                        if (tp == null || tp == Pack.Off || tkeys == null) continue;
                        TrashItem ti = new TrashItem();
                        ti.P = tp;
                        ti.Title = tj.Get("title") as string ?? "";
                        foreach (object tko in tkeys)
                        {
                            string tk = tko as string, trel;
                            if (tk == null || !tp.Files.TryGetValue(tk, out trel)) continue;
                            tp.Trash[tk] = trel;
                            tp.Files.Remove(tk);
                            ti.Keys.Add(tk);
                        }
                        if (ti.Keys.Count > 0) trashLog.Add(ti);
                    }
                expanded.Clear();
                List<object> open = root.Get("expanded") as List<object>;
                if (open != null) foreach (object k in open) if (k is string) expanded.Add((string)k);
                nameBox.Text = root.Get("name") as string ?? "";
                AfterTrash(); // обновляет витрину и список, как раньше, а заодно кнопку корзины
                cleanSig = TakeSnapshot().Sig;
                Cursor = Cursors.Default;
                Notify(notes);
            }
            catch (Exception ex)
            {
                Cursor = Cursors.Default;
                MessageBox.Show(this, L.T("Не удалось открыть проект:\n") + ex.Message, Text, MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        // ---------------------------------------------------------- файлы пака

        void SetMode()
        {
            bool files = modeFiles.Checked;
            if (!files) AskSave();
            tree.Visible = !files && !catsOff && !modePreview.Checked;
            fileTree.Visible = files;
            gallery.Visible = !files;
            galleryBar.Visible = !files;
            favBtn.Visible = !files; // «Избранное» относится к витрине; поиск работает в обоих режимах
            trashBtn.Visible = !files;
            viewer.Visible = files;
            if (files) { FillFiles(); UpdateViewer(); }
            else
            {
                status.Text = Legend;
                Recollect(); // файлы могли измениться в редакторе
            }
        }

        // Дерево файлов и папок пака, выбранного в списке сверху.
        string fileQuery = ""; // по какому запросу сейчас построен список файлов

        void FillFiles()
        {
            int i = packList.SelectedIndex;
            Pack p = i >= 0 && i < packs.Count ? packs[i] : null;
            string query = filterBox.Text.Trim().ToLowerInvariant();
            if (p == filesPack && query == fileQuery && fileTree.Nodes.Count > 0) return;
            if (p != filesPack)
            {
                // открытый файл закрывается только при смене пакета; поиск его не трогает
                AskSave();
                filesPack = p;
                CloseFile();
            }
            fileQuery = query;
            fileTree.BeginUpdate();
            fileTree.Nodes.Clear();
            if (p != null && query.Length > 0)
            {
                // поиск: вместо дерева папок — список найденных файлов с путями
                TreeNode root = fileTree.Nodes.Add(p.Name);
                root.Tag = "S";
                int found = 0;
                try
                {
                    string dir = p.Root.TrimEnd('\\', '/');
                    string[] all = Directory.GetFiles(dir, "*", SearchOption.AllDirectories);
                    Array.Sort(all, StringComparer.OrdinalIgnoreCase);
                    foreach (string file in all)
                    {
                        string rel = file.Substring(dir.Length + 1).Replace('\\', '/');
                        if (rel.ToLowerInvariant().IndexOf(query, StringComparison.Ordinal) < 0) continue;
                        if (++found > 500) continue; // длинный список не строим, только считаем
                        root.Nodes.Add(rel).Tag = "F|" + file;
                    }
                }
                catch (Exception ex) { root.Nodes.Add(L.T("не удалось прочитать: ") + ex.Message).Tag = "X"; }
                if (found == 0 && root.Nodes.Count == 0) root.Nodes.Add(L.T("Ничего не найдено")).Tag = "X";
                if (found > 500) root.Nodes.Add("…  +" + (found - 500)).Tag = "X";
                root.Text = p.Name + "   " + found;
                root.Expand();
            }
            else if (p != null)
            {
                TreeNode root = fileTree.Nodes.Add(p.Name);
                root.Tag = "D|" + p.Root;
                root.Nodes.Add("");
                root.Expand();
            }
            fileTree.EndUpdate();
        }

        // Папка заполняется при первом раскрытии, чтобы большие паки открывались сразу.
        void FillDir(TreeNode node)
        {
            string tag = node.Tag as string;
            if (tag == null || !tag.StartsWith("D|") || node.Nodes.Count != 1 || node.Nodes[0].Tag != null) return;
            node.Nodes.Clear();
            try
            {
                string dir = tag.Substring(2);
                string[] dirs = Directory.GetDirectories(dir), files = Directory.GetFiles(dir);
                Array.Sort(dirs, StringComparer.OrdinalIgnoreCase);
                Array.Sort(files, StringComparer.OrdinalIgnoreCase);
                foreach (string d in dirs)
                {
                    TreeNode n = node.Nodes.Add(Path.GetFileName(d));
                    n.Tag = "D|" + d;
                    n.NodeFont = new Font(fileTree.Font, FontStyle.Bold);
                    n.Nodes.Add("");
                }
                foreach (string file in files) node.Nodes.Add(Path.GetFileName(file)).Tag = "F|" + file;
            }
            catch (Exception ex) { node.Nodes.Add(L.T("не удалось прочитать: ") + ex.Message).Tag = "X"; }
        }

        void CloseFile()
        {
            viewPath = null;
            viewInfo = "";
            textDirty = false;
            imgView.SetImage(null);
            loading = true;
            editor.Text = "";
            editor.ReadOnly = true;
            loading = false;
            viewTitle.Text = L.T("Выберите файл в списке слева");
            imgScroll.Visible = false;
            editor.Visible = true;
            UpdateViewer();
        }

        void OpenFile(string path)
        {
            if (path == viewPath) return;
            AskSave();
            CloseFile();
            viewPath = path;
            bool isImg = Img.IsImage(path);
            loading = true;
            try
            {
                long size = new FileInfo(path).Length;
                viewInfo = size < 10240 ? size + L.T(" байт") : (size / 1024) + L.T(" КБ");
                if (isImg)
                {
                    Bitmap b = Img.Load(path);
                    imgView.SetImage(b);
                    // область просмотра должна получить свой настоящий размер до подбора масштаба
                    editor.Visible = false;
                    imgScroll.Visible = true;
                    viewer.PerformLayout();
                    imgView.Fit(imgScroll.ClientSize);
                    viewInfo = b.Width + "×" + b.Height + ",  " + viewInfo;
                }
                else
                {
                    // большой файл не читается в память целиком только ради того, чтобы сказать, что он не текстовый
                    byte[] data = size > 4000000 ? new byte[0] : File.ReadAllBytes(path);
                    bool binary = size > 4000000;
                    for (int i = 0; !binary && i < data.Length && i < 8000; i++) if (data[i] == 0) binary = true;
                    if (binary) editor.Text = L.T("Этот файл не текстовый, показать его здесь нельзя.\r\nЕго можно открыть кнопкой «Открыть в другой программе».");
                    else
                    {
                        string t = File.ReadAllText(path);
                        textCrLf = t.Contains("\r\n");
                        editor.Text = t.Replace("\r\n", "\n").Replace("\n", "\r\n");
                        editor.ReadOnly = false;
                    }
                }
            }
            catch (Exception ex)
            {
                isImg = false;
                editor.Text = L.T("Не удалось открыть файл: ") + ex.Message;
            }
            loading = false;
            textDirty = false;
            imgScroll.Visible = isImg;
            editor.Visible = !isImg;
            string root = filesPack == null ? "" : filesPack.Root.TrimEnd('\\', '/');
            viewTitle.Text = root.Length > 0 && path.StartsWith(root) ? path.Substring(root.Length + 1).Replace('\\', '/') : Path.GetFileName(path);
            UpdateViewer();
        }

        void UpdateViewer()
        {
            bool img = imgScroll.Visible && imgView.Image != null;
            viewSave.Enabled = textDirty;
            zoomOut.Enabled = zoomIn.Enabled = zoomFit.Enabled = img;
            viewOpen.Enabled = viewPath != null;
            if (!viewer.Visible) return;
            if (viewPath == null) { status.Text = L.T("Щёлкните пак в списке сверху, затем файл в дереве слева: текст можно править, картинки — рассматривать крупно (Ctrl+колесо меняет масштаб)."); return; }
            status.Text = viewTitle.Text + "   —   " + viewInfo + (img ? L.T(",  масштаб ×") + imgView.Zoom : "") + (textDirty ? L.T("   |   не сохранено") : "");
        }

        void SaveText()
        {
            if (viewPath == null || !textDirty) return;
            try
            {
                string t = editor.Text;
                if (!textCrLf) t = t.Replace("\r\n", "\n");
                File.WriteAllText(viewPath, t, new UTF8Encoding(false));
                textDirty = false;
                UpdateViewer();
                string ext = Path.GetExtension(viewPath).ToLowerInvariant();
                if (ext == ".json" || ext == ".material")
                {
                    // подсказка, а не запрет: файл сохранён в любом случае
                    try { Json.Parse(t); status.Text += L.T("   |   сохранено, JSON читается"); }
                    catch (Exception ex) { status.Text += L.T("   |   сохранено, но в JSON ошибка: ") + ex.Message; }
                }
                else status.Text += L.T("   |   сохранено");
                if (filesPack != null && filesPack.TempDir != null)
                    status.Text += L.T("   |   пакет из архива: правка действует до закрытия программы (в сборку попадёт)");
                // правленый файл мог быть моделью или описанием сущности: 3D-модели читаются заново
                if (ext == ".json")
                {
                    Geo.Forget();
                    if (Geo.SetPacks(packs)) gallery.ClearCache();
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show(this, L.T("Не удалось сохранить:\n") + ex.Message, Text, MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        void AskSave()
        {
            if (!textDirty || viewPath == null) return;
            if (MessageBox.Show(this, L.T("Сохранить изменения в ") + Path.GetFileName(viewPath) + "?", Text,
                MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes)
            {
                SaveText(); // при неудаче правка остаётся несохранённой, а не пропадает
                return;
            }
            textDirty = false;
        }

        // Пакеты, из которых в сборку попал хотя бы один файл, в порядке списка.
        List<Pack> Contributors()
        {
            HashSet<Pack> used = new HashSet<Pack>();
            foreach (Entry e in entries)
            {
                if (e.Excluded || e.Orphan) continue;
                if (e.AutoMerge) foreach (Pack src in e.Sources) used.Add(src);
                else used.Add(e.Winner);
            }
            List<Pack> r = new List<Pack>();
            foreach (Pack p in packs)
                if (used.Contains(p) || (p.Sub != null && used.Contains(p.Sub))) r.Add(p);
            return r;
        }

        // ---------------------------------------------------------- сборка

        void Export()
        {
            SetTrashView(false); // сборка идёт из обычного списка, а не из корзины
            AskSave(); // сборка читает файлы с диска: несохранённая правка текста в неё не попала бы
            if (packs.Count == 0)
            {
                MessageBox.Show(this, L.T("Сначала добавьте хотя бы один пак."), Text, MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }
            if (!entries.Exists(delegate(Entry x) { return !x.Excluded && !x.Orphan; }))
            {
                MessageBox.Show(this, L.T("В сборке нет ни одного файла: все текстуры выключены или убраны в корзину."), Text, MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }
            List<string> borrowed = new List<string>();
            foreach (Entry e in entries)
            {
                if (e.LayersOnly)
                {
                    borrowed.Add(e.Rel + "   —   " + L.T("только слои, без самой текстуры — игре нужна картинка цвета в том же пакете, поэтому слои могут не примениться"));
                    continue;
                }
                if (!e.PbrAuto || e.Excluded || e.Slots == null || e.Slots.Count == 0) continue;
                List<string> kinds = new List<string>();
                foreach (string slot in e.Slots.Keys) kinds.Add(slot == "mer" ? L.T("отражения и свечение") : L.T("рельеф"));
                borrowed.Add(e.Rel + "   —   " + string.Join(", ", kinds.ToArray()) + L.T(" — из «") + e.PbrChoice.Name + "»");
            }
            if (borrowed.Count > 0 && !ConfirmBorrowed(borrowed)) return;
            // Название берётся из поля наверху, а если оно пустое — стандартное; описание — нумерованный список
            // пакетов, вошедших в сборку. Вводить ничего не нужно, остаётся выбрать, куда сохранить файл.
            string name = PackName(), file;
            List<string> parts = new List<string>();
            foreach (Pack p in Contributors()) parts.Add((parts.Count + 1) + ". " + p.Name);
            string desc = string.Join("\n", parts.ToArray());
            using (SaveFileDialog d = new SaveFileDialog())
            {
                d.Filter = L.T("Пак Minecraft (*.mcpack)|*.mcpack|Архив ZIP (*.zip)|*.zip");
                string safe = name;
                foreach (char c in Path.GetInvalidFileNameChars()) safe = safe.Replace(c, '_');
                d.FileName = safe + ".mcpack";
                if (d.ShowDialog(this) != DialogResult.OK) return;
                file = d.FileName;
                // имя с точкой («MyPack 1.21») окно сохранения оставляет без расширения, и сборка приняла бы его за папку
                string typedExt = Path.GetExtension(file).ToLowerInvariant();
                if (typedExt != ".mcpack" && typedExt != ".zip")
                {
                    file += d.FilterIndex == 2 ? ".zip" : ".mcpack";
                    if (File.Exists(file) && MessageBox.Show(this, Path.GetFileName(file) + "\n" + L.T("Такой файл уже есть. Заменить его?"), Text, MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes) return;
                }
            }
            try
            {
                string missing = null;
                foreach (Pack p in packs)
                {
                    if (p.TempDir != null) continue;
                    // папку могли менять снаружи; если она пропала, список на экране всё равно обновляется, а сборка останавливается ниже
                    try { p.Scan(); }
                    catch (Exception) { if (missing == null) missing = p.Name + "  —  " + (p.Origin ?? p.Root); }
                }
                gallery.ClearCache();
                Rebuild();
                if (missing != null) throw new DirectoryNotFoundException(L.T("Не найден пакет: ") + missing);
                Cursor = Cursors.WaitCursor;
                string statusWas = status.Text;
                status.Text = L.T("Идёт сборка…");
                status.Refresh();
                List<string> log;
                try { log = Builder.Build(entries, packs, name, desc, file, VariantsForBuild()); }
                finally { status.Text = statusWas; }
                Cursor = Cursors.Default;
                // сборка состоит из чужих работ: пользователь должен знать, что делиться ею можно только с разрешения авторов
                string msg = L.T("Пак сохранён:\n") + file + "\n\n" + string.Join("\n", log.ToArray())
                    + "\n\n" + L.T("Этот пакет собран из чужих работ. Он только для вашей игры. Выкладывать или передавать его можно только с разрешения авторов (они перечислены в папке credits внутри пакета).")
                    + L.T("\n\nПоказать файл в проводнике?");
                if (MessageBox.Show(this, msg, Text, MessageBoxButtons.YesNo, MessageBoxIcon.Information) == DialogResult.Yes)
                    Process.Start("explorer.exe", "/select,\"" + file + "\"");
            }
            catch (Exception ex)
            {
                Cursor = Cursors.Default;
                MessageBox.Show(this, L.T("Сборка не удалась:\n") + ex.Message
                    + (ex is DirectoryNotFoundException || ex is FileNotFoundException ? "\n\n" + L.T("Файлы пакета пропали (папка temp очищена или пакет перемещён). Добавьте пакет заново.") : ""),
                    Text, MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        protected override void OnKeyDown(KeyEventArgs e)
        {
            base.OnKeyDown(e);
            if (e.Control && e.KeyCode == Keys.S && viewer.Visible)
            {
                SaveText();
                e.SuppressKeyPress = true;
            }
        }

        protected override void OnFormClosing(FormClosingEventArgs e)
        {
            // Открытый редактор текстуры (окно, принадлежащее этому) к этой минуте уже задал свой вопрос о несохранённом.
            // Если там нажали «Отмена», программа не закрывается, и остальные вопросы не задаются.
            if (e.Cancel && texEditor != null)
            {
                userClose = false;
                base.OnFormClosing(e);
                return;
            }
            AskSave();
            base.OnFormClosing(e);
            if (e.Cancel) return;
            // выбор изменился после загрузки или последнего сохранения проекта: без вопроса он пропал бы молча
            if (userClose && !shotMode && !Unchanged())
            {
                DialogResult keep = MessageBox.Show(this, L.T("Сохранить проект перед выходом?"), Text, MessageBoxButtons.YesNoCancel, MessageBoxIcon.Question);
                if (keep == DialogResult.Cancel || (keep == DialogResult.Yes && !SaveProject()))
                {
                    e.Cancel = true;
                    userClose = false;
                    return;
                }
            }
            if (!CleanOnClose())
            {
                e.Cancel = true;
                userClose = false;
            }
        }

        bool shotMode; // запуск для проверочного снимка: без вопросов при закрытии
        bool userClose; // окно закрывает пользователь; если его закрыли извне (обновление программы), вопросов не задаём

        static IEnumerable<Control> FindGear(Control root)
        {
            foreach (Control c in root.Controls)
            {
                if (c is PlainButton && c.Width == 26 && c.Left == 0 && c.Parent is Panel && c.Parent.Dock == DockStyle.Top && c.Text == "" && ((Button)c).Image == null) yield return c;
                foreach (Control inner in FindGear(c)) yield return inner;
            }
        }

        // Для проверки вёрстки: сохранить снимок окна и закрыться.
        // Значок «?» в окне (у него курсор справки): нужен только проверочному снимку подсказки.
        static IEnumerable<Control> FindHelp(Control root)
        {
            foreach (Control c in root.Controls)
            {
                if (c is Label && c.Cursor == Cursors.Help) yield return c;
                foreach (Control inner in FindHelp(c)) yield return inner;
            }
        }

        public void Shot(string file)
        {
            shotMode = true;
            Shown += delegate
            {
                if (Environment.GetEnvironmentVariable("BPS_CLOSEASK") != null) // для проверки: показать вопрос об очистке, как при закрытии
                {
                    Timer ct = new Timer();
                    ct.Interval = 600;
                    ct.Tick += delegate { ct.Stop(); shotMode = false; userClose = true; CleanOnClose(); userClose = false; shotMode = true; };
                    ct.Start();
                }
                if (Environment.GetEnvironmentVariable("BPS_SETTINGS") != null) // для проверки: открыть список настроек (с кнопкой поддержки)
                {
                    Timer st = new Timer();
                    st.Interval = 400;
                    st.Tick += delegate { st.Stop(); foreach (Control c in FindGear(this)) ShowSettings(c); };
                    st.Start();
                }
                string node = Environment.GetEnvironmentVariable("BPS_NODE"); // какой раздел открыть для снимка
                if (Environment.GetEnvironmentVariable("BPS_TOGGLE") != null) testSwitchLang(this, EventArgs.Empty);
                string favSpec = Environment.GetEnvironmentVariable("BPS_FAV"); // для проверки: сохранить текстуры в избранное со всеми слоями
                if (favSpec != null)
                    foreach (string k in favSpec.Split(';'))
                    {
                        Entry fe = entries.Find(delegate(Entry x) { return x.Key == k; });
                        List<KeyValuePair<string, string>> fl = null;
                        if (fe != null && fe.Attrs != null) fe.Attrs.TryGetValue(fe.Winner, out fl);
                        // BPS_FAVLAYERS — сохранить только слои, без отметки самой текстуры
                        if (fe != null) Favorites.Add(fe.Winner, fe, Environment.GetEnvironmentVariable("BPS_FAVLAYERS") == null, fl);
                    }
                if (Environment.GetEnvironmentVariable("BPS_FAVSHOW") != null) favBtn.Checked = true;
                if (Environment.GetEnvironmentVariable("BPS_ALLTEX") != null) SetFilter(allTextures); // общий список при включённом избранном
                // для проверки: навести мышь на значок пакета в строке с этим номером
                string iconAt = Environment.GetEnvironmentVariable("BPS_ICON");
                if (iconAt != null && hoverPackIcon != null) hoverPackIcon(Program.Int(iconAt, 0));
                // для проверки: нажать «Файлы» дважды (включить и отжать)
                if (Environment.GetEnvironmentVariable("BPS_FILESOFF") != null) { modeFiles.PerformClick(); modeFiles.PerformClick(); }
                // для проверки: нажать «Категории» (отжать её), как щелчком мыши
                if (Environment.GetEnvironmentVariable("BPS_CATSOFF") != null) modeCats.PerformClick();
                // для проверки: показать всплывающую подсказку (ту, что у значка «?») поверх окна
                if (Environment.GetEnvironmentVariable("BPS_HINTTIP") != null) status.TestTip();
                string scopeShot = Environment.GetEnvironmentVariable("BPS_SCOPE"); // для проверки: раскрыть список и сохранить его вид
                if (scopeShot != null)
                {
                    Timer sc = new Timer();
                    sc.Interval = 600;
                    sc.Tick += delegate
                    {
                        sc.Stop();
                        DropList dl = scopeMenu();
                        if (dl == null) return;
                        dl.Hot = 0;
                        using (Bitmap db = new Bitmap(dl.Width, dl.Height))
                        {
                            dl.DrawToBitmap(db, new Rectangle(Point.Empty, dl.Size));
                            db.Save(scopeShot);
                        }
                        File.WriteAllText(scopeShot + ".txt", dl.Size + " " + dl.Parent.Size + " " + scopeBtn.Size);
                        if (Environment.GetEnvironmentVariable("BPS_SCOPEPICK") != null) dl.Pick(1);
                    };
                    sc.Start();
                }
                if (Environment.GetEnvironmentVariable("BPS_TIP") != null)
                    foreach (Control hc in FindHelp(this))
                        helpTips.Show(helpTips.GetToolTip(hc), this, new Point(380, 70), 6000);
                // для проверки: открыть меню проводника для файла первого пакета, как правый щелчок по текстуре
                string shell = Environment.GetEnvironmentVariable("BPS_SHELL");
                if (shell != null && packs.Count > 0)
                {
                    Timer st = new Timer();
                    st.Interval = 250;
                    st.Tick += delegate
                    {
                        st.Stop();
                        bool chose;
                        bool ok = ShellMenu.Show(this, Path.Combine(packs[0].Root, shell), new Point(Left + 520, Top + 180), out chose);
                        File.WriteAllText(file + ".shell.txt", "shown=" + ok + " chose=" + chose);
                    };
                    st.Start();
                }
                // для проверки: добавить пакет уже в открытое окно, через 0,7 с после показа (как перетаскивание файла)
                string late = Environment.GetEnvironmentVariable("BPS_LATEADD");
                if (late != null)
                {
                    Timer lt = new Timer();
                    lt.Interval = Math.Max(1, Program.Int(Environment.GetEnvironmentVariable("BPS_LATEMS"), 700)); // снимок делается через 1300 мс после показа
                    lt.Tick += delegate { lt.Stop(); AddPaths(new string[] { late }); };
                    lt.Start();
                }
                // для проверки: "текстура:номер пакета,номер;…" добавляет случайные варианты, как Ctrl+щелчок
                string varSpec = Environment.GetEnvironmentVariable("BPS_VARIANTS");
                if (varSpec != null)
                    foreach (string one in varSpec.Split(';'))
                    {
                        string[] kv = one.Split(':');
                        foreach (string num in kv[1].Split(','))
                        {
                            Entry ve = entries.Find(delegate(Entry x) { return x.Key == kv[0]; });
                            if (ve != null) ToggleVariant(ve, packs[Program.Int(num, 0)]);
                        }
                    }
                string dropSpec = Environment.GetEnvironmentVariable("BPS_LAYDROP"); // для проверки: перенести слои, "ключ|откуда|куда|слот;…"
                string dumpTo = Environment.GetEnvironmentVariable("BPS_DUMPMINIS");  // и записать, какие значки слоёв стоят под каждой текстурой
                Action<string> dumpMinis = delegate(string title)
                {
                    if (dumpTo == null) return;
                    System.Text.StringBuilder sb = new System.Text.StringBuilder("== " + title + "\r\n");
                    foreach (Entry de in entries)
                    {
                        if (de.Hidden || de.Attrs == null) continue;
                        foreach (Pack dq in de.Sources)
                        {
                            sb.Append("  " + de.Key + " [" + dq.Name + (Chosen(de, dq) ? "*" : "") + "]:");
                            List<KeyValuePair<string, string>> dm = gallery.MultiMinis(de, dq);
                            if (dm != null)
                                foreach (KeyValuePair<string, string> it in dm)
                                {
                                    Pack owner = LayerPack(de, Builder.SlotOf(it.Key), it.Value);
                                    bool? lit = gallery.MultiLayerOn(de, dq, it.Key, it.Value);
                                    sb.Append(" " + Builder.SlotOf(it.Key) + "/" + (owner == null ? "?" : owner.Name) + (lit == true ? "+" : "-"));
                                }
                            sb.Append("\r\n");
                        }
                    }
                    File.AppendAllText(dumpTo, sb.ToString());
                };
                dumpMinis("start");
                if (dropSpec != null)
                    foreach (string oneDrop in dropSpec.Split((char)59))
                    {
                        string[] dp = oneDrop.Split(new char[] { (char)124 });
                        Entry de = entries.Find(delegate(Entry x) { return x.Key == dp[0]; });
                        if (de == null) continue;
                        KeyValuePair<string, string> di = SlotItem(de, packs[Program.Int(dp[1], 0)], dp[3]);
                        if (di.Key != null) DropLayer(de, di.Key, di.Value, packs[Program.Int(dp[2], 0)], gallery.MultiLayerOn(de, packs[Program.Int(dp[1], 0)], di.Key, di.Value) == true);
                        dumpMinis(oneDrop);
                    }
                string layTrash = Environment.GetEnvironmentVariable("BPS_LAYTRASH"); // для проверки: слой в корзину, "ключ|пакет|слот;…"
                if (layTrash != null)
                    foreach (string one in layTrash.Split((char)59))
                    {
                        string[] lt = one.Split(new char[] { (char)124 });
                        Entry le = entries.Find(delegate(Entry x) { return x.Key == lt[0]; });
                        if (le == null) continue;
                        KeyValuePair<string, string> li = SlotItem(le, packs[Program.Int(lt[1], 0)], lt[2]);
                        if (li.Key != null) TrashLayer(le, packs[Program.Int(lt[1], 0)], li.Key, li.Value);
                        dumpMinis("trash " + one);
                    }
                string trashSpec = Environment.GetEnvironmentVariable("BPS_TRASH"); // для проверки: убрать текстуры в корзину, "ключ|пакет;…"
                if (trashSpec != null)
                    foreach (string one in trashSpec.Split((char)59))
                    {
                        string[] tp = one.Split(new char[] { (char)124 });
                        Entry te = entries.Find(delegate(Entry x) { return x.Key == tp[0]; });
                        if (te != null) TrashTexture(te, packs[Program.Int(tp[1], 0)]);
                    }
                if (Environment.GetEnvironmentVariable("BPS_TRASHVIEW") != null) SetTrashView(true); // для проверки: открыть корзину
                string undoSpec = Environment.GetEnvironmentVariable("BPS_UNDO");                    // для проверки: отменить столько шагов
                if (undoSpec != null) for (int ui = 0; ui < Program.Int(undoSpec, 0); ui++) Undo();
                string navSpec = Environment.GetEnvironmentVariable("BPS_NAV"); // для проверки: нажатия стрелок, "Down,Right,Enter"
                if (navSpec != null)
                {
                    Timer nt = new Timer();
                    nt.Interval = 500;
                    nt.Tick += delegate
                    {
                        nt.Stop();
                        string navLog = Environment.GetEnvironmentVariable("BPS_NAVLOG"); // куда записать, что выделено после каждого шага
                        foreach (string k in navSpec.Split((char)44))
                        {
                            gallery.NavKey((Keys)Enum.Parse(typeof(Keys), k));
                            if (navLog != null) File.AppendAllText(navLog, k + " -> " + gallery.NavInfo + "\r\n");
                        }
                    };
                    nt.Start();
                }
                // для проверки: собрать пакет со сделанным в окне выбором
                string test3D = Environment.GetEnvironmentVariable("BPS_3D"); // для проверки: режим 3D; "h5" — окошко у объекта 5, "g5" — перейти к нему
                if (test3D != null)
                {
                    SetMode(true);
                    if (test3D.Length > 1)
                    {
                        Timer t3 = new Timer();
                        t3.Interval = 500;
                        t3.Tick += delegate
                        {
                            t3.Stop();
                            if (test3D[0] == (char)110) objView.TestNav(Program.Int(test3D.Substring(1), 0), 9); // "n5": выделить пятый и пройти 9 шагов
                            else objView.TestHover(Program.Int(test3D.Substring(1), 0), test3D[0] == (char)103);
                        };
                        t3.Start();
                    }
                }
                string attachSpec = Environment.GetEnvironmentVariable("BPS_ATTACH"); // для проверки: "ключ слоя|номер пакета|ключ текстуры|номер пакета"
                if (attachSpec != null)
                {
                    string[] atcParts = attachSpec.Split((char)124);
                    Entry atcLayer = entries.Find(delegate(Entry x) { return x.Key == atcParts[0]; }), atcTarget = entries.Find(delegate(Entry x) { return x.Key == atcParts[2]; });
                    if (atcLayer != null && atcTarget != null) AttachLayer(atcLayer, packs[Program.Int(atcParts[1], 0)], atcTarget, packs[Program.Int(atcParts[3], 0)]);
                }
                if (Environment.GetEnvironmentVariable("BPS_PANE") != null) PickLeft(modePreview); // для проверки: нажать «Превью»
                string buildTo = Environment.GetEnvironmentVariable("BPS_BUILD");
                if (buildTo != null)
                {
                    try
                    {
                        List<string> buildParts = new List<string>();
                        foreach (Pack bp in Contributors()) buildParts.Add((buildParts.Count + 1) + ". " + bp.Name);
                        bool real = Environment.GetEnvironmentVariable("BPS_BUILDREAL") != null;
                        File.WriteAllLines(buildTo + ".log", Builder.Build(entries, packs, real ? PackName() : "Test", real ? string.Join("\n", buildParts.ToArray()) : "", buildTo, VariantsForBuild()).ToArray());
                    }
                    catch (Exception ex) { File.WriteAllText(buildTo + ".log", ex.ToString()); }
                }
                string find = Environment.GetEnvironmentVariable("BPS_FIND"); // для проверки: набрать текст в строке поиска
                if (find != null) filterBox.Text = find;
                if (Environment.GetEnvironmentVariable("BPS_ONLYPACK") != null) // для проверочного снимка: включить отбор по выбранному пакету
                {
                    allTextures.Checked = false;
                    onlyPack.Checked = true;
                }
                string open = Environment.GetEnvironmentVariable("BPS_OPEN"); // какие разделы развернуть
                if (open != null) foreach (string k in open.Split(',')) expanded.Add(k);
                if (node != null) selNode = node;
                if (Environment.GetEnvironmentVariable("BPS_ATTRS") != null) showAttrs.Checked = true;
                Program.TestSlots(packs, slotChoice);
                string offSpec = Environment.GetEnvironmentVariable("BPS_OFF"); // для проверки: выключить текстуры
                if (offSpec != null) foreach (string k in offSpec.Split(';')) overrides[k] = Pack.Off;
                if (node != null || open != null || slotChoice.Count > 0 || offSpec != null) Recollect();
                string hover = Environment.GetEnvironmentVariable("BPS_HOVER"); // "x,y" в координатах витрины
                if (hover != null) gallery.TestHover(new Point(Program.Int(hover.Split(',')[0], 0), Program.Int(hover.Split(',').Length > 1 ? hover.Split(',')[1] : null, 0)));
                string saveTo = Environment.GetEnvironmentVariable("BPS_SAVEPROJ"); // для проверки: сохранить проект без окна
                if (saveTo != null) SaveProjectTo(saveTo);
                string openFile = Environment.GetEnvironmentVariable("BPS_FILE"); // открыть файл первого пака в режиме «Файлы пака»
                if (openFile != null && packs.Count > 0)
                {
                    modeFiles.Checked = true;
                    OpenFile(Path.Combine(packs[0].Root, openFile));
                }
                Form target = this;
                string edit = Environment.GetEnvironmentVariable("BPS_EDIT"); // снять вместо главного окна редактор этой текстуры
                if (edit != null && packs.Count > 0)
                {
                    // BPS_EDIT — ключ текстуры или путь файла внутри первого пакета; BPS_EDITPACK — из какого пакета её взять;
                    // BPS_EDIT3D — включить 3D-вид; BPS_EDITHOVER — номер значка, превью которого показать;
                    // BPS_EDITDRAW — провести мазок ("save" — и сохранить); второй ключ через «;» — затем перейти к нему, как по кнопке «редактировать»
                    string editKey = edit.Split(';')[0].Replace('\\', '/').ToLowerInvariant(), editFrom = Environment.GetEnvironmentVariable("BPS_EDITPACK");
                    Entry editE = entries.Find(delegate(Entry x) { return x.Key == editKey; });
                    Pack editP = editE == null ? null : (editE.Sources.Find(delegate(Pack x) { return x.Name == editFrom; }) ?? editE.Winner);
                    TextureEditor.Show3D = Environment.GetEnvironmentVariable("BPS_EDIT3D") != null;
                    if (editE != null) openEditor(editE, editP, null);
                    else openEditor(null, null, Path.Combine(packs[0].Root, edit.Split(';')[0]));
                    if (texEditor != null)
                    {
                        texEditor.Location = new Point(Left + 40, Top + 40);
                        string editDraw = Environment.GetEnvironmentVariable("BPS_EDITDRAW");
                        if (editDraw != null) texEditor.TestStroke(editDraw == "save");
                        string editDo = Environment.GetEnvironmentVariable("BPS_EDITDO"); // действия редактора через «|», см. TestDo
                        if (editDo != null) foreach (string editStep in editDo.Split('|')) texEditor.TestDo(editStep);
                        Entry editNext = edit.Contains(";") ? entries.Find(delegate(Entry x) { return x.Key == edit.Split(';')[1]; }) : null;
                        if (editNext != null) openEditor(editNext, editNext.Winner, null);
                        string editHover = Environment.GetEnvironmentVariable("BPS_EDITHOVER");
                        if (editHover != null) texEditor.TestHover(Program.Int(editHover, 0));
                        target = texEditor;
                    }
                }
                Timer t = new Timer();
                t.Interval = Math.Max(1, Program.Int(Environment.GetEnvironmentVariable("BPS_SHOTMS"), 1300)); // через сколько после показа делать снимок
                t.Tick += delegate
                {
                    t.Stop();
                    using (Bitmap b = new Bitmap(target.Width, target.Height))
                    {
                        using (Graphics sg = Graphics.FromImage(b))
                        {
                            IntPtr dc = sg.GetHdc();
                            PrintWindow(target.Handle, dc, 2);
                            sg.ReleaseHdc(dc);
                        }
                        b.Save(file, ImageFormat.Png);
                    }
                    Close();
                };
                t.Start();
            };
        }
    }

    // Обычное меню проводника для файла (то, что Windows показывает по правому щелчку): открыть, копировать, свойства…
    static class ShellMenu
    {
        [StructLayout(LayoutKind.Sequential)]
        struct InvokeInfo
        {
            public int cbSize, fMask;
            public IntPtr hwnd, lpVerb;
            [MarshalAs(UnmanagedType.LPStr)] public string lpParameters;
            [MarshalAs(UnmanagedType.LPStr)] public string lpDirectory;
            public int nShow, dwHotKey;
            public IntPtr hIcon;
        }

        [ComImport, Guid("000214E6-0000-0000-C000-000000000046"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
        interface IShellFolder
        {
            [PreserveSig] int ParseDisplayName(IntPtr hwnd, IntPtr pbc, [MarshalAs(UnmanagedType.LPWStr)] string name, IntPtr eaten, out IntPtr pidl, IntPtr attrs);
            [PreserveSig] int EnumObjects(IntPtr hwnd, int flags, out IntPtr list);
            [PreserveSig] int BindToObject(IntPtr pidl, IntPtr pbc, ref Guid riid, out IntPtr ppv);
            [PreserveSig] int BindToStorage(IntPtr pidl, IntPtr pbc, ref Guid riid, out IntPtr ppv);
            [PreserveSig] int CompareIDs(IntPtr lParam, IntPtr pidl1, IntPtr pidl2);
            [PreserveSig] int CreateViewObject(IntPtr hwnd, ref Guid riid, out IntPtr ppv);
            [PreserveSig] int GetAttributesOf(uint cidl, [MarshalAs(UnmanagedType.LPArray)] IntPtr[] apidl, ref uint flags);
            [PreserveSig] int GetUIObjectOf(IntPtr hwnd, uint cidl, [MarshalAs(UnmanagedType.LPArray)] IntPtr[] apidl, ref Guid riid, IntPtr reserved, out IntPtr ppv);
        }

        [ComImport, Guid("000214E4-0000-0000-C000-000000000046"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
        interface IContextMenu
        {
            [PreserveSig] int QueryContextMenu(IntPtr hmenu, uint index, uint idFirst, uint idLast, uint flags);
            [PreserveSig] int InvokeCommand(ref InvokeInfo info);
            [PreserveSig] int GetCommandString(UIntPtr id, uint type, IntPtr reserved, IntPtr name, uint max);
        }

        [ComImport, Guid("000214F4-0000-0000-C000-000000000046"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
        interface IContextMenu2
        {
            [PreserveSig] int QueryContextMenu(IntPtr hmenu, uint index, uint idFirst, uint idLast, uint flags);
            [PreserveSig] int InvokeCommand(ref InvokeInfo info);
            [PreserveSig] int GetCommandString(UIntPtr id, uint type, IntPtr reserved, IntPtr name, uint max);
            [PreserveSig] int HandleMenuMsg(uint msg, IntPtr wParam, IntPtr lParam);
        }

        [ComImport, Guid("BCFCE0A0-EC17-11D0-8D10-00A0C90F2719"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
        interface IContextMenu3
        {
            [PreserveSig] int QueryContextMenu(IntPtr hmenu, uint index, uint idFirst, uint idLast, uint flags);
            [PreserveSig] int InvokeCommand(ref InvokeInfo info);
            [PreserveSig] int GetCommandString(UIntPtr id, uint type, IntPtr reserved, IntPtr name, uint max);
            [PreserveSig] int HandleMenuMsg(uint msg, IntPtr wParam, IntPtr lParam);
            [PreserveSig] int HandleMenuMsg2(uint msg, IntPtr wParam, IntPtr lParam, out IntPtr result);
        }

        [DllImport("shell32.dll", CharSet = CharSet.Unicode)]
        static extern int SHParseDisplayName(string name, IntPtr pbc, out IntPtr pidl, uint attrsIn, out uint attrsOut);
        [DllImport("shell32.dll")]
        static extern int SHBindToParent(IntPtr pidl, ref Guid riid, out IntPtr ppv, out IntPtr last);
        [DllImport("user32.dll")]
        static extern IntPtr CreatePopupMenu();
        [DllImport("user32.dll")]
        static extern bool DestroyMenu(IntPtr menu);
        [DllImport("user32.dll")]
        static extern uint TrackPopupMenuEx(IntPtr menu, uint flags, int x, int y, IntPtr hwnd, IntPtr tpm);
        [DllImport("ole32.dll")]
        static extern void CoTaskMemFree(IntPtr p);
        [DllImport("user32.dll")]
        static extern bool SetForegroundWindow(IntPtr hwnd);

        // Подменю («Открыть с помощью», «Отправить») рисует сама оболочка: ей нужно передавать сообщения окна, пока меню открыто.
        class Relay : NativeWindow
        {
            public IContextMenu2 M2;
            public IContextMenu3 M3;

            protected override void WndProc(ref Message m)
            {
                const int InitMenuPopup = 0x117, DrawItem = 0x2B, MeasureItem = 0x2C, MenuChar = 0x120;
                try
                {
                    IntPtr res;
                    if (M3 != null && m.Msg == MenuChar && M3.HandleMenuMsg2((uint)m.Msg, m.WParam, m.LParam, out res) == 0) { m.Result = res; return; }
                    if (M2 != null && (m.Msg == InitMenuPopup || m.Msg == DrawItem || m.Msg == MeasureItem) && M2.HandleMenuMsg((uint)m.Msg, m.WParam, m.LParam) == 0)
                    {
                        m.Result = m.Msg == InitMenuPopup ? IntPtr.Zero : (IntPtr)1;
                        return;
                    }
                }
                catch (Exception) { }
                base.WndProc(ref m);
            }
        }

        // Показывает меню в точке экрана; false — меню получить не удалось. chose — в меню что-то выбрали.
        public static bool Show(Form owner, string path, Point at, out bool chose)
        {
            chose = false;
            IntPtr pidl = IntPtr.Zero, pFolder = IntPtr.Zero, pMenu = IntPtr.Zero, hMenu = IntPtr.Zero;
            object folderObj = null, menuObj = null;
            Relay relay = new Relay();
            try
            {
                uint attrs;
                if (SHParseDisplayName(path, IntPtr.Zero, out pidl, 0, out attrs) != 0 || pidl == IntPtr.Zero) return false;
                Guid iidFolder = typeof(IShellFolder).GUID, iidMenu = typeof(IContextMenu).GUID;
                IntPtr child;
                if (SHBindToParent(pidl, ref iidFolder, out pFolder, out child) != 0) return false;
                folderObj = Marshal.GetTypedObjectForIUnknown(pFolder, typeof(IShellFolder));
                if (((IShellFolder)folderObj).GetUIObjectOf(owner.Handle, 1, new IntPtr[] { child }, ref iidMenu, IntPtr.Zero, out pMenu) != 0) return false;
                menuObj = Marshal.GetTypedObjectForIUnknown(pMenu, typeof(IContextMenu));
                IContextMenu menu = (IContextMenu)menuObj;
                hMenu = CreatePopupMenu();
                if (menu.QueryContextMenu(hMenu, 0, 1, 0x7FFF, 0) < 0) return false;
                relay.M2 = menuObj as IContextMenu2;
                relay.M3 = menuObj as IContextMenu3;
                relay.AssignHandle(owner.Handle);
                SetForegroundWindow(owner.Handle); // иначе меню не закроется по щелчку мимо него
                uint cmd = TrackPopupMenuEx(hMenu, 0x100 | 0x2, at.X, at.Y, owner.Handle, IntPtr.Zero); // вернуть номер команды, правая кнопка тоже выбирает
                relay.ReleaseHandle();
                if (cmd == 0) return true;
                InvokeInfo info = new InvokeInfo();
                info.cbSize = Marshal.SizeOf(typeof(InvokeInfo));
                info.hwnd = owner.Handle;
                info.lpVerb = (IntPtr)(int)(cmd - 1);
                info.nShow = 1;
                menu.InvokeCommand(ref info);
                chose = true;
                return true;
            }
            catch (Exception) { return false; }
            finally
            {
                try { if (relay.Handle != IntPtr.Zero) relay.ReleaseHandle(); } catch (Exception) { }
                if (hMenu != IntPtr.Zero) DestroyMenu(hMenu);
                if (menuObj != null) Marshal.ReleaseComObject(menuObj);
                if (folderObj != null) Marshal.ReleaseComObject(folderObj);
                if (pMenu != IntPtr.Zero) Marshal.Release(pMenu);
                if (pFolder != IntPtr.Zero) Marshal.Release(pFolder);
                if (pidl != IntPtr.Zero) CoTaskMemFree(pidl);
            }
        }
    }

    // Превью, закреплённое в левом нижнем углу окна (кнопка «Превью»): то же, что всплывающее окошко у текстуры,
    // но на постоянном месте. До него можно довести мышь и нажать карандаш; всплывающие окошки при этом отключены.
    class PreviewPane : Control
    {
        Bitmap image;
        string title = "", sub = "";
        public Entry E;
        public Pack P;
        public string File;   // файл слоя, если показан слой, а не сама текстура
        public bool Pinned;   // закреплено клавишей Shift: наведение на другие текстуры его не сменяет
        bool penHot;
        public event Action Edit;
        // правая кнопка с перетаскиванием по картинке вращает показанный объект (режим 3D): сообщается сдвиг от места нажатия
        public event Action TurnStart;
        public event Action<int, int> Turn;
        bool turning;
        Point turnFrom;
        // анимированная текстура — лента кадров сверху вниз: показывается по одному кадру, они сменяются
        int frames = 1, ticks = 2, tick;
        Timer anim = new Timer();

        public PreviewPane()
        {
            SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
            anim.Interval = 50; // один такт игры
            anim.Tick += delegate
            {
                if (frames < 2 || !Visible) { anim.Stop(); return; }
                int before = tick / ticks % frames;
                tick++;
                if (tick / ticks % frames != before) Invalidate();
            };
        }

        // Лента из count кадров, каждый держится perFrame тактов; count = 1 — обычная картинка.
        public void Animate(int count, int perFrame)
        {
            frames = Math.Max(1, count);
            ticks = Math.Max(1, perFrame);
            tick = 0;
            if (frames > 1) anim.Start(); else anim.Stop();
            Invalidate();
        }

        // Новый кадр того же объекта (режим 3D): подпись и закрепление не меняются.
        public void SetImage(Bitmap img)
        {
            if (image != null) image.Dispose();
            image = img;
            Invalidate();
        }

        public void Set(Bitmap img, string name, string from, Entry e, Pack p, string file)
        {
            frames = 1;
            anim.Stop();
            if (image != null) image.Dispose();
            image = img;
            title = name ?? "";
            sub = from ?? "";
            E = e;
            P = p;
            File = file;
            Invalidate();
        }

        Rectangle PenRect { get { return new Rectangle(ClientSize.Width - 36, ClientSize.Height - 34, 28, 26); } }
        bool CanEdit { get { return image != null && E != null && P != null && Edit != null; } }

        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.Clear(Theme.Field);
            using (Pen edge = new Pen(Theme.Edge)) g.DrawRectangle(edge, 0, 0, ClientSize.Width - 1, ClientSize.Height - 1);
            if (image == null)
            {
                TextRenderer.DrawText(g, L.T("Наведите мышь на текстуру — здесь появится её превью.\nShift над текстурой закрепляет превью на ней, Shift в пустом месте — отпускает."), Font,
                    Rectangle.Inflate(ClientRectangle, -12, -12), Theme.Dim, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix);
                return;
            }
            Rectangle pic = new Rectangle(8, 8, ClientSize.Width - 16, ClientSize.Height - 16 - 42);
            if (pic.Width > 8 && pic.Height > 8)
            {
                // у ленты кадров показывается один кадр — текущий
                int fh = frames > 1 ? image.Height / frames : image.Height, fy = frames > 1 ? (tick / ticks % frames) * fh : 0;
                double k = Math.Min((double)pic.Width / image.Width, (double)pic.Height / fh);
                int w = Math.Max(1, (int)(image.Width * k)), h = Math.Max(1, (int)(fh * k));
                Rectangle to = new Rectangle(pic.X + (pic.Width - w) / 2, pic.Y + (pic.Height - h) / 2, w, h);
                using (SolidBrush under = new SolidBrush(Theme.CellOff)) g.FillRectangle(under, to);
                g.InterpolationMode = k >= 1 ? InterpolationMode.NearestNeighbor : InterpolationMode.HighQualityBicubic;
                g.PixelOffsetMode = PixelOffsetMode.Half;
                g.DrawImage(image, to, new Rectangle(0, fy, image.Width, fh), GraphicsUnit.Pixel);
            }
            int ty = ClientSize.Height - 44, tw = ClientSize.Width - 16 - (CanEdit ? 34 : 0);
            using (Font bold = new Font(Font, FontStyle.Bold))
                TextRenderer.DrawText(g, title, bold, new Rectangle(8, ty, tw, 18), Theme.Text, TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix);
            TextRenderer.DrawText(g, Pinned ? sub + "   ·   " + L.T("закреплено") : sub, Font, new Rectangle(8, ty + 19, tw, 18), Pinned ? Theme.Accent : Theme.Dim,
                TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix);
            if (!CanEdit) return;
            // карандаш: открыть текстуру в редакторе
            Rectangle pr = PenRect;
            using (SolidBrush back = new SolidBrush(penHot ? Theme.CellHot : Theme.Card)) g.FillRectangle(back, pr);
            using (Pen edge = new Pen(penHot ? Theme.Accent : Theme.Edge)) g.DrawRectangle(edge, pr.X, pr.Y, pr.Width - 1, pr.Height - 1);
            SmoothingMode was = g.SmoothingMode;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            using (Pen body = new Pen(Color.FromArgb(240, 178, 52), 5)) g.DrawLine(body, pr.X + 10, pr.Y + 17, pr.X + 19, pr.Y + 8);
            using (SolidBrush tip = new SolidBrush(Theme.Text)) g.FillPolygon(tip, new Point[] { new Point(pr.X + 6, pr.Y + 21), new Point(pr.X + 7, pr.Y + 15), new Point(pr.X + 12, pr.Y + 20) });
            g.SmoothingMode = was;
        }

        protected override void OnMouseDown(MouseEventArgs e)
        {
            base.OnMouseDown(e);
            if (e.Button != MouseButtons.Right || image == null || PenRect.Contains(e.Location)) return;
            turning = true;
            turnFrom = e.Location;
            if (TurnStart != null) TurnStart();
        }

        protected override void OnMouseMove(MouseEventArgs e)
        {
            base.OnMouseMove(e);
            if (turning)
            {
                if ((e.Button & MouseButtons.Right) == 0) { turning = false; return; }
                if (Turn != null) Turn(e.X - turnFrom.X, e.Y - turnFrom.Y);
                return;
            }
            bool hot = CanEdit && PenRect.Contains(e.Location);
            Cursor = hot ? Cursors.Hand : Cursors.Default;
            if (hot == penHot) return;
            penHot = hot;
            Invalidate();
        }

        protected override void OnMouseLeave(EventArgs e)
        {
            base.OnMouseLeave(e);
            if (!penHot) return;
            penHot = false;
            Invalidate();
        }

        protected override void OnMouseUp(MouseEventArgs e)
        {
            base.OnMouseUp(e);
            if (e.Button == MouseButtons.Right) turning = false;
            if (e.Button == MouseButtons.Left && CanEdit && PenRect.Contains(e.Location)) Edit();
        }
    }

    // Файлы, которым не место в пакете ресурсов. Пакет — это картинки, звуки и текст; программа или сценарий внутри
    // чужого пакета — способ заставить пользователя запустить вредный код, а вложенный архив игра всё равно не читает.
    static class Risk
    {
        static readonly HashSet<string> programs = new HashSet<string>(new string[] {
            ".exe", ".com", ".scr", ".pif", ".bat", ".cmd", ".lnk", ".url", ".js", ".jse", ".vbs", ".vbe", ".wsf", ".wsh", ".ps1", ".psm1",
            ".msi", ".msp", ".hta", ".jar", ".reg", ".cpl", ".dll", ".sys", ".inf", ".chm", ".application", ".appref-ms", ".gadget", ".scf", ".sh", ".py",
            // то, что Windows тоже может запустить или исполнить: страницы со скриптами, документы с макросами, установщики приложений, ярлыки
            ".msc", ".msu", ".msh", ".ws", ".wsc", ".sct", ".xbap", ".xll", ".jnlp", ".diagcab", ".website", ".iqy", ".slk",
            ".html", ".htm", ".xht", ".xhtml", ".mht", ".mhtml", ".svg",
            ".docm", ".dotm", ".xlsm", ".xltm", ".xlam", ".pptm", ".potm", ".ppam", ".ppsm", ".sldm",
            ".appx", ".appxbundle", ".msix", ".msixbundle", ".appinstaller",
            ".settingcontent-ms", ".library-ms", ".search-ms", ".searchconnector-ms", ".vhd", ".vhdx" });
        static readonly HashSet<string> archives = new HashSet<string>(new string[] {
            ".zip", ".mcpack", ".mcaddon", ".mcworld", ".mctemplate", ".rar", ".7z", ".tar", ".gz", ".cab", ".iso" });
        // то, из чего состоит пакет ресурсов: это можно открывать без вопросов
        static readonly HashSet<string> plain = new HashSet<string>(new string[] {
            ".png", ".tga", ".jpg", ".jpeg", ".gif", ".bmp", ".json", ".txt", ".lang", ".md", ".material", ".mcmeta", ".properties",
            ".ogg", ".wav", ".mp3", ".fsb", ".ttf", ".otf", ".fragment", ".vertex", ".glsl", ".hlsl", ".sh.txt", ".csv", ".ini", ".cfg" });

        static string Ext(string path) { return Path.GetExtension(path).ToLowerInvariant(); }
        public static bool Program(string path) { return programs.Contains(Ext(path)); }
        public static bool Archive(string path) { return archives.Contains(Ext(path)); }
        public static bool Plain(string path) { return plain.Contains(Ext(path)); }
    }

    // Строка с галочкой в списке настроек: нарисована цветами темы, щелчок в любом месте строки переключает её.
    class CheckRow : Control
    {
        bool on, hot;
        public bool OnWindow; // строка лежит прямо на окне, а не в списке: фон как у окна
        public event Action Changed;

        public CheckRow()
        {
            SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
            Height = 30;
            Cursor = Cursors.Hand;
        }

        public bool Checked
        {
            get { return on; }
            set { if (on == value) return; on = value; Invalidate(); }
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.Clear(hot ? Theme.CellHot : (OnWindow ? Theme.Back : Theme.Field));
            Rectangle box = new Rectangle(10, (Height - 16) / 2, 16, 16);
            using (SolidBrush b = new SolidBrush(on ? Theme.Accent : Theme.Field)) g.FillRectangle(b, box);
            using (Pen p = new Pen(on ? Theme.Accent : Theme.Dim)) g.DrawRectangle(p, box.X, box.Y, box.Width - 1, box.Height - 1);
            if (on)
            {
                SmoothingMode was = g.SmoothingMode;
                g.SmoothingMode = SmoothingMode.AntiAlias;
                using (Pen tick = new Pen(Color.White, 2)) g.DrawLines(tick, new Point[] { new Point(box.X + 3, box.Y + 8), new Point(box.X + 7, box.Y + 12), new Point(box.X + 13, box.Y + 4) });
                g.SmoothingMode = was;
            }
            TextRenderer.DrawText(g, Text, Font, new Rectangle(34, 0, Width - 40, Height), Theme.Text, TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.EndEllipsis);
        }

        protected override void OnMouseEnter(EventArgs e) { base.OnMouseEnter(e); hot = true; Invalidate(); }
        protected override void OnMouseLeave(EventArgs e) { base.OnMouseLeave(e); hot = false; Invalidate(); }

        protected override void OnMouseUp(MouseEventArgs e)
        {
            base.OnMouseUp(e);
            if (e.Button != MouseButtons.Left || !ClientRectangle.Contains(e.Location)) return;
            on = !on;
            Invalidate();
            if (Changed != null) Changed();
        }
    }

    // Журнал действий для поиска ошибок: пишется, только если программа запущена с переменной BPS_TRACE (путь к файлу).
    static class Diag
    {
        static readonly string file = Environment.GetEnvironmentVariable("BPS_TRACE");
        public static bool On { get { return file != null; } }

        public static void Log(string text)
        {
            if (file == null) return;
            try { File.AppendAllText(file, DateTime.Now.ToString("HH:mm:ss.fff") + "  " + text + "\r\n"); }
            catch (Exception) { }
        }
    }

    // Размер всплывающих превью. Он общий для всех превью программы: меняется колесом мыши при зажатом Alt
    // (от 50% до 200%) и держится до закрытия программы. Пока Alt зажат, поверх превью показан текущий размер.
    static class Preview
    {
        // для проверочных снимков: BPS_PREVIEW — размер в процентах и «зажатый» Alt
        static readonly string test = Environment.GetEnvironmentVariable("BPS_PREVIEW");
        public static float Scale = test == null ? 1f : Math.Max(50, Math.Min(200, Program.Int(test, 100))) / 100f;

        public static bool Alt { get { return test != null || (Control.ModifierKeys & Keys.Alt) != 0; } }

        public static int Size(int basis) { return Math.Max(8, (int)Math.Round(basis * Scale)); }

        // Шаг зависит от системной настройки колеса: одна строка прокрутки — 5%. Возвращает, изменился ли размер.
        public static bool Wheel(int delta)
        {
            int lines = SystemInformation.MouseWheelScrollLines;
            if (lines <= 0) lines = 6; // колесо настроено листать по странице
            float next = Math.Max(0.5f, Math.Min(2f, Scale + delta / 120f * lines * 0.05f));
            next = (float)Math.Round(next * 100) / 100;
            if (next == Scale) return false;
            Scale = next;
            return true;
        }

        public static void Badge(Graphics g, Rectangle box, Font font)
        {
            string text = (int)Math.Round(Scale * 100) + "%";
            using (Font big = new Font(font.FontFamily, 15f, FontStyle.Bold))
            {
                Size ts = TextRenderer.MeasureText(g, text, big);
                Rectangle r = new Rectangle(box.X + (box.Width - ts.Width - 24) / 2, box.Y + (box.Height - ts.Height - 14) / 2, ts.Width + 24, ts.Height + 14);
                using (SolidBrush back = new SolidBrush(Color.FromArgb(165, 18, 18, 22))) g.FillRectangle(back, r);
                using (Pen edge = new Pen(Color.FromArgb(150, 255, 255, 255))) g.DrawRectangle(edge, r.X, r.Y, r.Width - 1, r.Height - 1);
                TextRenderer.DrawText(g, text, big, r, Color.White, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix);
            }
        }
    }

    // Всплывающий крупный значок пакета с названием под ним. Окно не забирает фокус и не ловит мышь.
    // Название, которое не помещается, через секунду после появления начинает ехать бегущей строкой по кругу.
    class PackPreview : Form
    {
        const int Pad = 8, NameH = 22, Wait = 1000;
        int Side { get { return Preview.Size(192); } }
        bool altWas;

        // Размер превью изменили: окно подстраивается.
        public void Rescale()
        {
            ClientSize = new Size(Side + Pad * 2, Pad + Side + 4 + NameH + 4);
            Invalidate();
        }
        Bitmap image;
        string name = "";
        Timer timer = new Timer();
        Stopwatch since = Stopwatch.StartNew();
        float offset;

        public PackPreview()
        {
            FormBorderStyle = FormBorderStyle.None;
            ShowInTaskbar = false;
            StartPosition = FormStartPosition.Manual;
            ClientSize = new Size(Side + Pad * 2, Pad + Side + 4 + NameH + 4);
            SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer, true);
            timer.Interval = 30;
            timer.Tick += delegate
            {
                if (!Visible) { timer.Stop(); return; }
                if (Preview.Alt != altWas) { altWas = !altWas; Invalidate(); }
                if (since.ElapsedMilliseconds < Wait) return;
                offset += 1.2f;
                Invalidate(new Rectangle(0, Pad + Side + 4, ClientSize.Width, NameH));
            };
        }

        protected override bool ShowWithoutActivation { get { return true; } }

        protected override CreateParams CreateParams
        {
            get
            {
                CreateParams cp = base.CreateParams;
                cp.ExStyle |= 0x08000000 | 0x80 | 0x20; // не активируется, не видно в Alt+Tab, щелчки проходят сквозь окно
                return cp;
            }
        }

        public void ShowFor(Form owner, Bitmap big, string title, Point at)
        {
            if (image != null) image.Dispose();
            image = big;
            name = title ?? "";
            offset = 0;
            since.Restart();
            Font = owner.Font;
            ClientSize = new Size(Side + Pad * 2, Pad + Side + 4 + NameH + 4);
            // не вылезаем за нижний и правый край экрана
            Rectangle area = Screen.FromPoint(at).WorkingArea;
            at.X = Math.Min(at.X, area.Right - Width);
            at.Y = Math.Max(area.Top, Math.Min(at.Y, area.Bottom - Height));
            Location = at;
            if (!Visible) Show(owner);
            Invalidate();
            timer.Start();
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.Clear(Theme.Card);
            using (Pen edge = new Pen(Theme.Dim)) g.DrawRectangle(edge, 0, 0, ClientSize.Width - 1, ClientSize.Height - 1);
            Rectangle pic = new Rectangle(Pad, Pad, Side, Side);
            if (image != null)
            {
                double k = Math.Min((double)Side / image.Width, (double)Side / image.Height);
                int w = Math.Max(1, (int)(image.Width * k)), h = Math.Max(1, (int)(image.Height * k));
                g.InterpolationMode = k >= 1 ? InterpolationMode.NearestNeighbor : InterpolationMode.HighQualityBicubic;
                g.PixelOffsetMode = PixelOffsetMode.Half;
                g.DrawImage(image, new Rectangle(pic.X + (Side - w) / 2, pic.Y + (Side - h) / 2, w, h));
            }
            if (Preview.Alt) Preview.Badge(g, pic, Font);
            Rectangle line = new Rectangle(Pad, Pad + Side + 4, Side, NameH);
            TextFormatFlags flags = TextFormatFlags.VerticalCenter | TextFormatFlags.NoPadding | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine
                | TextFormatFlags.PreserveGraphicsClipping;
            using (Font bold = new Font(Font, FontStyle.Bold))
            {
                int textW = TextRenderer.MeasureText(g, name, bold, new Size(int.MaxValue, NameH), flags).Width;
                g.SetClip(line);
                if (textW <= line.Width)
                    TextRenderer.DrawText(g, name, bold, line, Theme.Text, flags | TextFormatFlags.HorizontalCenter);
                else
                {
                    // название длиннее окошка: едет влево по кругу, между концом и новым началом — промежуток
                    int total = textW + 40, shift = (int)offset % total;
                    TextRenderer.DrawText(g, name, bold, new Rectangle(line.X - shift, line.Y, textW + 4, NameH), Theme.Text, flags);
                    TextRenderer.DrawText(g, name, bold, new Rectangle(line.X - shift + total, line.Y, textW + 4, NameH), Theme.Text, flags);
                }
                g.ResetClip();
            }
        }

        protected override void Dispose(bool disposing)
        {
            if (disposing)
            {
                timer.Dispose();
                if (image != null) image.Dispose();
            }
            base.Dispose(disposing);
        }
    }

    static class Program
    {
        // Число из проверочной переменной; неправильное значение — значение по умолчанию, а не ошибка.
        public static int Int(string s, int fallback)
        {
            int v;
            return s != null && int.TryParse(s.Trim(), out v) ? v : fallback;
        }

        // Для проверок: BPS_SLOTS="файл|вид слоя=имя пака;…" задаёт выбор отдельных слоёв (имя off — выключить).
        public static void TestSlots(List<Pack> packs, Dictionary<string, Pack> slots)
        {
            string spec = Environment.GetEnvironmentVariable("BPS_SLOTS");
            if (spec == null) return;
            foreach (string part in spec.Split(';'))
            {
                string[] kv = part.Split('=');
                Pack p = kv[1] == "off" ? Pack.Off : packs.Find(delegate(Pack x) { return x.Name == kv[1]; });
                if (p != null) slots[kv[0]] = p;
            }
        }

        [STAThread]
        static int Main(string[] args)
        {
            L.Init();
            string theme = Environment.GetEnvironmentVariable("BPS_THEME") ?? Settings.Get("theme"); // переменная — для проверочных снимков
            Theme.Dark = theme == "dark";
            // Сборка без окна: --merge <результат> <название> <пак1> <пак2> ...  (пак1 — самый важный)
            if (args.Length >= 4 && args[0] == "--merge")
            {
                List<Pack> packs = new List<Pack>();
                try
                {
                    List<string> notes = new List<string>();
                    for (int i = 3; i < args.Length; i++) packs.AddRange(PackLoader.Load(args[i], notes));
                    Dictionary<string, Pack> slots = new Dictionary<string, Pack>();
                    TestSlots(packs, slots);
                    // для проверок: BPS_OFF="файл;файл" выключает текстуры, как щелчок по ним в окне
                    Dictionary<string, Pack> off = new Dictionary<string, Pack>();
                    string offSpec = Environment.GetEnvironmentVariable("BPS_OFF");
                    if (offSpec != null) foreach (string k in offSpec.Split(';')) off[k] = Pack.Off;
                    List<Entry> entries = Builder.Collect(packs, off, new Dictionary<string, Pack>(), slots);
                    // в окне эти случаи показываются на подтверждение; при сборке без окна они просто попадают в журнал
                    foreach (Entry e in entries)
                        if (e.PbrAuto && !e.Excluded) notes.Add("auto layers: " + e.Rel + " <- " + e.PbrChoice.Name);
                    notes.AddRange(Builder.Build(entries, packs, args[2], "", args[1]));
                    File.WriteAllLines(args[1] + ".log", notes.ToArray());
                    return 0;
                }
                catch (Exception ex)
                {
                    File.WriteAllText(args[1] + ".log", ex.ToString());
                    return 1;
                }
                finally
                {
                    // только распакованное этим запуском: в общей папке могут лежать пакеты открытого окна программы
                    foreach (Pack p in packs) PackLoader.DropTemp(p.TempDir);
                }
            }

            Application.EnableVisualStyles();
            Application.SetCompatibleTextRenderingDefault(false);
            // непредвиденная ошибка в окне — сообщение, а не стандартное окно с предложением закрыть программу
            Application.SetUnhandledExceptionMode(UnhandledExceptionMode.CatchException);
            Application.ThreadException += delegate(object sender, System.Threading.ThreadExceptionEventArgs e)
            {
                MessageBox.Show(L.T("Непредвиденная ошибка:\n") + e.Exception.Message, "Resource Pack Constructor", MessageBoxButtons.OK, MessageBoxIcon.Warning);
            };
            MainForm f = new MainForm();
            int first = 0;
            if (args.Length >= 2 && args[0] == "--shot") { f.Shot(args[1]); first = 2; }
            if (args.Length > first)
            {
                string[] rest = new string[args.Length - first];
                Array.Copy(args, first, rest, 0, rest.Length);
                f.AddPaths(rest);
            }
            Application.Run(f);
            return 0;
        }
    }
}